#[derive(Clone)]
struct SessionToken(Arc<()>);

impl PartialEq for SessionToken {
    fn eq(&self, other: &Self) -> bool {
        Arc::ptr_eq(&self.0, &other.0)
    }
}

impl Eq for SessionToken {}

impl std::fmt::Debug for SessionToken {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str("SessionToken")
    }
}

/// Owns the query runtime and the session state for the implemented frontend.
///
/// The driver applies VFS inputs before requesting tracked syntax and
/// item-tree queries. Snapshot-bound results are always rebound to the
/// [`WorkspaceSnapshot`] passed by the caller.
///
/// APIs that access the file interner require `FileId`s created by this
/// database. MVS dependency candidate manifests instead use distinct IDs from
/// their supplied snapshot because multiple versions on one compatibility
/// line share a stable package/file key.
pub struct RootDatabase {
    query_database: QueryDatabase,
    vfs: VfsInputs,
    syntax: SyntaxQueries,
    hir: ItemTreeQueries,
    resolve: ModuleTreeQueries<VfsInputs>,
    packages: Arc<PackageInterner>,
    files: FileInterner,
    symbols: Arc<Interner>,
    /// Canonical semantic types retained for this compiler session.
    semantic_types: sai_ty::ty::TyInterner,
    primitive_prelude: Result<Prelude, PrimitivePreludeBuildError>,
    /// Retained for the lifetime of this database so every `DefId` returned
    /// by Phase 1 remains associated with its original package-local paths.
    def_paths: HashMap<PackageId, Arc<DefPathInterner>>,
    /// Shares the source package interners with WIT view queries so generated
    /// origin IDs can be validated against the same persistent paths.
    wit_source_def_paths: Arc<Mutex<HashMap<PackageId, Arc<DefPathInterner>>>>,
    /// Tracked append-only source path counts invalidate generated WIT views
    /// when their origin definitions become available.
    wit_source_def_path_generations: InputQuery<String, u64>,
    package_scopes: Phase1PackageScopesQueries,
    package_wit_names: PackageWitNamesQueries,
    interface_uses: InterfaceUsesQueries,
    type_owner_paths: TypeOwnerPathQueries,
    local_enum_variant_value_types:
        local_enum_variant_value_queries::LocalEnumVariantValueTypeQueries,
    declared_requirements: DeclaredRequirementsQueries,
    wit_contracts: WitContractQueries,
    generated_wit_texts: GeneratedWitTextQueries,
    phase1_generated_wit_packages: HashSet<PackageId>,
    wit_units: WitUnitOfQueries,
    package_graph: InputQuery<u8, Option<PackageGraph>>,
    wit_packages: WitPackageQueries,
    wit_views: WitViewQueries,
    wasi_packages: WasiPackageQueries,
    #[allow(dead_code)]
    /// Retains one append-only path interner per WIT view unit across query
    /// rebuilds and the generic and embedded-WASI view APIs.
    wit_view_def_paths: Arc<Mutex<HashMap<String, Arc<DefPathInterner>>>>,
    /// Distinguishes session-local view DefIds and symbols in opaque WIT
    /// closures passed back through public driver APIs.
    session_token: SessionToken,
}

/// A semantically usable direct requirement retained from `sai.package`.
///
/// Target spellings stay as strings so query results remain independent of
/// session-local symbol IDs. The order of `only` targets is manifest order.
/// `declaration_order` is the source ordinal of the first declaration for
/// this identity, even though query results are sorted by identity.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct DeclaredRequirement {
    pub identity: String,
    pub declaration_order: u32,
    pub only: Option<Arc<[String]>>,
    pub test: bool,
}

impl StableHash for DeclaredRequirement {
    fn stable_hash(&self, hasher: &mut StableHasher) {
        hasher.write_tag(0xD4);
        self.identity.stable_hash(hasher);
        self.declaration_order.stable_hash(hasher);
        self.only.stable_hash(hasher);
        self.test.stable_hash(hasher);
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct DeclaredRequirementsInput {
    source_bytes: Arc<[u8]>,
    dependency: bool,
}

impl StableHash for DeclaredRequirementsInput {
    fn stable_hash(&self, hasher: &mut StableHasher) {
        hasher.write_tag(0xD3);
        self.source_bytes.stable_hash(hasher);
        self.dependency.stable_hash(hasher);
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct DeclaredRequirementsQueryOutput {
    requirements: Arc<[DeclaredRequirement]>,
    status: DeclaredRequirementsStatus,
}

impl StableHash for DeclaredRequirementsQueryOutput {
    fn stable_hash(&self, hasher: &mut StableHasher) {
        self.requirements.stable_hash(hasher);
        self.status.stable_hash(hasher);
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum DeclaredRequirementsStatus {
    Valid,
    InvalidManifest,
    PackageMismatch {
        found_identity: String,
        found_compatibility_line: String,
    },
}

impl StableHash for DeclaredRequirementsStatus {
    fn stable_hash(&self, hasher: &mut StableHasher) {
        match self {
            Self::Valid => hasher.write_tag(0xD5),
            Self::InvalidManifest => hasher.write_tag(0xD6),
            Self::PackageMismatch {
                found_identity,
                found_compatibility_line,
            } => {
                hasher.write_tag(0xD7);
                found_identity.stable_hash(hasher);
                found_compatibility_line.stable_hash(hasher);
            }
        }
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum DeclaredRequirementsError {
    Package(PackageIdError),
    PackageKey(PackageKeyError),
    Query(QueryError),
    InvalidManifest {
        package_key: String,
    },
    ManifestPackageMismatch {
        expected_package_key: String,
        found_identity: String,
        found_compatibility_line: String,
    },
}

impl From<PackageIdError> for DeclaredRequirementsError {
    fn from(error: PackageIdError) -> Self {
        Self::Package(error)
    }
}

impl From<PackageKeyError> for DeclaredRequirementsError {
    fn from(error: PackageKeyError) -> Self {
        Self::PackageKey(error)
    }
}

impl From<QueryError> for DeclaredRequirementsError {
    fn from(error: QueryError) -> Self {
        Self::Query(error)
    }
}

struct DeclaredRequirementsQueries {
    input: InputQuery<PackageKey, DeclaredRequirementsInput>,
    query: DerivedQuery<PackageKey, DeclaredRequirementsQueryOutput>,
}

impl DeclaredRequirementsQueries {
    fn new() -> Result<Self, QueryError> {
        let input = InputQuery::<PackageKey, DeclaredRequirementsInput>::new(
            "declared_requirements_input",
            Durability::Low,
        )?;
        let query_input = input.clone();
        let query = DerivedQuery::new(
            "declared_requirements",
            move |database: &mut QueryDatabase, key: &PackageKey| {
                let input = query_input.get(database, key.clone())?;
                let role = if input.dependency {
                    PackageRole::Dependency
                } else {
                    PackageRole::Root
                };
                let parsed = sai_package::manifest::parse_for_role_with_error_limit(
                    &input.source_bytes,
                    role,
                    0,
                );
                if !parsed.is_syntax_valid() {
                    return Ok(DeclaredRequirementsQueryOutput {
                        requirements: Arc::from([]),
                        status: DeclaredRequirementsStatus::InvalidManifest,
                    });
                }
                let Some(header) = parsed.file().header.as_ref() else {
                    return Ok(DeclaredRequirementsQueryOutput {
                        requirements: Arc::from([]),
                        status: DeclaredRequirementsStatus::InvalidManifest,
                    });
                };
                let found_identity = header.value.identity.to_string();
                let found_compatibility_line =
                    header.value.version.compatibility_line().to_string();
                if !manifest_matches_package_key(key, &found_identity, &found_compatibility_line) {
                    return Ok(DeclaredRequirementsQueryOutput {
                        requirements: Arc::from([]),
                        status: DeclaredRequirementsStatus::PackageMismatch {
                            found_identity,
                            found_compatibility_line,
                        },
                    });
                }
                let mut by_identity = BTreeMap::<String, DeclaredRequirement>::new();
                let mut declaration_ordinal = 0_u32;
                for declaration in &parsed.file().declarations {
                    let sai_package::manifest::PackageDeclaration::Requires { test, entries } =
                        &declaration.value
                    else {
                        continue;
                    };
                    for entry in entries {
                        let source_ordinal = declaration_ordinal;
                        declaration_ordinal = declaration_ordinal.saturating_add(1);
                        let requirement = &entry.value;
                        let only = requirement.only.as_ref().map(|targets| {
                            targets
                                .value
                                .iter()
                                .map(|target| target.value.to_string())
                                .collect::<Vec<_>>()
                                .into()
                        });
                        by_identity
                            .entry(requirement.package.to_string())
                            .or_insert(DeclaredRequirement {
                                identity: requirement.package.to_string(),
                                declaration_order: source_ordinal,
                                only,
                                test: *test,
                            });
                    }
                }
                Ok(DeclaredRequirementsQueryOutput {
                    requirements: Arc::from(
                        by_identity
                            .into_values()
                            .collect::<Vec<DeclaredRequirement>>(),
                    ),
                    status: DeclaredRequirementsStatus::Valid,
                })
            },
        )?;
        Ok(Self { input, query })
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum WitContractQueryFailure {
    Projection(WitContractError),
    PackageMismatch {
        found_identity: String,
        found_compatibility_line: String,
    },
}

impl StableHash for WitContractQueryFailure {
    fn stable_hash(&self, hasher: &mut StableHasher) {
        match self {
            Self::Projection(error) => {
                hasher.write_tag(0xD8);
                match error {
                    WitContractError::MissingHeader => hasher.write_tag(0x01),
                    WitContractError::MalformedHeader { span } => {
                        hasher.write_tag(0x02);
                        stable_hash_byte_range(span, hasher);
                    }
                    WitContractError::MissingContentKind => hasher.write_tag(0x03),
                    WitContractError::InvalidContentPath { field, span, error } => {
                        hasher.write_tag(0x04);
                        stable_hash_wit_contract_field(*field, hasher);
                        stable_hash_byte_range(span, hasher);
                        hasher.write_tag(match error {
                            sai_package::package_path::PackagePathError::InvalidPackagePath => 0x01,
                            sai_package::package_path::PackagePathError::PathEscapesRepository => {
                                0x02
                            }
                        });
                    }
                    WitContractError::DuplicateDeclaration {
                        field,
                        first_span,
                        duplicate_span,
                    } => {
                        hasher.write_tag(0x05);
                        stable_hash_wit_contract_field(*field, hasher);
                        stable_hash_byte_range(first_span, hasher);
                        stable_hash_byte_range(duplicate_span, hasher);
                    }
                    WitContractError::MalformedDeclaration { span } => {
                        hasher.write_tag(0x06);
                        stable_hash_byte_range(span, hasher);
                    }
                    WitContractError::MalformedManifest {
                        lexical_error_count,
                        parser_error_count,
                    } => {
                        hasher.write_tag(0x07);
                        stable_hash_usize(*lexical_error_count, hasher);
                        stable_hash_usize(*parser_error_count, hasher);
                    }
                }
            }
            Self::PackageMismatch {
                found_identity,
                found_compatibility_line,
            } => {
                hasher.write_tag(0xD9);
                found_identity.stable_hash(hasher);
                found_compatibility_line.stable_hash(hasher);
            }
        }
    }
}

fn stable_hash_wit_contract_field(field: WitContractField, hasher: &mut StableHasher) {
    hasher.write_tag(match field {
        WitContractField::PackageHeader => 0x01,
        WitContractField::Source => 0x02,
        WitContractField::Artifact => 0x03,
        WitContractField::Wit => 0x04,
        WitContractField::ExportWorld => 0x05,
    });
}

fn stable_hash_byte_range(range: &std::ops::Range<usize>, hasher: &mut StableHasher) {
    stable_hash_usize(range.start, hasher);
    stable_hash_usize(range.end, hasher);
}

fn stable_hash_usize(value: usize, hasher: &mut StableHasher) {
    hasher.write_tag(0xDA);
    hasher.write_u64(u64::try_from(value).unwrap_or(u64::MAX));
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct WitContractQueryOutput {
    result: Result<Arc<WitContract>, WitContractQueryFailure>,
}

impl StableHash for WitContractQueryOutput {
    fn stable_hash(&self, hasher: &mut StableHasher) {
        match &self.result {
            Ok(contract) => {
                hasher.write_tag(0xDB);
                contract.stable_hash(hasher);
            }
            Err(error) => {
                hasher.write_tag(0xDC);
                error.stable_hash(hasher);
            }
        }
    }
}

/// Errors returned by the tracked WIT projection of a package manifest.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum WitContractQueryError {
    Package(PackageIdError),
    PackageKey(PackageKeyError),
    Query(QueryError),
    Projection {
        package_key: String,
        error: WitContractError,
    },
    ManifestPackageMismatch {
        expected_package_key: String,
        found_identity: String,
        found_compatibility_line: String,
    },
}

impl From<PackageIdError> for WitContractQueryError {
    fn from(error: PackageIdError) -> Self {
        Self::Package(error)
    }
}

impl From<PackageKeyError> for WitContractQueryError {
    fn from(error: PackageKeyError) -> Self {
        Self::PackageKey(error)
    }
}

impl From<QueryError> for WitContractQueryError {
    fn from(error: QueryError) -> Self {
        Self::Query(error)
    }
}

struct WitContractQueries {
    query: DerivedQuery<PackageKey, WitContractQueryOutput>,
}

impl WitContractQueries {
    fn new(input: InputQuery<PackageKey, DeclaredRequirementsInput>) -> Result<Self, QueryError> {
        let query = DerivedQuery::new(
            "wit_contract",
            move |database: &mut QueryDatabase, key: &PackageKey| {
                let input = input.get(database, key.clone())?;
                let role = if input.dependency {
                    PackageRole::Dependency
                } else {
                    PackageRole::Root
                };
                let parsed = sai_package::manifest::parse_for_role_with_error_limit(
                    &input.source_bytes,
                    role,
                    0,
                );
                let contract = WitContract::from_package_parse_output(&parsed)
                    .map_err(|error| WitContractQueryFailure::Projection(error));
                let result = contract.and_then(|contract| {
                    let found_identity = contract.identity().to_string();
                    let found_compatibility_line =
                        contract.version().compatibility_line().to_string();
                    if !manifest_matches_package_key(
                        key,
                        &found_identity,
                        &found_compatibility_line,
                    ) {
                        return Err(WitContractQueryFailure::PackageMismatch {
                            found_identity,
                            found_compatibility_line,
                        });
                    }
                    Ok(Arc::new(contract))
                });
                Ok(WitContractQueryOutput { result })
            },
        )?;
        Ok(Self { query })
    }
}

struct GeneratedWitTextQueries {
    input: InputQuery<PackageKey, GeneratedText>,
    query: DerivedQuery<PackageKey, Option<Arc<GeneratedText>>>,
}

impl GeneratedWitTextQueries {
    fn new() -> Result<Self, QueryError> {
        let input = InputQuery::<PackageKey, GeneratedText>::new(
            "generated_wit_text_input",
            Durability::Low,
        )?;
        let query_input = input.clone();
        let query = DerivedQuery::new(
            "generated_wit_text",
            move |database: &mut QueryDatabase, key: &PackageKey| {
                query_input.get_opt(database, key.clone())
            },
        )?;
        Ok(Self { input, query })
    }
}

