impl TypeOwnerPathQueries {
    fn new() -> Result<Self, QueryError> {
        let input = InputQuery::<TypeOwnerPathQueryKey, TypeOwnerPathQueryIdentity>::new(
            "type_owner_paths_input",
            Durability::Low,
        )?;
        let query_input = input.clone();
        let query = DerivedQuery::new(
            "type_owner_paths",
            move |database: &mut QueryDatabase, key: &TypeOwnerPathQueryKey| {
                let identity = query_input.get(database, key.clone())?;
                let prepared = STAGED_TYPE_OWNER_PATH_QUERIES.with(|staged| {
                    staged
                        .borrow()
                        .get(key)
                        .filter(|staged| staged.identity.as_ref() == identity.as_ref())
                        .map(|staged| Arc::clone(&staged.prepared))
                });
                let Some(prepared) = prepared else {
                    return Err(QueryError::MissingInput {
                        query: "type_owner_paths_prepared_inputs".to_owned(),
                    });
                };
                let result = resolve_prepared_type_owner_paths(&prepared);
                Ok(TypeOwnerPathQueryOutput {
                    input_fingerprint: fingerprint(identity.as_ref()),
                    identity,
                    result,
                })
            },
        )?;
        Ok(Self { input, query })
    }

    fn resolve(
        &self,
        database: &mut QueryDatabase,
        key: TypeOwnerPathQueryKey,
        identity: TypeOwnerPathQueryIdentity,
        prepared: PreparedTypeOwnerPathQuery,
    ) -> Result<Arc<TypeOwnerPathQueryOutput>, QueryError> {
        let identity = Arc::new(identity);
        let _staged = StagedTypeOwnerPathQueryGuard::install(
            key.clone(),
            Arc::clone(&identity),
            Arc::new(prepared),
        );
        self.input
            .set(database, key.clone(), identity.as_ref().clone())?;
        let output = self.query.get(database, key)?;
        if output.identity != identity {
            return Err(QueryError::MissingInput {
                query: "type_owner_paths_identity_mismatch".to_owned(),
            });
        }
        Ok(output)
    }
}

impl From<QueryError> for OwnerControlFlowResolutionError {
    fn from(error: QueryError) -> Self {
        Self::Query(error)
    }
}

impl Phase1PackageScopesQueries {
    fn new(packages: Arc<PackageInterner>, symbols: Arc<Interner>) -> Result<Self, QueryError> {
        let input = InputQuery::<PackageKey, Phase1PackageScopesIdentity>::new(
            "package_scopes_input",
            Durability::Low,
        )?;
        let query_input = input.clone();
        let query = DerivedQuery::new(
            "package_scopes",
            move |database: &mut QueryDatabase, key: &PackageKey| {
                let identity = query_input.get(database, key.clone())?;
                let staged = STAGED_PHASE1_PACKAGE_SCOPES.with(|staged| {
                    staged
                        .borrow()
                        .get(key)
                        .filter(|staged| staged.identity.as_ref() == identity.as_ref())
                        .map(|staged| Arc::clone(&staged.prepared))
                });
                let Some(prepared) = staged else {
                    return Err(QueryError::MissingInput {
                        query: "package_scopes_prepared_inputs".to_owned(),
                    });
                };
                let result = collect_prepared_phase1_package_scopes(&prepared, &packages, &symbols);
                Ok(Phase1PackageScopesQueryOutput {
                    input_fingerprint: fingerprint(identity.as_ref()),
                    identity,
                    result,
                })
            },
        )?;
        Ok(Self { input, query })
    }
}

impl StableHash for Phase1PackageScopesIdentity {
    fn stable_hash(&self, hasher: &mut StableHasher) {
        hasher.write_tag(0xD1);
        self.package.stable_hash(hasher);
        self.modules.stable_hash(hasher);
        self.namespaces.stable_hash(hasher);
        self.target_name.stable_hash(hasher);
        self.target_capabilities.stable_hash(hasher);
        self.build_context.is_root_package.stable_hash(hasher);
        self.build_context
            .is_root_core_module_build
            .stable_hash(hasher);
        self.build_context.is_test_build.stable_hash(hasher);
        self.build_context.analyzes_tests.stable_hash(hasher);
        self.declared_requirements.stable_hash(hasher);
        self.package_graph.stable_hash(hasher);
        self.foreign_packages.stable_hash(hasher);
        self.foreign_wit_views.stable_hash(hasher);
    }
}

impl StableHash for Phase1ForeignPackageIdentity {
    fn stable_hash(&self, hasher: &mut StableHasher) {
        hasher.write_tag(0xDB);
        self.visible_identity.stable_hash(hasher);
        self.package_key.stable_hash(hasher);
        self.input_fingerprint.stable_hash(hasher);
    }
}

impl StableHash for Phase1ActiveSourceMemberScopeIdentity {
    fn stable_hash(&self, hasher: &mut StableHasher) {
        hasher.write_tag(0xDC);
        self.requester.stable_hash(hasher);
        self.requester_input_fingerprint.stable_hash(hasher);
        self.package_graph_fingerprint.stable_hash(hasher);
        self.package_fingerprints.stable_hash(hasher);
    }
}

impl StableHash for Phase1ActiveWitViewEntryIdentity {
    fn stable_hash(&self, hasher: &mut StableHasher) {
        hasher.write_tag(0xE0);
        self.package_key.stable_hash(hasher);
        self.package_identity.stable_hash(hasher);
        self.exact_version.stable_hash(hasher);
        self.kind.stable_hash(hasher);
        self.unit_stable_key.stable_hash(hasher);
        self.unit_canonical_name.stable_hash(hasher);
        self.view_fingerprint.stable_hash(hasher);
        self.failure.stable_hash(hasher);
    }
}

impl StableHash for Phase1ActiveWitViewEntryKind {
    fn stable_hash(&self, hasher: &mut StableHasher) {
        hasher.write_tag(0xE2);
        match self {
            Self::PackageGraph { form, role } => {
                hasher.write_tag(0x01);
                form.stable_hash(hasher);
                role.stable_hash(hasher);
            }
            Self::EmbeddedWasi => hasher.write_tag(0x02),
        }
    }
}

impl StableHash for Phase1ActiveWitViewScopesIdentity {
    fn stable_hash(&self, hasher: &mut StableHasher) {
        hasher.write_tag(0xE1);
        self.requester.stable_hash(hasher);
        self.target_name.stable_hash(hasher);
        self.target_capabilities.stable_hash(hasher);
        self.package_graph_fingerprint.stable_hash(hasher);
        self.entries.stable_hash(hasher);
    }
}

fn sort_foreign_scope_provenance(provenance: &mut [Phase1ForeignPackageIdentity]) {
    provenance.sort_by(|left, right| {
        left.visible_identity
            .as_bytes()
            .cmp(right.visible_identity.as_bytes())
            .then_with(|| left.package_key.cmp(&right.package_key))
    });
}

impl StableHash for Phase1PackageGraphProjection {
    fn stable_hash(&self, hasher: &mut StableHasher) {
        match self {
            Self::Package { outgoing_edges } => {
                hasher.write_tag(0xD8);
                outgoing_edges.stable_hash(hasher);
            }
            Self::ImplicitToolchain { version } => {
                hasher.write_tag(0xD9);
                version.to_string().stable_hash(hasher);
            }
        }
    }
}

impl StableHash for StableActivePackageEdge {
    fn stable_hash(&self, hasher: &mut StableHasher) {
        hasher.write_tag(0xDA);
        self.visible_identity.stable_hash(hasher);
        self.target.stable_hash(hasher);
        self.target_version.to_string().stable_hash(hasher);
        self.target_form.stable_hash(hasher);
        self.target_role.stable_hash(hasher);
    }
}

impl StableHash for Phase1ModuleIdentity {
    fn stable_hash(&self, hasher: &mut StableHasher) {
        hasher.write_tag(0xD2);
        self.path.stable_hash(hasher);
        self.file_id.stable_hash(hasher);
        self.source_path.stable_hash(hasher);
        self.source_package.stable_hash(hasher);
        self.document_version.stable_hash(hasher);
        self.source_bytes.stable_hash(hasher);
        self.parent_dir.stable_hash(hasher);
        self.children.stable_hash(hasher);
    }
}

impl StableHash for Phase1NamespaceIdentity {
    fn stable_hash(&self, hasher: &mut StableHasher) {
        hasher.write_tag(0xD3);
        self.path.stable_hash(hasher);
        self.children.stable_hash(hasher);
    }
}

impl StableHash for StableChildEntry {
    fn stable_hash(&self, hasher: &mut StableHasher) {
        hasher.write_tag(0xD4);
        match self {
            Self::Module(module) => {
                hasher.write_tag(0);
                module.stable_hash(hasher);
            }
            Self::Namespace(namespace) => {
                hasher.write_tag(1);
                namespace.stable_hash(hasher);
            }
            Self::Both(module, namespace) => {
                hasher.write_tag(2);
                module.stable_hash(hasher);
                namespace.stable_hash(hasher);
            }
        }
    }
}

/// Owns the CLI's cancellation state and installs the process interrupt handler.
pub struct InterruptHandler {
    cancellation: CancellationToken,
}

pub type CancellationToken = sai_query::CancellationToken;

/// Builds the target facts used by `sai check` for a target's core-module
/// analysis.
///
/// The check command analyzes the core-module column for core targets.
/// `host` therefore applies only to core targets; WASI targets have no
/// artifact-specific predicates here. Wasm64 always supplies `memory64`, and
/// native targets supply `native_ffi` and `process`.
pub fn target_cfg_for_check(target: &str) -> Result<TargetCfg, TargetCfgError> {
    let capabilities: &[&str] = match target {
        "wasm32-core" => &["host"],
        "wasm64-core" => &["host", "memory64"],
        "wasm32-wasi" => &[],
        "wasm64-wasi" => &["memory64"],
        "x86_64-linux" | "aarch64-linux" | "aarch64-macos" | "x86_64-windows" => {
            &["native_ffi", "process"]
        }
        _ => &[],
    };
    TargetCfg::new(target, capabilities.iter().copied())
}

impl InterruptHandler {
    /// Installs SIGINT/Ctrl-C handling. Every interrupt requests cancellation;
    /// filesystem owners then unwind through their cleanup paths.
    pub fn install() -> Result<Self, ctrlc::Error> {
        let cancellation = CancellationToken::default();
        let handler_cancellation = cancellation.clone();
        ctrlc::set_handler(move || {
            handler_cancellation.cancel();
        })?;
        Ok(Self { cancellation })
    }

    pub fn cancellation_token(&self) -> CancellationToken {
        self.cancellation.clone()
    }
}

/// The package creation operations used by the command-line frontend.
///
/// Keeping this small facade in the driver lets `sai_cli` depend on only one
/// runtime crate while package filesystem work remains owned by `sai_package`.
pub mod new_package {
    use sai_query::CancellationToken;
    use std::path::Path;

    pub use sai_package::new_package::{
        NewPackageError, NewPackageFile, NewPackageReceipt, create_new_package,
        validate_new_package_identity,
    };

    /// Creates a package while honoring the driver's interrupt token at
    /// filesystem safe points.
    pub fn create_new_package_with_cancellation(
        destination: &Path,
        identity: &str,
        targets: &[String],
        cancellation: &CancellationToken,
    ) -> Result<NewPackageReceipt, NewPackageError> {
        sai_package::new_package::create_new_package_with_cancel_check(
            destination,
            identity,
            targets,
            || cancellation.is_cancelled(),
        )
    }
}

/// The package value validators exposed to command-line argument handling.
pub mod package_validation {
    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    pub enum GitUrlValidationError {
        Insecure,
        Unsupported,
        Credentials,
    }

    pub fn is_valid_identity(value: &str) -> bool {
        sai_package::identity::PackageIdentity::parse(value).is_ok()
    }

    pub fn is_standard_package_identity(value: &str) -> bool {
        matches!(
            value,
            "sai:collections"
                | "sai:text"
                | "sai:fmt"
                | "sai:io"
                | "sai:fs"
                | "sai:net"
                | "sai:http"
                | "sai:async"
                | "sai:process"
        )
    }

    pub fn is_valid_exact_version(value: &str) -> bool {
        sai_package::version::Version::parse(value).is_ok()
    }

    pub fn is_valid_version_requirement(value: &str) -> bool {
        sai_package::version_req::VersionReq::parse(value).is_ok()
    }

    pub fn is_supported_git_url(value: &str) -> bool {
        validate_git_url(value).is_ok()
    }

    pub fn validate_git_url(value: &str) -> Result<(), GitUrlValidationError> {
        sai_package::git_remote::validate_git_url(value).map_err(|error| match error {
            sai_package::git_remote::GitUrlValidationError::Insecure => {
                GitUrlValidationError::Insecure
            }
            sai_package::git_remote::GitUrlValidationError::Unsupported => {
                GitUrlValidationError::Unsupported
            }
            sai_package::git_remote::GitUrlValidationError::Credentials => {
                GitUrlValidationError::Credentials
            }
        })
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum RootDatabaseError {
    Query(QueryError),
    ModuleTree(ModuleTreeQueryError),
    Package(PackageIdError),
    PackageKey(PackageKeyError),
    FileInterner(FileInternerError),
    /// The numeric file index is outside this database's file interner.
    FileNotInterned,
    PackageDiagnostics(MvsDuplicatePackageLineDiagnosticError),
    MissingPackageManifest(MvsPackageVersion),
    UnexpectedPackageManifest(MvsPackageVersion),
    MixedSourceAuditLoadMismatch,
    MixedSourceManifestContractMismatch(MvsPackageVersion),
    FinalManifestSourceDecode {
        package_version: MvsPackageVersion,
        error: SourceDecodeError,
    },
    FinalManifestSnapshot(WorkspaceSnapshotError),
    FinalManifestFileIdsExhausted,
    FinalManifestPathOrdinalsExhausted,
    PackageManifestFileKeyMismatch {
        file_id: FileId,
        expected_package_key: String,
        found_package_key: String,
        found_path: String,
    },
}

/// Failure while creating a WASI unit owned by this compiler session.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum WasiWitUnitError {
    Symbol(sai_intern::InternError),
    InvalidEmbeddedVersion,
    NotWasi,
    Identity(WitUnitIdentityError),
}

impl std::fmt::Display for WasiWitUnitError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Symbol(error) => {
                write!(formatter, "could not intern WASI package name: {error:?}")
            }
            Self::InvalidEmbeddedVersion => {
                formatter.write_str("the embedded WASI version is invalid")
            }
            Self::NotWasi => formatter.write_str("the WIT unit is not a WASI unit"),
            Self::Identity(error) => write!(formatter, "invalid embedded WASI unit: {error:?}"),
        }
    }
}

impl std::error::Error for WasiWitUnitError {}

/// Failure returned by the tracked embedded-WASI package or root-view queries.
///
/// Loader and view-construction errors are ordinary result values from the
/// query graph. Only query-runtime failures are represented by `Query`.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum WasiWitQueryError {
    Query(QueryError),
    Unit(WasiWitUnitError),
    Load(WitWasiLoadError),
    View(WitViewError),
    ViewQuery(WitViewQueryError),
}

impl std::fmt::Display for WasiWitQueryError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Query(error) => write!(formatter, "WASI query failed: {error}"),
            Self::Unit(error) => error.fmt(formatter),
            Self::Load(error) => error.fmt(formatter),
            Self::View(error) => write!(formatter, "WASI view construction failed: {error}"),
            Self::ViewQuery(error) => write!(formatter, "WASI view query failed: {error}"),
        }
    }
}

impl std::error::Error for WasiWitQueryError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Query(error) => Some(error),
            Self::Unit(error) => Some(error),
            Self::Load(error) => Some(error),
            Self::View(error) => Some(error),
            Self::ViewQuery(error) => Some(error),
        }
    }
}

/// A failure while assembling snapshot-bound inputs for Phase 1 collection.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum Phase1CollectionError {
    Parse(ParseQueryError),
    ItemTree(ItemTreeQueryError),
    TargetFilter(TargetFilterError),
    PackageScopes(PackageScopesError),
    PackageWitNamesQuery(PackageWitNamesQueryError),
    InterfaceUsesQuery(InterfaceUsesQueryError),
    SnapshotIdentityMismatch,
    UseTargetDiagnostics(UseTargetDiagnosticsError),
    DefPathInterner(DefPathInternerError),
    MissingSnapshotFile(FileId),
    TooManyModules,
    SnapshotBoundDiagnosticHasFixes,
    Query(QueryError),
    DeclaredRequirements(DeclaredRequirementsError),
    Package(PackageIdError),
    GeneratedWitText(GeneratedWitTextError),
    PackageGraphMissingNode(PackageKey),
    PackageGraphRequirementEdgeMismatch {
        package: PackageKey,
        identity: String,
        expected_active: bool,
        found_active: bool,
    },
    ActiveWitViewMismatch(PackageKey),
    ActiveWitViewRuntimeFailure {
        package_key: PackageKey,
        failure: Phase1WitViewRuntimeFailure,
    },
    ForeignPackageScopeMismatch {
        package: PackageKey,
        visible_identity: String,
        target: PackageKey,
    },
}

/// Runtime failures encountered while deriving an active WIT view closure.
///
/// Semantic package and WIT failures are retained in the closure so imports
/// can defer. These variants instead abort collection and remain visible to
/// the caller.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum Phase1WitViewRuntimeFailure {
    Query(QueryError),
    UnitOf(WitUnitOfError),
    View(WitViewQueryError),
    Wasi(WasiWitQueryError),
}

/// Invalid or incomplete input while assembling transitive active-source
/// scopes for qualified module-member lookup.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum Phase1ModuleMemberScopeError {
    WitViewRuntimeFailure {
        package_key: PackageKey,
        failure: Phase1WitViewRuntimeFailure,
    },
    RequesterPackageIdMismatch,
    PackageGraphMismatch(PackageKey),
    PackageGraphMissingNode(PackageKey),
    RequesterIsNotSource(PackageKey),
    MissingSourcePackage(PackageKey),
    UnexpectedPackage(PackageKey),
    DuplicatePackage(PackageKey),
    SnapshotMismatch(PackageKey),
    TargetConfigMismatch(PackageKey),
    PackageIdMismatch(PackageKey),
    ScopePackageMismatch(PackageKey),
    ModuleTreeScopeCountMismatch(PackageKey),
    DirectScopeProvenanceMismatch(PackageKey),
    WitViewScopeMismatch(PackageKey),
}

fn wit_contract_error_is_runtime(error: &WitContractQueryError) -> bool {
    matches!(
        error,
        WitContractQueryError::Package(_)
            | WitContractQueryError::PackageKey(_)
            | WitContractQueryError::Query(_)
    )
}

fn wit_unit_of_error_is_runtime(error: &WitUnitOfError) -> bool {
    match error {
        WitUnitOfError::Package(_)
        | WitUnitOfError::PackageKey(_)
        | WitUnitOfError::Query(_)
        | WitUnitOfError::PackageGraphUnavailable
        | WitUnitOfError::PackageNotActive { .. }
        | WitUnitOfError::UnitIdentity { .. } => true,
        WitUnitOfError::Contract(error) => wit_contract_error_is_runtime(error),
        WitUnitOfError::PackageVersionMismatch { .. }
        | WitUnitOfError::PackageFormMismatch { .. } => false,
    }
}

fn wit_package_failure_is_runtime(failure: &WitPackageFailure) -> bool {
    match failure {
        WitPackageFailure::PackageGraphUnavailable
        | WitPackageFailure::PackageNotActive { .. }
        | WitPackageFailure::UnitProjection { .. }
        | WitPackageFailure::RequestedUnitMismatch { .. } => true,
        WitPackageFailure::Contract { .. }
        | WitPackageFailure::RootDirectoryNotDeclared { .. }
        | WitPackageFailure::Graph(_) => false,
        WitPackageFailure::Load(error) => match error.failure() {
            WitPackageLoadFailure::Source(
                WitPackageSourceFailure::Query(_)
                | WitPackageSourceFailure::InvalidFileKey { .. }
                | WitPackageSourceFailure::FileReadError { .. },
            ) => true,
            WitPackageLoadFailure::Source(_)
            | WitPackageLoadFailure::Parse(_)
            | WitPackageLoadFailure::Graph(_)
            | WitPackageLoadFailure::ReferenceResolution(_)
            | WitPackageLoadFailure::Closure(_)
            | WitPackageLoadFailure::MissingResolvedPackage(_)
            | WitPackageLoadFailure::ClosureDoesNotEndAtRoot
            | WitPackageLoadFailure::Model(_) => false,
        },
    }
}

fn wit_view_error_is_runtime(error: &WitViewError) -> bool {
    matches!(
        error,
        WitViewError::PackageId(_)
            | WitViewError::Symbol(_)
            | WitViewError::Lookup(_)
            | WitViewError::DefPath(_)
            | WitViewError::DefPathInterner(_)
            | WitViewError::DefPathPackageMismatch { .. }
            | WitViewError::GeneratedOriginInternerRequired
            | WitViewError::GeneratedOriginInternerPackageMismatch { .. }
            | WitViewError::GeneratedOriginPath { .. }
            | WitViewError::TooManyDefinitions
            | WitViewError::DefinitionIndexOutOfBounds(_)
            | WitViewError::DuplicateDefinitionIndex(_)
            | WitViewError::MissingDefinition(_)
    )
}

fn wit_view_query_error_is_runtime(error: &WitViewQueryError) -> bool {
    match error {
        WitViewQueryError::InvalidUnit(_) | WitViewQueryError::Query(_) => true,
        WitViewQueryError::Package(error) => wit_package_failure_is_runtime(error),
        WitViewQueryError::View(error) => wit_view_error_is_runtime(error),
        WitViewQueryError::GeneratedSnapshotMissing { .. } => false,
    }
}

/// A finalized, direct source dependency scope available to one package's
/// Phase 2–3 import resolution.
///
/// `visible_identity` and `package_key` come from the requiring package's
/// exact active graph edge. The selected key is retained so query identity and
/// graph validation never resolve a dependency by identity alone.
#[derive(Clone, Debug)]
pub struct Phase1ForeignPackageScopes {
    visible_identity: String,
    package_key: PackageKey,
    module_tree: Arc<ModuleTree>,
    scopes: Arc<Phase1PackageScopes>,
    input_fingerprint: Fingerprint,
}

/// A finalized package collection retained for qualified member lookup.
///
/// This is separate from [`Phase1ForeignPackageScopes`]: the latter is an
/// edge-specific direct-import input, while this value retains the exact
/// collection provenance needed to validate a transitive active-source
/// closure.
#[derive(Clone, Debug)]
pub struct Phase1ModuleMemberScopePackage {
    collection: Phase1PackageScopesCollection,
}

impl Phase1ModuleMemberScopePackage {
    pub fn package_key(&self) -> &PackageKey {
        &self.collection.package_key
    }

    pub fn module_tree(&self) -> &ModuleTree {
        &self.collection.module_tree
    }

    pub fn scopes(&self) -> &Phase1PackageScopes {
        &self.collection.scopes
    }

    pub const fn input_fingerprint(&self) -> Fingerprint {
        self.collection.input_fingerprint
    }

    /// Adapts the finalized package into the direct-edge form used by Phase 1.
    pub fn as_foreign_package_scopes(
        &self,
        visible_identity: impl Into<String>,
    ) -> Phase1ForeignPackageScopes {
        Phase1ForeignPackageScopes {
            visible_identity: visible_identity.into(),
            package_key: self.collection.package_key.clone(),
            module_tree: Arc::new(self.collection.module_tree.clone()),
            scopes: Arc::new(self.collection.scopes.clone()),
            input_fingerprint: self.collection.input_fingerprint,
        }
    }
}

/// A validated active-source scope closure for qualified module-member paths.
///
/// The requesting collection and every reachable source dependency are bound
/// to one active package graph, workspace snapshot, and target configuration.
#[derive(Clone, Debug)]
pub struct Phase1ActiveSourceMemberScopes {
    requester: PackageKey,
    requester_input_fingerprint: Fingerprint,
    snapshot_id: WorkspaceSnapshotId,
    session_token: SessionToken,
    target_cfg: TargetCfg,
    package_graph_fingerprint: Fingerprint,
    source_packages: Vec<Phase1ModuleMemberScopePackage>,
    source_graph_packages: HashSet<PackageId>,
    package_identities: BTreeMap<String, String>,
    closure_fingerprint: Fingerprint,
}

impl Phase1ActiveSourceMemberScopes {
    pub fn requester(&self) -> &PackageKey {
        &self.requester
    }

    pub fn source_packages(&self) -> &[Phase1ModuleMemberScopePackage] {
        &self.source_packages
    }

    fn package_identity(&self, package_key: &str) -> Option<&str> {
        self.package_identities.get(package_key).map(String::as_str)
    }

    pub const fn closure_fingerprint(&self) -> Fingerprint {
        self.closure_fingerprint
    }

    pub fn matches_collection(&self, collection: &Phase1PackageScopesCollection) -> bool {
        self.requester == collection.package_key
            && self.requester_input_fingerprint == collection.input_fingerprint
            && self.snapshot_id == collection.snapshot_id
            && self.session_token == collection.session_token
            && self.target_cfg == collection.target_cfg
            && collection.package_graph_fingerprint == Some(self.package_graph_fingerprint)
    }
}

#[derive(Clone)]
struct OwnedPhase1ForeignWitView {
    visible_identity: String,
    view: Arc<WitView>,
    source_def_paths: Option<Arc<DefPathInterner>>,
    directly_visible: bool,
}

#[derive(Clone)]
struct Phase1ActiveWitViewEntry {
    identity: Phase1ActiveWitViewEntryIdentity,
    /// The canonical WIT unit, retained even when constructing its view
    /// fails so data-shape validation can still scan a loaded package.
    unit: Option<WitUnit>,
    available: Option<OwnedPhase1ForeignWitView>,
    /// Direct package edges in the package graph's canonical order, followed
    /// by catalog-ordered embedded WASI units.
    direct_order: Option<usize>,
}

/// A validated WIT-view closure for the active package graph reachable from
/// one source package.
///
/// Successful views are retained for Phase 1 `use` binding and qualified
/// member lookup. Unit and load failures remain in the closure identity as
/// values, allowing callers to defer paths whose WIT producer is unavailable.
#[derive(Clone)]
pub struct Phase1ActiveWitViewScopes {
    requester: PackageKey,
    snapshot_id: WorkspaceSnapshotId,
    target_cfg: TargetCfg,
    package_graph_fingerprint: Fingerprint,
    entries: Vec<Phase1ActiveWitViewEntry>,
    closure_fingerprint: Fingerprint,
    session_token: SessionToken,
}

impl Phase1ActiveWitViewScopes {
    pub fn requester(&self) -> &PackageKey {
        &self.requester
    }

    pub const fn closure_fingerprint(&self) -> Fingerprint {
        self.closure_fingerprint
    }

    pub fn available_unit_names(&self) -> impl Iterator<Item = &str> {
        self.entries.iter().filter_map(|entry| {
            entry
                .identity
                .unit_canonical_name
                .as_deref()
                .filter(|_| entry.available.is_some())
        })
    }

    pub fn unavailable_unit_names(&self) -> impl Iterator<Item = &str> {
        self.entries.iter().filter_map(|entry| {
            entry
                .identity
                .unit_canonical_name
                .as_deref()
                .filter(|_| entry.available.is_none() && entry.identity.failure.is_some())
        })
    }

    pub fn matches_collection(&self, collection: &Phase1PackageScopesCollection) -> bool {
        self.session_token == collection.session_token
            && self.requester == collection.package_key
            && self.snapshot_id == collection.snapshot_id
            && self.target_cfg == collection.target_cfg
            && collection.package_graph_fingerprint == Some(self.package_graph_fingerprint)
            && collection.wit_view_closure_fingerprint == Some(self.closure_fingerprint)
    }

    fn matches_request(
        &self,
        package: &PackageKey,
        snapshot: &WorkspaceSnapshot,
        target_cfg: &TargetCfg,
        package_graph_fingerprint: Fingerprint,
        session_token: &SessionToken,
    ) -> bool {
        self.requester == *package
            && self.snapshot_id == snapshot.id()
            && self.target_cfg == *target_cfg
            && self.package_graph_fingerprint == package_graph_fingerprint
            && self.session_token == *session_token
    }

    fn views(&self) -> impl Iterator<Item = &OwnedPhase1ForeignWitView> {
        self.entries
            .iter()
            .filter_map(|entry| entry.available.as_ref())
    }

    fn ordered_direct_entries(&self) -> Vec<&Phase1ActiveWitViewEntry> {
        let mut entries = self
            .entries
            .iter()
            .filter_map(|entry| entry.direct_order.map(|order| (order, entry)))
            .collect::<Vec<_>>();
        entries.sort_by_key(|(order, _)| *order);
        entries.into_iter().map(|(_, entry)| entry).collect()
    }

    fn direct_view_package_keys<'a>(
        &'a self,
        graph: &'a PackageGraph,
    ) -> impl Iterator<Item = &'a PackageKey> + 'a {
        let Some(node) = graph.node(&self.requester) else {
            return Box::new(std::iter::empty()) as Box<dyn Iterator<Item = &'a PackageKey>>;
        };
        let direct_targets = node
            .active_edges()
            .iter()
            .map(|edge| (edge.target(), edge.visible_identity()))
            .collect::<HashMap<_, _>>();
        Box::new(self.entries.iter().filter_map(move |entry| {
            entry.available.as_ref()?;
            match entry.identity.kind {
                Phase1ActiveWitViewEntryKind::EmbeddedWasi => Some(&entry.identity.package_key),
                Phase1ActiveWitViewEntryKind::PackageGraph { .. } => {
                    let visible_identity = direct_targets.get(&entry.identity.package_key)?;
                    (*visible_identity == entry.identity.package_identity.as_str())
                        .then_some(&entry.identity.package_key)
                }
            }
        }))
    }

    fn direct_unavailable_package_identities<'a>(
        &'a self,
        graph: &'a PackageGraph,
    ) -> impl Iterator<Item = &'a str> + 'a {
        let direct_targets = graph
            .node(&self.requester)
            .map(|node| {
                node.active_edges()
                    .iter()
                    .map(|edge| (edge.target(), edge.visible_identity()))
                    .collect::<HashMap<_, _>>()
            })
            .unwrap_or_default();
        self.entries.iter().filter_map(move |entry| {
            if entry.identity.kind == Phase1ActiveWitViewEntryKind::EmbeddedWasi {
                return None;
            }
            let visible_identity = direct_targets.get(&entry.identity.package_key)?;
            (entry.available.is_none() && entry.identity.failure.is_some())
                .then_some(*visible_identity)
        })
    }
}

/// The finalized package scopes and the request provenance needed to bind
/// their owner descriptors to the same source snapshot and target settings.
#[derive(Clone, Debug)]
pub struct Phase1PackageScopesCollection {
    package_key: PackageKey,
    scopes: Phase1PackageScopes,
    package_symbol_inventory: Phase1PackageSymbolInventory,
    package_wit_names: PackageWitNames,
    package_wit_names_fingerprint: Fingerprint,
    interface_uses: InterfaceUses,
    interface_uses_fingerprint: Fingerprint,
    local_flags_adts: Vec<LocalFlagsAdtDef>,
    local_interface_enum_projections: Vec<LocalInterfaceEnumAdtProjection>,
    world_interface_uses: WorldInterfaceUseGraph,
    world_interface_uses_fingerprint: Fingerprint,
    interface_check_diagnostics: Vec<Diagnostic>,
    input_fingerprint: Fingerprint,
    snapshot_id: WorkspaceSnapshotId,
    target_cfg: TargetCfg,
    build_context: Phase1BuildContext,
    module_tree: ModuleTree,
    declared_requirements: Option<Arc<[DeclaredRequirement]>>,
    package_graph_fingerprint: Option<Fingerprint>,
    wit_view_closure_fingerprint: Option<Fingerprint>,
    foreign_scope_provenance: Vec<Phase1ForeignPackageIdentity>,
    session_token: SessionToken,
}

impl Phase1PackageScopesCollection {
    pub fn package_key(&self) -> &PackageKey {
        &self.package_key
    }

    pub const fn input_fingerprint(&self) -> Fingerprint {
        self.input_fingerprint
    }

    pub const fn wit_view_closure_fingerprint(&self) -> Option<Fingerprint> {
        self.wit_view_closure_fingerprint
    }

    pub fn scopes(&self) -> &Phase1PackageScopes {
        &self.scopes
    }

    /// Target-filtered symbols supported by the first package inventory
    /// slice. An available inventory may be incomplete; callers must inspect
    /// its coverage before reconciliation.
    pub fn package_symbol_inventory(&self) -> &Phase1PackageSymbolInventory {
        &self.package_symbol_inventory
    }

    /// The package-level WIT names and diagnostics derived from this exact
    /// target-filtered Phase 1 collection.
    pub fn package_wit_names(&self) -> &PackageWitNames {
        &self.package_wit_names
    }

    /// Stable result fingerprint for `package_wit_names(P)`.
    ///
    /// It uses canonical definition paths and WIT generation order rather
    /// than the session-local order of the returned definition-ID map.
    pub const fn package_wit_names_fingerprint(&self) -> Fingerprint {
        self.package_wit_names_fingerprint
    }

    /// Local interface-use edges and cycle diagnostics derived from this
    /// target-filtered Phase 1 collection.
    pub fn interface_uses(&self) -> &InterfaceUses {
        &self.interface_uses
    }

    /// Stable result fingerprint for `interface_uses(P)`.
    ///
    /// The fingerprint follows interface generation order and canonical
    /// definition paths, never the session-local order of the graph maps.
    pub const fn interface_uses_fingerprint(&self) -> Fingerprint {
        self.interface_uses_fingerprint
    }

    /// Look up a validated local flags ADT owned by this exact source
    /// snapshot. `None` means this partial flags-only projection has no
    /// accepted local flags declaration for `owner`; it does not classify
    /// arbitrary definitions as non-ADTs.
    pub fn local_flags_adt_def(
        &self,
        snapshot: &WorkspaceSnapshot,
        owner: DefId,
    ) -> Result<Option<&LocalFlagsAdtDef>, Phase1CollectionError> {
        if self.snapshot_id != snapshot.id() {
            return Err(Phase1CollectionError::SnapshotIdentityMismatch);
        }
        Ok(self
            .local_flags_adts
            .iter()
            .find(|flags| flags.adt_def().def_id() == owner))
    }

    /// Look up this snapshot's partial local-interface-enum projection.
    ///
    /// Every collected interface enum has an explicit outcome: a unit enum,
    /// a validated flags enum, or an unsupported reason. `None` only means
    /// the owner was not a local interface enum in this projection; it does
    /// not classify arbitrary definitions as non-ADTs.
    pub fn local_interface_enum_adt_projection(
        &self,
        snapshot: &WorkspaceSnapshot,
        owner: DefId,
    ) -> Result<Option<&LocalInterfaceEnumAdtProjection>, Phase1CollectionError> {
        if self.snapshot_id != snapshot.id() {
            return Err(Phase1CollectionError::SnapshotIdentityMismatch);
        }
        Ok(self
            .local_interface_enum_projections
            .iter()
            .find(|projection| projection.owner() == owner))
    }

    /// Ordered local and external interface-use identities consumed by world
    /// elaboration.
    pub fn world_interface_uses(&self) -> &WorldInterfaceUseGraph {
        &self.world_interface_uses
    }

    /// Stable fingerprint for the ordered world interface-use projection.
    pub const fn world_interface_uses_fingerprint(&self) -> Fingerprint {
        self.world_interface_uses_fingerprint
    }

    /// Snapshot-bound interface-item diagnostics derived while collecting
    /// local interface owners.
    pub fn interface_check_diagnostics(&self) -> &[Diagnostic] {
        &self.interface_check_diagnostics
    }

    pub const fn build_context(&self) -> Phase1BuildContext {
        self.build_context
    }

    pub fn into_scopes(self) -> Phase1PackageScopes {
        self.scopes
    }

    /// Retains this exact finalized collection for a later member-scope
    /// closure. The returned value cannot be assembled from detached scopes
    /// and a claimed fingerprint.
    pub fn module_member_scope_package(&self) -> Phase1ModuleMemberScopePackage {
        Phase1ModuleMemberScopePackage {
            collection: self.clone(),
        }
    }
}

/// Owned control-flow, local, module, type-path, and test-only results for
/// one top-level function owner.
///
/// The temporary HIR arena and snapshot-bound source map used to produce these
/// values are discarded before they are returned.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct FunctionOwnerResolution {
    owner: OwnerId,
    resolution: Result<LabelResolution, FunctionOwnerResolutionError>,
    local_resolution: Result<Option<LocalResolution>, FunctionOwnerResolutionError>,
    body_type_check: Result<FunctionBodyTypeCheck, FunctionOwnerResolutionError>,
    primitive_body_type_results: Result<
        Option<sai_ty::typeck::body::PrimitiveBodyTypeResults>,
        FunctionOwnerResolutionError,
    >,
    signature_projection: Result<FunctionSignatureProjection, FunctionOwnerResolutionError>,
    module_resolution: Result<Option<ModuleResolution>, FunctionOwnerResolutionError>,
    type_path_resolution: Result<Option<TypeOwnerPathResolution>, FunctionOwnerResolutionError>,
    local_enum_variant_paths:
        Result<Option<LocalEnumVariantPathResolution>, FunctionOwnerResolutionError>,
    module_path_diagnostics: Result<Option<Vec<Diagnostic>>, FunctionOwnerResolutionError>,
    test_only_path_resolution:
        Result<Option<OwnerTestOnlyPathResolution>, FunctionOwnerResolutionError>,
    test_only_diagnostics: Result<Vec<Diagnostic>, FunctionOwnerResolutionError>,
    world_field_resolution:
        Result<Option<sai_resolve::WorldFieldResolution>, FunctionOwnerResolutionError>,
    /// Diagnostics produced while lowering the owner, kept separate from the
    /// label resolver's diagnostics so the caller can preserve phase order.
    lowering_diagnostics: Vec<Diagnostic>,
}

/// Supported semantic function signature data or the explicit boundary that
/// kept the current HIR signature out of the partial projection.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum FunctionSignatureProjection {
    Supported(sai_ty::ty::FnSig),
    Unsupported(sai_ty::lower_ty::UnsupportedFnSig),
}

/// Resolution outcome for one direct, uppercase `E.V` expression path.
///
/// Every successful or diagnosed result remains tied to the exact HIR enum
/// owner and definition. `NotEnum` is limited to a current-package type owner;
/// dependencies, WIT items, aliases, and unsupported local enum definitions
/// stay deferred for their owning resolver. A qualified local enum type head,
/// such as `module_alias.Child.Variant`, is also eligible when the full prefix
/// resolves to that exact local enum.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum LocalEnumVariantPathOutcome {
    Resolved {
        enum_owner: OwnerId,
        enum_def: DefId,
        variant: DefId,
    },
    UnknownVariant {
        enum_owner: OwnerId,
        enum_def: DefId,
        candidates: Vec<Symbol>,
    },
    NotEnum {
        type_owner: OwnerId,
        type_def: DefId,
    },
    UnsupportedEnum {
        enum_owner: OwnerId,
        enum_def: DefId,
        reason: LocalEnumVariantPathUnsupportedReason,
    },
}

/// Why a local type head is not eligible for the direct enum-variant slice.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum LocalEnumVariantPathUnsupportedReason {
    GenericEnum,
    Enum(LocalEnumAdtUnsupportedReason),
}

/// The supported subset of type-dependent definitions selected by direct
/// local enum-variant paths. This is not the complete typeck result enum.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum LocalTypeDependentDef {
    Variant(DefId),
}

/// One direct enum-variant suffix and the exact HIR/source identity used to
/// resolve it.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct LocalEnumVariantPathEntry {
    field: HirId,
    base_expression: HirId,
    base_path: HirId,
    name: Symbol,
    field_span: sai_hir::Span,
    name_span: sai_hir::Span,
    outcome: LocalEnumVariantPathOutcome,
}

impl LocalEnumVariantPathEntry {
    /// HIR identity of the field expression containing the variant suffix.
    pub const fn field(&self) -> HirId {
        self.field
    }

    /// HIR identity of the expression used as the enum type head.
    ///
    /// For a direct path this is the same node as `base_path`. A qualified
    /// type head retains the final `Field` prefix node here.
    pub const fn base_expression(&self) -> HirId {
        self.base_expression
    }

    /// HIR identity of the root path in the enum type head.
    ///
    /// This remains the root path when qualified type heads contain nested
    /// `Field` expressions.
    pub const fn base_path(&self) -> HirId {
        self.base_path
    }

    /// Source-level spelling of the variant suffix.
    pub const fn name(&self) -> Symbol {
        self.name
    }

    /// Full field-expression span retained from HIR.
    pub const fn field_span(&self) -> sai_hir::Span {
        self.field_span
    }

    /// Variant-name span retained from HIR.
    pub const fn name_span(&self) -> sai_hir::Span {
        self.name_span
    }

    /// Exact local enum, variant, or typed failure outcome.
    pub const fn outcome(&self) -> &LocalEnumVariantPathOutcome {
        &self.outcome
    }
}

/// Value-type projection for one resolved direct local enum-variant path.
///
/// This is keyed by the exact suffix `Field` HIR ID and remains a narrow
/// projection; it is not the expression-type map required by `TypeckResults`.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct LocalEnumVariantPathTypeEntry {
    field: HirId,
    enum_owner: OwnerId,
    enum_def: DefId,
    variant: DefId,
    value_type: sai_ty::adt::LocalEnumVariantValueType,
}

impl LocalEnumVariantPathTypeEntry {
    /// HIR identity of the direct variant field expression.
    pub const fn field(&self) -> HirId {
        self.field
    }

    /// Exact validated local enum owner.
    pub const fn enum_owner(&self) -> OwnerId {
        self.enum_owner
    }

    /// Exact enum definition paired with `enum_owner`.
    pub const fn enum_def(&self) -> DefId {
        self.enum_def
    }

    /// Exact variant definition selected by the path resolver.
    pub const fn variant(&self) -> DefId {
        self.variant
    }

    /// Unit, tuple-constructor, or record-no-value result for this path.
    pub const fn value_type(&self) -> &sai_ty::adt::LocalEnumVariantValueType {
        &self.value_type
    }
}

/// Arity result for one call whose callee is a direct supported local enum
/// variant path. This projection does not type-check argument expressions.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum LocalEnumVariantCallOutcome {
    TupleVariantArityMatches { expected: usize },
    WrongArgumentCount { expected: usize, found: usize },
    UnitVariantCalled { found: usize },
}

/// Arity information for one direct local enum-variant constructor call.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct LocalEnumVariantCallEntry {
    call: HirId,
    callee_field: HirId,
    enum_owner: OwnerId,
    enum_def: DefId,
    variant: DefId,
    arguments: Vec<HirId>,
    outcome: LocalEnumVariantCallOutcome,
}

impl LocalEnumVariantCallEntry {
    /// HIR identity of the complete call expression.
    pub const fn call(&self) -> HirId {
        self.call
    }

    /// HIR identity of the direct enum-variant path used as the callee.
    pub const fn callee_field(&self) -> HirId {
        self.callee_field
    }

    /// Exact validated local enum owner.
    pub const fn enum_owner(&self) -> OwnerId {
        self.enum_owner
    }

    /// Exact enum definition paired with `enum_owner`.
    pub const fn enum_def(&self) -> DefId {
        self.enum_def
    }

    /// Exact variant definition selected by the path resolver.
    pub const fn variant(&self) -> DefId {
        self.variant
    }

    /// HIR identities of the call's arguments in source order.
    pub fn arguments(&self) -> &[HirId] {
        &self.arguments
    }

    /// Arity comparison against the projected tuple-variant signature.
    pub const fn outcome(&self) -> LocalEnumVariantCallOutcome {
        self.outcome
    }
}

/// Owned direct enum-variant paths and diagnostics for one function owner.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct LocalEnumVariantPathResolution {
    owner: OwnerId,
    entries: HashMap<HirId, LocalEnumVariantPathEntry>,
    value_type_entries: HashMap<HirId, LocalEnumVariantPathTypeEntry>,
    type_dependent_defs: HashMap<HirId, LocalTypeDependentDef>,
    calls: HashMap<HirId, LocalEnumVariantCallEntry>,
    diagnostics: Vec<Diagnostic>,
    call_diagnostics: Vec<Diagnostic>,
}

impl LocalEnumVariantPathResolution {
    pub const fn owner(&self) -> OwnerId {
        self.owner
    }

    /// Results keyed by the HIR identity of each direct field expression.
    pub fn entries(&self) -> &HashMap<HirId, LocalEnumVariantPathEntry> {
        &self.entries
    }

    /// Value-type projections keyed by the exact resolved suffix `Field` HIR
    /// ID. Unknown, non-enum, and unsupported paths have no entry; record
    /// variants do have an entry whose value type is `RecordHasNoValueType`.
    pub fn value_type_entries(&self) -> &HashMap<HirId, LocalEnumVariantPathTypeEntry> {
        &self.value_type_entries
    }

    /// Value-type projection for the exact direct variant field expression.
    pub fn value_type_for_field(&self, field: HirId) -> Option<&LocalEnumVariantPathTypeEntry> {
        self.value_type_entries.get(&field)
    }

    /// Successful type-dependent item selections, keyed by exact `Field` HIR ID.
    /// Only supported direct local enum paths are recorded.
    pub fn type_dependent_defs(&self) -> &HashMap<HirId, LocalTypeDependentDef> {
        &self.type_dependent_defs
    }

    /// Selected type-dependent item for this exact direct variant field.
    pub fn type_dependent_def_for_field(&self, field: HirId) -> Option<LocalTypeDependentDef> {
        self.type_dependent_defs.get(&field).copied()
    }

    /// Arity projections keyed by the exact call-expression HIR ID.
    pub fn calls(&self) -> &HashMap<HirId, LocalEnumVariantCallEntry> {
        &self.calls
    }

    /// Arity projection for the exact direct local enum-variant call.
    pub fn call_for_expr(&self, call: HirId) -> Option<&LocalEnumVariantCallEntry> {
        self.calls.get(&call)
    }

    /// Source-ordered unknown-variant and non-enum diagnostics.
    pub fn diagnostics(&self) -> &[Diagnostic] {
        &self.diagnostics
    }

    /// Source-ordered argument diagnostics for local variant calls.
    pub fn call_diagnostics(&self) -> &[Diagnostic] {
        &self.call_diagnostics
    }
}

impl FunctionOwnerResolution {
    pub const fn owner(&self) -> OwnerId {
        self.owner
    }

    pub fn resolution(&self) -> Result<&LabelResolution, &FunctionOwnerResolutionError> {
        self.resolution.as_ref()
    }

    pub fn local_resolution(
        &self,
    ) -> Result<Option<&LocalResolution>, &FunctionOwnerResolutionError> {
        self.local_resolution
            .as_ref()
            .map(|resolution| resolution.as_ref())
    }

    /// Returns the result of the supported direct function-body type checks.
    ///
    /// `Unsupported` keeps the owner behind the caller's feature gate.
    pub fn body_type_check(&self) -> Result<&FunctionBodyTypeCheck, &FunctionOwnerResolutionError> {
        self.body_type_check.as_ref()
    }

    /// Returns the bounded primitive-local expression and binding types
    /// produced for this exact owner. `None` means the existing body checker
    /// did not accept this owner's body shape.
    pub fn primitive_body_type_results(
        &self,
    ) -> Result<
        Option<&sai_ty::typeck::body::PrimitiveBodyTypeResults>,
        &FunctionOwnerResolutionError,
    > {
        self.primitive_body_type_results
            .as_ref()
            .map(Option::as_ref)
    }

    /// Returns module-scope path results for names not resolved as locals or
    /// generic parameters, plus candidates still deferred for later lookup.
    pub fn module_resolution(
        &self,
    ) -> Result<Option<&ModuleResolution>, &FunctionOwnerResolutionError> {
        self.module_resolution
            .as_ref()
            .map(|resolution| resolution.as_ref())
    }

    /// Returns type-path results for the function signature and body.
    /// Qualified local module/interface prefixes are consumed through the
    /// first non-module member; its type-relative suffix remains for later
    /// resolution.
    pub fn type_path_resolution(
        &self,
    ) -> Result<Option<&TypeOwnerPathResolution>, &FunctionOwnerResolutionError> {
        self.type_path_resolution
            .as_ref()
            .map(|resolution| resolution.as_ref())
    }

    /// Direct local enum-variant suffixes resolved while the owner's HIR and
    /// source map were live.
    pub fn local_enum_variant_paths(
        &self,
    ) -> Result<Option<&LocalEnumVariantPathResolution>, &FunctionOwnerResolutionError> {
        self.local_enum_variant_paths
            .as_ref()
            .map(|resolution| resolution.as_ref())
    }

    /// Returns snapshot-bound diagnostics for typed member failures when this
    /// owner was resolved with a validated active-source closure. Package-local
    /// calls leave diagnostic mapping to their caller.
    pub fn module_path_diagnostics(
        &self,
    ) -> Result<Option<&[Diagnostic]>, &FunctionOwnerResolutionError> {
        self.module_path_diagnostics
            .as_ref()
            .map(|diagnostics| diagnostics.as_deref())
    }

    pub fn test_only_path_resolution(
        &self,
    ) -> Result<Option<&OwnerTestOnlyPathResolution>, &FunctionOwnerResolutionError> {
        self.test_only_path_resolution
            .as_ref()
            .map(|resolution| resolution.as_ref())
    }

    pub fn test_only_diagnostics(&self) -> Result<&[Diagnostic], &FunctionOwnerResolutionError> {
        self.test_only_diagnostics.as_ref().map(Vec::as_slice)
    }

    /// World-function fields resolved while the lowered body and source map
    /// were live. `None` means this owner analysis did not receive validated
    /// world-reference inputs.
    pub fn world_field_resolution(
        &self,
    ) -> Result<Option<&sai_resolve::WorldFieldResolution>, &FunctionOwnerResolutionError> {
        self.world_field_resolution
            .as_ref()
            .map(|resolution| resolution.as_ref())
    }

    pub fn lowering_diagnostics(&self) -> &[Diagnostic] {
        &self.lowering_diagnostics
    }
}

/// Non-expression owner paths rejected because their module binding is
/// test-only. This includes types, effects, and path patterns.
///
/// Other paths remain for later generic/module/prelude/effect resolution.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct OwnerTestOnlyPathResolution {
    owner: OwnerId,
    paths: HashMap<HirId, PathRes>,
}

impl OwnerTestOnlyPathResolution {
    pub const fn owner(&self) -> OwnerId {
        self.owner
    }

    pub fn paths(&self) -> &HashMap<HirId, PathRes> {
        &self.paths
    }
}

/// Partial type-head and test-only path results for one direct trait or impl
/// header.
///
/// This pass checks declaration-header references. Qualified target suffixes
/// resolve when an active source or WIT member-scope closure is supplied;
/// associated members remain for their separate analysis pass.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct TraitImplHeaderResolution {
    owner: OwnerId,
    kind: TopLevelOwnerKind,
    type_path_resolution: Result<TypeOwnerPathResolution, OwnerControlFlowResolutionError>,
    interface_impl_target_diagnostics: Result<Vec<Diagnostic>, OwnerControlFlowResolutionError>,
    module_path_diagnostics: Result<Option<Vec<Diagnostic>>, OwnerControlFlowResolutionError>,
    test_only_path_resolution: Result<OwnerTestOnlyPathResolution, OwnerControlFlowResolutionError>,
    test_only_diagnostics: Result<Vec<Diagnostic>, OwnerControlFlowResolutionError>,
    lowering_diagnostics: Vec<Diagnostic>,
}

impl TraitImplHeaderResolution {
    pub const fn owner(&self) -> OwnerId {
        self.owner
    }

    pub const fn kind(&self) -> TopLevelOwnerKind {
        self.kind
    }

    pub fn type_path_resolution(
        &self,
    ) -> Result<&TypeOwnerPathResolution, &OwnerControlFlowResolutionError> {
        self.type_path_resolution.as_ref()
    }

    /// Returns snapshot-bound diagnostics for interface impls whose resolved
    /// target path does not name an interface.
    ///
    /// Unresolved targets remain owned by name resolution and do not produce
    /// this diagnostic.
    pub fn interface_impl_target_diagnostics(
        &self,
    ) -> Result<&[Diagnostic], &OwnerControlFlowResolutionError> {
        self.interface_impl_target_diagnostics
            .as_ref()
            .map(Vec::as_slice)
    }

    /// Returns snapshot-bound type member diagnostics for headers analyzed
    /// with a validated active-source member-scope closure.
    ///
    /// Package-local adapters leave this channel absent so callers can keep
    /// mapping their typed path errors with their own snapshot context.
    pub fn module_path_diagnostics(
        &self,
    ) -> Result<Option<&[Diagnostic]>, &OwnerControlFlowResolutionError> {
        self.module_path_diagnostics
            .as_ref()
            .map(|diagnostics| diagnostics.as_deref())
    }

    pub fn test_only_path_resolution(
        &self,
    ) -> Result<&OwnerTestOnlyPathResolution, &OwnerControlFlowResolutionError> {
        self.test_only_path_resolution.as_ref()
    }

    pub fn test_only_diagnostics(&self) -> Result<&[Diagnostic], &OwnerControlFlowResolutionError> {
        self.test_only_diagnostics.as_ref().map(Vec::as_slice)
    }

    pub fn lowering_diagnostics(&self) -> &[Diagnostic] {
        &self.lowering_diagnostics
    }
}

/// Provenance-tagged trait and impl header test-only diagnostics.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct TraitImplHeaderResolutions {
    snapshot_id: WorkspaceSnapshotId,
    target_cfg: TargetCfg,
    collection_input_fingerprint: Fingerprint,
    member_scope_closure_fingerprint: Option<Fingerprint>,
    wit_view_closure_fingerprint: Option<Fingerprint>,
    owners: Vec<TraitImplHeaderResolution>,
    session_token: SessionToken,
}

impl TraitImplHeaderResolutions {
    pub const fn snapshot_id(&self) -> WorkspaceSnapshotId {
        self.snapshot_id
    }

    pub fn matches_snapshot(&self, snapshot: &WorkspaceSnapshot) -> bool {
        self.snapshot_id == snapshot.id()
    }

    pub fn matches_collection(&self, collection: &Phase1PackageScopesCollection) -> bool {
        self.session_token == collection.session_token
            && self.snapshot_id == collection.snapshot_id
            && self.target_cfg == collection.target_cfg
            && self.collection_input_fingerprint == collection.input_fingerprint
    }

    pub fn matches_member_scopes(
        &self,
        collection: &Phase1PackageScopesCollection,
        member_scopes: &Phase1ActiveSourceMemberScopes,
    ) -> bool {
        self.matches_collection(collection)
            && member_scopes.matches_collection(collection)
            && self.member_scope_closure_fingerprint == Some(member_scopes.closure_fingerprint)
    }

    pub const fn member_scope_closure_fingerprint(&self) -> Option<Fingerprint> {
        self.member_scope_closure_fingerprint
    }

    pub fn matches_wit_view_scopes(
        &self,
        collection: &Phase1PackageScopesCollection,
        wit_view_scopes: &Phase1ActiveWitViewScopes,
    ) -> bool {
        self.matches_collection(collection)
            && wit_view_scopes.matches_collection(collection)
            && self.wit_view_closure_fingerprint == Some(wit_view_scopes.closure_fingerprint)
    }

    pub const fn wit_view_closure_fingerprint(&self) -> Option<Fingerprint> {
        self.wit_view_closure_fingerprint
    }

    pub fn target_cfg(&self) -> &TargetCfg {
        &self.target_cfg
    }

    pub fn owners(&self) -> &[TraitImplHeaderResolution] {
        &self.owners
    }
}

