/// Why the verified payload projection could not become a typed payload-only
/// enum template.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum LocalEnumPayloadTemplateProjectionError {
    UnsupportedProjection(LocalEnumPayloadTypesUnsupportedReason),
    InvalidProjectionProvenance,
    InvalidBinderMetadata,
    InvalidPayloadIdentity(LocalEnumPayloadTypeIdentity),
    UnsupportedPayload {
        identity: LocalEnumPayloadTypeIdentity,
        reason: sai_ty::lower_ty::UnsupportedTy,
    },
    UnsupportedTemplate(LocalEnumPayloadTypeIdentity),
    InvalidTemplateDefinition(LocalEnumPayloadTemplateDefError),
}

/// Opaque validation record attached to driver-created enum projections.
///
/// Instantiation checks that the visible owner, ordered binders, and every
/// source-ordered variant and payload still match the validated owner.
#[doc(hidden)]
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct LocalEnumPayloadTypesValidation {
    owner: OwnerId,
    type_params: Arc<[(DefId, sai_ty::ty::ParamTy)]>,
    variants: Arc<[LocalEnumVariantPayloadProjection]>,
}

/// The bounded payload-type projection for one direct local enum.
///
/// Successful projections retain variants and their payloads in source order.
/// Each payload has an independent lowering result, so an unsupported type
/// does not hide supported siblings.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum LocalEnumPayloadTypesProjection {
    Supported {
        owner: OwnerId,
        type_params: Arc<[(DefId, sai_ty::ty::ParamTy)]>,
        variants: Arc<[LocalEnumVariantPayloadProjection]>,
        provenance: LocalEnumPayloadTypesValidation,
    },
    Unsupported {
        owner: OwnerId,
        reason: LocalEnumPayloadTypesUnsupportedReason,
    },
}

impl LocalEnumPayloadTypesProjection {
    /// Exact enum owner whose payloads were projected.
    pub const fn owner(&self) -> OwnerId {
        match self {
            Self::Supported { owner, .. } | Self::Unsupported { owner, .. } => *owner,
        }
    }

    /// Source-ordered variant and payload results when the enum passed
    /// validation.
    pub fn variants(&self) -> Option<&[LocalEnumVariantPayloadProjection]> {
        match self {
            Self::Supported { variants, .. } => Some(variants),
            Self::Unsupported { .. } => None,
        }
    }

    /// Exact source-ordered type binders for the payload templates.
    pub fn type_params(&self) -> Option<&[(DefId, sai_ty::ty::ParamTy)]> {
        match self {
            Self::Supported { type_params, .. } => Some(type_params),
            Self::Unsupported { .. } => None,
        }
    }

    /// Owner-level reason when this enum cannot be projected.
    pub const fn unsupported_reason(&self) -> Option<LocalEnumPayloadTypesUnsupportedReason> {
        match self {
            Self::Supported { .. } => None,
            Self::Unsupported { reason, .. } => Some(*reason),
        }
    }

    /// Convert a fully supported, provenance-verified payload projection
    /// into the payload-only semantic ADT template model.
    ///
    /// This does not build a full `AdtDef`: discriminants and `@repr` are not
    /// part of the IR-913 payload projection and remain the responsibility of
    /// a later full-ADT adapter.
    pub fn to_payload_template_def(
        &self,
    ) -> Result<LocalEnumPayloadTemplateDef, LocalEnumPayloadTemplateProjectionError> {
        let (owner, type_params, variants, provenance) = match self {
            Self::Supported {
                owner,
                type_params,
                variants,
                provenance,
            } => (owner, type_params, variants, provenance),
            Self::Unsupported { reason, .. } => {
                return Err(
                    LocalEnumPayloadTemplateProjectionError::UnsupportedProjection(*reason),
                );
            }
        };
        if provenance.owner != *owner
            || provenance.type_params.as_ref() != type_params.as_ref()
            || provenance.variants.as_ref() != variants.as_ref()
        {
            return Err(LocalEnumPayloadTemplateProjectionError::InvalidProjectionProvenance);
        }
        validate_local_projection_type_params(type_params)
            .map_err(|()| LocalEnumPayloadTemplateProjectionError::InvalidBinderMetadata)?;

        let mut template_variants = Vec::with_capacity(variants.len());
        for variant in variants.iter() {
            let payload = match variant.payload() {
                LocalEnumVariantPayload::Unit => LocalEnumPayloadTemplateShape::Unit,
                LocalEnumVariantPayload::Tuple(payloads) => {
                    let mut templates = Vec::with_capacity(payloads.len());
                    for (index, payload) in payloads.iter().enumerate() {
                        let index = u32::try_from(index).map_err(|_| {
                            LocalEnumPayloadTemplateProjectionError::InvalidPayloadIdentity(
                                payload.identity(),
                            )
                        })?;
                        let expected_identity = LocalEnumPayloadTypeIdentity::Tuple {
                            variant: variant.def_id(),
                            index,
                        };
                        if payload.identity() != expected_identity || payload.visibility().is_some()
                        {
                            return Err(
                                LocalEnumPayloadTemplateProjectionError::InvalidPayloadIdentity(
                                    payload.identity(),
                                ),
                            );
                        }
                        let ty = payload.ty().map_err(|reason| {
                            LocalEnumPayloadTemplateProjectionError::UnsupportedPayload {
                                identity: payload.identity(),
                                reason,
                            }
                        })?;
                        if !type_params.is_empty()
                            && !local_type_template_matches_binders(ty, type_params)
                        {
                            return Err(
                                LocalEnumPayloadTemplateProjectionError::UnsupportedTemplate(
                                    payload.identity(),
                                ),
                            );
                        }
                        templates.push(LocalEnumTuplePayloadTemplate::new(
                            variant.def_id(),
                            index,
                            ty.clone(),
                        ));
                    }
                    LocalEnumPayloadTemplateShape::Tuple(templates.into())
                }
                LocalEnumVariantPayload::Record(fields) => {
                    let mut templates = Vec::with_capacity(fields.len());
                    for field in fields.iter() {
                        let LocalEnumPayloadTypeIdentity::Record {
                            variant: identity_variant,
                            field: field_id,
                            name,
                        } = field.identity()
                        else {
                            return Err(
                                LocalEnumPayloadTemplateProjectionError::InvalidPayloadIdentity(
                                    field.identity(),
                                ),
                            );
                        };
                        if identity_variant != variant.def_id() {
                            return Err(
                                LocalEnumPayloadTemplateProjectionError::InvalidPayloadIdentity(
                                    field.identity(),
                                ),
                            );
                        }
                        let visibility = field.visibility().ok_or(
                            LocalEnumPayloadTemplateProjectionError::InvalidPayloadIdentity(
                                field.identity(),
                            ),
                        )?;
                        let ty = field.ty().map_err(|reason| {
                            LocalEnumPayloadTemplateProjectionError::UnsupportedPayload {
                                identity: field.identity(),
                                reason,
                            }
                        })?;
                        if !type_params.is_empty()
                            && !local_type_template_matches_binders(ty, type_params)
                        {
                            return Err(
                                LocalEnumPayloadTemplateProjectionError::UnsupportedTemplate(
                                    field.identity(),
                                ),
                            );
                        }
                        templates.push(LocalEnumRecordPayloadTemplate::new(
                            variant.def_id(),
                            field_id,
                            name,
                            visibility,
                            ty.clone(),
                        ));
                    }
                    LocalEnumPayloadTemplateShape::Record(templates.into())
                }
            };
            template_variants.push(LocalEnumPayloadVariantTemplateDef::new(
                variant.def_id(),
                variant.name(),
                payload,
            ));
        }

        LocalEnumPayloadTemplateDef::try_new(
            owner.def_id.to_def_id(),
            Arc::clone(type_params),
            template_variants,
        )
        .map_err(LocalEnumPayloadTemplateProjectionError::InvalidTemplateDefinition)
    }

    /// Instantiate one generic payload template from an exact local-enum
    /// application.
    ///
    /// The enum type must have the projected enum's exact `DefId` and one
    /// type argument per validated binder. The tuple/record identity must
    /// exactly match one source payload in this projection. Substitution is
    /// performed once, so caller parameters in replacement arguments remain
    /// in their caller's binder.
    pub fn instantiate_payload_type(
        &self,
        interner: &sai_ty::ty::TyInterner,
        enum_ty: &sai_ty::ty::Ty,
        identity: LocalEnumPayloadTypeIdentity,
    ) -> Result<sai_ty::ty::Ty, LocalEnumPayloadTypeInstantiationError> {
        let (owner, type_params, variants, provenance) = match self {
            Self::Supported {
                owner,
                type_params,
                variants,
                provenance,
            } => (owner, type_params, variants, provenance),
            Self::Unsupported { reason, .. } => {
                return Err(LocalEnumPayloadTypeInstantiationError::UnsupportedProjection(*reason));
            }
        };
        if provenance.owner != *owner
            || provenance.type_params.as_ref() != type_params.as_ref()
            || provenance.variants.as_ref() != variants.as_ref()
        {
            return Err(LocalEnumPayloadTypeInstantiationError::InvalidProjectionProvenance);
        }
        if type_params.is_empty() {
            return Err(LocalEnumPayloadTypeInstantiationError::NotGenericEnum);
        }
        validate_local_projection_type_params(type_params)
            .map_err(|()| LocalEnumPayloadTypeInstantiationError::InvalidBinderMetadata)?;

        let sai_ty::ty::TyKind::Adt(enum_def, type_args) = enum_ty.kind() else {
            return Err(LocalEnumPayloadTypeInstantiationError::NotAdt);
        };
        let expected_enum_def = owner.def_id.to_def_id();
        if *enum_def != expected_enum_def {
            return Err(LocalEnumPayloadTypeInstantiationError::WrongEnum {
                expected: expected_enum_def,
                found: *enum_def,
            });
        }
        if type_args.len() != type_params.len() {
            return Err(
                LocalEnumPayloadTypeInstantiationError::WrongNumberOfTypeArguments {
                    expected: type_params.len(),
                    found: type_args.len(),
                },
            );
        }

        let payload = variants
            .iter()
            .flat_map(|variant| match &variant.payload {
                LocalEnumVariantPayload::Unit => &[][..],
                LocalEnumVariantPayload::Tuple(payloads)
                | LocalEnumVariantPayload::Record(payloads) => payloads.as_ref(),
            })
            .find(|payload| payload.identity == identity)
            .ok_or(LocalEnumPayloadTypeInstantiationError::PayloadNotFound(
                identity,
            ))?;
        let template = payload.ty.as_ref().map_err(|reason| {
            LocalEnumPayloadTypeInstantiationError::UnsupportedPayload(*reason)
        })?;
        if !local_type_template_matches_binders(template, type_params) {
            return Err(LocalEnumPayloadTypeInstantiationError::UnsupportedTemplate);
        }
        let arguments = type_args
            .iter()
            .cloned()
            .map(sai_ty::ty::GenericArg::Type)
            .collect::<Vec<_>>();
        interner
            .substitute(template, &arguments)
            .map_err(LocalEnumPayloadTypeInstantiationError::Substitution)
    }
}

/// The enum-level typed definition produced by joining one verified payload
/// template with discriminants and validated representation from its exact
/// current HIR owner.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum LocalEnumAdtProjection {
    Supported {
        owner: OwnerId,
        definition: LocalEnumAdtDef,
        issues: Arc<[LocalEnumDiscriminantIssue]>,
    },
    Unsupported {
        owner: OwnerId,
        reason: LocalEnumAdtUnsupportedReason,
        build_error: Option<LocalEnumAdtDefBuildError>,
    },
}

impl LocalEnumAdtProjection {
    /// Exact enum owner represented by this projection.
    pub const fn owner(&self) -> OwnerId {
        match self {
            Self::Supported { owner, .. } | Self::Unsupported { owner, .. } => *owner,
        }
    }

    /// Typed enum definition when all values needed to compute it are
    /// representable.
    pub fn definition(&self) -> Option<&LocalEnumAdtDef> {
        match self {
            Self::Supported { definition, .. } => Some(definition),
            Self::Unsupported { .. } => None,
        }
    }

    /// Owner-level reason when the enum definition could not be built.
    pub const fn unsupported_reason(&self) -> Option<LocalEnumAdtUnsupportedReason> {
        match self {
            Self::Supported { .. } => None,
            Self::Unsupported { reason, .. } => Some(*reason),
        }
    }

    /// Discriminant values, issues, and failures retained when semantic
    /// definition construction had to fail closed.
    pub fn build_error(&self) -> Option<&LocalEnumAdtDefBuildError> {
        match self {
            Self::Supported { .. } => None,
            Self::Unsupported { build_error, .. } => build_error.as_ref(),
        }
    }

    /// Any discriminants that could be computed before construction failed.
    pub fn partial_discriminants(&self) -> &[sai_ty::adt::LocalEnumVariantDiscriminant] {
        self.build_error()
            .map_or(&[], LocalEnumAdtDefBuildError::discriminants)
    }

    /// Range and duplicate issues found for all computed values, including
    /// values after an unrepresentable source discriminant.
    pub fn discriminant_issues(&self) -> &[LocalEnumDiscriminantIssue] {
        match self {
            Self::Supported { issues, .. } => issues,
            Self::Unsupported { build_error, .. } => build_error
                .as_ref()
                .map_or(&[], LocalEnumAdtDefBuildError::issues),
        }
    }
}

/// Why a direct local enum could not be composed into a typed enum definition.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum LocalEnumAdtUnsupportedReason {
    OwnerAnalysisFailed,
    InvalidOwnerIdentity,
    MissingValidatedAttrs,
    RecoveredSyntax,
    PayloadTemplate(LocalEnumPayloadTemplateProjectionError),
    Definition(LocalEnumAdtDefError),
}

/// The type of one exact variant value exposed through a validated enum owner.
///
/// This projection preserves the enum owner and requested variant identity.
/// An unsupported enum-level definition remains unsupported here; callers
/// cannot bypass an unrepresentable discriminant by reading its payload
/// template directly.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum LocalEnumVariantValueTypeProjection {
    Supported {
        owner: OwnerId,
        variant: DefId,
        value_type: sai_ty::adt::LocalEnumVariantValueType,
    },
    UnsupportedEnum {
        owner: OwnerId,
        variant: DefId,
        reason: LocalEnumAdtUnsupportedReason,
    },
    InvalidVariant {
        owner: OwnerId,
        variant: DefId,
        reason: sai_ty::adt::LocalEnumVariantTypeError,
    },
}

impl LocalEnumVariantValueTypeProjection {
    /// Exact enum owner used to validate this request.
    pub const fn owner(&self) -> OwnerId {
        match self {
            Self::Supported { owner, .. }
            | Self::UnsupportedEnum { owner, .. }
            | Self::InvalidVariant { owner, .. } => *owner,
        }
    }

    /// Exact requested variant identity.
    pub const fn variant(&self) -> DefId {
        match self {
            Self::Supported { variant, .. }
            | Self::UnsupportedEnum { variant, .. }
            | Self::InvalidVariant { variant, .. } => *variant,
        }
    }

    /// Derived unit, tuple-constructor, or record-no-value result.
    pub fn value_type(&self) -> Option<&sai_ty::adt::LocalEnumVariantValueType> {
        match self {
            Self::Supported { value_type, .. } => Some(value_type),
            Self::UnsupportedEnum { .. } | Self::InvalidVariant { .. } => None,
        }
    }
}

fn validate_local_projection_type_params(
    type_params: &[(DefId, sai_ty::ty::ParamTy)],
) -> Result<(), ()> {
    let mut def_ids = HashSet::with_capacity(type_params.len());
    let mut names = HashSet::with_capacity(type_params.len());
    for (index, (def_id, parameter)) in type_params.iter().enumerate() {
        if u32::try_from(index).ok() != Some(parameter.index)
            || parameter.name.is_error()
            || !def_ids.insert(*def_id)
            || !names.insert(parameter.name)
        {
            return Err(());
        }
    }
    Ok(())
}

fn local_type_template_matches_binders(
    template: &sai_ty::ty::Ty,
    type_params: &[(DefId, sai_ty::ty::ParamTy)],
) -> bool {
    let mut pending = vec![template];
    while let Some(ty) = pending.pop() {
        match ty.kind() {
            sai_ty::ty::TyKind::Param(parameter) => {
                let Some(index) = usize::try_from(parameter.index).ok() else {
                    return false;
                };
                if type_params
                    .get(index)
                    .is_none_or(|(_, expected)| expected != parameter)
                {
                    return false;
                }
            }
            sai_ty::ty::TyKind::Ref(..) => return false,
            sai_ty::ty::TyKind::Tuple(elements) => pending.extend(elements.iter()),
            sai_ty::ty::TyKind::Array(element, length) => {
                if matches!(length, sai_ty::ty::Const::Param(_)) {
                    return false;
                }
                pending.push(element);
            }
            sai_ty::ty::TyKind::FnPtr(signature) => {
                pending.extend(signature.inputs());
                pending.push(signature.output());
            }
            sai_ty::ty::TyKind::FnDef(_, arguments) => pending.extend(arguments.iter()),
            sai_ty::ty::TyKind::Adt(_, arguments) => pending.extend(arguments.iter()),
            sai_ty::ty::TyKind::Int(_)
            | sai_ty::ty::TyKind::Uint(_)
            | sai_ty::ty::TyKind::Float(_)
            | sai_ty::ty::TyKind::Bool
            | sai_ty::ty::TyKind::Byte
            | sai_ty::ty::TyKind::Char
            | sai_ty::ty::TyKind::Never => {}
        }
    }
    true
}

/// Compatibility name for the original type-owner test-only adapter result.
pub type TypeOwnerTestOnlyResolution = TypeOwnerResolution;

/// Provenance-tagged partial type-path results and test-only diagnostics.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct TypeOwnerResolutions {
    snapshot_id: WorkspaceSnapshotId,
    target_cfg: TargetCfg,
    collection_input_fingerprint: Fingerprint,
    member_scope_closure_fingerprint: Option<Fingerprint>,
    wit_view_closure_fingerprint: Option<Fingerprint>,
    owners: Vec<TypeOwnerResolution>,
    session_token: SessionToken,
}

impl TypeOwnerResolutions {
    pub const fn snapshot_id(&self) -> WorkspaceSnapshotId {
        self.snapshot_id
    }

    pub fn matches_snapshot(&self, snapshot: &WorkspaceSnapshot) -> bool {
        self.snapshot_id == snapshot.id()
    }

    pub fn matches_collection(&self, collection: &Phase1PackageScopesCollection) -> bool {
        self.session_token == collection.session_token
            && self.snapshot_id == collection.snapshot_id
            && self.target_cfg == collection.target_cfg
            && self.collection_input_fingerprint == collection.input_fingerprint
    }

    /// Checks both the requesting package collection and the validated
    /// transitive member-scope closure used during resolution.
    pub fn matches_member_scopes(
        &self,
        collection: &Phase1PackageScopesCollection,
        member_scopes: &Phase1ActiveSourceMemberScopes,
    ) -> bool {
        self.matches_collection(collection)
            && member_scopes.matches_collection(collection)
            && self.member_scope_closure_fingerprint == Some(member_scopes.closure_fingerprint)
    }

    pub const fn member_scope_closure_fingerprint(&self) -> Option<Fingerprint> {
        self.member_scope_closure_fingerprint
    }

    pub fn matches_wit_view_scopes(
        &self,
        collection: &Phase1PackageScopesCollection,
        wit_view_scopes: &Phase1ActiveWitViewScopes,
    ) -> bool {
        self.matches_collection(collection)
            && wit_view_scopes.matches_collection(collection)
            && self.wit_view_closure_fingerprint == Some(wit_view_scopes.closure_fingerprint)
    }

    pub const fn wit_view_closure_fingerprint(&self) -> Option<Fingerprint> {
        self.wit_view_closure_fingerprint
    }

    pub fn target_cfg(&self) -> &TargetCfg {
        &self.target_cfg
    }

    pub fn owners(&self) -> &[TypeOwnerResolution] {
        &self.owners
    }

    /// Returns one direct local record's field-type projection after checking
    /// collection and active-scope provenance.
    pub fn local_record_field_types(
        &self,
        collection: &Phase1PackageScopesCollection,
        owner: OwnerId,
    ) -> Result<Option<&LocalRecordFieldTypesProjection>, OwnerControlFlowResolutionError> {
        self.local_record_field_types_with_scopes(collection, None, None, owner)
    }

    /// Returns a field-type projection after checking every source-member and
    /// WIT-view closure used to resolve its field paths.
    pub fn local_record_field_types_with_scopes(
        &self,
        collection: &Phase1PackageScopesCollection,
        member_scopes: Option<&Phase1ActiveSourceMemberScopes>,
        wit_view_scopes: Option<&Phase1ActiveWitViewScopes>,
        owner: OwnerId,
    ) -> Result<Option<&LocalRecordFieldTypesProjection>, OwnerControlFlowResolutionError> {
        let matches_member_scopes = match member_scopes {
            Some(scopes) => self.matches_member_scopes(collection, scopes),
            None => {
                self.matches_collection(collection)
                    && self.member_scope_closure_fingerprint.is_none()
            }
        };
        let matches_wit_view_scopes = match wit_view_scopes {
            Some(scopes) => self.matches_wit_view_scopes(collection, scopes),
            None => {
                self.matches_collection(collection) && self.wit_view_closure_fingerprint.is_none()
            }
        };
        if !self.matches_collection(collection)
            || !matches_member_scopes
            || !matches_wit_view_scopes
        {
            return Err(OwnerControlFlowResolutionError::SnapshotMismatch);
        }
        Ok(self
            .owners
            .iter()
            .find(|result| result.owner == owner)
            .and_then(|result| result.local_record_field_types.as_ref()))
    }

    /// Returns one direct local enum's payload-type projection after checking
    /// collection and active-scope provenance.
    pub fn local_enum_payload_types(
        &self,
        collection: &Phase1PackageScopesCollection,
        owner: OwnerId,
    ) -> Result<Option<&LocalEnumPayloadTypesProjection>, OwnerControlFlowResolutionError> {
        self.local_enum_payload_types_with_scopes(collection, None, None, owner)
    }

    /// Returns an enum-payload projection after checking every source-member
    /// and WIT-view closure used to resolve its payload paths.
    pub fn local_enum_payload_types_with_scopes(
        &self,
        collection: &Phase1PackageScopesCollection,
        member_scopes: Option<&Phase1ActiveSourceMemberScopes>,
        wit_view_scopes: Option<&Phase1ActiveWitViewScopes>,
        owner: OwnerId,
    ) -> Result<Option<&LocalEnumPayloadTypesProjection>, OwnerControlFlowResolutionError> {
        let matches_member_scopes = match member_scopes {
            Some(scopes) => self.matches_member_scopes(collection, scopes),
            None => {
                self.matches_collection(collection)
                    && self.member_scope_closure_fingerprint.is_none()
            }
        };
        let matches_wit_view_scopes = match wit_view_scopes {
            Some(scopes) => self.matches_wit_view_scopes(collection, scopes),
            None => {
                self.matches_collection(collection) && self.wit_view_closure_fingerprint.is_none()
            }
        };
        if !self.matches_collection(collection)
            || !matches_member_scopes
            || !matches_wit_view_scopes
        {
            return Err(OwnerControlFlowResolutionError::SnapshotMismatch);
        }
        Ok(self
            .owners
            .iter()
            .find(|result| result.owner == owner)
            .and_then(|result| result.local_enum_payload_types.as_ref()))
    }

    /// Returns one direct local enum's typed metadata after checking
    /// collection and active-scope provenance.
    pub fn local_enum_adt(
        &self,
        collection: &Phase1PackageScopesCollection,
        owner: OwnerId,
    ) -> Result<Option<&LocalEnumAdtProjection>, OwnerControlFlowResolutionError> {
        self.local_enum_adt_with_scopes(collection, None, None, owner)
    }

    /// Returns enum-level typed metadata after checking every source-member
    /// and WIT-view closure used to resolve its payload paths.
    pub fn local_enum_adt_with_scopes(
        &self,
        collection: &Phase1PackageScopesCollection,
        member_scopes: Option<&Phase1ActiveSourceMemberScopes>,
        wit_view_scopes: Option<&Phase1ActiveWitViewScopes>,
        owner: OwnerId,
    ) -> Result<Option<&LocalEnumAdtProjection>, OwnerControlFlowResolutionError> {
        let matches_member_scopes = match member_scopes {
            Some(scopes) => self.matches_member_scopes(collection, scopes),
            None => {
                self.matches_collection(collection)
                    && self.member_scope_closure_fingerprint.is_none()
            }
        };
        let matches_wit_view_scopes = match wit_view_scopes {
            Some(scopes) => self.matches_wit_view_scopes(collection, scopes),
            None => {
                self.matches_collection(collection) && self.wit_view_closure_fingerprint.is_none()
            }
        };
        if !self.matches_collection(collection)
            || !matches_member_scopes
            || !matches_wit_view_scopes
        {
            return Err(OwnerControlFlowResolutionError::SnapshotMismatch);
        }
        Ok(self
            .owners
            .iter()
            .find(|result| result.owner == owner)
            .and_then(|result| result.local_enum_adt.as_ref()))
    }

    /// Returns one exact local enum variant's value type through the
    /// collection- and scope-validated enum definition.
    ///
    /// Unit variants yield the enum identity application, tuple variants
    /// yield their exact `FnDef` and signature template, and record variants
    /// explicitly have no value-constructor type. An absent owner returns
    /// `None`; an unsupported enum definition or invalid variant identity is
    /// preserved as a projection result.
    pub fn local_enum_variant_value_type(
        &self,
        interner: &sai_ty::ty::TyInterner,
        collection: &Phase1PackageScopesCollection,
        owner: OwnerId,
        variant: DefId,
    ) -> Result<Option<LocalEnumVariantValueTypeProjection>, OwnerControlFlowResolutionError> {
        self.local_enum_variant_value_type_with_scopes(
            interner, collection, None, None, owner, variant,
        )
    }

    /// Returns a variant value type after validating the exact current
    /// collection and every source-member/WIT-view closure used by enum
    /// payload resolution.
    pub fn local_enum_variant_value_type_with_scopes(
        &self,
        interner: &sai_ty::ty::TyInterner,
        collection: &Phase1PackageScopesCollection,
        member_scopes: Option<&Phase1ActiveSourceMemberScopes>,
        wit_view_scopes: Option<&Phase1ActiveWitViewScopes>,
        owner: OwnerId,
        variant: DefId,
    ) -> Result<Option<LocalEnumVariantValueTypeProjection>, OwnerControlFlowResolutionError> {
        let Some(enum_projection) =
            self.local_enum_adt_with_scopes(collection, member_scopes, wit_view_scopes, owner)?
        else {
            return Ok(None);
        };
        let value_type_projection = match enum_projection {
            LocalEnumAdtProjection::Supported {
                owner: projected_owner,
                definition,
                ..
            } => match definition.value_type_of_variant(interner, variant) {
                Ok(value_type) => LocalEnumVariantValueTypeProjection::Supported {
                    owner: *projected_owner,
                    variant,
                    value_type,
                },
                Err(reason) => LocalEnumVariantValueTypeProjection::InvalidVariant {
                    owner: *projected_owner,
                    variant,
                    reason,
                },
            },
            LocalEnumAdtProjection::Unsupported {
                owner: projected_owner,
                reason,
                ..
            } => LocalEnumVariantValueTypeProjection::UnsupportedEnum {
                owner: *projected_owner,
                variant,
                reason: *reason,
            },
        };
        Ok(Some(value_type_projection))
    }
}

