/// Partial type-head, bounded body, and test-only path results for one
/// associated declaration owner.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct TraitImplMemberTestOnlyResolution {
    parent_owner: OwnerId,
    owner: OwnerId,
    kind: TraitImplMemberKind,
    body_type_check: Result<FunctionBodyTypeCheck, OwnerControlFlowResolutionError>,
    primitive_body_type_results: Result<
        Option<sai_ty::typeck::body::PrimitiveBodyTypeResults>,
        OwnerControlFlowResolutionError,
    >,
    type_path_resolution: Result<TypeOwnerPathResolution, OwnerControlFlowResolutionError>,
    module_path_diagnostics: Result<Option<Vec<Diagnostic>>, OwnerControlFlowResolutionError>,
    test_only_path_resolution: Result<OwnerTestOnlyPathResolution, OwnerControlFlowResolutionError>,
    test_only_diagnostics: Result<Vec<Diagnostic>, OwnerControlFlowResolutionError>,
    local_resolution: Result<Option<LocalResolution>, OwnerControlFlowResolutionError>,
    module_resolution: Result<Option<ModuleResolution>, OwnerControlFlowResolutionError>,
    lowering_diagnostics: Vec<Diagnostic>,
}

impl TraitImplMemberTestOnlyResolution {
    pub const fn parent_owner(&self) -> OwnerId {
        self.parent_owner
    }

    pub const fn owner(&self) -> OwnerId {
        self.owner
    }

    pub const fn kind(&self) -> TraitImplMemberKind {
        self.kind
    }

    /// Returns the bounded associated-method body check, independently of
    /// test-only path diagnostics.
    ///
    /// Only public inherent methods in a non-generic safe impl with a first
    /// shared `Self` receiver used only as the base of a supported direct
    /// primitive field initializer or direct block-tail projection, named
    /// immutable primitive parameters, an explicit primitive return type, and
    /// the supported primitive-local body shape are checked; every other
    /// associated member is unsupported.
    pub fn body_type_check(
        &self,
    ) -> Result<&FunctionBodyTypeCheck, &OwnerControlFlowResolutionError> {
        self.body_type_check.as_ref()
    }

    /// Returns bounded primitive-local body facts for this exact associated
    /// method owner. `None` means the body checker did not accept the body.
    pub fn primitive_body_type_results(
        &self,
    ) -> Result<
        Option<&sai_ty::typeck::body::PrimitiveBodyTypeResults>,
        &OwnerControlFlowResolutionError,
    > {
        self.primitive_body_type_results
            .as_ref()
            .map(Option::as_ref)
    }

    pub fn type_path_resolution(
        &self,
    ) -> Result<&TypeOwnerPathResolution, &OwnerControlFlowResolutionError> {
        self.type_path_resolution.as_ref()
    }

    /// Returns snapshot-bound type member diagnostics for this associated
    /// declaration when analyzed with a validated active-source closure.
    ///
    /// Package-local adapters leave this channel absent so callers can keep
    /// mapping their typed path results with their own snapshot context.
    pub fn module_path_diagnostics(
        &self,
    ) -> Result<Option<&[Diagnostic]>, &OwnerControlFlowResolutionError> {
        self.module_path_diagnostics
            .as_ref()
            .map(|diagnostics| diagnostics.as_deref())
    }

    pub fn test_only_path_resolution(
        &self,
    ) -> Result<&OwnerTestOnlyPathResolution, &OwnerControlFlowResolutionError> {
        self.test_only_path_resolution.as_ref()
    }

    pub fn test_only_diagnostics(&self) -> Result<&[Diagnostic], &OwnerControlFlowResolutionError> {
        self.test_only_diagnostics.as_ref().map(Vec::as_slice)
    }

    /// Lexical resolution for a method body and its contracts.
    ///
    /// Associated types and methods without a lowered body return `Ok(None)`.
    pub fn local_resolution(
        &self,
    ) -> Result<Option<&LocalResolution>, &OwnerControlFlowResolutionError> {
        self.local_resolution
            .as_ref()
            .map(|resolution| resolution.as_ref())
    }

    /// Module fallback for deferred method-body and contract paths.
    ///
    /// Associated types and methods without a lowered body return `Ok(None)`.
    pub fn module_resolution(
        &self,
    ) -> Result<Option<&ModuleResolution>, &OwnerControlFlowResolutionError> {
        self.module_resolution
            .as_ref()
            .map(|resolution| resolution.as_ref())
    }

    pub fn lowering_diagnostics(&self) -> &[Diagnostic] {
        &self.lowering_diagnostics
    }
}

