/// Result of checking one supported direct function-body form.
///
/// This is an initial Stage 0 body-checking slice, not a general expression
/// type checker. It also accepts an explicit unit return with an empty body or
/// a direct unit tail. Unsupported owner and expression shapes remain gated.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum FunctionBodyTypeCheck {
    Unsupported,
    Supported { diagnostics: Vec<Diagnostic> },
}

impl FunctionBodyTypeCheck {
    pub const fn is_supported(&self) -> bool {
        matches!(self, Self::Supported { .. })
    }

    pub fn diagnostics(&self) -> &[Diagnostic] {
        match self {
            Self::Unsupported => &[],
            Self::Supported { diagnostics } => diagnostics,
        }
    }
}

/// Result of checking one public primitive, canonical `Str`, unit, or flat tuple constant.
///
/// This deliberately covers only direct literals of supported primitive
/// types, canonical `Str`, the unit literal `()`, and flat tuple literals
/// whose fields are supported direct scalar or unit literals. It does not
/// imply that other constant expressions are evaluated.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum ConstLiteralCheck {
    /// The declaration or HIR shape is outside this checking slice.
    Unsupported,
    /// The primitive type and literal form are in scope for this checker.
    ///
    /// A nonempty diagnostic list represents a supported but invalid
    /// initializer. An empty list means the initializer passed this check.
    Supported {
        primitive: sai_resolve::prelude::PrimTy,
        diagnostics: Vec<Diagnostic>,
    },
    /// A direct string literal checked against the canonical `Str` prelude
    /// item whose early name resolution is intentionally deferred.
    SupportedStr { diagnostics: Vec<Diagnostic> },
    /// The empty tuple type and direct unit literal, checked without general
    /// type resolution.
    SupportedUnit { diagnostics: Vec<Diagnostic> },
    /// A flat tuple whose fields each have a supported direct scalar or unit literal.
    SupportedTuple { diagnostics: Vec<Diagnostic> },
}

impl ConstLiteralCheck {
    pub const fn is_supported(&self) -> bool {
        matches!(
            self,
            Self::Supported { .. }
                | Self::SupportedStr { .. }
                | Self::SupportedUnit { .. }
                | Self::SupportedTuple { .. }
        )
    }

    pub fn is_valid(&self) -> bool {
        match self {
            Self::Supported { diagnostics, .. }
            | Self::SupportedStr { diagnostics }
            | Self::SupportedUnit { diagnostics }
            | Self::SupportedTuple { diagnostics } => diagnostics.is_empty(),
            Self::Unsupported => false,
        }
    }

    pub fn diagnostics(&self) -> &[Diagnostic] {
        match self {
            Self::Unsupported => &[],
            Self::Supported { diagnostics, .. }
            | Self::SupportedStr { diagnostics }
            | Self::SupportedUnit { diagnostics }
            | Self::SupportedTuple { diagnostics } => diagnostics,
        }
    }
}

fn check_const_literal_owner(
    owner: &HirOwner<'_>,
    type_paths: Option<&TypeOwnerPathResolution>,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
    target_cfg: &TargetCfg,
) -> Result<ConstLiteralCheck, OwnerControlFlowResolutionError> {
    if !owner.raw_attrs.is_empty() {
        return Ok(ConstLiteralCheck::Unsupported);
    }
    let OwnerNode::Item(item) = owner.node else {
        return Ok(ConstLiteralCheck::Unsupported);
    };
    if item.vis != Visibility::Pub {
        return Ok(ConstLiteralCheck::Unsupported);
    }
    let ItemKind::Const { ty } = item.kind else {
        return Ok(ConstLiteralCheck::Unsupported);
    };
    let Ok(name) = symbols.resolve(item.name.sym) else {
        return Ok(ConstLiteralCheck::Unsupported);
    };
    let Some(written_name) = inputs
        .source
        .text()
        .get(item.name.span.range.start().to_usize()..item.name.span.range.end().to_usize())
    else {
        return Ok(ConstLiteralCheck::Unsupported);
    };
    if !is_supported_const_name_convention(&name, written_name) {
        return Ok(ConstLiteralCheck::Unsupported);
    }
    let Some(body) = owner.body else {
        return Ok(ConstLiteralCheck::Unsupported);
    };
    if let TyKind::Tuple(elements) = ty.kind {
        if elements.is_empty() {
            let Some(diagnostics) = check_const_literal_leaf(
                owner,
                *ty,
                &body.value,
                type_paths,
                symbols,
                inputs,
                snapshot,
                target_cfg,
            )?
            else {
                return Ok(ConstLiteralCheck::Unsupported);
            };
            return Ok(ConstLiteralCheck::SupportedUnit { diagnostics });
        }

        let Some(diagnostics) = check_const_tuple_literal(
            owner,
            elements,
            &body.value,
            type_paths,
            symbols,
            inputs,
            snapshot,
            target_cfg,
        )?
        else {
            return Ok(ConstLiteralCheck::Unsupported);
        };
        return Ok(ConstLiteralCheck::SupportedTuple { diagnostics });
    }

    let Some(literal_type) = resolve_const_literal_type(*ty, type_paths, symbols, inputs) else {
        return Ok(ConstLiteralCheck::Unsupported);
    };
    let Some(diagnostics) = check_const_literal_leaf(
        owner,
        *ty,
        &body.value,
        type_paths,
        symbols,
        inputs,
        snapshot,
        target_cfg,
    )?
    else {
        return Ok(ConstLiteralCheck::Unsupported);
    };

    Ok(match literal_type {
        ConstLiteralType::Primitive(primitive) => ConstLiteralCheck::Supported {
            primitive,
            diagnostics,
        },
        ConstLiteralType::Str => ConstLiteralCheck::SupportedStr { diagnostics },
        ConstLiteralType::Unit => ConstLiteralCheck::SupportedUnit { diagnostics },
    })
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ConstLiteralType {
    Primitive(sai_resolve::prelude::PrimTy),
    Str,
    Unit,
}

fn resolve_const_literal_type(
    ty: Ty<'_>,
    type_paths: Option<&TypeOwnerPathResolution>,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
) -> Option<ConstLiteralType> {
    match ty.kind {
        TyKind::Tuple(elements) if elements.is_empty() => Some(ConstLiteralType::Unit),
        TyKind::Tuple(_) => None,
        TyKind::Path(path)
            if path.root == PathRoot::Plain
                && path.segments.len() == 1
                && path.segments[0].args.is_none()
                && is_plain_ascii_identifier(path.segments[0].name, inputs) =>
        {
            let type_paths = type_paths?;
            match type_paths.paths().get(&path.hir_id) {
                Some(PathRes {
                    base: Res::PrimTy(primitive),
                    resolved_segments: 1,
                    segment_count: 1,
                }) if is_supported_const_literal_primitive(*primitive) => {
                    Some(ConstLiteralType::Primitive(*primitive))
                }
                None if is_deferred_canonical_str_path(path, type_paths, symbols, inputs) => {
                    Some(ConstLiteralType::Str)
                }
                _ => None,
            }
        }
        _ => None,
    }
}

fn check_function_body_type(
    owner: &HirOwner<'_>,
    body: &sai_hir::body::Body<'_>,
    locals: &LocalResolution,
    type_paths: Option<&TypeOwnerPathResolution>,
    direct_call_signatures: Option<&HashMap<HirId, sai_ty::typeck::body::PrimitiveCallSignature>>,
    semantic_types: &sai_ty::ty::TyInterner,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
    target_cfg: &TargetCfg,
    primitive_type_results: &mut Option<sai_ty::typeck::body::PrimitiveBodyTypeResults>,
) -> Result<FunctionBodyTypeCheck, OwnerControlFlowResolutionError> {
    if !owner.raw_attrs.is_empty() || !body.contracts.is_empty() || !body.invariant_preds.is_empty()
    {
        return Ok(FunctionBodyTypeCheck::Unsupported);
    }
    let OwnerNode::Item(item) = owner.node else {
        return Ok(FunctionBodyTypeCheck::Unsupported);
    };
    if item.vis != Visibility::Pub {
        return Ok(FunctionBodyTypeCheck::Unsupported);
    }
    let ItemKind::Fn {
        sig,
        generics,
        has_body: true,
    } = item.kind
    else {
        return Ok(FunctionBodyTypeCheck::Unsupported);
    };
    if sig.safety != sai_hir::Safety::Safe
        || sig.is_async
        || sig.borrows.is_some()
        || sig.effects.is_some()
        || !sig.requires.is_empty()
        || !sig.ensures.is_empty()
        || !generics.params.is_empty()
        || !generics.where_preds.is_empty()
        || !function_name_is_supported(item.name, symbols, inputs)
    {
        return Ok(FunctionBodyTypeCheck::Unsupported);
    }
    if sig.params.len() == body.params.len() {
        if let Some((diagnostics, type_results)) = check_function_body_primitive_local_block(
            owner,
            sig,
            body,
            locals,
            type_paths,
            direct_call_signatures,
            semantic_types,
            symbols,
            None,
            None,
            inputs,
            snapshot,
            target_cfg,
        )? {
            *primitive_type_results = Some(type_results);
            return Ok(FunctionBodyTypeCheck::Supported { diagnostics });
        }
    }
    let (parameter, parameter_pair) = match (sig.params, body.params) {
        ([], []) => (None, None),
        ([parameter], [body_parameter])
            if !parameter.is_self
                && !parameter.mutable
                && !body_parameter.mutable
                && parameter
                    .name
                    .is_some_and(|name| function_name_is_supported(name, symbols, inputs))
                && parameter.name == body_parameter.name =>
        {
            (Some((parameter, body_parameter)), None)
        }
        ([first, second], [first_body, second_body])
            if !first.is_self
                && !second.is_self
                && !first.mutable
                && !second.mutable
                && !first_body.mutable
                && !second_body.mutable
                && first
                    .name
                    .is_some_and(|name| function_name_is_supported(name, symbols, inputs))
                && second
                    .name
                    .is_some_and(|name| function_name_is_supported(name, symbols, inputs))
                && first.name == first_body.name
                && second.name == second_body.name
                && first.name != second.name
                && first_body.binding != second_body.binding =>
        {
            (None, Some((first, first_body, second, second_body)))
        }
        _ => return Ok(FunctionBodyTypeCheck::Unsupported),
    };

    let block = match body.value.kind {
        ExprKind::Block(block)
            if block.safety == sai_hir::Safety::Safe && block.stmts.is_empty() =>
        {
            block
        }
        _ => return Ok(FunctionBodyTypeCheck::Unsupported),
    };
    let diagnostics = if let Some((parameter, body_parameter)) = parameter {
        let Some(tail) = block.tail else {
            return Ok(FunctionBodyTypeCheck::Unsupported);
        };
        if let ExprKind::If {
            cond,
            then,
            els: Some(else_expr),
        } = tail.kind
        {
            let Some(return_ty) = sig.ret else {
                return Ok(FunctionBodyTypeCheck::Unsupported);
            };
            if !matches!(
                resolve_function_direct_type(*return_ty, type_paths, symbols, inputs),
                Some(FunctionDirectType::Primitive(_))
            ) {
                return Ok(FunctionBodyTypeCheck::Unsupported);
            }
            let condition_diagnostics = if function_if_condition_uses_parameter_binding(
                cond,
                body_parameter,
                locals,
                inputs,
            ) && matches!(
                resolve_function_direct_type(*parameter.ty, type_paths, symbols, inputs),
                Some(FunctionDirectType::Primitive(
                    sai_resolve::prelude::PrimTy::Bool
                ))
            ) {
                Some(Vec::new())
            } else {
                check_function_if_parameter_comparison_condition(
                    owner,
                    cond,
                    *parameter.ty,
                    body_parameter,
                    locals,
                    type_paths,
                    symbols,
                    inputs,
                    snapshot,
                    target_cfg,
                )?
            };
            let Some(mut condition_diagnostics) = condition_diagnostics else {
                return Ok(FunctionBodyTypeCheck::Unsupported);
            };
            let Some(mut branch_diagnostics) = check_function_if_literal_branches(
                owner, *return_ty, true, then, else_expr, type_paths, symbols, inputs, snapshot,
                target_cfg,
            )?
            else {
                return Ok(FunctionBodyTypeCheck::Unsupported);
            };
            condition_diagnostics.append(&mut branch_diagnostics);
            condition_diagnostics
        } else {
            let ExprKind::Path(path) = tail.kind else {
                return Ok(FunctionBodyTypeCheck::Unsupported);
            };
            if path.root != PathRoot::Plain
                || path.segments.len() != 1
                || path.segments[0].args.is_some()
                || !is_plain_ascii_identifier(path.segments[0].name, inputs)
            {
                return Ok(FunctionBodyTypeCheck::Unsupported);
            }
            if !matches!(
                locals.paths.get(&path.hir_id),
                Some(PathRes {
                    base: Res::Local(resolved_binding),
                    resolved_segments: 1,
                    segment_count: 1,
                }) if *resolved_binding == body_parameter.binding
            ) {
                return Ok(FunctionBodyTypeCheck::Unsupported);
            }

            let Some(found) =
                resolve_function_direct_type(*parameter.ty, type_paths, symbols, inputs)
            else {
                return Ok(FunctionBodyTypeCheck::Unsupported);
            };
            let expected = match sig.ret {
                Some(ty) => {
                    let Some(expected) =
                        resolve_function_direct_type(*ty, type_paths, symbols, inputs)
                    else {
                        return Ok(FunctionBodyTypeCheck::Unsupported);
                    };
                    expected
                }
                None => FunctionDirectType::Unit,
            };
            if found == FunctionDirectType::Str || expected == FunctionDirectType::Str {
                if found != FunctionDirectType::Str || expected != FunctionDirectType::Str {
                    return Ok(FunctionBodyTypeCheck::Unsupported);
                }
                Vec::new()
            } else if expected == found || expected == FunctionDirectType::Unit {
                Vec::new()
            } else {
                vec![const_literal_diagnostic(
                    owner.id,
                    inputs,
                    snapshot,
                    tail.span,
                    sai_diagnostics::Code::TypeMismatch,
                    format!(
                        "expected `{}`, found `{}`",
                        function_direct_type_name(expected),
                        function_direct_type_name(found)
                    ),
                    "type mismatch",
                )?]
            }
        }
    } else if let Some((first, first_body, second, second_body)) = parameter_pair {
        let Some(tail) = block.tail else {
            return Ok(FunctionBodyTypeCheck::Unsupported);
        };
        let ExprKind::If {
            cond,
            then,
            els: Some(else_expr),
        } = tail.kind
        else {
            return Ok(FunctionBodyTypeCheck::Unsupported);
        };
        let Some(return_ty) = sig.ret else {
            return Ok(FunctionBodyTypeCheck::Unsupported);
        };
        if !matches!(
            resolve_function_direct_type(*return_ty, type_paths, symbols, inputs),
            Some(FunctionDirectType::Primitive(_))
        ) {
            return Ok(FunctionBodyTypeCheck::Unsupported);
        }
        let first_parameter_type =
            resolve_function_direct_type(*first.ty, type_paths, symbols, inputs);
        let second_parameter_type =
            resolve_function_direct_type(*second.ty, type_paths, symbols, inputs);
        let (comparison_condition, condition_is_negated) = match cond.kind {
            ExprKind::Unary(UnOp::Not, operand) => (operand, true),
            _ => (cond, false),
        };
        let condition_is_supported_when_negated = matches!(
            comparison_condition.kind,
            ExprKind::Binary(
                BinOp::And
                    | BinOp::Or
                    | BinOp::Eq
                    | BinOp::Ne
                    | BinOp::Lt
                    | BinOp::Le
                    | BinOp::Gt
                    | BinOp::Ge,
                _,
                _
            )
        );
        let parameter_types_are_supported = match comparison_condition.kind {
            ExprKind::Binary(BinOp::And | BinOp::Or, _, _) => {
                let bool_type = Some(FunctionDirectType::Primitive(
                    sai_resolve::prelude::PrimTy::Bool,
                ));
                first_parameter_type == bool_type && second_parameter_type == bool_type
            }
            ExprKind::Binary(
                BinOp::Eq | BinOp::Ne | BinOp::Lt | BinOp::Le | BinOp::Gt | BinOp::Ge,
                _,
                _,
            ) => matches!(
                (first_parameter_type, second_parameter_type),
                (
                    Some(FunctionDirectType::Primitive(first)),
                    Some(FunctionDirectType::Primitive(second))
                ) if first == second
            ),
            _ => false,
        };
        let mixed_condition_diagnostics = check_function_if_mixed_logical_comparison_condition(
            owner,
            comparison_condition,
            !condition_is_negated,
            *first.ty,
            first_body,
            *second.ty,
            second_body,
            locals,
            type_paths,
            symbols,
            inputs,
            snapshot,
            target_cfg,
        )?;
        let direct_condition_is_supported = (!condition_is_negated
            || condition_is_supported_when_negated)
            && function_if_binary_condition_uses_parameter_bindings(
                comparison_condition,
                first_body,
                second_body,
                locals,
                inputs,
            )
            && parameter_types_are_supported;
        let condition_is_supported =
            direct_condition_is_supported || mixed_condition_diagnostics.is_some();
        let Some(mut diagnostics) = check_function_if_literal_branches(
            owner,
            *return_ty,
            condition_is_supported,
            then,
            else_expr,
            type_paths,
            symbols,
            inputs,
            snapshot,
            target_cfg,
        )?
        else {
            return Ok(FunctionBodyTypeCheck::Unsupported);
        };
        if let Some(mut condition_diagnostics) = mixed_condition_diagnostics {
            condition_diagnostics.append(&mut diagnostics);
            condition_diagnostics
        } else {
            diagnostics
        }
    } else {
        let Some(return_ty) = sig.ret else {
            return Ok(FunctionBodyTypeCheck::Unsupported);
        };
        match resolve_function_direct_type(*return_ty, type_paths, symbols, inputs) {
            Some(FunctionDirectType::Unit) if block.tail.is_none() => Vec::new(),
            Some(FunctionDirectType::Unit) => {
                let Some(tail) = block.tail else {
                    return Ok(FunctionBodyTypeCheck::Unsupported);
                };
                if !matches!(tail.kind, ExprKind::Tuple(elements) if elements.is_empty()) {
                    return Ok(FunctionBodyTypeCheck::Unsupported);
                }
                let Some(diagnostics) = check_const_literal_leaf(
                    owner, *return_ty, tail, type_paths, symbols, inputs, snapshot, target_cfg,
                )?
                else {
                    return Ok(FunctionBodyTypeCheck::Unsupported);
                };
                diagnostics
            }
            Some(FunctionDirectType::Primitive(_)) => {
                let Some(tail) = block.tail else {
                    return Ok(FunctionBodyTypeCheck::Unsupported);
                };
                if let ExprKind::If {
                    cond,
                    then,
                    els: Some(else_expr),
                } = tail.kind
                {
                    let Some(diagnostics) = check_function_if_literal_branches(
                        owner,
                        *return_ty,
                        matches!(cond.kind, ExprKind::Lit(Lit::Bool(_))),
                        then,
                        else_expr,
                        type_paths,
                        symbols,
                        inputs,
                        snapshot,
                        target_cfg,
                    )?
                    else {
                        return Ok(FunctionBodyTypeCheck::Unsupported);
                    };
                    diagnostics
                } else {
                    if !is_direct_function_scalar_literal(tail) {
                        return Ok(FunctionBodyTypeCheck::Unsupported);
                    }
                    let Some(diagnostics) = check_const_literal_leaf(
                        owner, *return_ty, tail, type_paths, symbols, inputs, snapshot, target_cfg,
                    )?
                    else {
                        return Ok(FunctionBodyTypeCheck::Unsupported);
                    };
                    diagnostics
                }
            }
            Some(FunctionDirectType::Str) => {
                let Some(tail) = block.tail else {
                    return Ok(FunctionBodyTypeCheck::Unsupported);
                };
                if !matches!(tail.kind, ExprKind::Lit(Lit::Str(_)))
                    && !is_direct_function_scalar_literal(tail)
                {
                    return Ok(FunctionBodyTypeCheck::Unsupported);
                }
                let Some(diagnostics) = check_const_literal_leaf(
                    owner, *return_ty, tail, type_paths, symbols, inputs, snapshot, target_cfg,
                )?
                else {
                    return Ok(FunctionBodyTypeCheck::Unsupported);
                };
                diagnostics
            }
            None => return Ok(FunctionBodyTypeCheck::Unsupported),
        }
    };
    Ok(FunctionBodyTypeCheck::Supported { diagnostics })
}

fn check_inherent_method_body_type(
    impl_owner: &HirOwner<'_>,
    method_owner: &HirOwner<'_>,
    body: &sai_hir::body::Body<'_>,
    locals: &LocalResolution,
    type_paths: Option<&TypeOwnerPathResolution>,
    semantic_types: &sai_ty::ty::TyInterner,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
    target_cfg: &TargetCfg,
    primitive_type_results: &mut Option<sai_ty::typeck::body::PrimitiveBodyTypeResults>,
) -> Result<FunctionBodyTypeCheck, OwnerControlFlowResolutionError> {
    if !impl_owner.raw_attrs.is_empty()
        || !method_owner.raw_attrs.is_empty()
        || !body.contracts.is_empty()
        || !body.invariant_preds.is_empty()
    {
        return Ok(FunctionBodyTypeCheck::Unsupported);
    }

    let OwnerNode::Item(impl_item) = impl_owner.node else {
        return Ok(FunctionBodyTypeCheck::Unsupported);
    };
    let ItemKind::Impl {
        safety: sai_hir::Safety::Safe,
        generics: impl_generics,
        kind: ImplKind::Inherent { self_ty },
        ..
    } = impl_item.kind
    else {
        return Ok(FunctionBodyTypeCheck::Unsupported);
    };
    if !impl_generics.params.is_empty()
        || !impl_generics.where_preds.is_empty()
        || !matches!(
            self_ty.kind,
            TyKind::Path(path)
                if path.root == PathRoot::Plain
                    && path.segments.len() == 1
                    && path.segments[0].args.is_none()
        )
    {
        return Ok(FunctionBodyTypeCheck::Unsupported);
    }

    let OwnerNode::ImplItem(method) = method_owner.node else {
        return Ok(FunctionBodyTypeCheck::Unsupported);
    };
    if method.owner_id != method_owner.id
        || method.impl_def != impl_item.owner_id.def_id
        || method.vis != Visibility::Pub
        || !function_name_is_supported(method.name, symbols, inputs)
    {
        return Ok(FunctionBodyTypeCheck::Unsupported);
    }
    let ImplItemKind::Fn {
        sig,
        generics,
        has_body: true,
    } = method.kind
    else {
        return Ok(FunctionBodyTypeCheck::Unsupported);
    };
    if sig.safety != sai_hir::Safety::Safe
        || sig.is_async
        || sig.borrows.is_some()
        || sig.effects.is_some()
        || !sig.requires.is_empty()
        || !sig.ensures.is_empty()
        || !generics.params.is_empty()
        || !generics.where_preds.is_empty()
    {
        return Ok(FunctionBodyTypeCheck::Unsupported);
    }

    let Some((receiver, explicit_params)) = sig.params.split_first() else {
        return Ok(FunctionBodyTypeCheck::Unsupported);
    };
    let Some((body_receiver, explicit_body_params)) = body.params.split_first() else {
        return Ok(FunctionBodyTypeCheck::Unsupported);
    };
    if !receiver.is_self
        || receiver.mutable
        || !matches!(
            receiver.ty.kind,
            TyKind::Borrow(
                sai_hir::Mutability::Not,
                inner
            ) if matches!(
                inner.kind,
                TyKind::Path(path)
                    if path.root == PathRoot::SelfType && path.segments.is_empty()
            )
        )
        || body_receiver.mutable
        || !matches!(
            locals.bindings.get(&body_receiver.binding),
            Some(sai_resolve::owner::LocalBinding {
                kind: sai_resolve::owner::BindingKind::Param,
                ..
            })
        )
        || explicit_params.iter().any(|parameter| parameter.is_self)
        || explicit_params.len() != explicit_body_params.len()
    {
        return Ok(FunctionBodyTypeCheck::Unsupported);
    }

    let ExprKind::Block(method_block) = body.value.kind else {
        return Ok(FunctionBodyTypeCheck::Unsupported);
    };
    let Some(field_types) = inherent_method_primitive_field_types(*self_ty, symbols, inputs) else {
        return Ok(FunctionBodyTypeCheck::Unsupported);
    };
    let mut self_field_projections = HashMap::new();
    let mut unknown_self_fields = HashSet::new();
    let mut diagnostics = Vec::new();
    for stmt in method_block.stmts {
        let StmtKind::Let { init, .. } = stmt.kind else {
            continue;
        };
        match init.kind {
            ExprKind::Field { .. } => {
                if !collect_inherent_method_self_field(
                    method_owner.id,
                    init,
                    true,
                    &field_types,
                    &mut self_field_projections,
                    &mut unknown_self_fields,
                    &mut diagnostics,
                    symbols,
                    inputs,
                    snapshot,
                )? {
                    return Ok(FunctionBodyTypeCheck::Unsupported);
                }
            }
            ExprKind::Binary(_, left, right) => {
                for operand in [left, right] {
                    if matches!(operand.kind, ExprKind::Field { .. })
                        && !collect_inherent_method_self_field(
                            method_owner.id,
                            operand,
                            false,
                            &field_types,
                            &mut self_field_projections,
                            &mut unknown_self_fields,
                            &mut diagnostics,
                            symbols,
                            inputs,
                            snapshot,
                        )?
                    {
                        return Ok(FunctionBodyTypeCheck::Unsupported);
                    }
                }
            }
            _ => {}
        }
    }
    if let Some(tail) = method_block.tail {
        if matches!(tail.kind, ExprKind::Field { .. }) {
            if !collect_inherent_method_self_field(
                method_owner.id,
                tail,
                true,
                &field_types,
                &mut self_field_projections,
                &mut unknown_self_fields,
                &mut diagnostics,
                symbols,
                inputs,
                snapshot,
            )? {
                return Ok(FunctionBodyTypeCheck::Unsupported);
            }
        }
    }

    let explicit_sig = sai_hir::body::FnSig {
        params: explicit_params,
        ..sig
    };
    let explicit_body = sai_hir::body::Body {
        params: explicit_body_params,
        ..*body
    };
    if let Some((type_diagnostics, type_results)) = check_function_body_primitive_local_block(
        method_owner,
        explicit_sig,
        &explicit_body,
        locals,
        type_paths,
        None,
        semantic_types,
        symbols,
        Some(&self_field_projections),
        Some(&unknown_self_fields),
        inputs,
        snapshot,
        target_cfg,
    )? {
        diagnostics.extend(type_diagnostics);
        *primitive_type_results = Some(type_results);
        Ok(FunctionBodyTypeCheck::Supported { diagnostics })
    } else {
        Ok(FunctionBodyTypeCheck::Unsupported)
    }
}

struct InherentMethodPrimitiveFields {
    type_name: String,
    type_name_span: sai_diagnostics::Span,
    fields: HashMap<String, sai_resolve::prelude::PrimTy>,
    candidate_names: Vec<String>,
}

fn collect_inherent_method_self_field(
    owner: OwnerId,
    expression: &HirExpr<'_>,
    collect_known_type: bool,
    fields: &InherentMethodPrimitiveFields,
    self_field_projections: &mut HashMap<HirId, sai_resolve::prelude::PrimTy>,
    unknown_self_fields: &mut HashSet<HirId>,
    diagnostics: &mut Vec<Diagnostic>,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
) -> Result<bool, OwnerControlFlowResolutionError> {
    let Some(field_lookup) = primitive_self_field_type(expression, &fields.fields, symbols) else {
        return Ok(false);
    };
    match field_lookup {
        Ok(field_type) if collect_known_type => {
            self_field_projections.insert(expression.hir_id, field_type);
        }
        Ok(_) => {}
        Err(name) => {
            unknown_self_fields.insert(expression.hir_id);
            diagnostics.push(unknown_self_field_diagnostic(
                owner, fields, name, inputs, snapshot,
            )?);
        }
    }
    Ok(true)
}

fn inherent_method_primitive_field_types(
    self_ty: Ty<'_>,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
) -> Option<InherentMethodPrimitiveFields> {
    use sai_syntax::ast::AstNode as _;

    let TyKind::Path(path) = self_ty.kind else {
        return None;
    };
    if path.root != PathRoot::Plain || path.segments.len() != 1 || path.segments[0].args.is_some() {
        return None;
    }
    let target_name = symbols.resolve(path.segments[0].name.sym).ok()?;
    if primitive_method_field_type(target_name.as_ref()).is_some() {
        return None;
    }
    let source_file = ast::SourceFile::cast(inputs.root.clone())?;
    if source_file.module_header().is_some()
        || source_file.test_decls().next().is_some()
        || source_file.property_decls().next().is_some()
        || source_file
            .syntax()
            .children()
            .any(|child| ast::UseDecl::can_cast(child.kind()))
    {
        return None;
    }
    let mut items = source_file.items();
    let Some(ast::Item::Type(type_decl)) = items.next() else {
        return None;
    };
    let Some(ast::Item::Impl(impl_decl)) = items.next() else {
        return None;
    };
    let type_name_node = type_decl.name()?;
    let type_name = type_name_node.token()?.text().to_owned();
    let type_name_span =
        sai_diagnostics::Span::new(inputs.source.id(), type_name_node.syntax().text_range());
    let struct_def = type_decl.struct_def()?;
    let fields = struct_def.fields()?;
    if items.next().is_some()
        || type_decl.attrs().next().is_some()
        || type_decl
            .syntax()
            .children()
            .any(|child| ast::GenericParamList::can_cast(child.kind()))
        || type_decl
            .syntax()
            .descendants()
            .any(|node| ast::Attribute::can_cast(node.kind()))
        || struct_def.where_clause().is_some()
        || fields.fields().next().is_none()
        || impl_decl.attrs().next().is_some()
        || impl_decl
            .syntax()
            .children()
            .any(|child| ast::GenericParamList::can_cast(child.kind()))
        || impl_decl
            .syntax()
            .descendants()
            .any(|node| ast::Attribute::can_cast(node.kind()))
        || impl_decl.unsafe_token().is_some()
    {
        return None;
    }
    let normalized_type_name =
        sai_syntax::normalize_identifier(type_name.strip_prefix("r#").unwrap_or(&type_name));
    if normalized_type_name != target_name.as_ref() {
        return None;
    }
    let inherent_type = impl_decl.inherent_type()?;
    let range = inherent_type.syntax().text_range();
    if inputs
        .source
        .text()
        .get(range.start().to_usize()..range.end().to_usize())
        != Some(type_name.as_str())
    {
        return None;
    }
    let mut field_types = HashMap::new();
    let mut candidate_names = Vec::new();
    for field in fields.fields() {
        if field.attrs().next().is_some() {
            return None;
        }
        let field_name_node = field.name()?;
        let field_name = field_name_node.token()?.text().to_owned();
        let field_spelling = field_name.strip_prefix("r#").unwrap_or(&field_name);
        let normalized_field_name = sai_syntax::normalize_identifier(field_spelling);
        let ty = field.ty()?;
        let range = ty.syntax().text_range();
        let ty_text = inputs
            .source
            .text()
            .get(range.start().to_usize()..range.end().to_usize())?;
        let field_type = primitive_method_field_type(ty_text)?;
        if field_types
            .insert(normalized_field_name, field_type)
            .is_some()
        {
            return None;
        }
        candidate_names.push(field_spelling.to_owned());
    }
    Some(InherentMethodPrimitiveFields {
        type_name: type_name
            .strip_prefix("r#")
            .unwrap_or(&type_name)
            .to_owned(),
        type_name_span,
        fields: field_types,
        candidate_names,
    })
}

fn primitive_method_field_type(ty: &str) -> Option<sai_resolve::prelude::PrimTy> {
    use sai_resolve::prelude::PrimTy;

    Some(match ty {
        "Bool" => PrimTy::Bool,
        "Byte" => PrimTy::Byte,
        "Char" => PrimTy::Char,
        "I8" => PrimTy::I8,
        "I16" => PrimTy::I16,
        "I32" => PrimTy::I32,
        "I64" => PrimTy::I64,
        "ISize" => PrimTy::ISize,
        "U8" => PrimTy::U8,
        "U16" => PrimTy::U16,
        "U32" => PrimTy::U32,
        "U64" => PrimTy::U64,
        "USize" => PrimTy::USize,
        "F32" => PrimTy::F32,
        "F64" => PrimTy::F64,
        _ => return None,
    })
}

fn is_direct_self_value_expression(expression: &HirExpr<'_>) -> bool {
    matches!(
        expression.kind,
        ExprKind::Path(HirPath {
            root: PathRoot::SelfValue,
            segments,
            ..
        }) if segments.is_empty()
    )
}

fn primitive_self_field_type(
    expression: &HirExpr<'_>,
    field_types: &HashMap<String, sai_resolve::prelude::PrimTy>,
    symbols: &Interner,
) -> Option<Result<sai_resolve::prelude::PrimTy, Name>> {
    let ExprKind::Field {
        base,
        name,
        args: None,
    } = expression.kind
    else {
        return None;
    };
    if !is_direct_self_value_expression(base) {
        return None;
    }
    let field_name = symbols.resolve(name.sym).ok()?;
    Some(field_types.get(field_name.as_ref()).copied().ok_or(name))
}

fn name_node_id_for_span(root: &SyntaxNode, span: sai_hir::Span) -> Option<String> {
    fn visit(
        node: &SyntaxNode,
        target: sai_vfs::TextRange,
        next_index: &mut u64,
        found: &mut Option<NodeId>,
    ) -> Option<()> {
        let index = *next_index;
        *next_index = next_index.checked_add(1)?;
        if node.text_range() == target
            && matches!(
                node.kind(),
                sai_syntax::SyntaxKind::NAME | sai_syntax::SyntaxKind::NAME_REF
            )
        {
            *found = Some(NodeId::new(NodeGroup::Name, index));
        }
        for element in node.children_with_tokens() {
            match element {
                SyntaxElement::Node(child) => visit(&child, target, next_index, found)?,
                SyntaxElement::Token(_) => *next_index = next_index.checked_add(1)?,
            }
        }
        Some(())
    }

    let mut next_index = 0;
    let mut found = None;
    visit(root, span.range, &mut next_index, &mut found)?;
    found.map(|node| node.to_string())
}

fn unknown_self_field_diagnostic(
    owner: OwnerId,
    fields: &InherentMethodPrimitiveFields,
    name: Name,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
) -> Result<Diagnostic, OwnerControlFlowResolutionError> {
    let written_field = inputs
        .source
        .text()
        .get(name.span.range.start().to_usize()..name.span.range.end().to_usize())
        .ok_or(OwnerControlFlowResolutionError::InvalidSourceLocation(
            owner,
        ))?;
    let field = written_field.strip_prefix("r#").unwrap_or(written_field);
    let include_all = fields.candidate_names.len() <= 5;
    let threshold = (field.chars().count() / 3).max(1);
    let mut candidates = fields
        .candidate_names
        .iter()
        .enumerate()
        .filter_map(|(declaration_order, candidate)| {
            let distance = unicode_damerau_levenshtein(field, candidate);
            (include_all || distance <= threshold).then_some((
                distance,
                declaration_order,
                candidate,
            ))
        })
        .collect::<Vec<_>>();
    candidates.sort_by_key(|(distance, declaration_order, _)| (*distance, *declaration_order));
    candidates.truncate(10);
    let candidate_names = candidates
        .into_iter()
        .map(|(_, _, candidate)| candidate.clone())
        .collect::<Vec<_>>();
    let primary = sai_diagnostics::Location::from_decoded_source(
        inputs.source_ref.clone(),
        sai_diagnostics::Span::new(name.span.file, name.span.range),
        &inputs.source,
    )
    .ok_or(OwnerControlFlowResolutionError::InvalidSourceLocation(
        owner,
    ))?;
    let declaration = sai_diagnostics::Location::from_decoded_source(
        inputs.source_ref.clone(),
        fields.type_name_span,
        &inputs.source,
    )
    .ok_or(OwnerControlFlowResolutionError::InvalidSourceLocation(
        owner,
    ))?;
    let node = name_node_id_for_span(&inputs.root, name.span).ok_or(
        OwnerControlFlowResolutionError::InvalidSourceLocation(owner),
    )?;
    let mut diagnostic = Diagnostic::new(
        sai_diagnostics::Code::UnknownField,
        sai_diagnostics::Severity::Error,
        format!("`{}` has no field `{field}`", fields.type_name),
        Some(primary),
    );
    diagnostic.primary_label = "unknown field".to_owned();
    diagnostic.node = Some(node);
    diagnostic.package = inputs.source_ref.package.clone();
    diagnostic.data.insert(
        "type_name".to_owned(),
        sai_diagnostics::Value::String(fields.type_name.clone()),
    );
    diagnostic.data.insert(
        "field".to_owned(),
        sai_diagnostics::Value::String(written_field.to_owned()),
    );
    diagnostic.data.insert(
        "candidates".to_owned(),
        sai_diagnostics::Value::Array(
            candidate_names
                .iter()
                .cloned()
                .map(sai_diagnostics::Value::String)
                .collect(),
        ),
    );
    diagnostic
        .push_related(Related::DeclaredHere {
            location: declaration,
            what: format!("`{}`", fields.type_name),
        })
        .map_err(|_| OwnerControlFlowResolutionError::InvalidSourceLocation(owner))?;
    if !candidate_names.is_empty() {
        diagnostic
            .push_child(Child {
                kind: ChildKind::Help,
                message: format!("available fields:\n{}", candidate_names.join("\n")),
                location: None,
            })
            .map_err(|_| OwnerControlFlowResolutionError::InvalidSourceLocation(owner))?;
    }
    diagnostic
        .with_workspace_snapshot(snapshot)
        .map_err(|_| OwnerControlFlowResolutionError::InvalidSourceLocation(owner))
}

fn check_function_body_primitive_local_block(
    owner: &HirOwner<'_>,
    sig: sai_hir::body::FnSig<'_>,
    body: &sai_hir::body::Body<'_>,
    locals: &LocalResolution,
    type_paths: Option<&TypeOwnerPathResolution>,
    direct_call_signatures: Option<&HashMap<HirId, sai_ty::typeck::body::PrimitiveCallSignature>>,
    semantic_types: &sai_ty::ty::TyInterner,
    symbols: &Interner,
    self_field_projections: Option<&HashMap<HirId, sai_resolve::prelude::PrimTy>>,
    unknown_self_fields: Option<&HashSet<HirId>>,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
    target_cfg: &TargetCfg,
) -> Result<
    Option<(
        Vec<Diagnostic>,
        sai_ty::typeck::body::PrimitiveBodyTypeResults,
    )>,
    OwnerControlFlowResolutionError,
> {
    let mut initial_bindings = HashMap::new();
    if sig.params.len() != body.params.len() {
        return Ok(None);
    }
    for (parameter, body_parameter) in sig.params.iter().zip(body.params) {
        if parameter.is_self
            || parameter.mutable
            || body_parameter.mutable
            || !parameter
                .name
                .is_some_and(|name| function_name_is_supported(name, symbols, inputs))
            || parameter.name != body_parameter.name
            || !matches!(
                locals.bindings.get(&body_parameter.binding),
                Some(sai_resolve::owner::LocalBinding {
                    kind: sai_resolve::owner::BindingKind::Param,
                    ..
                })
            )
        {
            return Ok(None);
        }
        let Some(FunctionDirectType::Primitive(parameter_type)) =
            resolve_function_direct_type(*parameter.ty, type_paths, symbols, inputs)
        else {
            return Ok(None);
        };
        if !sai_ty::typeck::literal::supports_primitive_literal(parameter_type) {
            return Ok(None);
        }
        initial_bindings.insert(body_parameter.binding, parameter_type);
    }

    let Some(return_ty) = sig.ret else {
        return Ok(None);
    };
    let Some(FunctionDirectType::Primitive(return_type)) =
        resolve_function_direct_type(*return_ty, type_paths, symbols, inputs)
    else {
        return Ok(None);
    };
    let ExprKind::Block(block) = body.value.kind else {
        return Ok(None);
    };
    if block.safety != sai_hir::Safety::Safe {
        return Ok(None);
    }
    let Some(tail) = block.tail else {
        return Ok(None);
    };
    let is_supported_field_tail = matches!(tail.kind, ExprKind::Field { .. })
        && (self_field_projections.is_some_and(|fields| fields.contains_key(&tail.hir_id))
            || unknown_self_fields.is_some_and(|fields| fields.contains(&tail.hir_id)));
    let is_supported_call_tail = matches!(tail.kind, ExprKind::Call { base: None, .. })
        && direct_call_signatures.is_some_and(|signatures| signatures.contains_key(&tail.hir_id));
    let tail_binding = match tail.kind {
        ExprKind::Path(tail_path) => {
            let Some(tail_binding) = resolved_plain_local_path_binding(tail_path, locals, inputs)
            else {
                return Ok(None);
            };
            Some(tail_binding)
        }
        ExprKind::Field { .. } if is_supported_field_tail => None,
        ExprKind::Call { .. } if is_supported_call_tail => None,
        _ => return Ok(None),
    };
    if block.stmts.is_empty() && !is_supported_field_tail && !is_supported_call_tail {
        return Ok(None);
    }

    // Track direct integer addition-pair provenance separately so Char
    // bitwise diagnostics can still be deferred through unannotated copies.
    // The arithmetic initializer itself is admitted independently below.
    let mut integer_addition_pair_roots = HashMap::new();
    let mut char_bitwise_rhs_roots = HashSet::new();
    for stmt in block.stmts {
        let StmtKind::Let {
            pat,
            init,
            els: None,
            ..
        } = stmt.kind
        else {
            continue;
        };
        let PatKind::Binding {
            binding, sub: None, ..
        } = pat.kind
        else {
            continue;
        };

        match init.kind {
            ExprKind::Binary(BinOp::Add, left, right)
                if is_direct_function_integer_literal(left)
                    && is_direct_function_integer_literal(right) =>
            {
                integer_addition_pair_roots.insert(binding, binding);
            }
            ExprKind::Path(path) => {
                if let Some(root) = resolved_plain_local_path_binding(path, locals, inputs)
                    .and_then(|source| integer_addition_pair_roots.get(&source).copied())
                {
                    integer_addition_pair_roots.insert(binding, root);
                }
            }
            ExprKind::Binary(BinOp::BitAnd | BinOp::BitOr | BinOp::BitXor, left, right)
                if matches!(left.kind, ExprKind::Lit(Lit::Char(_))) =>
            {
                let ExprKind::Path(path) = right.kind else {
                    continue;
                };
                if let Some(root) = resolved_plain_local_path_binding(path, locals, inputs)
                    .and_then(|source| integer_addition_pair_roots.get(&source).copied())
                {
                    char_bitwise_rhs_roots.insert(root);
                }
            }
            _ => {}
        }
    }

    let mut primitive_types = HashMap::new();
    let mut preceding_bindings = initial_bindings.keys().copied().collect::<HashSet<_>>();
    for stmt in block.stmts {
        let StmtKind::Let {
            pat,
            ty,
            init,
            els: None,
        } = stmt.kind
        else {
            return Ok(None);
        };
        let PatKind::Binding {
            mode: sai_hir::patterns::BindingMode::Value,
            name,
            binding,
            sub: None,
            ..
        } = pat.kind
        else {
            return Ok(None);
        };
        if !function_name_is_supported(name, symbols, inputs)
            || !matches!(
                locals.bindings.get(&binding),
                Some(sai_resolve::owner::LocalBinding {
                    kind: sai_resolve::owner::BindingKind::Let,
                    ..
                })
            )
        {
            return Ok(None);
        }
        if let Some(ty) = ty {
            let Some(FunctionDirectType::Primitive(local_type)) =
                resolve_function_direct_type(*ty, type_paths, symbols, inputs)
            else {
                return Ok(None);
            };
            primitive_types.insert(ty.hir_id, local_type);
        }

        match init.kind {
            ExprKind::Lit(_) if is_direct_function_scalar_literal(init) => {}
            ExprKind::Field { .. }
                if self_field_projections
                    .is_some_and(|fields| fields.contains_key(&init.hir_id))
                    || unknown_self_fields.is_some_and(|fields| fields.contains(&init.hir_id)) => {}
            ExprKind::Call {
                args, base: None, ..
            } if direct_call_signatures
                .and_then(|signatures| signatures.get(&init.hir_id))
                .is_some_and(|signature| {
                    args.iter()
                        .take(signature.parameters.len())
                        .all(|argument| {
                            is_supported_direct_call_argument_shape(
                                argument.expr,
                                &preceding_bindings,
                                locals,
                                inputs,
                                direct_call_signatures,
                            )
                        })
                }) => {}
            ExprKind::Path(path) => {
                let Some(source_binding) = resolved_plain_local_path_binding(path, locals, inputs)
                else {
                    return Ok(None);
                };
                if !preceding_bindings.contains(&source_binding) {
                    return Ok(None);
                }
            }
            ExprKind::Unary(UnOp::Not, operand) => {
                let ExprKind::Path(path) = operand.kind else {
                    return Ok(None);
                };
                let Some(source_binding) = resolved_plain_local_path_binding(path, locals, inputs)
                else {
                    return Ok(None);
                };
                if !preceding_bindings.contains(&source_binding) {
                    return Ok(None);
                }
            }
            ExprKind::Unary(UnOp::BitNot, operand) => {
                if !is_direct_function_integer_literal(operand)
                    && !matches!(operand.kind, ExprKind::Lit(Lit::Byte(_)))
                {
                    let ExprKind::Path(path) = operand.kind else {
                        return Ok(None);
                    };
                    let Some(source_binding) =
                        resolved_plain_local_path_binding(path, locals, inputs)
                    else {
                        return Ok(None);
                    };
                    if !preceding_bindings.contains(&source_binding) {
                        return Ok(None);
                    }
                }
            }
            ExprKind::Binary(operator, left, right)
                if is_function_primitive_local_binary_operator(operator) =>
            {
                let is_preceding_path = |operand: &HirExpr<'_>| {
                    let ExprKind::Path(path) = operand.kind else {
                        return false;
                    };
                    resolved_plain_local_path_binding(path, locals, inputs)
                        .is_some_and(|binding| preceding_bindings.contains(&binding))
                };
                let is_unknown_self_field = |operand: &HirExpr<'_>| {
                    matches!(operand.kind, ExprKind::Field { .. })
                        && unknown_self_fields
                            .is_some_and(|fields| fields.contains(&operand.hir_id))
                };
                let is_preceding_path_or_unknown_field = |operand: &HirExpr<'_>| {
                    is_preceding_path(operand) || is_unknown_self_field(operand)
                };
                let supported_shape = match operator {
                    BinOp::And | BinOp::Or => {
                        is_preceding_path_or_unknown_field(left)
                            && is_preceding_path_or_unknown_field(right)
                    }
                    BinOp::Shl | BinOp::Shr => {
                        (is_preceding_path_or_unknown_field(left)
                            && (is_preceding_path_or_unknown_field(right)
                                || is_direct_function_integer_literal(right)))
                            || (is_direct_function_integer_literal(left)
                                && is_preceding_path_or_unknown_field(right))
                            || (matches!(left.kind, ExprKind::Lit(Lit::Byte(_)))
                                && (is_preceding_path_or_unknown_field(right)
                                    || is_direct_function_integer_literal(right)))
                    }
                    BinOp::BitAnd | BinOp::BitOr | BinOp::BitXor => {
                        (is_preceding_path_or_unknown_field(left)
                            && is_preceding_path_or_unknown_field(right))
                            || (is_preceding_path_or_unknown_field(left)
                                && is_direct_function_integer_literal(right))
                            || (is_preceding_path_or_unknown_field(left)
                                && matches!(right.kind, ExprKind::Lit(Lit::Byte(_))))
                            || (is_preceding_path_or_unknown_field(left)
                                && matches!(
                                    right.kind,
                                    ExprKind::Lit(Lit::Bool(_) | Lit::Char(_) | Lit::Float { .. })
                                ))
                            || (is_direct_function_integer_literal(left)
                                && is_preceding_path_or_unknown_field(right))
                            || (is_direct_function_integer_literal(left)
                                && is_direct_function_integer_literal(right))
                            || (matches!(left.kind, ExprKind::Lit(Lit::Bool(_)))
                                && matches!(right.kind, ExprKind::Lit(Lit::Bool(_))))
                            || (matches!(left.kind, ExprKind::Lit(Lit::Char(_)))
                                && matches!(
                                    right.kind,
                                    ExprKind::Lit(
                                        Lit::Char(_)
                                            | Lit::Bool(_)
                                            | Lit::Byte(_)
                                            | Lit::Float { .. }
                                    )
                                ))
                            || (matches!(left.kind, ExprKind::Lit(Lit::Char(_)))
                                && is_direct_function_integer_literal(right))
                            || (matches!(left.kind, ExprKind::Lit(Lit::Char(_)))
                                && is_preceding_path_or_unknown_field(right))
                            || (matches!(left.kind, ExprKind::Lit(Lit::Byte(_)))
                                && (is_preceding_path_or_unknown_field(right)
                                    || is_direct_function_scalar_literal(right)))
                    }
                    BinOp::WrapAdd | BinOp::WrapSub | BinOp::WrapMul => {
                        (is_preceding_path_or_unknown_field(left)
                            && is_preceding_path_or_unknown_field(right))
                            || (is_preceding_path_or_unknown_field(left)
                                && is_direct_function_integer_literal(right))
                            || (is_direct_function_integer_literal(left)
                                && is_preceding_path_or_unknown_field(right))
                            || (is_direct_function_integer_literal(left)
                                && is_direct_function_integer_literal(right))
                    }
                    BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div | BinOp::Rem => {
                        (is_preceding_path_or_unknown_field(left)
                            && is_preceding_path_or_unknown_field(right))
                            || (is_preceding_path_or_unknown_field(left)
                                && is_direct_function_numeric_literal(right))
                            || (is_direct_function_numeric_literal(left)
                                && is_preceding_path_or_unknown_field(right))
                            || (matches!(
                                operator,
                                BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div | BinOp::Rem
                            ) && is_direct_function_integer_literal(left)
                                && is_direct_function_integer_literal(right))
                    }
                    BinOp::Eq | BinOp::Ne | BinOp::Lt | BinOp::Le | BinOp::Gt | BinOp::Ge => {
                        (is_preceding_path_or_unknown_field(left)
                            && is_preceding_path_or_unknown_field(right))
                            || (is_preceding_path_or_unknown_field(left)
                                && is_direct_function_scalar_literal(right))
                            || (is_direct_function_scalar_literal(left)
                                && is_preceding_path_or_unknown_field(right))
                    }
                };
                if !supported_shape {
                    return Ok(None);
                }
            }
            _ => return Ok(None),
        }
        preceding_bindings.insert(binding);
    }
    if tail_binding.is_some_and(|binding| !preceding_bindings.contains(&binding)) {
        return Ok(None);
    }
    if let (
        true,
        ExprKind::Call {
            args, base: None, ..
        },
    ) = (is_supported_call_tail, tail.kind)
    {
        let Some(signature) =
            direct_call_signatures.and_then(|signatures| signatures.get(&tail.hir_id))
        else {
            return Ok(None);
        };
        if !args
            .iter()
            .take(signature.parameters.len())
            .all(|argument| {
                is_supported_direct_call_argument_shape(
                    argument.expr,
                    &preceding_bindings,
                    locals,
                    inputs,
                    direct_call_signatures,
                )
            })
        {
            return Ok(None);
        }
    }

    let local_paths = locals
        .paths
        .iter()
        .filter_map(|(hir_id, resolution)| match resolution.base {
            Res::Local(binding)
                if resolution.resolved_segments == 1 && resolution.segment_count == 1 =>
            {
                Some((*hir_id, binding))
            }
            _ => None,
        })
        .collect::<HashMap<_, _>>();
    let check = sai_ty::typeck::body::check_primitive_local_block_body(
        sai_ty::typeck::body::PrimitiveBodyInput {
            body,
            return_type,
            initial_bindings: &initial_bindings,
            primitive_types: &primitive_types,
            self_field_projections,
            unknown_self_fields,
            local_paths: &local_paths,
            call_signatures: direct_call_signatures,
            symbols,
            pointer_width: target_cfg.pointer_width(),
        },
    );
    let sai_ty::typeck::body::PrimitiveBodyCheck::Supported {
        errors,
        type_results,
    } = check
    else {
        return Ok(None);
    };

    let Some(diagnostics) =
        primitive_body_errors_to_diagnostics(owner, block, tail, errors, inputs, snapshot)?
    else {
        return Ok(None);
    };
    Ok(Some((
        diagnostics,
        type_results.with_canonical_primitive_types(semantic_types),
    )))
}

fn is_function_primitive_local_binary_operator(operator: BinOp) -> bool {
    matches!(
        operator,
        BinOp::Add
            | BinOp::Sub
            | BinOp::Mul
            | BinOp::Div
            | BinOp::Rem
            | BinOp::WrapAdd
            | BinOp::WrapSub
            | BinOp::WrapMul
            | BinOp::BitAnd
            | BinOp::BitOr
            | BinOp::BitXor
            | BinOp::Shl
            | BinOp::Shr
            | BinOp::And
            | BinOp::Or
    ) || is_function_primitive_local_comparison_operator(operator)
}

fn is_function_primitive_local_comparison_operator(operator: BinOp) -> bool {
    matches!(
        operator,
        BinOp::Eq | BinOp::Ne | BinOp::Lt | BinOp::Le | BinOp::Gt | BinOp::Ge
    )
}

fn resolved_plain_local_path_binding(
    path: HirPath<'_>,
    locals: &LocalResolution,
    inputs: &CurrentOwnerInputs,
) -> Option<sai_hir::BindingId> {
    if path.root != PathRoot::Plain
        || path.segments.len() != 1
        || path.segments[0].args.is_some()
        || !is_plain_ascii_identifier(path.segments[0].name, inputs)
    {
        return None;
    }
    match locals.paths.get(&path.hir_id) {
        Some(PathRes {
            base: Res::Local(binding),
            resolved_segments: 1,
            segment_count: 1,
        }) => Some(*binding),
        _ => None,
    }
}

fn is_supported_direct_call_argument_shape(
    expression: &HirExpr<'_>,
    preceding_bindings: &HashSet<sai_hir::BindingId>,
    locals: &LocalResolution,
    inputs: &CurrentOwnerInputs,
    direct_call_signatures: Option<&HashMap<HirId, sai_ty::typeck::body::PrimitiveCallSignature>>,
) -> bool {
    match expression.kind {
        ExprKind::Lit(_) => is_direct_function_scalar_literal(expression),
        ExprKind::Path(path) => resolved_plain_local_path_binding(path, locals, inputs)
            .is_some_and(|binding| preceding_bindings.contains(&binding)),
        ExprKind::Call {
            callee,
            args,
            base: None,
        } => {
            let Some(signature) = direct_call_signatures
                .and_then(|signatures| signatures.get(&expression.hir_id))
                .filter(|signature| signature.callee == callee.hir_id)
            else {
                return false;
            };
            args.iter()
                .take(signature.parameters.len())
                .all(|argument| {
                    is_supported_direct_call_leaf_argument_shape(
                        argument.expr,
                        preceding_bindings,
                        locals,
                        inputs,
                    )
                })
        }
        _ => false,
    }
}

fn is_supported_direct_call_leaf_argument_shape(
    expression: &HirExpr<'_>,
    preceding_bindings: &HashSet<sai_hir::BindingId>,
    locals: &LocalResolution,
    inputs: &CurrentOwnerInputs,
) -> bool {
    match expression.kind {
        ExprKind::Lit(_) => is_direct_function_scalar_literal(expression),
        ExprKind::Path(path) => resolved_plain_local_path_binding(path, locals, inputs)
            .is_some_and(|binding| preceding_bindings.contains(&binding)),
        _ => false,
    }
}

fn primitive_body_errors_to_diagnostics(
    owner: &HirOwner<'_>,
    block: &sai_hir::expressions::Block<'_>,
    tail: &HirExpr<'_>,
    errors: Vec<sai_ty::typeck::body::PrimitiveBodyError>,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
) -> Result<Option<Vec<Diagnostic>>, OwnerControlFlowResolutionError> {
    let sort_by_source_span = errors.iter().any(|error| {
        matches!(
            error.kind,
            sai_ty::typeck::body::PrimitiveBodyErrorKind::DeferredOperatorTraitNotSupported { .. }
        )
    });
    let mut diagnostics = Vec::with_capacity(errors.len());
    for error in errors {
        let span = match error.kind {
            sai_ty::typeck::body::PrimitiveBodyErrorKind::NamedArgumentOnFunction { name_span } => {
                Some(name_span)
            }
            _ => block
                .stmts
                .iter()
                .find_map(|stmt| match stmt.kind {
                    StmtKind::Let { init, .. } => primitive_body_error_span(init, error.node),
                    _ => None,
                })
                .or_else(|| primitive_body_error_span(tail, error.node)),
        };
        let Some(span) = span else {
            return Ok(None);
        };
        use sai_ty::typeck::body::{
            PrimitiveBodyErrorKind, PrimitiveLiteralKind, PrimitiveOperatorOperand,
        };
        let diagnostic = match error.kind {
            PrimitiveBodyErrorKind::LiteralTypeMismatch { expected, found } => {
                let found = match found {
                    PrimitiveLiteralKind::Integer => "an integer literal",
                    PrimitiveLiteralKind::FloatingPoint => "a floating-point literal",
                    PrimitiveLiteralKind::Bool => "a Bool literal",
                    PrimitiveLiteralKind::Byte => "a byte literal",
                    PrimitiveLiteralKind::Character => "a character literal",
                };
                const_literal_diagnostic(
                    owner.id,
                    inputs,
                    snapshot,
                    span,
                    sai_diagnostics::Code::TypeMismatch,
                    format!(
                        "expected `{}`, found {found}",
                        const_primitive_name(expected)
                    ),
                    "type mismatch",
                )?
            }
            PrimitiveBodyErrorKind::LiteralOutOfRange { expected, found } => {
                let label = match found {
                    PrimitiveLiteralKind::Integer => "integer",
                    PrimitiveLiteralKind::FloatingPoint => "floating-point",
                    PrimitiveLiteralKind::Bool
                    | PrimitiveLiteralKind::Byte
                    | PrimitiveLiteralKind::Character => return Ok(None),
                };
                const_literal_diagnostic(
                    owner.id,
                    inputs,
                    snapshot,
                    span,
                    sai_diagnostics::Code::LiteralOutOfRange,
                    format!(
                        "{label} literal is out of range for `{}`",
                        const_primitive_name(expected)
                    ),
                    "literal out of range",
                )?
            }
            PrimitiveBodyErrorKind::TypeMismatch { expected, found } => const_literal_diagnostic(
                owner.id,
                inputs,
                snapshot,
                span,
                sai_diagnostics::Code::TypeMismatch,
                format!(
                    "expected `{}`, found `{}`",
                    const_primitive_name(expected),
                    const_primitive_name(found)
                ),
                "type mismatch",
            )?,
            PrimitiveBodyErrorKind::OperatorNotSupported { operator, operand } => {
                let operator_text = match operator {
                    BinOp::Rem => "%",
                    BinOp::WrapAdd => "+%",
                    BinOp::WrapSub => "-%",
                    BinOp::WrapMul => "*%",
                    BinOp::BitAnd => "&",
                    BinOp::BitOr => "|",
                    BinOp::BitXor => "^",
                    BinOp::Shl => "<<",
                    BinOp::Shr => ">>",
                    _ => return Ok(None),
                };
                let message = match operand {
                    PrimitiveOperatorOperand::Concrete(operand) => format!(
                        "operator `{operator_text}` is not defined for `{}`",
                        const_primitive_name(operand)
                    ),
                    PrimitiveOperatorOperand::FloatingPointLiteral => {
                        format!(
                            "operator `{operator_text}` is not defined for floating-point values"
                        )
                    }
                };
                let label = match operator {
                    BinOp::Rem => "floating-point remainder is not supported",
                    BinOp::WrapAdd | BinOp::WrapSub | BinOp::WrapMul => {
                        "wrapping arithmetic is not supported for this primitive"
                    }
                    BinOp::BitAnd | BinOp::BitOr | BinOp::BitXor => {
                        "bitwise operator is not supported for this primitive"
                    }
                    BinOp::Shl | BinOp::Shr => "shift operator is not supported for this primitive",
                    _ => return Ok(None),
                };
                let mut diagnostic = const_literal_diagnostic(
                    owner.id,
                    inputs,
                    snapshot,
                    span,
                    sai_diagnostics::Code::OperatorNotSupported,
                    message,
                    label,
                )?;
                if operator == BinOp::Rem {
                    diagnostic
                        .push_child(Child {
                            kind: ChildKind::Help,
                            message:
                                "use the floating-point `rem` method (for example, `left.rem(right)`)"
                                    .to_owned(),
                            location: None,
                        })
                        .map_err(|_| {
                            OwnerControlFlowResolutionError::InvalidSourceLocation(owner.id)
                        })?;
                }
                diagnostic
            }
            PrimitiveBodyErrorKind::OperatorTraitNotSupported {
                operator,
                left,
                right,
            }
            | PrimitiveBodyErrorKind::DeferredOperatorTraitNotSupported {
                operator,
                left,
                right,
            } => {
                let (operator_text, trait_name) = match operator {
                    BinOp::BitAnd => ("&", "BitAnd"),
                    BinOp::BitOr => ("|", "BitOr"),
                    BinOp::BitXor => ("^", "BitXor"),
                    _ => return Ok(None),
                };
                const_literal_diagnostic(
                    owner.id,
                    inputs,
                    snapshot,
                    span,
                    sai_diagnostics::Code::OperatorNotSupported,
                    format!(
                        "operator `{operator_text}` has no `{trait_name}<{}>` implementation for `{}`",
                        const_primitive_name(right),
                        const_primitive_name(left)
                    ),
                    "operator trait implementation is not available",
                )?
            }
            PrimitiveBodyErrorKind::UnaryOperatorNotSupported { operator, operand } => {
                let (operator_text, trait_name) = match operator {
                    UnOp::BitNot => ("~", "BitNot"),
                    _ => return Ok(None),
                };
                const_literal_diagnostic(
                    owner.id,
                    inputs,
                    snapshot,
                    span,
                    sai_diagnostics::Code::OperatorNotSupported,
                    format!(
                        "operator `{operator_text}` has no `{trait_name}` implementation for `{}`",
                        const_primitive_name(operand)
                    ),
                    "operator trait implementation is not available",
                )?
            }
            PrimitiveBodyErrorKind::WrongArgumentCount { expected, found } => {
                let noun = if expected == 1 {
                    "argument"
                } else {
                    "arguments"
                };
                const_literal_diagnostic(
                    owner.id,
                    inputs,
                    snapshot,
                    span,
                    sai_diagnostics::Code::WrongArgumentCount,
                    format!("function expects {expected} {noun} but found {found}"),
                    "wrong number of arguments",
                )?
            }
            PrimitiveBodyErrorKind::NamedArgumentOnFunction { .. } => const_literal_diagnostic(
                owner.id,
                inputs,
                snapshot,
                span,
                sai_diagnostics::Code::NamedArgumentOnFunction,
                "named arguments are only allowed when constructing a record".to_owned(),
                "named argument is not allowed in a function call",
            )?,
        };
        diagnostics.push(diagnostic);
    }
    if sort_by_source_span {
        sort_phase1_diagnostics(&mut diagnostics);
    }
    Ok(Some(diagnostics))
}

fn primitive_body_error_span(expression: &HirExpr<'_>, node: HirId) -> Option<sai_hir::Span> {
    if expression.hir_id == node {
        return Some(expression.span);
    }
    match expression.kind {
        ExprKind::Unary(_, operand) if operand.hir_id == node => Some(operand.span),
        ExprKind::Binary(_, left, right) => {
            if left.hir_id == node {
                Some(left.span)
            } else if right.hir_id == node {
                Some(right.span)
            } else {
                None
            }
        }
        ExprKind::Call { callee, args, base } => primitive_body_error_span(callee, node)
            .or_else(|| {
                args.iter()
                    .find_map(|argument| primitive_body_error_span(argument.expr, node))
            })
            .or_else(|| base.and_then(|base| primitive_body_error_span(base, node))),
        _ => None,
    }
}

fn function_if_condition_uses_parameter_binding(
    condition: &HirExpr<'_>,
    body_parameter: &sai_hir::body::BodyParam,
    locals: &LocalResolution,
    inputs: &CurrentOwnerInputs,
) -> bool {
    let path_expression = match condition.kind {
        ExprKind::Path(_) => Some(condition),
        ExprKind::Unary(UnOp::Not, operand) => match operand.kind {
            ExprKind::Path(_) => Some(operand),
            _ => None,
        },
        _ => None,
    };
    let Some(path_expression) = path_expression else {
        return false;
    };
    function_if_path_uses_parameter_binding(path_expression, body_parameter, locals, inputs)
}

fn function_if_path_uses_parameter_binding(
    expression: &HirExpr<'_>,
    body_parameter: &sai_hir::body::BodyParam,
    locals: &LocalResolution,
    inputs: &CurrentOwnerInputs,
) -> bool {
    let ExprKind::Path(path) = expression.kind else {
        return false;
    };
    path.root == PathRoot::Plain
        && path.segments.len() == 1
        && path.segments[0].args.is_none()
        && is_plain_ascii_identifier(path.segments[0].name, inputs)
        && matches!(
            locals.paths.get(&path.hir_id),
            Some(PathRes {
                base: Res::Local(resolved_binding),
                resolved_segments: 1,
                segment_count: 1,
            }) if *resolved_binding == body_parameter.binding
        )
}

fn check_function_if_parameter_comparison_condition(
    owner: &HirOwner<'_>,
    condition: &HirExpr<'_>,
    parameter_ty: Ty<'_>,
    body_parameter: &sai_hir::body::BodyParam,
    locals: &LocalResolution,
    type_paths: Option<&TypeOwnerPathResolution>,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
    target_cfg: &TargetCfg,
) -> Result<Option<Vec<Diagnostic>>, OwnerControlFlowResolutionError> {
    let comparison_condition = match condition.kind {
        ExprKind::Unary(UnOp::Not, operand) => operand,
        _ => condition,
    };
    let ExprKind::Binary(operator, left, right) = comparison_condition.kind else {
        return Ok(None);
    };
    if !matches!(
        operator,
        BinOp::Eq | BinOp::Ne | BinOp::Lt | BinOp::Le | BinOp::Gt | BinOp::Ge
    ) {
        return Ok(None);
    }
    let (literal, parameter_path, literal_is_left) =
        if function_if_path_uses_parameter_binding(left, body_parameter, locals, inputs)
            && is_direct_function_scalar_literal(right)
        {
            (right, left, false)
        } else if is_direct_function_scalar_literal(left)
            && function_if_path_uses_parameter_binding(right, body_parameter, locals, inputs)
        {
            (left, right, true)
        } else {
            return Ok(None);
        };
    let Some(FunctionDirectType::Primitive(parameter_primitive)) =
        resolve_function_direct_type(parameter_ty, type_paths, symbols, inputs)
    else {
        return Ok(None);
    };
    if literal_is_left {
        let literal_primitive = match literal.kind {
            ExprKind::Lit(Lit::Bool(_)) => Some(sai_resolve::prelude::PrimTy::Bool),
            ExprKind::Lit(Lit::Char(_)) => Some(sai_resolve::prelude::PrimTy::Char),
            ExprKind::Lit(Lit::Byte(_)) => Some(sai_resolve::prelude::PrimTy::Byte),
            _ => None,
        };
        if let Some(literal_primitive) = literal_primitive {
            if literal_primitive == parameter_primitive {
                return Ok(Some(Vec::new()));
            }
            return Ok(Some(vec![const_literal_diagnostic(
                owner.id,
                inputs,
                snapshot,
                parameter_path.span,
                sai_diagnostics::Code::TypeMismatch,
                format!(
                    "expected `{}`, found `{}`",
                    const_primitive_name(literal_primitive),
                    const_primitive_name(parameter_primitive)
                ),
                "type mismatch",
            )?]));
        }
        let default_primitive = match literal.kind {
            ExprKind::Lit(Lit::Int { .. }) if !is_integer_primitive(parameter_primitive) => {
                Some(sai_resolve::prelude::PrimTy::I64)
            }
            ExprKind::Lit(Lit::Float { .. })
                if !matches!(
                    parameter_primitive,
                    sai_resolve::prelude::PrimTy::F32 | sai_resolve::prelude::PrimTy::F64
                ) =>
            {
                Some(sai_resolve::prelude::PrimTy::F64)
            }
            _ => None,
        };
        if let Some(default_primitive) = default_primitive {
            return Ok(Some(vec![const_literal_diagnostic(
                owner.id,
                inputs,
                snapshot,
                parameter_path.span,
                sai_diagnostics::Code::TypeMismatch,
                format!(
                    "expected `{}`, found `{}`",
                    const_primitive_name(default_primitive),
                    const_primitive_name(parameter_primitive)
                ),
                "type mismatch",
            )?]));
        }
    }
    check_const_literal_leaf(
        owner,
        parameter_ty,
        literal,
        type_paths,
        symbols,
        inputs,
        snapshot,
        target_cfg,
    )
}

fn check_function_if_mixed_logical_comparison_condition(
    owner: &HirOwner<'_>,
    condition: &HirExpr<'_>,
    allow_negated_comparison_operand: bool,
    first_parameter_ty: Ty<'_>,
    first_body_parameter: &sai_hir::body::BodyParam,
    second_parameter_ty: Ty<'_>,
    second_body_parameter: &sai_hir::body::BodyParam,
    locals: &LocalResolution,
    type_paths: Option<&TypeOwnerPathResolution>,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
    target_cfg: &TargetCfg,
) -> Result<Option<Vec<Diagnostic>>, OwnerControlFlowResolutionError> {
    let ExprKind::Binary(BinOp::And | BinOp::Or, left, right) = condition.kind else {
        return Ok(None);
    };
    let (bool_path, comparison) = if matches!(left.kind, ExprKind::Path(_)) {
        (left, right)
    } else if matches!(right.kind, ExprKind::Path(_)) {
        (right, left)
    } else {
        return Ok(None);
    };
    let comparison_for_shape = match comparison.kind {
        ExprKind::Unary(UnOp::Not, operand) if allow_negated_comparison_operand => operand,
        _ => comparison,
    };
    if !matches!(
        comparison_for_shape.kind,
        ExprKind::Binary(
            BinOp::Eq | BinOp::Ne | BinOp::Lt | BinOp::Le | BinOp::Gt | BinOp::Ge,
            _,
            _
        )
    ) {
        return Ok(None);
    }

    let bool_type = Some(FunctionDirectType::Primitive(
        sai_resolve::prelude::PrimTy::Bool,
    ));
    let (comparison_parameter, comparison_parameter_ty) =
        if resolve_function_direct_type(first_parameter_ty, type_paths, symbols, inputs)
            == bool_type
            && function_if_path_uses_parameter_binding(
                bool_path,
                first_body_parameter,
                locals,
                inputs,
            )
        {
            (second_body_parameter, second_parameter_ty)
        } else if resolve_function_direct_type(second_parameter_ty, type_paths, symbols, inputs)
            == bool_type
            && function_if_path_uses_parameter_binding(
                bool_path,
                second_body_parameter,
                locals,
                inputs,
            )
        {
            (first_body_parameter, first_parameter_ty)
        } else {
            return Ok(None);
        };
    check_function_if_parameter_comparison_condition(
        owner,
        comparison,
        comparison_parameter_ty,
        comparison_parameter,
        locals,
        type_paths,
        symbols,
        inputs,
        snapshot,
        target_cfg,
    )
}

fn function_if_binary_condition_uses_parameter_bindings(
    condition: &HirExpr<'_>,
    first_body_parameter: &sai_hir::body::BodyParam,
    second_body_parameter: &sai_hir::body::BodyParam,
    locals: &LocalResolution,
    inputs: &CurrentOwnerInputs,
) -> bool {
    let ExprKind::Binary(operator, left, right) = condition.kind else {
        return false;
    };
    if !matches!(
        operator,
        BinOp::And
            | BinOp::Or
            | BinOp::Eq
            | BinOp::Ne
            | BinOp::Lt
            | BinOp::Le
            | BinOp::Gt
            | BinOp::Ge
    ) {
        return false;
    }
    let path_binding = |expression: &HirExpr<'_>| {
        let ExprKind::Path(path) = expression.kind else {
            return None;
        };
        if path.root != PathRoot::Plain
            || path.segments.len() != 1
            || path.segments[0].args.is_some()
            || !is_plain_ascii_identifier(path.segments[0].name, inputs)
        {
            return None;
        }
        match locals.paths.get(&path.hir_id) {
            Some(PathRes {
                base: Res::Local(binding),
                resolved_segments: 1,
                segment_count: 1,
            }) => Some(*binding),
            _ => None,
        }
    };
    let (Some(left_binding), Some(right_binding)) = (path_binding(left), path_binding(right))
    else {
        return false;
    };
    left_binding != right_binding
        && ((left_binding == first_body_parameter.binding
            && right_binding == second_body_parameter.binding)
            || (left_binding == second_body_parameter.binding
                && right_binding == first_body_parameter.binding))
}

fn check_function_if_literal_branches(
    owner: &HirOwner<'_>,
    return_ty: Ty<'_>,
    condition_is_supported: bool,
    then_block: &HirBlock<'_>,
    else_expr: &HirExpr<'_>,
    type_paths: Option<&TypeOwnerPathResolution>,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
    target_cfg: &TargetCfg,
) -> Result<Option<Vec<Diagnostic>>, OwnerControlFlowResolutionError> {
    if !condition_is_supported
        || then_block.safety != sai_hir::Safety::Safe
        || !then_block.stmts.is_empty()
    {
        return Ok(None);
    }
    let Some(then_tail) = then_block.tail else {
        return Ok(None);
    };
    if !is_direct_function_scalar_literal(then_tail) {
        return Ok(None);
    }

    let ExprKind::Block(else_block) = else_expr.kind else {
        return Ok(None);
    };
    if else_block.safety != sai_hir::Safety::Safe || !else_block.stmts.is_empty() {
        return Ok(None);
    }
    let Some(else_tail) = else_block.tail else {
        return Ok(None);
    };
    if !is_direct_function_scalar_literal(else_tail) {
        return Ok(None);
    }

    let Some(mut diagnostics) = check_const_literal_leaf(
        owner, return_ty, then_tail, type_paths, symbols, inputs, snapshot, target_cfg,
    )?
    else {
        return Ok(None);
    };
    let Some(mut else_diagnostics) = check_const_literal_leaf(
        owner, return_ty, else_tail, type_paths, symbols, inputs, snapshot, target_cfg,
    )?
    else {
        return Ok(None);
    };
    diagnostics.append(&mut else_diagnostics);
    Ok(Some(diagnostics))
}

fn is_direct_function_scalar_literal(expression: &HirExpr<'_>) -> bool {
    matches!(
        expression.kind,
        ExprKind::Lit(
            Lit::Bool(_) | Lit::Char(_) | Lit::Byte(_) | Lit::Int { .. } | Lit::Float { .. }
        )
    )
}

fn is_direct_function_numeric_literal(expression: &HirExpr<'_>) -> bool {
    matches!(
        expression.kind,
        ExprKind::Lit(Lit::Int { .. } | Lit::Float { .. })
    )
}

fn is_direct_function_integer_literal(expression: &HirExpr<'_>) -> bool {
    matches!(expression.kind, ExprKind::Lit(Lit::Int { .. }))
}

fn function_name_is_supported(name: Name, symbols: &Interner, inputs: &CurrentOwnerInputs) -> bool {
    is_plain_ascii_identifier(name, inputs)
        && symbols
            .resolve(name.sym)
            .is_ok_and(|name| !name.chars().any(char::is_uppercase))
}

fn is_plain_ascii_identifier(name: Name, inputs: &CurrentOwnerInputs) -> bool {
    inputs
        .source
        .text()
        .get(name.span.range.start().to_usize()..name.span.range.end().to_usize())
        .is_some_and(|written| written.is_ascii() && !written.starts_with("r#"))
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum FunctionDirectType {
    Primitive(sai_resolve::prelude::PrimTy),
    Str,
    Unit,
}

#[derive(Clone, Debug)]
struct PrimitiveFunctionCallSignature {
    owner: OwnerId,
    parameters: Vec<sai_resolve::prelude::PrimTy>,
    output: sai_resolve::prelude::PrimTy,
}

fn resolve_function_direct_type(
    ty: Ty<'_>,
    type_paths: Option<&TypeOwnerPathResolution>,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
) -> Option<FunctionDirectType> {
    match resolve_const_literal_type(ty, type_paths, symbols, inputs)? {
        ConstLiteralType::Primitive(primitive) => Some(FunctionDirectType::Primitive(primitive)),
        ConstLiteralType::Str => Some(FunctionDirectType::Str),
        ConstLiteralType::Unit => Some(FunctionDirectType::Unit),
    }
}

fn function_direct_type_name(ty: FunctionDirectType) -> &'static str {
    match ty {
        FunctionDirectType::Primitive(primitive) => const_primitive_name(primitive),
        FunctionDirectType::Str => "Str",
        FunctionDirectType::Unit => "()",
    }
}

fn direct_primitive_call_sites(
    body: &sai_hir::body::Body<'_>,
    module_paths: &ModuleResolution,
    signatures: &HashMap<DefId, PrimitiveFunctionCallSignature>,
    requesting_package: PackageId,
    inputs: &CurrentOwnerInputs,
) -> HashMap<HirId, sai_ty::typeck::body::PrimitiveCallSignature> {
    let mut calls = HashMap::new();
    if module_paths.owner != body.owner {
        return calls;
    }
    let ExprKind::Block(block) = body.value.kind else {
        return calls;
    };
    let mut index_root_and_one_level_arguments = |expression: &HirExpr<'_>| {
        let Some(signature) = direct_primitive_call_site(
            expression,
            module_paths,
            signatures,
            requesting_package,
            inputs,
        ) else {
            return;
        };
        let argument_count = signature.parameters.len();
        calls.insert(expression.hir_id, signature);
        let ExprKind::Call {
            args, base: None, ..
        } = expression.kind
        else {
            return;
        };
        for argument in args.iter().take(argument_count) {
            if matches!(argument.expr.kind, ExprKind::Call { .. })
                && let Some(nested_signature) = direct_primitive_call_site(
                    argument.expr,
                    module_paths,
                    signatures,
                    requesting_package,
                    inputs,
                )
            {
                calls.insert(argument.expr.hir_id, nested_signature);
            }
        }
    };
    for statement in block.stmts {
        if let StmtKind::Let { init, .. } = statement.kind
            && matches!(init.kind, ExprKind::Call { .. })
        {
            index_root_and_one_level_arguments(init);
        }
    }
    if let Some(tail) = block.tail
        && matches!(tail.kind, ExprKind::Call { .. })
    {
        index_root_and_one_level_arguments(tail);
    }
    calls
}

fn direct_primitive_call_site(
    expression: &HirExpr<'_>,
    module_paths: &ModuleResolution,
    signatures: &HashMap<DefId, PrimitiveFunctionCallSignature>,
    requesting_package: PackageId,
    inputs: &CurrentOwnerInputs,
) -> Option<sai_ty::typeck::body::PrimitiveCallSignature> {
    let ExprKind::Call {
        callee, base: None, ..
    } = expression.kind
    else {
        return None;
    };
    let ExprKind::Path(path) = callee.kind else {
        return None;
    };
    if path.root != PathRoot::Plain
        || path.segments.len() != 1
        || path.segments[0].args.is_some()
        || !is_plain_ascii_identifier(path.segments[0].name, inputs)
    {
        return None;
    }
    let Some(PathRes {
        base: Res::Def(DefKind::Fn, target),
        resolved_segments: 1,
        segment_count: 1,
    }) = module_paths.paths.get(&path.hir_id)
    else {
        return None;
    };
    if target.package != requesting_package {
        return None;
    }
    let signature = signatures.get(target)?;
    (signature.owner.def_id.to_def_id() == *target
        && signature.owner.def_id.package() == requesting_package)
        .then(|| sai_ty::typeck::body::PrimitiveCallSignature {
            callee: callee.hir_id,
            parameters: signature.parameters.clone(),
            output: signature.output,
        })
}

fn check_const_tuple_literal(
    owner: &HirOwner<'_>,
    expected_elements: &[Ty<'_>],
    value: &HirExpr<'_>,
    type_paths: Option<&TypeOwnerPathResolution>,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
    target_cfg: &TargetCfg,
) -> Result<Option<Vec<Diagnostic>>, OwnerControlFlowResolutionError> {
    let Some(_expected_types) = expected_elements
        .iter()
        .map(|ty| resolve_const_literal_type(*ty, type_paths, symbols, inputs))
        .collect::<Option<Vec<_>>>()
    else {
        return Ok(None);
    };

    let ExprKind::Tuple(values) = value.kind else {
        let ExprKind::Lit(literal) = value.kind else {
            return Ok(None);
        };
        return Ok(Some(vec![const_literal_diagnostic(
            owner.id,
            inputs,
            snapshot,
            value.span,
            sai_diagnostics::Code::TypeMismatch,
            format!(
                "expected a tuple, found {}",
                const_literal_found_type(literal)
            ),
            "type mismatch",
        )?]));
    };

    if values
        .iter()
        .any(|value| !is_direct_const_literal_or_unit(value))
    {
        return Ok(None);
    }
    if values.len() != expected_elements.len() {
        return Ok(Some(vec![const_literal_diagnostic(
            owner.id,
            inputs,
            snapshot,
            value.span,
            sai_diagnostics::Code::TypeMismatch,
            format!(
                "expected a tuple with {} elements, found {}",
                expected_elements.len(),
                values.len()
            ),
            "type mismatch",
        )?]));
    }

    let mut diagnostics = Vec::new();
    for (expected_ty, value) in expected_elements.iter().zip(values) {
        let Some(mut field_diagnostics) = check_const_literal_leaf(
            owner,
            *expected_ty,
            value,
            type_paths,
            symbols,
            inputs,
            snapshot,
            target_cfg,
        )?
        else {
            return Ok(None);
        };
        diagnostics.append(&mut field_diagnostics);
    }
    Ok(Some(diagnostics))
}

fn is_direct_const_literal_or_unit(value: &HirExpr<'_>) -> bool {
    match value.kind {
        ExprKind::Lit(_) => true,
        ExprKind::Tuple(elements) => elements.is_empty(),
        _ => false,
    }
}

fn check_const_literal_leaf(
    owner: &HirOwner<'_>,
    ty: Ty<'_>,
    value: &HirExpr<'_>,
    type_paths: Option<&TypeOwnerPathResolution>,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
    target_cfg: &TargetCfg,
) -> Result<Option<Vec<Diagnostic>>, OwnerControlFlowResolutionError> {
    let Some(literal_type) = resolve_const_literal_type(ty, type_paths, symbols, inputs) else {
        return Ok(None);
    };
    check_const_literal_against_type(
        owner.id,
        literal_type,
        value,
        symbols,
        inputs,
        snapshot,
        target_cfg,
    )
}

fn local_enum_variant_literal_type(ty: &sai_ty::ty::Ty) -> Option<ConstLiteralType> {
    use sai_resolve::prelude::PrimTy;

    let primitive = match ty.kind() {
        sai_ty::ty::TyKind::Int(sai_ty::ty::IntTy::I8) => PrimTy::I8,
        sai_ty::ty::TyKind::Int(sai_ty::ty::IntTy::I16) => PrimTy::I16,
        sai_ty::ty::TyKind::Int(sai_ty::ty::IntTy::I32) => PrimTy::I32,
        sai_ty::ty::TyKind::Int(sai_ty::ty::IntTy::I64) => PrimTy::I64,
        sai_ty::ty::TyKind::Int(sai_ty::ty::IntTy::ISize) => PrimTy::ISize,
        sai_ty::ty::TyKind::Uint(sai_ty::ty::UintTy::U8) => PrimTy::U8,
        sai_ty::ty::TyKind::Uint(sai_ty::ty::UintTy::U16) => PrimTy::U16,
        sai_ty::ty::TyKind::Uint(sai_ty::ty::UintTy::U32) => PrimTy::U32,
        sai_ty::ty::TyKind::Uint(sai_ty::ty::UintTy::U64) => PrimTy::U64,
        sai_ty::ty::TyKind::Uint(sai_ty::ty::UintTy::USize) => PrimTy::USize,
        sai_ty::ty::TyKind::Float(sai_ty::ty::FloatTy::F32) => PrimTy::F32,
        sai_ty::ty::TyKind::Float(sai_ty::ty::FloatTy::F64) => PrimTy::F64,
        sai_ty::ty::TyKind::Bool => PrimTy::Bool,
        sai_ty::ty::TyKind::Byte => PrimTy::Byte,
        sai_ty::ty::TyKind::Char => PrimTy::Char,
        sai_ty::ty::TyKind::Tuple(elements) if elements.is_empty() => {
            return Some(ConstLiteralType::Unit);
        }
        _ => return None,
    };
    Some(ConstLiteralType::Primitive(primitive))
}

fn local_enum_variant_parameter_primitive(
    value: &HirExpr<'_>,
    hir_owner: &HirOwner<'_>,
    body: &sai_hir::body::Body<'_>,
    locals: &LocalResolution,
    type_paths: Option<&TypeOwnerPathResolution>,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
) -> Option<sai_resolve::prelude::PrimTy> {
    let ExprKind::Path(path) = value.kind else {
        return None;
    };
    if path.root != PathRoot::Plain || path.segments.len() != 1 || path.segments[0].args.is_some() {
        return None;
    }
    let PathRes {
        base: Res::Local(binding),
        resolved_segments: 1,
        segment_count: 1,
    } = *locals.paths.get(&path.hir_id)?
    else {
        return None;
    };
    if !matches!(
        locals.bindings.get(&binding)?.kind,
        BindingKind::Param | BindingKind::VarParam
    ) {
        return None;
    }

    let parameter_index = body
        .params
        .iter()
        .position(|parameter| parameter.binding == binding)?;
    let OwnerNode::Item(item) = hir_owner.node else {
        return None;
    };
    let ItemKind::Fn { sig, .. } = item.kind else {
        return None;
    };
    if sig.params.len() != body.params.len() {
        return None;
    }
    let body_parameter = body.params.get(parameter_index)?;
    let signature_parameter = sig.params.get(parameter_index)?;
    if signature_parameter.is_self
        || body_parameter.mutable != signature_parameter.mutable
        || body_parameter.name.map(|name| name.sym) != signature_parameter.name.map(|name| name.sym)
    {
        return None;
    }

    match resolve_function_direct_type(*signature_parameter.ty, type_paths, symbols, inputs)? {
        FunctionDirectType::Primitive(primitive) => Some(primitive),
        FunctionDirectType::Str | FunctionDirectType::Unit => None,
    }
}

fn local_enum_variant_annotated_local_type(
    value: &HirExpr<'_>,
    body: &sai_hir::body::Body<'_>,
    locals: &LocalResolution,
    type_paths: Option<&TypeOwnerPathResolution>,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
) -> Option<ConstLiteralType> {
    let ExprKind::Path(path) = value.kind else {
        return None;
    };
    if path.root != PathRoot::Plain || path.segments.len() != 1 || path.segments[0].args.is_some() {
        return None;
    }
    let PathRes {
        base: Res::Local(binding),
        resolved_segments: 1,
        segment_count: 1,
    } = *locals.paths.get(&path.hir_id)?
    else {
        return None;
    };
    let binding_kind = locals.bindings.get(&binding)?.kind;
    if !matches!(binding_kind, BindingKind::Let | BindingKind::Var) {
        return None;
    }

    let ExprKind::Block(body_block) = body.value.kind else {
        return None;
    };
    let mut annotated_type = None;
    for statement in body_block.stmts {
        let StmtKind::Let {
            pat,
            ty: Some(ty),
            els: None,
            ..
        } = statement.kind
        else {
            continue;
        };
        let PatKind::Binding {
            mode,
            name,
            binding: declared_binding,
            sub: None,
        } = pat.kind
        else {
            continue;
        };
        if declared_binding != binding {
            continue;
        }
        if name.sym != path.segments[0].name.sym
            || !matches!(
                (binding_kind, mode),
                (BindingKind::Let, sai_hir::patterns::BindingMode::Value)
                    | (BindingKind::Var, sai_hir::patterns::BindingMode::Var)
            )
            || annotated_type.is_some()
        {
            return None;
        }
        annotated_type = Some(ty);
    }

    match resolve_function_direct_type(*annotated_type?, type_paths, symbols, inputs)? {
        FunctionDirectType::Primitive(primitive) => Some(ConstLiteralType::Primitive(primitive)),
        FunctionDirectType::Unit => Some(ConstLiteralType::Unit),
        FunctionDirectType::Str => None,
    }
}

fn local_enum_variant_annotated_local_primitive(
    value: &HirExpr<'_>,
    body: &sai_hir::body::Body<'_>,
    locals: &LocalResolution,
    type_paths: Option<&TypeOwnerPathResolution>,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
) -> Option<sai_resolve::prelude::PrimTy> {
    match local_enum_variant_annotated_local_type(value, body, locals, type_paths, symbols, inputs)?
    {
        ConstLiteralType::Primitive(primitive) => Some(primitive),
        ConstLiteralType::Str | ConstLiteralType::Unit => None,
    }
}

fn local_enum_variant_annotated_simple_tuple_local_annotation<'hir>(
    value: &HirExpr<'hir>,
    body: &sai_hir::body::Body<'hir>,
    locals: &LocalResolution,
) -> Option<&'hir sai_hir::types::Ty<'hir>> {
    let ExprKind::Path(path) = value.kind else {
        return None;
    };
    if path.root != PathRoot::Plain || path.segments.len() != 1 || path.segments[0].args.is_some() {
        return None;
    }
    let PathRes {
        base: Res::Local(binding),
        resolved_segments: 1,
        segment_count: 1,
    } = *locals.paths.get(&path.hir_id)?
    else {
        return None;
    };
    let local_binding = locals.bindings.get(&binding)?;
    let binding_kind = local_binding.kind;
    if !matches!(binding_kind, BindingKind::Let | BindingKind::Var)
        || local_binding.name != Some(path.segments[0].name.sym)
    {
        return None;
    }

    let ExprKind::Block(body_block) = body.value.kind else {
        return None;
    };

    enum Work<'hir> {
        Block(&'hir HirBlock<'hir>),
        Expr(&'hir HirExpr<'hir>),
        Stmt(&'hir Stmt<'hir>),
    }

    let mut annotation = None;
    let mut work = vec![Work::Block(body_block)];
    while let Some(next) = work.pop() {
        match next {
            Work::Block(block) => {
                if let Some(tail) = block.tail {
                    work.push(Work::Expr(tail));
                }
                work.extend(block.stmts.iter().rev().map(Work::Stmt));
            }
            Work::Stmt(statement) => match statement.kind {
                StmtKind::Let { pat, ty, init, els } => {
                    if let PatKind::Binding {
                        mode,
                        name,
                        binding: declared_binding,
                        sub: None,
                    } = pat.kind
                        && declared_binding == binding
                    {
                        let Some(ty) = ty else {
                            return None;
                        };
                        if els.is_some()
                            || name.sym != path.segments[0].name.sym
                            || !matches!(
                                (binding_kind, mode),
                                (BindingKind::Let, sai_hir::patterns::BindingMode::Value)
                                    | (BindingKind::Var, sai_hir::patterns::BindingMode::Var)
                            )
                            || annotation.is_some()
                        {
                            return None;
                        }
                        let sai_hir::types::TyKind::Tuple(elements) = ty.kind else {
                            return None;
                        };
                        if elements.is_empty() {
                            return None;
                        }
                        annotation = Some(ty);
                    }
                    // `let ... else` declarations remain out of this bounded
                    // projection, including declarations in their else block.
                    work.push(Work::Expr(init));
                }
                StmtKind::Assign { lhs, rhs } | StmtKind::AssignOp { lhs, rhs, .. } => {
                    work.push(Work::Expr(rhs));
                    work.push(Work::Expr(lhs));
                }
                StmtKind::Assert { cond, msg, .. } => {
                    if let Some(msg) = msg {
                        work.push(Work::Expr(msg));
                    }
                    work.push(Work::Expr(cond));
                }
                StmtKind::Expr(expr) => work.push(Work::Expr(expr)),
            },
            Work::Expr(expression) => match expression.kind {
                ExprKind::Field { base, .. }
                | ExprKind::TupleField { base, .. }
                | ExprKind::Unary(_, base)
                | ExprKind::Borrow(_, base)
                | ExprKind::Try(base)
                | ExprKind::Await(base) => work.push(Work::Expr(base)),
                ExprKind::Call { callee, args, base } => {
                    if let Some(base) = base {
                        work.push(Work::Expr(base));
                    }
                    work.extend(args.iter().rev().map(|argument| Work::Expr(&argument.expr)));
                    work.push(Work::Expr(callee));
                }
                ExprKind::Binary(_, left, right) | ExprKind::Index(left, right) => {
                    work.push(Work::Expr(right));
                    work.push(Work::Expr(left));
                }
                ExprKind::Range { start, end, .. } => {
                    if let Some(end) = end {
                        work.push(Work::Expr(end));
                    }
                    if let Some(start) = start {
                        work.push(Work::Expr(start));
                    }
                }
                ExprKind::Tuple(elements) | ExprKind::Array(elements) => {
                    work.extend(elements.iter().rev().map(Work::Expr));
                }
                ExprKind::Block(block)
                | ExprKind::Loop { body: block, .. }
                | ExprKind::Region { block, .. } => work.push(Work::Block(block)),
                ExprKind::If { cond, then, els } => {
                    if let Some(els) = els {
                        work.push(Work::Expr(els));
                    }
                    work.push(Work::Block(then));
                    work.push(Work::Expr(cond));
                }
                ExprKind::Match {
                    scrutinee, arms, ..
                } => {
                    for arm in arms.iter().rev() {
                        work.push(Work::Expr(&arm.body));
                        if let Some(guard) = arm.guard {
                            work.push(Work::Expr(guard));
                        }
                    }
                    work.push(Work::Expr(scrutinee));
                }
                ExprKind::Break { value, .. } | ExprKind::Return(value) => {
                    if let Some(value) = value {
                        work.push(Work::Expr(value));
                    }
                }
                ExprKind::FormatString(pieces) => {
                    for piece in pieces.iter().rev() {
                        if let FmtPiece::Arg { expr, .. } = piece {
                            work.push(Work::Expr(expr));
                        }
                    }
                }
                ExprKind::ContractOld { args, base } => {
                    if let Some(base) = base {
                        work.push(Work::Expr(base));
                    }
                    work.extend(args.iter().rev().map(|argument| Work::Expr(&argument.expr)));
                }
                ExprKind::AsCast { operand, .. } => work.push(Work::Expr(operand)),
                // These introduce nested body owners and are intentionally
                // outside the ordinary lexical-block search.
                ExprKind::AsyncBlock { .. } | ExprKind::Closure(_) => {}
                ExprKind::Lit(_)
                | ExprKind::Path(_)
                | ExprKind::ImplicitMember(_)
                | ExprKind::Continue { .. }
                | ExprKind::ContractResult
                | ExprKind::Err => {}
            },
        }
    }
    annotation
}

fn local_enum_variant_annotated_tuple_local_arity_mismatch(
    expected_type: &sai_ty::ty::Ty,
    annotation: &sai_hir::types::Ty<'_>,
) -> Option<(usize, usize)> {
    let mut pending = vec![(expected_type, annotation)];
    while let Some((expected_type, annotation)) = pending.pop() {
        let (
            sai_ty::ty::TyKind::Tuple(expected_elements),
            sai_hir::types::TyKind::Tuple(actual_elements),
        ) = (expected_type.kind(), annotation.kind)
        else {
            continue;
        };
        if expected_elements.is_empty() || actual_elements.is_empty() {
            continue;
        }
        if expected_elements.len() != actual_elements.len() {
            return Some((expected_elements.len(), actual_elements.len()));
        }
        pending.extend(
            expected_elements
                .iter()
                .zip(actual_elements)
                .rev()
                .map(|(expected, actual)| (expected, actual)),
        );
    }
    None
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum LocalEnumVariantAnnotatedTupleLocalMismatch {
    LeafType {
        expected: ConstLiteralType,
        actual: ConstLiteralType,
    },
    TupleAgainstScalar {
        expected: ConstLiteralType,
        actual_arity: usize,
    },
}

fn local_enum_variant_annotated_tuple_local_leaf_mismatch(
    expected_type: &sai_ty::ty::Ty,
    annotation: &sai_hir::types::Ty<'_>,
    type_paths: Option<&TypeOwnerPathResolution>,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
) -> Option<LocalEnumVariantAnnotatedTupleLocalMismatch> {
    let mut pending = vec![(expected_type, annotation)];
    while let Some((expected_type, annotation)) = pending.pop() {
        match (expected_type.kind(), annotation.kind) {
            (
                sai_ty::ty::TyKind::Tuple(expected_elements),
                sai_hir::types::TyKind::Tuple(actual_elements),
            ) if !expected_elements.is_empty() && !actual_elements.is_empty() => {
                // IR-946 owns tuple-shape diagnostics and must win over any
                // leaf mismatch, even when the leaf occurs earlier in source.
                if expected_elements.len() != actual_elements.len() {
                    return None;
                }
                pending.extend(
                    expected_elements
                        .iter()
                        .zip(actual_elements)
                        .rev()
                        .map(|(expected, actual)| (expected, actual)),
                );
                continue;
            }
            (sai_ty::ty::TyKind::Tuple(elements), _) if !elements.is_empty() => continue,
            (_, sai_hir::types::TyKind::Tuple(elements)) if !elements.is_empty() => {
                let Some(expected) = local_enum_variant_literal_type(expected_type) else {
                    continue;
                };
                if matches!(
                    expected,
                    ConstLiteralType::Primitive(_) | ConstLiteralType::Unit
                ) {
                    return Some(
                        LocalEnumVariantAnnotatedTupleLocalMismatch::TupleAgainstScalar {
                            expected,
                            actual_arity: elements.len(),
                        },
                    );
                }
                continue;
            }
            _ => {}
        }

        let Some(expected_leaf) = local_enum_variant_literal_type(expected_type) else {
            continue;
        };
        let Some(actual_leaf) =
            resolve_function_direct_type(*annotation, type_paths, symbols, inputs)
        else {
            continue;
        };
        let actual_leaf = match actual_leaf {
            FunctionDirectType::Primitive(primitive) => ConstLiteralType::Primitive(primitive),
            FunctionDirectType::Unit => ConstLiteralType::Unit,
            FunctionDirectType::Str => continue,
        };
        if !matches!(
            expected_leaf,
            ConstLiteralType::Primitive(_) | ConstLiteralType::Unit
        ) {
            continue;
        }
        if expected_leaf != actual_leaf {
            return Some(LocalEnumVariantAnnotatedTupleLocalMismatch::LeafType {
                expected: expected_leaf,
                actual: actual_leaf,
            });
        }
    }
    None
}

fn local_enum_variant_annotated_tuple_local_type(
    value: &HirExpr<'_>,
    body: &sai_hir::body::Body<'_>,
    locals: &LocalResolution,
    type_paths: Option<&TypeOwnerPathResolution>,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
) -> Option<ConstLiteralType> {
    let ExprKind::Path(path) = value.kind else {
        return None;
    };
    if path.root != PathRoot::Plain || path.segments.len() != 1 || path.segments[0].args.is_some() {
        return None;
    }
    let PathRes {
        base: Res::Local(binding),
        resolved_segments: 1,
        segment_count: 1,
    } = *locals.paths.get(&path.hir_id)?
    else {
        return None;
    };
    if !matches!(
        locals.bindings.get(&binding)?.kind,
        BindingKind::Pattern { .. }
    ) {
        return None;
    }

    let ExprKind::Block(body_block) = body.value.kind else {
        return None;
    };
    let mut annotated_type = None;
    for statement in body_block.stmts {
        let StmtKind::Let {
            pat,
            ty: Some(ty),
            els: None,
            ..
        } = statement.kind
        else {
            continue;
        };
        if !matches!(pat.kind, PatKind::Tuple(_)) {
            continue;
        }

        let mut target_type = None;
        if local_enum_variant_annotated_tuple_pattern_matches(
            pat,
            *ty,
            1,
            binding,
            path.segments[0].name.sym,
            locals,
            type_paths,
            symbols,
            inputs,
            &mut target_type,
        )
        .is_none()
        {
            continue;
        }
        let Some(target_type) = target_type else {
            continue;
        };
        if annotated_type.replace(target_type).is_some() {
            return None;
        }
    }
    annotated_type
}

fn local_enum_variant_annotated_tuple_pattern_matches(
    pattern: &HirPat<'_>,
    ty: Ty<'_>,
    tuple_depth: usize,
    target_binding: sai_hir::BindingId,
    target_name: Symbol,
    locals: &LocalResolution,
    type_paths: Option<&TypeOwnerPathResolution>,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
    target_type: &mut Option<ConstLiteralType>,
) -> Option<()> {
    use sai_hir::patterns::BindingMode;

    match (pattern.kind, ty.kind) {
        (PatKind::Tuple(patterns), TyKind::Tuple(types)) => {
            if tuple_depth > 3 || patterns.is_empty() || patterns.len() != types.len() {
                return None;
            }
            for (pattern, ty) in patterns.iter().zip(types) {
                local_enum_variant_annotated_tuple_pattern_matches(
                    pattern,
                    *ty,
                    tuple_depth + 1,
                    target_binding,
                    target_name,
                    locals,
                    type_paths,
                    symbols,
                    inputs,
                    target_type,
                )?;
            }
            Some(())
        }
        (PatKind::Wild, _) => matches!(
            resolve_function_direct_type(ty, type_paths, symbols, inputs),
            Some(FunctionDirectType::Primitive(_) | FunctionDirectType::Unit)
        )
        .then_some(()),
        (
            PatKind::Binding {
                mode,
                name,
                binding,
                sub: None,
            },
            _,
        ) => {
            let Some(leaf_type) = resolve_function_direct_type(ty, type_paths, symbols, inputs)
            else {
                return None;
            };
            let leaf_type = match leaf_type {
                FunctionDirectType::Primitive(primitive) => ConstLiteralType::Primitive(primitive),
                FunctionDirectType::Unit => ConstLiteralType::Unit,
                FunctionDirectType::Str => return None,
            };
            let local_binding = locals.bindings.get(&binding)?;
            let supported_mode = matches!(
                (local_binding.kind, mode),
                (BindingKind::Pattern { var: false }, BindingMode::Value)
                    | (BindingKind::Pattern { var: true }, BindingMode::Var)
            );
            if !supported_mode || local_binding.name != Some(name.sym) {
                return None;
            }
            if binding == target_binding {
                if name.sym != target_name || target_type.is_some() {
                    return None;
                }
                *target_type = Some(leaf_type);
            }
            Some(())
        }
        _ => None,
    }
}

fn local_enum_variant_unannotated_fixed_local_type(
    value: &HirExpr<'_>,
    body: &sai_hir::body::Body<'_>,
    locals: &LocalResolution,
) -> Option<ConstLiteralType> {
    let ExprKind::Path(path) = value.kind else {
        return None;
    };
    if path.root != PathRoot::Plain || path.segments.len() != 1 || path.segments[0].args.is_some() {
        return None;
    }
    let PathRes {
        base: Res::Local(binding),
        resolved_segments: 1,
        segment_count: 1,
    } = *locals.paths.get(&path.hir_id)?
    else {
        return None;
    };
    let binding_kind = locals.bindings.get(&binding)?.kind;
    if !matches!(
        binding_kind,
        BindingKind::Let | BindingKind::Var | BindingKind::Pattern { .. }
    ) {
        return None;
    }

    let ExprKind::Block(body_block) = body.value.kind else {
        return None;
    };
    let mut initializer = None;
    for statement in body_block.stmts {
        let StmtKind::Let {
            pat,
            ty: None,
            init,
            els: None,
        } = statement.kind
        else {
            continue;
        };
        let Some(binding_initializer) = local_enum_variant_simple_pattern_initializer(
            pat,
            init,
            binding,
            path.segments[0].name.sym,
            locals,
        ) else {
            continue;
        };
        if locals.bindings.get(&binding)?.kind != binding_kind || initializer.is_some() {
            return None;
        }
        initializer = Some(binding_initializer);
    }

    match initializer?.kind {
        ExprKind::Lit(Lit::Bool(_)) => Some(ConstLiteralType::Primitive(
            sai_resolve::prelude::PrimTy::Bool,
        )),
        ExprKind::Lit(Lit::Byte(_)) => Some(ConstLiteralType::Primitive(
            sai_resolve::prelude::PrimTy::Byte,
        )),
        ExprKind::Lit(Lit::Char(_)) => Some(ConstLiteralType::Primitive(
            sai_resolve::prelude::PrimTy::Char,
        )),
        ExprKind::Tuple(elements) if elements.is_empty() => Some(ConstLiteralType::Unit),
        _ => None,
    }
}

fn local_enum_variant_unannotated_fixed_let_var_type(
    value: &HirExpr<'_>,
    body: &sai_hir::body::Body<'_>,
    locals: &LocalResolution,
) -> Option<ConstLiteralType> {
    let ExprKind::Path(path) = value.kind else {
        return None;
    };
    let PathRes {
        base: Res::Local(binding),
        resolved_segments: 1,
        segment_count: 1,
    } = *locals.paths.get(&path.hir_id)?
    else {
        return None;
    };
    if !matches!(
        locals.bindings.get(&binding)?.kind,
        BindingKind::Let | BindingKind::Var
    ) {
        return None;
    }

    local_enum_variant_unannotated_fixed_local_type(value, body, locals)
}

fn local_enum_variant_unannotated_fixed_pattern_type(
    value: &HirExpr<'_>,
    body: &sai_hir::body::Body<'_>,
    locals: &LocalResolution,
) -> Option<ConstLiteralType> {
    let ExprKind::Path(path) = value.kind else {
        return None;
    };
    let PathRes {
        base: Res::Local(binding),
        resolved_segments: 1,
        segment_count: 1,
    } = *locals.paths.get(&path.hir_id)?
    else {
        return None;
    };
    if !matches!(
        locals.bindings.get(&binding)?.kind,
        BindingKind::Pattern { .. }
    ) {
        return None;
    }

    local_enum_variant_unannotated_fixed_local_type(value, body, locals)
}

fn local_enum_variant_simple_pattern_initializer<'hir>(
    pattern: &'hir HirPat<'hir>,
    initializer: &'hir HirExpr<'hir>,
    target_binding: sai_hir::BindingId,
    target_name: Symbol,
    locals: &LocalResolution,
) -> Option<&'hir HirExpr<'hir>> {
    use sai_hir::patterns::BindingMode;

    let binding_mode_is_supported =
        |binding: sai_hir::BindingId, mode: BindingMode, allow_pattern_binding: bool| {
            let kind = locals.bindings.get(&binding)?.kind;
            (matches!(
                (kind, mode),
                (BindingKind::Let, BindingMode::Value) | (BindingKind::Var, BindingMode::Var)
            ) || (allow_pattern_binding
                && matches!(
                    (kind, mode),
                    (BindingKind::Pattern { var: false }, BindingMode::Value)
                        | (BindingKind::Pattern { var: true }, BindingMode::Var)
                )))
            .then_some(())
        };

    match pattern.kind {
        PatKind::Binding {
            mode,
            name,
            binding,
            sub: None,
        } => {
            binding_mode_is_supported(binding, mode, false)?;
            (binding == target_binding && name.sym == target_name).then_some(initializer)
        }
        PatKind::Tuple(_) => {
            let mut binding_initializer = None;
            if local_enum_variant_fixed_tuple_pattern_matches(
                pattern,
                initializer,
                1,
                target_binding,
                target_name,
                locals,
                &mut binding_initializer,
            ) {
                binding_initializer
            } else {
                None
            }
        }
        _ => None,
    }
}

fn local_enum_variant_fixed_tuple_pattern_matches<'hir>(
    pattern: &'hir HirPat<'hir>,
    initializer: &'hir HirExpr<'hir>,
    tuple_depth: usize,
    target_binding: sai_hir::BindingId,
    target_name: Symbol,
    locals: &LocalResolution,
    binding_initializer: &mut Option<&'hir HirExpr<'hir>>,
) -> bool {
    use sai_hir::patterns::BindingMode;

    match pattern.kind {
        PatKind::Wild => local_enum_variant_fixed_tuple_initializer_leaf(initializer),
        PatKind::Binding {
            mode,
            name,
            binding,
            sub: None,
        } => {
            if !local_enum_variant_fixed_tuple_initializer_leaf(initializer) {
                return false;
            }
            let Some(kind) = locals.bindings.get(&binding).map(|binding| binding.kind) else {
                return false;
            };
            let supported_mode = matches!(
                (kind, mode),
                (BindingKind::Pattern { var: false }, BindingMode::Value)
                    | (BindingKind::Pattern { var: true }, BindingMode::Var)
            );
            if !supported_mode {
                return false;
            }
            if binding == target_binding {
                if name.sym != target_name || binding_initializer.is_some() {
                    return false;
                }
                *binding_initializer = Some(initializer);
            }
            true
        }
        PatKind::Tuple(patterns) => {
            if tuple_depth > 3 {
                return false;
            }
            let ExprKind::Tuple(values) = initializer.kind else {
                return false;
            };
            if patterns.len() != values.len() {
                return false;
            }
            patterns.iter().zip(values).all(|(pattern, value)| {
                local_enum_variant_fixed_tuple_pattern_matches(
                    pattern,
                    value,
                    tuple_depth + 1,
                    target_binding,
                    target_name,
                    locals,
                    binding_initializer,
                )
            })
        }
        _ => false,
    }
}

fn local_enum_variant_fixed_literal_description(value: &HirExpr<'_>) -> Option<&'static str> {
    match value.kind {
        ExprKind::Lit(Lit::Bool(_)) => Some("a Bool literal"),
        ExprKind::Lit(Lit::Byte(_)) => Some("a byte literal"),
        ExprKind::Lit(Lit::Char(_)) => Some("a character literal"),
        ExprKind::Tuple(elements) if elements.is_empty() => Some("unit"),
        _ => None,
    }
}

fn local_enum_variant_fixed_tuple_initializer_leaf(value: &HirExpr<'_>) -> bool {
    local_enum_variant_fixed_literal_description(value).is_some()
}

fn check_local_enum_variant_parameter_argument(
    owner: OwnerId,
    expected_type: &sai_ty::ty::Ty,
    value: &HirExpr<'_>,
    hir_owner: &HirOwner<'_>,
    body: &sai_hir::body::Body<'_>,
    locals: &LocalResolution,
    type_paths: Option<&TypeOwnerPathResolution>,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
) -> Result<Option<Diagnostic>, OwnerControlFlowResolutionError> {
    let Some(expected) = local_enum_variant_literal_type(expected_type) else {
        return Ok(None);
    };
    if let ConstLiteralType::Primitive(expected_primitive) = expected {
        let Some(actual) = local_enum_variant_parameter_primitive(
            value, hir_owner, body, locals, type_paths, symbols, inputs,
        )
        .or_else(|| {
            local_enum_variant_annotated_local_primitive(
                value, body, locals, type_paths, symbols, inputs,
            )
        }) else {
            // Tuple-pattern locals are handled below because these earlier
            // path projections only recognize single primitive bindings.
            return check_local_enum_variant_annotated_tuple_argument(
                owner, expected, value, body, locals, type_paths, symbols, inputs, snapshot,
            );
        };
        if expected_primitive == actual {
            return Ok(None);
        }
        return Ok(Some(const_literal_diagnostic(
            owner,
            inputs,
            snapshot,
            value.span,
            sai_diagnostics::Code::TypeMismatch,
            format!(
                "expected `{}`, found `{}`",
                const_primitive_name(expected_primitive),
                const_primitive_name(actual)
            ),
            "type mismatch",
        )?));
    }
    check_local_enum_variant_annotated_tuple_argument(
        owner, expected, value, body, locals, type_paths, symbols, inputs, snapshot,
    )
}

fn check_local_enum_variant_annotated_tuple_argument(
    owner: OwnerId,
    expected: ConstLiteralType,
    value: &HirExpr<'_>,
    body: &sai_hir::body::Body<'_>,
    locals: &LocalResolution,
    type_paths: Option<&TypeOwnerPathResolution>,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
) -> Result<Option<Diagnostic>, OwnerControlFlowResolutionError> {
    let Some(actual) = local_enum_variant_annotated_tuple_local_type(
        value, body, locals, type_paths, symbols, inputs,
    ) else {
        return Ok(None);
    };
    if expected == actual {
        return Ok(None);
    }
    Ok(Some(const_literal_diagnostic(
        owner,
        inputs,
        snapshot,
        value.span,
        sai_diagnostics::Code::TypeMismatch,
        format!(
            "expected `{}`, found `{}`",
            local_enum_variant_type_name(expected),
            local_enum_variant_type_name(actual)
        ),
        "type mismatch",
    )?))
}

fn check_local_enum_variant_unannotated_local_argument(
    owner: OwnerId,
    expected_type: &sai_ty::ty::Ty,
    value: &HirExpr<'_>,
    body: &sai_hir::body::Body<'_>,
    locals: &LocalResolution,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
) -> Result<Option<Diagnostic>, OwnerControlFlowResolutionError> {
    let Some(expected) = local_enum_variant_literal_type(expected_type) else {
        return Ok(None);
    };
    let Some(actual) = local_enum_variant_unannotated_fixed_local_type(value, body, locals) else {
        return Ok(None);
    };
    if expected == actual {
        return Ok(None);
    }
    Ok(Some(const_literal_diagnostic(
        owner,
        inputs,
        snapshot,
        value.span,
        sai_diagnostics::Code::TypeMismatch,
        format!(
            "expected `{}`, found `{}`",
            local_enum_variant_type_name(expected),
            local_enum_variant_type_name(actual)
        ),
        "type mismatch",
    )?))
}

fn expected_tuple_literal_mismatch(
    expected_arity: usize,
    actual_literal_description: &str,
) -> String {
    format!("expected tuple of arity {expected_arity}, found {actual_literal_description}")
}

fn expected_tuple_primitive_mismatch(
    expected_arity: usize,
    actual_primitive: sai_resolve::prelude::PrimTy,
) -> String {
    format!(
        "expected tuple of arity {expected_arity}, found `{}`",
        const_primitive_name(actual_primitive)
    )
}

fn expected_tuple_local_type_mismatch(
    expected_arity: usize,
    actual_type: ConstLiteralType,
) -> String {
    format!(
        "expected tuple of arity {expected_arity}, found `{}`",
        local_enum_variant_type_name(actual_type)
    )
}

fn local_enum_variant_type_name(literal_type: ConstLiteralType) -> &'static str {
    match literal_type {
        ConstLiteralType::Primitive(primitive) => const_primitive_name(primitive),
        ConstLiteralType::Str => "Str",
        ConstLiteralType::Unit => "()",
    }
}

fn check_local_enum_variant_literal_argument(
    owner: OwnerId,
    expected_type: &sai_ty::ty::Ty,
    value: &HirExpr<'_>,
    hir_owner: &HirOwner<'_>,
    body: &sai_hir::body::Body<'_>,
    locals: &LocalResolution,
    type_paths: Option<&TypeOwnerPathResolution>,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
    target_cfg: &TargetCfg,
) -> Result<Vec<Diagnostic>, OwnerControlFlowResolutionError> {
    let mut pending = vec![(expected_type, value)];
    let mut diagnostics = Vec::new();

    while let Some((expected_type, value)) = pending.pop() {
        if let sai_ty::ty::TyKind::Tuple(expected_elements) = expected_type.kind()
            && !expected_elements.is_empty()
            && let Some(actual_description) = local_enum_variant_fixed_literal_description(value)
        {
            diagnostics.push(const_literal_diagnostic(
                owner,
                inputs,
                snapshot,
                value.span,
                sai_diagnostics::Code::TypeMismatch,
                expected_tuple_literal_mismatch(expected_elements.len(), actual_description),
                "type mismatch",
            )?);
            continue;
        }

        if let sai_ty::ty::TyKind::Tuple(expected_elements) = expected_type.kind()
            && !expected_elements.is_empty()
            && let Some(annotation) =
                local_enum_variant_annotated_simple_tuple_local_annotation(value, body, locals)
            && let Some((expected_arity, actual_arity)) =
                local_enum_variant_annotated_tuple_local_arity_mismatch(expected_type, annotation)
        {
            diagnostics.push(const_literal_diagnostic(
                owner,
                inputs,
                snapshot,
                value.span,
                sai_diagnostics::Code::TypeMismatch,
                format!(
                    "expected tuple of arity {}, found tuple of arity {}",
                    expected_arity, actual_arity
                ),
                "type mismatch",
            )?);
            continue;
        }

        if let Some(annotation) =
            local_enum_variant_annotated_simple_tuple_local_annotation(value, body, locals)
            && let Some(mismatch) = local_enum_variant_annotated_tuple_local_leaf_mismatch(
                expected_type,
                annotation,
                type_paths,
                symbols,
                inputs,
            )
        {
            let message = match mismatch {
                LocalEnumVariantAnnotatedTupleLocalMismatch::LeafType { expected, actual } => {
                    format!(
                        "expected `{}`, found `{}`",
                        local_enum_variant_type_name(expected),
                        local_enum_variant_type_name(actual)
                    )
                }
                LocalEnumVariantAnnotatedTupleLocalMismatch::TupleAgainstScalar {
                    expected,
                    actual_arity,
                } => format!(
                    "expected `{}`, found tuple of arity {}",
                    local_enum_variant_type_name(expected),
                    actual_arity
                ),
            };
            diagnostics.push(const_literal_diagnostic(
                owner,
                inputs,
                snapshot,
                value.span,
                sai_diagnostics::Code::TypeMismatch,
                message,
                "type mismatch",
            )?);
            continue;
        }

        if let sai_ty::ty::TyKind::Tuple(expected_elements) = expected_type.kind()
            && !expected_elements.is_empty()
            && let Some(ConstLiteralType::Unit) = local_enum_variant_annotated_local_type(
                value, body, locals, type_paths, symbols, inputs,
            )
        {
            diagnostics.push(const_literal_diagnostic(
                owner,
                inputs,
                snapshot,
                value.span,
                sai_diagnostics::Code::TypeMismatch,
                expected_tuple_local_type_mismatch(expected_elements.len(), ConstLiteralType::Unit),
                "type mismatch",
            )?);
            continue;
        }

        if let sai_ty::ty::TyKind::Tuple(expected_elements) = expected_type.kind()
            && !expected_elements.is_empty()
            && let Some(actual_primitive) = local_enum_variant_parameter_primitive(
                value, hir_owner, body, locals, type_paths, symbols, inputs,
            )
            .or_else(|| {
                local_enum_variant_annotated_local_primitive(
                    value, body, locals, type_paths, symbols, inputs,
                )
            })
        {
            diagnostics.push(const_literal_diagnostic(
                owner,
                inputs,
                snapshot,
                value.span,
                sai_diagnostics::Code::TypeMismatch,
                expected_tuple_primitive_mismatch(expected_elements.len(), actual_primitive),
                "type mismatch",
            )?);
            continue;
        }

        if let sai_ty::ty::TyKind::Tuple(expected_elements) = expected_type.kind()
            && !expected_elements.is_empty()
            && let Some(actual_type) =
                local_enum_variant_unannotated_fixed_let_var_type(value, body, locals)
                    .or_else(|| {
                        local_enum_variant_unannotated_fixed_pattern_type(value, body, locals)
                    })
                    .or_else(|| {
                        local_enum_variant_annotated_tuple_local_type(
                            value, body, locals, type_paths, symbols, inputs,
                        )
                    })
        {
            diagnostics.push(const_literal_diagnostic(
                owner,
                inputs,
                snapshot,
                value.span,
                sai_diagnostics::Code::TypeMismatch,
                expected_tuple_local_type_mismatch(expected_elements.len(), actual_type),
                "type mismatch",
            )?);
            continue;
        }

        if let (sai_ty::ty::TyKind::Tuple(expected_elements), ExprKind::Tuple(values)) =
            (expected_type.kind(), value.kind)
        {
            if expected_elements.is_empty() {
                // An empty tuple type is unit. Let the existing scalar literal
                // projection below handle a nonempty tuple expression here.
            } else if values.is_empty() {
                // Empty tuple expressions are unit, outside tuple shape checks.
                continue;
            } else {
                if expected_elements.len() == values.len() {
                    pending.extend(
                        expected_elements
                            .iter()
                            .zip(values.iter())
                            .rev()
                            .map(|(expected, value)| (expected, value)),
                    );
                } else {
                    diagnostics.push(const_literal_diagnostic(
                        owner,
                        inputs,
                        snapshot,
                        value.span,
                        sai_diagnostics::Code::TypeMismatch,
                        format!(
                            "expected tuple of arity {}, found tuple of arity {}",
                            expected_elements.len(),
                            values.len()
                        ),
                        "type mismatch",
                    )?);
                }
                continue;
            }
        }

        let Some(literal_type) = local_enum_variant_literal_type(expected_type) else {
            continue;
        };
        if let ExprKind::Tuple(values) = value.kind
            && !values.is_empty()
            && matches!(
                literal_type,
                ConstLiteralType::Primitive(_) | ConstLiteralType::Unit
            )
        {
            diagnostics.push(const_literal_diagnostic(
                owner,
                inputs,
                snapshot,
                value.span,
                sai_diagnostics::Code::TypeMismatch,
                format!(
                    "expected `{}`, found tuple of arity {}",
                    local_enum_variant_type_name(literal_type),
                    values.len()
                ),
                "type mismatch",
            )?);
            continue;
        }
        if let Some(mut literal_diagnostics) = check_const_literal_against_type(
            owner,
            literal_type,
            value,
            symbols,
            inputs,
            snapshot,
            target_cfg,
        )? {
            diagnostics.append(&mut literal_diagnostics);
        }
        if let Some(diagnostic) = check_local_enum_variant_parameter_argument(
            owner,
            expected_type,
            value,
            hir_owner,
            body,
            locals,
            type_paths,
            symbols,
            inputs,
            snapshot,
        )? {
            diagnostics.push(diagnostic);
        }
        if let Some(diagnostic) = check_local_enum_variant_unannotated_local_argument(
            owner,
            expected_type,
            value,
            body,
            locals,
            inputs,
            snapshot,
        )? {
            diagnostics.push(diagnostic);
        }
    }

    Ok(diagnostics)
}

fn check_const_literal_against_type(
    owner: OwnerId,
    literal_type: ConstLiteralType,
    value: &HirExpr<'_>,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
    target_cfg: &TargetCfg,
) -> Result<Option<Vec<Diagnostic>>, OwnerControlFlowResolutionError> {
    let literal = match value.kind {
        ExprKind::Lit(literal) => Some(literal),
        ExprKind::Tuple(elements) if elements.is_empty() => None,
        _ => return Ok(None),
    };

    let mismatch = |expected: &str, found: &str| {
        const_literal_diagnostic(
            owner,
            inputs,
            snapshot,
            value.span,
            sai_diagnostics::Code::TypeMismatch,
            format!("expected `{expected}`, found {found}"),
            "type mismatch",
        )
    };

    let Some(literal) = literal else {
        let diagnostic = match literal_type {
            ConstLiteralType::Unit => None,
            ConstLiteralType::Primitive(primitive) => {
                Some(mismatch(const_primitive_name(primitive), "unit")?)
            }
            ConstLiteralType::Str => Some(mismatch("Str", "unit")?),
        };
        return Ok(Some(diagnostic.into_iter().collect()));
    };

    let diagnostics = match literal_type {
        ConstLiteralType::Unit => vec![const_literal_diagnostic(
            owner,
            inputs,
            snapshot,
            value.span,
            sai_diagnostics::Code::TypeMismatch,
            format!("expected `()`, found {}", const_literal_found_type(literal)),
            "type mismatch",
        )?],
        ConstLiteralType::Str => match literal {
            Lit::Str(_) => Vec::new(),
            literal => vec![mismatch("Str", const_literal_found_type(literal))?],
        },
        ConstLiteralType::Primitive(primitive) => {
            match sai_ty::typeck::literal::check_primitive_literal(
                primitive,
                literal,
                symbols,
                target_cfg.pointer_width(),
            ) {
                sai_ty::typeck::literal::PrimitiveLiteralResult::Match => Vec::new(),
                sai_ty::typeck::literal::PrimitiveLiteralResult::TypeMismatch => vec![mismatch(
                    const_primitive_name(primitive),
                    const_literal_found_type(literal),
                )?],
                sai_ty::typeck::literal::PrimitiveLiteralResult::OutOfRange => {
                    let label = if matches!(literal, Lit::Int { .. }) {
                        "integer"
                    } else {
                        "floating-point"
                    };
                    vec![const_literal_diagnostic(
                        owner,
                        inputs,
                        snapshot,
                        value.span,
                        sai_diagnostics::Code::LiteralOutOfRange,
                        format!(
                            "{label} literal is out of range for `{}`",
                            const_primitive_name(primitive)
                        ),
                        "literal out of range",
                    )?]
                }
            }
        }
    };
    Ok(Some(diagnostics))
}

fn is_deferred_canonical_str_path(
    path: HirPath<'_>,
    type_paths: &TypeOwnerPathResolution,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
) -> bool {
    if path.root != PathRoot::Plain || path.segments.len() != 1 || path.segments[0].args.is_some() {
        return false;
    }

    let symbol = path.segments[0].name.sym;
    if symbols.resolve(symbol).ok().as_deref() != Some("Str")
        || !type_paths
            .deferred_paths()
            .iter()
            .any(|deferred| deferred.hir_id == path.hir_id && deferred.name == symbol)
    {
        return false;
    }

    let canonical_str = CANONICAL_PRELUDE_ITEMS.iter().any(|item| {
        item.name == "Str"
            && item.path.package == "sai:core"
            && item.path.kind == CanonicalPreludeKind::Type
            && matches!(
                item.path.segments,
                [
                    CanonicalPreludeSegment::Module("str"),
                    CanonicalPreludeSegment::Type("Str")
                ]
            )
    });
    if !canonical_str {
        return false;
    }

    let range = path.span.range;
    inputs
        .source
        .text()
        .get(range.start().to_usize()..range.end().to_usize())
        == Some("Str")
}

fn is_supported_const_name_convention(name: &str, written_name: &str) -> bool {
    !written_name.starts_with("r#")
        && !name.is_empty()
        && name.chars().all(|character| {
            character == '_' || character.is_ascii_uppercase() || character.is_ascii_digit()
        })
}

fn is_supported_const_literal_primitive(primitive: sai_resolve::prelude::PrimTy) -> bool {
    sai_ty::typeck::literal::supports_primitive_literal(primitive)
}

fn is_integer_primitive(primitive: sai_resolve::prelude::PrimTy) -> bool {
    sai_ty::typeck::literal::is_integer_primitive(primitive)
}

fn const_primitive_name(primitive: sai_resolve::prelude::PrimTy) -> &'static str {
    match primitive {
        sai_resolve::prelude::PrimTy::I8 => "I8",
        sai_resolve::prelude::PrimTy::I16 => "I16",
        sai_resolve::prelude::PrimTy::I32 => "I32",
        sai_resolve::prelude::PrimTy::I64 => "I64",
        sai_resolve::prelude::PrimTy::U8 => "U8",
        sai_resolve::prelude::PrimTy::U16 => "U16",
        sai_resolve::prelude::PrimTy::U32 => "U32",
        sai_resolve::prelude::PrimTy::U64 => "U64",
        sai_resolve::prelude::PrimTy::ISize => "ISize",
        sai_resolve::prelude::PrimTy::USize => "USize",
        sai_resolve::prelude::PrimTy::F32 => "F32",
        sai_resolve::prelude::PrimTy::F64 => "F64",
        sai_resolve::prelude::PrimTy::Bool => "Bool",
        sai_resolve::prelude::PrimTy::Byte => "Byte",
        sai_resolve::prelude::PrimTy::Char => "Char",
        sai_resolve::prelude::PrimTy::Never => "Never",
        sai_resolve::prelude::PrimTy::Array => "Array",
    }
}

fn const_literal_found_type(literal: Lit<'_>) -> &'static str {
    match literal {
        Lit::Int { .. } => "an integer literal",
        Lit::Float { .. } => "a floating-point literal",
        Lit::Str(_) => "a string literal",
        Lit::ByteStr(_) => "a byte string literal",
        Lit::Char(_) => "a character literal",
        Lit::Byte(_) => "a byte literal",
        Lit::Bool(_) => "a Bool literal",
    }
}

fn const_literal_diagnostic(
    owner: OwnerId,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
    span: sai_hir::Span,
    code: sai_diagnostics::Code,
    message: String,
    primary_label: &str,
) -> Result<Diagnostic, OwnerControlFlowResolutionError> {
    let location = sai_diagnostics::Location::from_decoded_source(
        inputs.source_ref.clone(),
        sai_diagnostics::Span::new(span.file, span.range),
        &inputs.source,
    )
    .ok_or(OwnerControlFlowResolutionError::InvalidSourceLocation(
        owner,
    ))?;
    let mut diagnostic = Diagnostic::new(
        code,
        sai_diagnostics::Severity::Error,
        message,
        Some(location),
    );
    diagnostic.primary_label = primary_label.to_owned();
    diagnostic.package = inputs.source_ref.package.clone();
    diagnostic
        .with_workspace_snapshot(snapshot)
        .map_err(|_| OwnerControlFlowResolutionError::InvalidSourceLocation(owner))
}

fn repr_discriminant_ty(repr: ReprAttr) -> sai_ty::adt::IntTy {
    use sai_hir::attrs::ReprInteger;
    use sai_ty::adt::IntTy;

    match repr {
        ReprAttr::C => IntTy::I32,
        ReprAttr::Integer(ReprInteger::I8) => IntTy::I8,
        ReprAttr::Integer(ReprInteger::I16) => IntTy::I16,
        ReprAttr::Integer(ReprInteger::I32) => IntTy::I32,
        ReprAttr::Integer(ReprInteger::I64) => IntTy::I64,
        ReprAttr::Integer(ReprInteger::U8) => IntTy::U8,
        ReprAttr::Integer(ReprInteger::U16) => IntTy::U16,
        ReprAttr::Integer(ReprInteger::U32) => IntTy::U32,
        ReprAttr::Integer(ReprInteger::U64) => IntTy::U64,
    }
}

fn local_enum_discriminant_diagnostic(
    owner: OwnerId,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
    variants: &[sai_hir::items::Variant<'_>],
    issue: &LocalEnumDiscriminantIssue,
    discr_ty: sai_ty::adt::IntTy,
    symbols: &Interner,
) -> Result<Diagnostic, OwnerControlFlowResolutionError> {
    let variant = variants
        .iter()
        .find(|variant| variant.def_id.to_def_id() == issue.variant())
        .ok_or(OwnerControlFlowResolutionError::InvalidSourceLocation(
            owner,
        ))?;
    let (code, message, label, previous_variant) = match issue.kind() {
        LocalEnumDiscriminantIssueKind::OutOfRange => (
            sai_diagnostics::Code::DiscriminantOutOfRange,
            format!(
                "enum discriminant {} is outside the range of {:?}",
                issue.value(),
                discr_ty
            ),
            "discriminant is outside the representation range",
            None,
        ),
        LocalEnumDiscriminantIssueKind::Duplicate { previous_variant } => {
            let previous = variants
                .iter()
                .find(|variant| variant.def_id.to_def_id() == previous_variant)
                .ok_or(OwnerControlFlowResolutionError::InvalidSourceLocation(
                    owner,
                ))?;
            let previous_name = symbols
                .resolve(previous.name.sym)
                .map_err(OwnerControlFlowResolutionError::SymbolLookup)?
                .to_string();
            (
                sai_diagnostics::Code::DuplicateDiscriminant,
                format!(
                    "enum discriminant {} duplicates earlier variant `{}`",
                    issue.value(),
                    previous_name
                ),
                "duplicate discriminant",
                Some((previous.span, previous_name)),
            )
        }
    };
    let mut diagnostic =
        const_literal_diagnostic(owner, inputs, snapshot, variant.span, code, message, label)?;
    if let Some((previous_span, previous_name)) = previous_variant {
        let location = sai_diagnostics::Location::from_decoded_source(
            inputs.source_ref.clone(),
            sai_diagnostics::Span::new(previous_span.file, previous_span.range),
            &inputs.source,
        )
        .ok_or(OwnerControlFlowResolutionError::InvalidSourceLocation(
            owner,
        ))?;
        diagnostic
            .push_related(Related::DeclaredHere {
                location,
                what: format!("earlier variant `{previous_name}` declared here"),
            })
            .map_err(|_| OwnerControlFlowResolutionError::InvalidSourceLocation(owner))?;
    }
    Ok(diagnostic)
}

/// Per-owner path results tagged with their package-collection provenance.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ConstOwnerResolutions {
    snapshot_id: WorkspaceSnapshotId,
    target_cfg: TargetCfg,
    collection_input_fingerprint: Fingerprint,
    member_scope_closure_fingerprint: Option<Fingerprint>,
    wit_view_closure_fingerprint: Option<Fingerprint>,
    owners: Vec<ConstOwnerResolution>,
    session_token: SessionToken,
}

impl ConstOwnerResolutions {
    pub const fn snapshot_id(&self) -> WorkspaceSnapshotId {
        self.snapshot_id
    }

    pub fn matches_snapshot(&self, snapshot: &WorkspaceSnapshot) -> bool {
        self.snapshot_id == snapshot.id()
    }

    pub fn matches_collection(&self, collection: &Phase1PackageScopesCollection) -> bool {
        self.session_token == collection.session_token
            && self.snapshot_id == collection.snapshot_id
            && self.target_cfg == collection.target_cfg
            && self.collection_input_fingerprint == collection.input_fingerprint
    }

    pub fn matches_member_scopes(
        &self,
        collection: &Phase1PackageScopesCollection,
        member_scopes: &Phase1ActiveSourceMemberScopes,
    ) -> bool {
        self.matches_collection(collection)
            && member_scopes.matches_collection(collection)
            && self.member_scope_closure_fingerprint == Some(member_scopes.closure_fingerprint)
    }

    pub const fn member_scope_closure_fingerprint(&self) -> Option<Fingerprint> {
        self.member_scope_closure_fingerprint
    }

    pub fn matches_wit_view_scopes(
        &self,
        collection: &Phase1PackageScopesCollection,
        wit_view_scopes: &Phase1ActiveWitViewScopes,
    ) -> bool {
        self.matches_collection(collection)
            && wit_view_scopes.matches_collection(collection)
            && self.wit_view_closure_fingerprint == Some(wit_view_scopes.closure_fingerprint)
    }

    pub const fn wit_view_closure_fingerprint(&self) -> Option<Fingerprint> {
        self.wit_view_closure_fingerprint
    }

    pub fn target_cfg(&self) -> &TargetCfg {
        &self.target_cfg
    }

    pub fn owners(&self) -> &[ConstOwnerResolution] {
        &self.owners
    }
}

/// Failure while lowering or resolving a current-snapshot HIR owner.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum OwnerControlFlowResolutionError {
    Query(QueryError),
    PrimitivePrelude(PrimitivePreludeBuildError),
    SessionMismatch,
    SnapshotMismatch,
    ModuleTreeMismatch,
    WorldReferenceCollectionMismatch,
    ModuleMemberScopes(Phase1ModuleMemberScopeError),
    TestAnalysisDisabled,
    MissingSnapshotFile(FileId),
    Parse(ParseQueryError),
    ItemTree(ItemTreeQueryError),
    TargetFilter(TargetFilterError),
    DefPathInterner(DefPathInternerError),
    SymbolLookup(LookupError),
    PackageId(PackageIdError),
    MissingDefPath(OwnerId),
    MissingTargetDefPath(DefId),
    DuplicateFunctionSignatureOwnerDefId(DefId),
    MissingInterfaceImplTarget(DefId),
    WorldElaboration(sai_resolve::WorldElaborationError),
    ExportWorldQuery(ExportWorldQueryError),
    ExportWorldSelectionMismatch,
    MissingExportWorldLocation,
    InterfaceImplDiagnosticSourceMismatch {
        file_path: Option<String>,
    },
    DescriptorNotInCurrentTarget {
        owner: OwnerId,
        file: FileId,
    },
    MissingSourcePackageIdentity {
        owner: OwnerId,
        file: FileId,
        package_key: String,
    },
    LocalEnumVariantPathTypeInvariant {
        field: HirId,
        enum_owner: OwnerId,
        enum_def: DefId,
        variant: DefId,
    },
    TopLevelOwnerDescriptorMismatch {
        owner: OwnerId,
        file: FileId,
    },
    TopLevelOwnerKindMismatch {
        owner: OwnerId,
        file: FileId,
        descriptor: TopLevelOwnerKind,
        current: ItemTreeKind,
    },
    MissingModuleScope(FileId),
    MissingRootModuleScope,
    MissingInterfaceScope(OwnerId),
    MissingImportBinding {
        owner: OwnerId,
        import: ImportIndex,
    },
    MissingTestOnlyUseSyntax {
        owner: OwnerId,
        import: ImportIndex,
    },
    MissingEffectDeclarationSyntax(OwnerId),
    MissingWorldItemSyntax {
        world: OwnerId,
        item: OwnerId,
    },
    MissingRefinedTypeSyntax(OwnerId),
    MissingInterfaceFunctionSyntax(OwnerId),
    InvalidSourceLocation(OwnerId),
    Lowering(HirLoweringError),
    Labels(LabelResolutionError),
    Locals(LocalResolutionError),
    WorldField(sai_resolve::WorldFieldResolutionError),
}

/// Compatibility name for the original function label adapter error.
pub type FunctionOwnerResolutionError = OwnerControlFlowResolutionError;

/// Compatibility name for the original function label adapter error.
pub type FunctionOwnerLabelResolutionError = FunctionOwnerResolutionError;

struct CurrentOwnerInputs {
    source: Arc<SourceFile>,
    root: SyntaxNode,
    ast_ids: ast::AstIdMap,
    filtered_item_tree: ItemTree,
    validated_attrs: BTreeMap<ast::ErasedAstId, ValidatedAttrs>,
    retained_item_kinds: HashMap<ast::ErasedAstId, ItemTreeKind>,
    accepted_flags_attributes: HashSet<ast::ErasedAstId>,
    source_ref: SourceRef,
}

fn index_top_level_owner_descriptors(
    collection: &Phase1PackageScopesCollection,
) -> HashMap<OwnerId, Option<TopLevelOwnerDescriptor>> {
    index_top_level_owner_descriptors_in_scopes(&collection.scopes)
}

fn index_top_level_owner_descriptors_in_scopes(
    scopes: &Phase1PackageScopes,
) -> HashMap<OwnerId, Option<TopLevelOwnerDescriptor>> {
    let mut index = HashMap::with_capacity(scopes.top_level_owners.len());
    for descriptor in &scopes.top_level_owners {
        if let Some(indexed) = index.get_mut(&descriptor.owner) {
            *indexed = None;
        } else {
            index.insert(descriptor.owner, Some(*descriptor));
        }
    }
    index
}

fn find_top_level_owner_descriptor(
    index: &HashMap<OwnerId, Option<TopLevelOwnerDescriptor>>,
    owner: OwnerId,
    file: FileId,
    item_id: ast::ErasedAstId,
    kind: TopLevelOwnerKind,
) -> Result<TopLevelOwnerDescriptor, OwnerControlFlowResolutionError> {
    match index.get(&owner).and_then(|descriptor| *descriptor) {
        Some(descriptor)
            if descriptor.file == file
                && descriptor.item_id == item_id
                && descriptor.kind == kind =>
        {
            Ok(descriptor)
        }
        _ => Err(OwnerControlFlowResolutionError::TopLevelOwnerDescriptorMismatch { owner, file }),
    }
}

fn item_tree_kind_for_top_level_owner(kind: TopLevelOwnerKind) -> ItemTreeKind {
    match kind {
        TopLevelOwnerKind::Function => ItemTreeKind::Function,
        TopLevelOwnerKind::Struct => ItemTreeKind::Struct,
        TopLevelOwnerKind::Alias => ItemTreeKind::Alias,
        TopLevelOwnerKind::Refined => ItemTreeKind::Refined,
        TopLevelOwnerKind::Enum => ItemTreeKind::Enum,
        TopLevelOwnerKind::Distinct => ItemTreeKind::Distinct,
        TopLevelOwnerKind::Resource => ItemTreeKind::Resource,
        TopLevelOwnerKind::Trait => ItemTreeKind::Trait,
        TopLevelOwnerKind::Impl => ItemTreeKind::Impl,
        TopLevelOwnerKind::Const => ItemTreeKind::Const,
        TopLevelOwnerKind::Invariant => ItemTreeKind::Invariant,
        TopLevelOwnerKind::Effect => ItemTreeKind::Effect,
        TopLevelOwnerKind::Interface => ItemTreeKind::Interface,
        TopLevelOwnerKind::World => ItemTreeKind::World,
        TopLevelOwnerKind::ExternBlock => ItemTreeKind::ExternBlock,
        TopLevelOwnerKind::Test => ItemTreeKind::Test,
        TopLevelOwnerKind::Property => ItemTreeKind::Property,
    }
}

fn trait_impl_member_kind(
    parent_kind: TopLevelOwnerKind,
    member_kind: ItemTreeKind,
) -> Option<TraitImplMemberKind> {
    match (parent_kind, member_kind) {
        (TopLevelOwnerKind::Trait, ItemTreeKind::AssocType) => {
            Some(TraitImplMemberKind::TraitAssociatedType)
        }
        (TopLevelOwnerKind::Trait, ItemTreeKind::AssocFn) => Some(TraitImplMemberKind::TraitMethod),
        (TopLevelOwnerKind::Impl, ItemTreeKind::AssocType) => {
            Some(TraitImplMemberKind::ImplAssociatedType)
        }
        (TopLevelOwnerKind::Impl, ItemTreeKind::AssocFn) => Some(TraitImplMemberKind::ImplMethod),
        _ => None,
    }
}

fn interface_member_kind(kind: ItemTreeKind) -> Option<InterfaceMemberKind> {
    match kind {
        ItemTreeKind::Struct => Some(InterfaceMemberKind::Struct),
        ItemTreeKind::Alias => Some(InterfaceMemberKind::Alias),
        ItemTreeKind::Refined => Some(InterfaceMemberKind::Refined),
        ItemTreeKind::Enum => Some(InterfaceMemberKind::Enum),
        ItemTreeKind::Resource => Some(InterfaceMemberKind::Resource),
        ItemTreeKind::InterfaceFn => Some(InterfaceMemberKind::Function),
        _ => None,
    }
}

fn interface_generation_order(
    module_tree: &ModuleTree,
    descriptors: Vec<TopLevelOwnerDescriptor>,
    symbols: &Interner,
) -> Result<Vec<TopLevelOwnerDescriptor>, OwnerControlFlowResolutionError> {
    let mut module_paths = HashMap::with_capacity(module_tree.modules.len());
    for module in &module_tree.modules {
        let path = module
            .path
            .iter()
            .map(|segment| {
                symbols
                    .resolve(*segment)
                    .map(|name| name.to_string())
                    .map_err(OwnerControlFlowResolutionError::SymbolLookup)
            })
            .collect::<Result<Vec<_>, _>>()?;
        if module_paths.insert(module.file, path).is_some() {
            return Err(OwnerControlFlowResolutionError::ModuleTreeMismatch);
        }
    }

    let mut ordered = descriptors
        .into_iter()
        .enumerate()
        .map(|(source_order, descriptor)| {
            let module_path = module_paths
                .get(&descriptor.file)
                .ok_or(OwnerControlFlowResolutionError::ModuleTreeMismatch)?;
            Ok((module_path, source_order, descriptor))
        })
        .collect::<Result<Vec<_>, OwnerControlFlowResolutionError>>()?;
    ordered.sort_by(|left, right| left.0.cmp(right.0).then_with(|| left.1.cmp(&right.1)));
    Ok(ordered
        .into_iter()
        .map(|(_, _, descriptor)| descriptor)
        .collect())
}

fn local_interface_type_member_owners(
    scopes: &Phase1PackageScopes,
    interface_owners: &[TopLevelOwnerDescriptor],
) -> HashMap<DefId, sai_hir::LocalDefId> {
    let interface_owner_ids = interface_owners
        .iter()
        .map(|descriptor| (descriptor.owner.def_id.to_def_id(), descriptor.owner.def_id))
        .collect::<HashMap<_, _>>();
    let mut member_owners = HashMap::new();
    for (interface, scope) in &scopes.interfaces {
        let Some(&interface_owner) = interface_owner_ids.get(interface) else {
            continue;
        };
        for binding in scope.members.values() {
            let Res::Def(kind, member) = binding.res else {
                continue;
            };
            if matches!(
                kind,
                DefKind::Struct
                    | DefKind::Enum
                    | DefKind::Distinct
                    | DefKind::Refined
                    | DefKind::Alias
                    | DefKind::Resource
            ) {
                member_owners.entry(member).or_insert(interface_owner);
            }
        }
    }
    member_owners
}

fn append_interface_use_references(
    references: &mut Vec<InterfaceUseReference>,
    interface: sai_hir::LocalDefId,
    candidates: &[OwnerPathHead<'_, '_>],
    resolution: &TypeOwnerPathResolution,
    interface_type_members: &HashMap<DefId, sai_hir::LocalDefId>,
    inputs: &CurrentOwnerInputs,
) -> Result<(), OwnerControlFlowResolutionError> {
    for candidate in candidates
        .iter()
        .filter(|candidate| candidate.kind == OwnerPathKind::Type)
    {
        let Some(PathRes {
            base: Res::Def(_, target),
            ..
        }) = resolution.paths().get(&candidate.hir_id)
        else {
            continue;
        };
        let Some(&to) = interface_type_members.get(target) else {
            continue;
        };
        let Some(location) = sai_diagnostics::Location::from_decoded_source(
            inputs.source_ref.clone(),
            sai_diagnostics::Span::new(candidate.span.file, candidate.span.range),
            &inputs.source,
        ) else {
            return Err(OwnerControlFlowResolutionError::InvalidSourceLocation(
                OwnerId { def_id: interface },
            ));
        };
        references.push(InterfaceUseReference {
            from: interface,
            to,
            location,
        });
    }
    Ok(())
}

fn collect_interface_owner_test_only_paths(
    owner: OwnerId,
    item_kind: InterfaceMemberKind,
    entry: &ItemTreeEntry,
    hir_owner: &HirOwner<'_>,
    module_scope: &Phase1ModuleScopes,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
    context: &HirLoweringContext<'_, '_>,
) -> (
    OwnerTestOnlyPathResolution,
    Result<Vec<Diagnostic>, OwnerControlFlowResolutionError>,
) {
    let mut generic_parameters = owner_generic_parameters(hir_owner);
    if item_kind == InterfaceMemberKind::Refined {
        generic_parameters.extend(item_tree_entry_generic_parameters(entry));
    }

    let mut path_resolution = OwnerTestOnlyPathResolution {
        owner,
        paths: HashMap::new(),
    };
    let hir_diagnostics = collect_test_only_module_head_diagnostics(
        owner,
        &owner_test_only_path_candidates(hir_owner),
        &generic_parameters,
        module_scope,
        &mut path_resolution,
        symbols,
        inputs,
        snapshot,
    );
    let syntax_diagnostics = match item_kind {
        InterfaceMemberKind::Refined => {
            let syntax = inputs
                .ast_ids
                .pointer(entry.ast_id)
                .and_then(|pointer| pointer.resolve(inputs.filtered_item_tree.file, &inputs.root))
                .ok_or(OwnerControlFlowResolutionError::MissingRefinedTypeSyntax(
                    owner,
                ))
                .and_then(|syntax| {
                    ast::TypeDecl::cast(syntax).ok_or(
                        OwnerControlFlowResolutionError::MissingRefinedTypeSyntax(owner),
                    )
                });
            syntax.and_then(|type_decl| {
                let (body, source_map) =
                    lower_interface_refinement_recovery_body(owner, &type_decl, context)
                        .map_err(OwnerControlFlowResolutionError::Lowering)?;
                let locally_resolved_expression_heads = if let Some(body) = body {
                    let locals =
                        resolve_owner_locals(body, &source_map, snapshot, symbols, &HashSet::new())
                            .map_err(OwnerControlFlowResolutionError::Locals)?;
                    local_expression_path_head_spans(&locals, &source_map, inputs)
                } else {
                    HashSet::new()
                };
                let candidates = interface_refinement_syntax_path_candidates(
                    &type_decl,
                    inputs.filtered_item_tree.file,
                    symbols,
                )
                .map_err(OwnerControlFlowResolutionError::Lowering)?;
                collect_ast_test_only_path_diagnostics(
                    owner,
                    &candidates,
                    &generic_parameters,
                    &locally_resolved_expression_heads,
                    module_scope,
                    symbols,
                    inputs,
                    snapshot,
                )
            })
        }
        InterfaceMemberKind::Function | InterfaceMemberKind::ResourceMethod => {
            let syntax = inputs
                .ast_ids
                .pointer(entry.ast_id)
                .and_then(|pointer| pointer.resolve(inputs.filtered_item_tree.file, &inputs.root))
                .ok_or(OwnerControlFlowResolutionError::MissingInterfaceFunctionSyntax(owner))
                .and_then(|syntax| {
                    ast::FnDecl::cast(syntax).ok_or(
                        OwnerControlFlowResolutionError::MissingInterfaceFunctionSyntax(owner),
                    )
                });
            syntax.and_then(|function| {
                let (body, source_map) =
                    lower_interface_function_recovery_body(owner, &function, context)
                        .map_err(OwnerControlFlowResolutionError::Lowering)?;
                let locally_resolved_expression_heads = if let Some(body) = body {
                    let locals =
                        resolve_owner_locals(body, &source_map, snapshot, symbols, &HashSet::new())
                            .map_err(OwnerControlFlowResolutionError::Locals)?;
                    local_expression_path_head_spans(&locals, &source_map, inputs)
                } else {
                    HashSet::new()
                };
                interface_function_recovered_syntax_path_candidates(
                    &function,
                    inputs.filtered_item_tree.file,
                    symbols,
                )
                .map_err(OwnerControlFlowResolutionError::Lowering)
                .and_then(|candidates| {
                    collect_ast_test_only_path_diagnostics(
                        owner,
                        &candidates,
                        &generic_parameters,
                        &locally_resolved_expression_heads,
                        module_scope,
                        symbols,
                        inputs,
                        snapshot,
                    )
                })
            })
        }
        _ => Ok(Vec::new()),
    };
    let diagnostics = match (hir_diagnostics, syntax_diagnostics) {
        (Ok(mut hir), Ok(syntax)) => {
            hir.extend(syntax);
            sort_phase1_diagnostics(&mut hir);
            Ok(hir)
        }
        (Err(error), _) | (_, Err(error)) => Err(error),
    };
    (path_resolution, diagnostics)
}

fn lower_top_level_owner<'hir>(
    descriptor: TopLevelOwnerDescriptor,
    expected_path: &DefPath,
    item_tree: &'hir ItemTree,
    retained_item_kinds: &HashMap<ast::ErasedAstId, ItemTreeKind>,
    context: &HirLoweringContext<'_, 'hir>,
) -> Result<(HirOwner<'hir>, HirSourceMap), OwnerControlFlowResolutionError> {
    let Some(current_kind) = retained_item_kinds.get(&descriptor.item_id).copied() else {
        return Err(
            OwnerControlFlowResolutionError::DescriptorNotInCurrentTarget {
                owner: descriptor.owner,
                file: descriptor.file,
            },
        );
    };
    let expected_kind = item_tree_kind_for_top_level_owner(descriptor.kind);
    if current_kind != expected_kind {
        return Err(OwnerControlFlowResolutionError::TopLevelOwnerKindMismatch {
            owner: descriptor.owner,
            file: descriptor.file,
            descriptor: descriptor.kind,
            current: current_kind,
        });
    }
    let lowered = match descriptor.kind {
        TopLevelOwnerKind::Function => lower_function_owner(
            descriptor.owner,
            expected_path,
            item_tree,
            descriptor.item_id,
            context,
        ),
        TopLevelOwnerKind::Struct => lower_struct_owner(
            descriptor.owner,
            expected_path,
            item_tree,
            descriptor.item_id,
            context,
        ),
        TopLevelOwnerKind::Alias => lower_alias_owner(
            descriptor.owner,
            expected_path,
            item_tree,
            descriptor.item_id,
            context,
        ),
        TopLevelOwnerKind::Refined => lower_refined_owner(
            descriptor.owner,
            expected_path,
            item_tree,
            descriptor.item_id,
            context,
        ),
        TopLevelOwnerKind::Enum => lower_enum_owner(
            descriptor.owner,
            expected_path,
            item_tree,
            descriptor.item_id,
            context,
        ),
        TopLevelOwnerKind::Distinct => lower_distinct_owner(
            descriptor.owner,
            expected_path,
            item_tree,
            descriptor.item_id,
            context,
        ),
        TopLevelOwnerKind::Resource => lower_resource_owner(
            descriptor.owner,
            expected_path,
            item_tree,
            descriptor.item_id,
            context,
        ),
        TopLevelOwnerKind::Trait => lower_trait_owner(
            descriptor.owner,
            expected_path,
            item_tree,
            descriptor.item_id,
            context,
        ),
        TopLevelOwnerKind::Impl => lower_impl_owner(
            descriptor.owner,
            expected_path,
            item_tree,
            descriptor.item_id,
            context,
        ),
        TopLevelOwnerKind::Const => lower_const_owner(
            descriptor.owner,
            expected_path,
            item_tree,
            descriptor.item_id,
            context,
        ),
        TopLevelOwnerKind::Invariant => lower_invariant_owner(
            descriptor.owner,
            expected_path,
            item_tree,
            descriptor.item_id,
            context,
        ),
        TopLevelOwnerKind::Effect => lower_effect_owner(
            descriptor.owner,
            expected_path,
            item_tree,
            descriptor.item_id,
            context,
        ),
        TopLevelOwnerKind::Interface => lower_interface_owner(
            descriptor.owner,
            expected_path,
            item_tree,
            descriptor.item_id,
            context,
        ),
        TopLevelOwnerKind::World => lower_world_owner(
            descriptor.owner,
            expected_path,
            item_tree,
            descriptor.item_id,
            context,
        ),
        TopLevelOwnerKind::ExternBlock => lower_extern_block_owner(
            descriptor.owner,
            expected_path,
            item_tree,
            descriptor.item_id,
            context,
        ),
        TopLevelOwnerKind::Test => lower_test_owner(
            descriptor.owner,
            expected_path,
            item_tree,
            descriptor.item_id,
            context,
        ),
        TopLevelOwnerKind::Property => lower_property_owner(
            descriptor.owner,
            expected_path,
            item_tree,
            descriptor.item_id,
            context,
        ),
    };
    lowered.map_err(OwnerControlFlowResolutionError::Lowering)
}

