fn world_dependency_path_diagnostic(
    owner: OwnerId,
    span: sai_hir::Span,
    code: sai_diagnostics::Code,
    identity: &str,
    allowed_targets: Option<&[String]>,
    target: &str,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
) -> Result<Diagnostic, OwnerControlFlowResolutionError> {
    let (message, label) = match code {
        sai_diagnostics::Code::InactiveDependency => (
            format!("dependency `{identity}` is inactive for target `{target}`"),
            "inactive dependency",
        ),
        sai_diagnostics::Code::TestDependencyUnavailable => (
            format!(
                "test dependency `{identity}` is unavailable because this package is not the root"
            ),
            "test dependency use",
        ),
        sai_diagnostics::Code::TestDependencyOutsideTest => (
            format!("test dependency `{identity}` cannot be referenced from a world declaration"),
            "test dependency reference outside a test or property",
        ),
        _ => unreachable!("only dependency-selection diagnostics are constructed here"),
    };
    let mut diagnostic =
        world_package_path_diagnostic(owner, span, code, message, label, inputs, snapshot)?;
    diagnostic.data.insert(
        "dependency".to_owned(),
        sai_diagnostics::Value::String(identity.to_owned()),
    );
    if code == sai_diagnostics::Code::InactiveDependency {
        diagnostic.data.insert(
            "target".to_owned(),
            sai_diagnostics::Value::String(target.to_owned()),
        );
        let allowed_targets = allowed_targets.unwrap_or_default();
        diagnostic.data.insert(
            "only".to_owned(),
            sai_diagnostics::Value::Array(
                allowed_targets
                    .iter()
                    .cloned()
                    .map(sai_diagnostics::Value::String)
                    .collect(),
            ),
        );
        let rendered_targets = allowed_targets
            .iter()
            .map(|target| format!("`{target}`"))
            .collect::<Vec<_>>()
            .join(", ");
        diagnostic
            .push_child(Child {
                kind: ChildKind::Help,
                message: format!("this dependency is available only for {rendered_targets}"),
                location: None,
            })
            .map_err(|_| OwnerControlFlowResolutionError::InvalidSourceLocation(owner))?;
    } else if code == sai_diagnostics::Code::TestDependencyUnavailable {
        diagnostic
            .push_child(Child {
                kind: ChildKind::Help,
                message:
                    "test dependencies are available only for the root package; run `sai test` in this package's directory"
                        .to_owned(),
                location: None,
            })
            .map_err(|_| OwnerControlFlowResolutionError::InvalidSourceLocation(owner))?;
    }
    Ok(diagnostic)
}

fn unknown_world_module_diagnostic(
    owner: OwnerId,
    original_path: &str,
    span: sai_hir::Span,
    matched_prefix: Vec<String>,
    module_candidates: Vec<String>,
    segments: &[Symbol],
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
) -> Result<Diagnostic, OwnerControlFlowResolutionError> {
    let mut diagnostic = world_package_path_diagnostic(
        owner,
        span,
        sai_diagnostics::Code::UnknownModule,
        format!("no module or interface has the path `{original_path}`"),
        "unknown module path",
        inputs,
        snapshot,
    )?;
    diagnostic.data.insert(
        "matched_prefix".to_owned(),
        sai_diagnostics::Value::Array(
            matched_prefix
                .iter()
                .cloned()
                .map(sai_diagnostics::Value::String)
                .collect(),
        ),
    );
    diagnostic.data.insert(
        "module_candidates".to_owned(),
        sai_diagnostics::Value::Array(
            module_candidates
                .iter()
                .cloned()
                .map(sai_diagnostics::Value::String)
                .collect(),
        ),
    );
    let prefix = if matched_prefix.is_empty() {
        "the package root".to_owned()
    } else {
        format!("`{}`", matched_prefix.join("/"))
    };
    let child_message = if module_candidates.is_empty() {
        format!("no modules directly under {prefix}")
    } else {
        format!(
            "modules directly under {prefix}: {}",
            module_candidates
                .iter()
                .map(|candidate| format!("`{candidate}`"))
                .collect::<Vec<_>>()
                .join(", ")
        )
    };
    diagnostic
        .push_child(Child {
            kind: ChildKind::Note,
            message: child_message,
            location: None,
        })
        .map_err(|_| OwnerControlFlowResolutionError::InvalidSourceLocation(owner))?;

    let spellings = segments
        .iter()
        .map(|segment| {
            symbols
                .resolve(*segment)
                .map(|spelling| spelling.to_string())
                .map_err(OwnerControlFlowResolutionError::SymbolLookup)
        })
        .collect::<Result<Vec<_>, _>>()?;
    if spellings.iter().any(|segment| segment == "lib") {
        diagnostic
            .push_child(Child {
                kind: ChildKind::Help,
                message: "the root module is named by the package identity alone".to_owned(),
                location: None,
            })
            .map_err(|_| OwnerControlFlowResolutionError::InvalidSourceLocation(owner))?;
    }
    if spellings.iter().any(|segment| segment.contains('-')) {
        let package_identity = original_path
            .split_once('/')
            .map_or(original_path, |(package, _)| package);
        let suggested_segments = spellings
            .iter()
            .map(|segment| segment.replace('-', "_"))
            .collect::<Vec<_>>();
        let suggested_path = if suggested_segments.is_empty() {
            package_identity.to_owned()
        } else {
            format!("{package_identity}/{}", suggested_segments.join("/"))
        };
        diagnostic
            .push_child(Child {
                kind: ChildKind::Help,
                message: format!(
                    "try `{suggested_path}`; hyphens do not normalize in SAI module paths"
                ),
                location: None,
            })
            .map_err(|_| OwnerControlFlowResolutionError::InvalidSourceLocation(owner))?;
    }
    Ok(diagnostic)
}

fn unknown_world_package_diagnostic(
    owner: OwnerId,
    span: sai_hir::Span,
    identity: &str,
    requirements: &[DeclaredRequirement],
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
) -> Result<Diagnostic, OwnerControlFlowResolutionError> {
    let candidate_names = suggest_world_packages(identity, requirements);
    let mut diagnostic = world_package_path_diagnostic(
        owner,
        span,
        sai_diagnostics::Code::UnknownPackage,
        format!("unknown package `{identity}`"),
        "unknown package",
        inputs,
        snapshot,
    )?;
    diagnostic.data.insert(
        "name".to_owned(),
        sai_diagnostics::Value::String(identity.to_owned()),
    );
    diagnostic.data.insert(
        "candidates".to_owned(),
        sai_diagnostics::Value::Array(
            candidate_names
                .iter()
                .cloned()
                .map(sai_diagnostics::Value::String)
                .collect(),
        ),
    );
    if !candidate_names.is_empty() {
        diagnostic
            .push_child(Child {
                kind: ChildKind::Help,
                message: format!(
                    "similar packages: {}",
                    candidate_names
                        .iter()
                        .map(|candidate| format!("`{candidate}`"))
                        .collect::<Vec<_>>()
                        .join(", ")
                ),
                location: None,
            })
            .map_err(|_| OwnerControlFlowResolutionError::InvalidSourceLocation(owner))?;
    }
    Ok(diagnostic)
}

fn suggest_world_packages(identity: &str, requirements: &[DeclaredRequirement]) -> Vec<String> {
    let mut candidates = requirements
        .iter()
        .filter_map(|requirement| {
            edit_distance_at_most_two(identity, &requirement.identity).map(|distance| {
                (
                    distance,
                    requirement.declaration_order,
                    requirement.identity.as_str(),
                )
            })
        })
        .collect::<Vec<_>>();
    candidates.sort_by(|left, right| {
        left.0
            .cmp(&right.0)
            .then_with(|| left.1.cmp(&right.1))
            .then_with(|| left.2.as_bytes().cmp(right.2.as_bytes()))
    });
    candidates
        .into_iter()
        .take(10)
        .map(|(_, _, identity)| identity.to_owned())
        .collect()
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum GeneratedSourceInterfaceView {
    Unavailable,
    Omitted,
    Resolved(DefId),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum GeneratedSourceWorldView {
    Unavailable,
    Omitted,
    Resolved(DefId, Option<Unsupported>),
}

fn suggest_wit_items(requested_name: &str, candidates: &[(usize, String)]) -> Vec<String> {
    let include_all = candidates.len() <= 5;
    let threshold = (requested_name.chars().count() / 3).max(1);
    let mut ranked = candidates
        .iter()
        .filter_map(|(declaration_order, name)| {
            let distance = unicode_damerau_levenshtein(requested_name, name);
            (include_all || distance <= threshold).then_some((distance, *declaration_order, name))
        })
        .collect::<Vec<_>>();
    ranked.sort_by_key(|(distance, declaration_order, _)| (*distance, *declaration_order));
    ranked
        .into_iter()
        .take(10)
        .map(|(_, _, name)| name.clone())
        .collect()
}

/// Unrestricted Damerau–Levenshtein distance over Unicode scalar values.
fn unicode_damerau_levenshtein(left: &str, right: &str) -> usize {
    let left = left.chars().collect::<Vec<_>>();
    let right = right.chars().collect::<Vec<_>>();
    let left_len = left.len();
    let right_len = right.len();
    let max_distance = left_len + right_len;
    let mut distances = vec![vec![0_usize; right_len + 2]; left_len + 2];
    distances[0][0] = max_distance;
    for index in 0..=left_len {
        distances[index + 1][0] = max_distance;
        distances[index + 1][1] = index;
    }
    for index in 0..=right_len {
        distances[0][index + 1] = max_distance;
        distances[1][index + 1] = index;
    }

    let mut last_seen_row = HashMap::new();
    for left_index in 1..=left_len {
        let mut last_matching_column = 0;
        for right_index in 1..=right_len {
            let previous_left = last_seen_row
                .get(&right[right_index - 1])
                .copied()
                .unwrap_or(0);
            let previous_right = last_matching_column;
            let substitution_cost = if left[left_index - 1] == right[right_index - 1] {
                last_matching_column = right_index;
                0
            } else {
                1
            };
            distances[left_index + 1][right_index + 1] = [
                distances[left_index][right_index] + substitution_cost,
                distances[left_index + 1][right_index] + 1,
                distances[left_index][right_index + 1] + 1,
                distances[previous_left][previous_right]
                    + (left_index - previous_left - 1)
                    + 1
                    + (right_index - previous_right - 1),
            ]
            .into_iter()
            .min()
            .expect("edit operations always include candidates");
        }
        last_seen_row.insert(left[left_index - 1], left_index);
    }
    distances[left_len + 1][right_len + 1]
}

fn module_scope_for_scopes<'a>(
    scopes: &'a Phase1PackageScopes,
    module_tree: &ModuleTree,
    file: FileId,
) -> Result<&'a Phase1ModuleScopes, OwnerControlFlowResolutionError> {
    if scopes.modules.len() != module_tree.modules.len() {
        return Err(OwnerControlFlowResolutionError::ModuleTreeMismatch);
    }
    let mut matching_modules = module_tree
        .modules
        .iter()
        .enumerate()
        .filter(|(_, module)| module.file == file);
    let Some((index, _)) = matching_modules.next() else {
        return Err(OwnerControlFlowResolutionError::ModuleTreeMismatch);
    };
    if matching_modules.next().is_some() {
        return Err(OwnerControlFlowResolutionError::ModuleTreeMismatch);
    }
    let Ok(raw_id) = u32::try_from(index) else {
        return Err(OwnerControlFlowResolutionError::ModuleTreeMismatch);
    };
    let module_id = ModuleId::from_raw(raw_id);
    let module_scope = scopes
        .module(module_id)
        .ok_or(OwnerControlFlowResolutionError::MissingModuleScope(file))?;
    Ok(module_scope)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum OwnerPathKind {
    Type,
    Effect,
    Expression,
    Pattern,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct OwnerPathHead<'paths, 'hir> {
    hir_id: HirId,
    name: Symbol,
    span: sai_hir::Span,
    segment_count: u32,
    kind: OwnerPathKind,
    segments: &'paths [sai_hir::types::PathSegment<'hir>],
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct RefinedGenericSyntaxPathHead {
    name: Symbol,
    span: sai_diagnostics::Span,
    kind: OwnerPathKind,
}

fn owner_test_only_path_candidates<'hir>(owner: &HirOwner<'hir>) -> Vec<OwnerPathHead<'hir, 'hir>> {
    owner_test_only_path_candidates_with_body(owner, true)
}

fn world_item_signature_type_path_candidates<'hir>(
    owner: &HirOwner<'hir>,
) -> Option<Vec<OwnerPathHead<'hir, 'hir>>> {
    let is_function = match owner.node {
        OwnerNode::WorldItem(item) => {
            matches!(
                item.kind,
                WorldItemKind::ImportFn { .. } | WorldItemKind::ExportFn { .. }
            )
        }
        _ => false,
    };
    is_function.then(|| {
        owner_test_only_path_candidates(owner)
            .into_iter()
            .filter(|candidate| candidate.kind == OwnerPathKind::Type)
            .collect()
    })
}

fn owner_test_only_path_candidates_with_body<'hir>(
    owner: &HirOwner<'hir>,
    include_body: bool,
) -> Vec<OwnerPathHead<'hir, 'hir>> {
    enum Work<'hir> {
        Expr(&'hir HirExpr<'hir>),
        Block(&'hir HirBlock<'hir>),
        Stmt(&'hir Stmt<'hir>),
        Pat(&'hir HirPat<'hir>),
        Ty(&'hir Ty<'hir>),
        Bound(Bound<'hir>),
        Path {
            path: HirPath<'hir>,
            kind: OwnerPathKind,
        },
        Args(GenericArgs<'hir>),
        Effect(HirEffectRef<'hir>),
    }

    let mut work = Vec::new();
    let mut header_generics = Vec::new();
    let signature = match owner.node {
        OwnerNode::Item(item) => match item.kind {
            ItemKind::Fn { sig, generics, .. } => Some((sig, generics)),
            ItemKind::Struct { generics, fields } => {
                header_generics.push(generics);
                work.extend(fields.iter().map(|field| Work::Ty(field.ty)));
                None
            }
            ItemKind::Alias { generics, ty } => {
                header_generics.push(generics);
                work.push(Work::Ty(ty));
                None
            }
            ItemKind::Enum { generics, variants } => {
                header_generics.push(generics);
                for variant in variants.iter() {
                    match variant.shape {
                        VariantShape::Unit => {}
                        VariantShape::Tuple(types) => {
                            work.extend(types.iter().rev().map(Work::Ty));
                        }
                        VariantShape::Record(fields) => {
                            work.extend(fields.iter().rev().map(|field| Work::Ty(field.ty)));
                        }
                    }
                }
                None
            }
            ItemKind::Resource { fields } => {
                work.extend(fields.iter().map(|field| Work::Ty(field.ty)));
                None
            }
            ItemKind::Effect { covers } => {
                work.extend(covers.iter().copied().map(Work::Effect));
                None
            }
            ItemKind::Trait { .. } | ItemKind::Impl { .. } => None,
            _ => None,
        },
        OwnerNode::ExternItem(item) => Some((item.sig, item.generics)),
        OwnerNode::TraitItem(item) => match item.kind {
            TraitItemKind::Fn { sig, generics, .. } => Some((sig, generics)),
            TraitItemKind::AssocType { .. } => None,
        },
        OwnerNode::ImplItem(item) => match item.kind {
            ImplItemKind::Fn { sig, generics, .. } => Some((sig, generics)),
            ImplItemKind::AssocType { .. } => None,
        },
        OwnerNode::InterfaceItem(item) => match item.kind {
            HirInterfaceItemKind::Fn { sig, generics }
            | HirInterfaceItemKind::ResourceMember { sig, generics, .. } => Some((sig, generics)),
            _ => None,
        },
        OwnerNode::WorldItem(item) => {
            match item.kind {
                WorldItemKind::Import(WorldRef::Mod(path))
                | WorldItemKind::Export(WorldRef::Mod(path))
                | WorldItemKind::Include(WorldRef::Mod(path)) => work.push(Work::Path {
                    path,
                    kind: OwnerPathKind::Type,
                }),
                WorldItemKind::ImportFn { sig, .. } | WorldItemKind::ExportFn { sig, .. } => {
                    work.extend(sig.params.iter().map(|parameter| Work::Ty(parameter.ty)));
                    if let Some(ret) = sig.ret {
                        work.push(Work::Ty(ret));
                    }
                    if let Some(effects) = sig.effects {
                        work.extend(effects.iter().copied().map(Work::Effect));
                    }
                }
                WorldItemKind::Import(_) | WorldItemKind::Export(_) | WorldItemKind::Include(_) => {
                }
            }
            None
        }
        _ => return Vec::new(),
    };
    if let Some((sig, generics)) = signature {
        for parameter in sig.params {
            work.push(Work::Ty(parameter.ty));
        }
        if let Some(effects) = sig.effects {
            work.extend(effects.iter().copied().map(Work::Effect));
        }
        if let Some(ret) = sig.ret {
            work.push(Work::Ty(ret));
        }
        for parameter in generics.params {
            match parameter.kind {
                GenericParamKind::Type { bounds } => {
                    work.extend(bounds.iter().copied().map(Work::Bound));
                }
                GenericParamKind::Const { ty } => work.push(Work::Ty(ty)),
            }
        }
        for predicate in generics.where_preds {
            work.push(Work::Ty(predicate.ty));
            work.extend(predicate.bounds.iter().copied().map(Work::Bound));
        }
    }
    match owner.node {
        OwnerNode::Item(item) => match item.kind {
            ItemKind::Fn { .. } => {}
            ItemKind::Struct { .. }
            | ItemKind::Alias { .. }
            | ItemKind::Enum { .. }
            | ItemKind::Resource { .. }
            | ItemKind::Effect { .. } => {}
            ItemKind::Trait {
                generics,
                supertraits,
                ..
            } => {
                header_generics.push(generics);
                work.extend(supertraits.iter().copied().map(Work::Bound));
            }
            ItemKind::Impl { generics, kind, .. } => {
                header_generics.push(generics);
                match kind {
                    ImplKind::Inherent { self_ty } => work.push(Work::Ty(self_ty)),
                    ImplKind::Trait { trait_ref, self_ty } => {
                        work.push(Work::Ty(self_ty));
                        work.push(Work::Path {
                            path: trait_ref,
                            kind: OwnerPathKind::Type,
                        });
                    }
                    ImplKind::Interface { path } => work.push(Work::Path {
                        path,
                        kind: OwnerPathKind::Type,
                    }),
                }
            }
            ItemKind::Const { ty } => work.push(Work::Ty(ty)),
            ItemKind::Refined { base } => work.push(Work::Ty(base)),
            ItemKind::Distinct { generics, base, .. } => {
                work.push(Work::Ty(base));
                for parameter in generics.params {
                    match parameter.kind {
                        GenericParamKind::Type { bounds } => {
                            work.extend(bounds.iter().copied().map(Work::Bound));
                        }
                        GenericParamKind::Const { ty } => work.push(Work::Ty(ty)),
                    }
                }
                for predicate in generics.where_preds {
                    work.push(Work::Ty(predicate.ty));
                    work.extend(predicate.bounds.iter().copied().map(Work::Bound));
                }
            }
            ItemKind::Invariant { target } => work.push(Work::Path {
                path: target,
                kind: OwnerPathKind::Type,
            }),
            _ => return Vec::new(),
        },
        OwnerNode::TraitItem(item) => match item.kind {
            TraitItemKind::AssocType { bounds } => {
                work.extend(bounds.iter().copied().map(Work::Bound));
            }
            TraitItemKind::Fn { .. } => {}
        },
        OwnerNode::ImplItem(item) => match item.kind {
            ImplItemKind::AssocType { ty } => work.push(Work::Ty(ty)),
            ImplItemKind::Fn { .. } => {}
        },
        OwnerNode::InterfaceItem(item) => match item.kind {
            HirInterfaceItemKind::Struct { generics, fields } => {
                header_generics.push(generics);
                work.extend(fields.iter().map(|field| Work::Ty(field.ty)));
            }
            HirInterfaceItemKind::Alias { generics, ty } => {
                header_generics.push(generics);
                work.push(Work::Ty(ty));
            }
            HirInterfaceItemKind::Refined { base, .. } => work.push(Work::Ty(base)),
            HirInterfaceItemKind::Enum { generics, variants } => {
                header_generics.push(generics);
                for variant in variants.iter() {
                    match variant.shape {
                        VariantShape::Unit => {}
                        VariantShape::Tuple(types) => {
                            work.extend(types.iter().rev().map(Work::Ty));
                        }
                        VariantShape::Record(fields) => {
                            work.extend(fields.iter().rev().map(|field| Work::Ty(field.ty)));
                        }
                    }
                }
            }
            HirInterfaceItemKind::Resource { .. }
            | HirInterfaceItemKind::Fn { .. }
            | HirInterfaceItemKind::ResourceMember { .. } => {}
        },
        OwnerNode::ExternItem(_) => {}
        OwnerNode::WorldItem(_) => {}
        _ => return Vec::new(),
    }
    for generics in header_generics {
        for parameter in generics.params {
            match parameter.kind {
                GenericParamKind::Type { bounds } => {
                    work.extend(bounds.iter().copied().map(Work::Bound));
                }
                GenericParamKind::Const { ty } => work.push(Work::Ty(ty)),
            }
        }
        for predicate in generics.where_preds {
            work.push(Work::Ty(predicate.ty));
            work.extend(predicate.bounds.iter().copied().map(Work::Bound));
        }
    }
    if include_body && let Some(body) = owner.body {
        work.push(Work::Expr(body.value));
        work.extend(
            body.contracts
                .iter()
                .rev()
                .map(|contract| Work::Expr(&contract.expr)),
        );
        work.extend(
            body.invariant_preds
                .iter()
                .rev()
                .map(|predicate| Work::Expr(predicate)),
        );
    }

    let mut paths = Vec::new();
    while let Some(next) = work.pop() {
        match next {
            Work::Expr(expr) => match expr.kind {
                ExprKind::Lit(_)
                | ExprKind::ImplicitMember(_)
                | ExprKind::ContractResult
                | ExprKind::Continue { .. }
                | ExprKind::Err => {}
                ExprKind::Path(path) => {
                    for segment in path.segments.iter().rev() {
                        if let Some(args) = segment.args {
                            work.push(Work::Args(*args));
                        }
                    }
                }
                ExprKind::Field { base, args, .. } => {
                    if let Some(args) = args {
                        work.push(Work::Args(*args));
                    }
                    work.push(Work::Expr(base));
                }
                ExprKind::TupleField { base, .. }
                | ExprKind::Unary(_, base)
                | ExprKind::Borrow(_, base)
                | ExprKind::Try(base)
                | ExprKind::Await(base) => work.push(Work::Expr(base)),
                ExprKind::Call { callee, args, base } => {
                    if let Some(base) = base {
                        work.push(Work::Expr(base));
                    }
                    work.extend(args.iter().rev().map(|arg| Work::Expr(&arg.expr)));
                    work.push(Work::Expr(callee));
                }
                ExprKind::Binary(_, left, right) | ExprKind::Index(left, right) => {
                    work.push(Work::Expr(right));
                    work.push(Work::Expr(left));
                }
                ExprKind::Range { start, end, .. } => {
                    if let Some(end) = end {
                        work.push(Work::Expr(end));
                    }
                    if let Some(start) = start {
                        work.push(Work::Expr(start));
                    }
                }
                ExprKind::Tuple(items) | ExprKind::Array(items) => {
                    work.extend(items.iter().rev().map(Work::Expr));
                }
                ExprKind::Block(block) => work.push(Work::Block(block)),
                ExprKind::AsyncBlock { block, .. }
                | ExprKind::Loop { body: block, .. }
                | ExprKind::Region { block, .. } => work.push(Work::Block(block)),
                ExprKind::If { cond, then, els } => {
                    if let Some(els) = els {
                        work.push(Work::Expr(els));
                    }
                    work.push(Work::Block(then));
                    work.push(Work::Expr(cond));
                }
                ExprKind::Match {
                    scrutinee, arms, ..
                } => {
                    for arm in arms.iter().rev() {
                        work.push(Work::Expr(&arm.body));
                        if let Some(guard) = arm.guard {
                            work.push(Work::Expr(guard));
                        }
                        work.push(Work::Pat(arm.pat));
                    }
                    work.push(Work::Expr(scrutinee));
                }
                ExprKind::Break { value, .. } | ExprKind::Return(value) => {
                    if let Some(value) = value {
                        work.push(Work::Expr(value));
                    }
                }
                ExprKind::Closure(closure) => {
                    work.push(Work::Block(closure.body));
                    if let Some(ret) = closure.ret {
                        work.push(Work::Ty(ret));
                    }
                    for parameter in closure.params.iter().rev() {
                        if let Some(ty) = parameter.ty {
                            work.push(Work::Ty(ty));
                        }
                    }
                }
                ExprKind::FormatString(pieces) => {
                    for piece in pieces.iter().rev() {
                        if let FmtPiece::Arg { expr, .. } = piece {
                            work.push(Work::Expr(expr));
                        }
                    }
                }
                ExprKind::ContractOld { args, base } => {
                    if let Some(base) = base {
                        work.push(Work::Expr(base));
                    }
                    work.extend(args.iter().rev().map(|arg| Work::Expr(&arg.expr)));
                }
                ExprKind::AsCast { operand, ty } => {
                    work.push(Work::Ty(ty));
                    work.push(Work::Expr(operand));
                }
            },
            Work::Block(block) => {
                if let Some(tail) = block.tail {
                    work.push(Work::Expr(tail));
                }
                work.extend(block.stmts.iter().rev().map(Work::Stmt));
            }
            Work::Stmt(stmt) => match stmt.kind {
                StmtKind::Let { pat, ty, init, els } => {
                    if let Some(els) = els {
                        work.push(Work::Block(els));
                    }
                    work.push(Work::Expr(init));
                    if let Some(ty) = ty {
                        work.push(Work::Ty(ty));
                    }
                    work.push(Work::Pat(pat));
                }
                StmtKind::Assign { lhs, rhs } | StmtKind::AssignOp { lhs, rhs, .. } => {
                    work.push(Work::Expr(rhs));
                    work.push(Work::Expr(lhs));
                }
                StmtKind::Assert { cond, msg, .. } => {
                    if let Some(msg) = msg {
                        work.push(Work::Expr(msg));
                    }
                    work.push(Work::Expr(cond));
                }
                StmtKind::Expr(expr) => work.push(Work::Expr(expr)),
            },
            Work::Pat(pat) => match pat.kind {
                PatKind::Wild | PatKind::Lit(_) | PatKind::Err => {}
                PatKind::Binding { sub, .. } => {
                    if let Some(sub) = sub {
                        work.push(Work::Pat(sub));
                    }
                }
                PatKind::Range { start, end, .. } => {
                    if let Some(PatRangeEnd::Path(path)) = end {
                        work.push(Work::Path {
                            path,
                            kind: OwnerPathKind::Pattern,
                        });
                    }
                    if let Some(PatRangeEnd::Path(path)) = start {
                        work.push(Work::Path {
                            path,
                            kind: OwnerPathKind::Pattern,
                        });
                    }
                }
                PatKind::Tuple(patterns) | PatKind::Or(patterns) => {
                    work.extend(patterns.iter().rev().map(Work::Pat));
                }
                PatKind::Slice {
                    before,
                    rest,
                    after,
                } => {
                    work.extend(after.iter().rev().map(Work::Pat));
                    if let Some(Some(rest)) = rest {
                        work.push(Work::Pat(rest));
                    }
                    work.extend(before.iter().rev().map(Work::Pat));
                }
                PatKind::Ctor { path, args, .. } => {
                    if let Some(args) = args {
                        work.extend(args.iter().rev().map(|arg| Work::Pat(&arg.pat)));
                    }
                    work.push(Work::Path {
                        path,
                        kind: OwnerPathKind::Pattern,
                    });
                }
                PatKind::ImplicitMember { args, .. } => {
                    if let Some(args) = args {
                        work.extend(args.iter().rev().map(|arg| Work::Pat(&arg.pat)));
                    }
                }
            },
            Work::Ty(ty) => match ty.kind {
                TyKind::Path(path) => work.push(Work::Path {
                    path,
                    kind: OwnerPathKind::Type,
                }),
                TyKind::Borrow(_, inner) => work.push(Work::Ty(inner)),
                TyKind::Tuple(elements) => {
                    work.extend(elements.iter().rev().map(Work::Ty));
                }
                TyKind::FnPtr {
                    params,
                    ret,
                    effects,
                    ..
                } => {
                    if let Some(effects) = effects {
                        work.extend(effects.iter().copied().map(Work::Effect));
                    }
                    if let Some(ret) = ret {
                        work.push(Work::Ty(ret));
                    }
                    work.extend(params.iter().rev().map(Work::Ty));
                }
                TyKind::Infer | TyKind::Err => {}
            },
            Work::Bound(bound) => {
                if let Some(effects) = bound.effects {
                    work.extend(effects.iter().copied().map(Work::Effect));
                }
                match bound.kind {
                    BoundKind::Trait(path) => work.push(Work::Path {
                        path,
                        kind: OwnerPathKind::Type,
                    }),
                    BoundKind::FnSugar { params, ret, .. } => {
                        if let Some(ret) = ret {
                            work.push(Work::Ty(ret));
                        }
                        work.extend(params.iter().rev().map(Work::Ty));
                    }
                }
            }
            Work::Path { path, kind } => {
                if path.root == PathRoot::Plain
                    && let Some(segment) = path.segments.first()
                    && let Ok(segment_count) = u32::try_from(path.segments.len())
                {
                    let name = segment.name.sym;
                    if !name.is_error() {
                        paths.push(OwnerPathHead {
                            hir_id: path.hir_id,
                            name,
                            span: segment.name.span,
                            segment_count,
                            kind,
                            segments: path.segments,
                        });
                    }
                }
                for segment in path.segments.iter().rev() {
                    if let Some(args) = segment.args {
                        work.push(Work::Args(*args));
                    }
                }
            }
            Work::Effect(effect) => {
                if let Some(segment) = effect.segments.first()
                    && let Ok(segment_count) = u32::try_from(effect.segments.len())
                    && !segment.sym.is_error()
                {
                    paths.push(OwnerPathHead {
                        hir_id: effect.hir_id,
                        name: segment.sym,
                        span: segment.span,
                        segment_count,
                        kind: OwnerPathKind::Effect,
                        segments: &[],
                    });
                }
            }
            Work::Args(args) => {
                for arg in args.args.iter().rev() {
                    match arg {
                        GenericArg::Type(ty) | GenericArg::Binding { ty, .. } => {
                            work.push(Work::Ty(ty));
                        }
                        GenericArg::Const(_) => {}
                    }
                }
            }
        }
    }
    paths.sort_by_key(|path| path.span.range.start());
    paths
}

#[derive(Clone)]
struct DirectEnumVariantPathCandidate<'hir> {
    field: &'hir HirExpr<'hir>,
    base_expression: &'hir HirExpr<'hir>,
    base_path: HirPath<'hir>,
    type_head_segments: Vec<PathSegment<'hir>>,
    name: Name,
    direct_call: Option<&'hir HirExpr<'hir>>,
}

fn direct_enum_variant_type_head<'hir>(
    mut base: &'hir HirExpr<'hir>,
) -> Option<(HirPath<'hir>, Vec<PathSegment<'hir>>)> {
    let mut field_segments = Vec::new();
    loop {
        match base.kind {
            ExprKind::Field {
                base: inner,
                name,
                args: None,
            } => {
                field_segments.push(PathSegment {
                    hir_id: base.hir_id,
                    name,
                    args: None,
                });
                base = inner;
            }
            ExprKind::Path(path) => {
                let mut segments = path.segments.to_vec();
                field_segments.reverse();
                segments.extend(field_segments);
                return Some((path, segments));
            }
            _ => return None,
        }
    }
}

fn direct_enum_variant_path_candidates<'hir>(
    body: &'hir sai_hir::body::Body<'hir>,
) -> Vec<DirectEnumVariantPathCandidate<'hir>> {
    enum Work<'hir> {
        Expr(&'hir HirExpr<'hir>),
        Block(&'hir HirBlock<'hir>),
        Stmt(&'hir Stmt<'hir>),
    }

    let mut work = vec![Work::Expr(body.value)];
    work.extend(
        body.contracts
            .iter()
            .rev()
            .map(|contract| Work::Expr(&contract.expr)),
    );
    work.extend(
        body.invariant_preds
            .iter()
            .rev()
            .map(|predicate| Work::Expr(predicate)),
    );
    let mut candidates = Vec::new();
    let mut calls_by_callee = HashMap::new();
    while let Some(next) = work.pop() {
        match next {
            Work::Expr(expr) => match expr.kind {
                ExprKind::Lit(_)
                | ExprKind::Path(_)
                | ExprKind::ImplicitMember(_)
                | ExprKind::ContractResult
                | ExprKind::Continue { .. }
                | ExprKind::Err => {}
                ExprKind::Field { base, name, args } => {
                    if args.is_none()
                        && let Some((base_path, type_head_segments)) =
                            direct_enum_variant_type_head(base)
                    {
                        candidates.push(DirectEnumVariantPathCandidate {
                            field: expr,
                            base_expression: base,
                            base_path,
                            type_head_segments,
                            name,
                            direct_call: calls_by_callee.get(&expr.hir_id).copied(),
                        });
                    }
                    work.push(Work::Expr(base));
                }
                ExprKind::TupleField { base, .. }
                | ExprKind::Unary(_, base)
                | ExprKind::Borrow(_, base)
                | ExprKind::Try(base)
                | ExprKind::Await(base) => work.push(Work::Expr(base)),
                ExprKind::Call { callee, args, base } => {
                    if base.is_none()
                        && matches!(
                            callee.kind,
                            ExprKind::Field {
                                base,
                                args: None,
                                ..
                            } if direct_enum_variant_type_head(base).is_some()
                        )
                    {
                        calls_by_callee.insert(callee.hir_id, expr);
                    }
                    if let Some(base) = base {
                        work.push(Work::Expr(base));
                    }
                    work.extend(args.iter().rev().map(|arg| Work::Expr(&arg.expr)));
                    work.push(Work::Expr(callee));
                }
                ExprKind::Binary(_, left, right) | ExprKind::Index(left, right) => {
                    work.push(Work::Expr(right));
                    work.push(Work::Expr(left));
                }
                ExprKind::Range { start, end, .. } => {
                    if let Some(end) = end {
                        work.push(Work::Expr(end));
                    }
                    if let Some(start) = start {
                        work.push(Work::Expr(start));
                    }
                }
                ExprKind::Tuple(items) | ExprKind::Array(items) => {
                    work.extend(items.iter().rev().map(Work::Expr));
                }
                ExprKind::Block(block)
                | ExprKind::AsyncBlock { block, .. }
                | ExprKind::Loop { body: block, .. }
                | ExprKind::Region { block, .. } => work.push(Work::Block(block)),
                ExprKind::If { cond, then, els } => {
                    if let Some(els) = els {
                        work.push(Work::Expr(els));
                    }
                    work.push(Work::Block(then));
                    work.push(Work::Expr(cond));
                }
                ExprKind::Match {
                    scrutinee, arms, ..
                } => {
                    for arm in arms.iter().rev() {
                        work.push(Work::Expr(&arm.body));
                        if let Some(guard) = arm.guard {
                            work.push(Work::Expr(guard));
                        }
                    }
                    work.push(Work::Expr(scrutinee));
                }
                ExprKind::Break { value, .. } | ExprKind::Return(value) => {
                    if let Some(value) = value {
                        work.push(Work::Expr(value));
                    }
                }
                ExprKind::Closure(closure) => work.push(Work::Block(closure.body)),
                ExprKind::FormatString(pieces) => {
                    for piece in pieces.iter().rev() {
                        if let FmtPiece::Arg { expr, .. } = piece {
                            work.push(Work::Expr(expr));
                        }
                    }
                }
                ExprKind::ContractOld { args, base } => {
                    if let Some(base) = base {
                        work.push(Work::Expr(base));
                    }
                    work.extend(args.iter().rev().map(|arg| Work::Expr(&arg.expr)));
                }
                ExprKind::AsCast { operand, .. } => work.push(Work::Expr(operand)),
            },
            Work::Block(block) => {
                if let Some(tail) = block.tail {
                    work.push(Work::Expr(tail));
                }
                work.extend(block.stmts.iter().rev().map(Work::Stmt));
            }
            Work::Stmt(stmt) => match stmt.kind {
                StmtKind::Let { init, els, .. } => {
                    if let Some(els) = els {
                        work.push(Work::Block(els));
                    }
                    work.push(Work::Expr(init));
                }
                StmtKind::Assign { lhs, rhs } | StmtKind::AssignOp { lhs, rhs, .. } => {
                    work.push(Work::Expr(rhs));
                    work.push(Work::Expr(lhs));
                }
                StmtKind::Assert { cond, msg, .. } => {
                    if let Some(msg) = msg {
                        work.push(Work::Expr(msg));
                    }
                    work.push(Work::Expr(cond));
                }
                StmtKind::Expr(expr) => work.push(Work::Expr(expr)),
            },
        }
    }
    candidates.sort_by_key(|candidate| candidate.field.span.range.start());
    candidates
}

fn refined_generic_syntax_path_candidates(
    type_decl: &ast::TypeDecl,
    file: FileId,
    symbols: &Interner,
) -> Result<Vec<RefinedGenericSyntaxPathHead>, HirLoweringError> {
    let mut paths = Vec::new();
    let mut roots = Vec::new();
    if let Some(generic_params) = type_decl.generic_params() {
        roots.push(generic_params.syntax().clone());
    }
    roots.extend(
        type_decl
            .syntax()
            .descendants()
            .filter_map(ast::WhereClause::cast)
            .map(|clause| clause.syntax().clone()),
    );
    for root in roots {
        for node in root.descendants() {
            if let Some(path) = ast::PathType::cast(node.clone())
                && let Some(name) = path.segments().next().and_then(|segment| segment.name())
                && let Some(symbol) = intern_ast_name_ref(&name, symbols)?
            {
                paths.push(RefinedGenericSyntaxPathHead {
                    name: symbol,
                    span: sai_diagnostics::Span::new(file, name.syntax().text_range()),
                    kind: OwnerPathKind::Type,
                });
            }

            if let Some(path) = ast::PathExpr::cast(node.clone())
                && let Some(name) = path.name()
                && let Some(symbol) = intern_ast_name_ref(&name, symbols)?
            {
                paths.push(RefinedGenericSyntaxPathHead {
                    name: symbol,
                    span: sai_diagnostics::Span::new(file, name.syntax().text_range()),
                    kind: OwnerPathKind::Expression,
                });
            }

            if let Some(effect) = ast::EffectRef::cast(node)
                && let Some(name) = effect.segments().next()
                && let Some(symbol) = intern_ast_name_ref(&name, symbols)?
            {
                paths.push(RefinedGenericSyntaxPathHead {
                    name: symbol,
                    span: sai_diagnostics::Span::new(file, name.syntax().text_range()),
                    kind: OwnerPathKind::Effect,
                });
            }
        }
    }

    paths.sort_by_key(|path| (path.span.range.start(), path.span.range.end()));
    paths.dedup_by_key(|path| path.span);
    Ok(paths)
}

fn interface_refinement_syntax_path_candidates(
    type_decl: &ast::TypeDecl,
    file: FileId,
    symbols: &Interner,
) -> Result<Vec<RefinedGenericSyntaxPathHead>, HirLoweringError> {
    let definition = type_decl
        .alias_def()
        .ok_or(HirLoweringError::ItemTreeEntryMismatch)?;
    let refinement = definition
        .refinement()
        .ok_or(HirLoweringError::ItemTreeEntryMismatch)?;
    let Some(expression) = refinement.expression() else {
        return Ok(Vec::new());
    };

    syntax_path_candidates(expression.syntax(), file, symbols)
}

fn interface_function_recovered_syntax_path_candidates(
    function: &ast::FnDecl,
    file: FileId,
    symbols: &Interner,
) -> Result<Vec<RefinedGenericSyntaxPathHead>, HirLoweringError> {
    let mut paths = Vec::new();
    for node in function.syntax().descendants().filter(|node| {
        matches!(
            node.kind(),
            sai_syntax::SyntaxKind::BLOCK
                | sai_syntax::SyntaxKind::REQUIRES_CLAUSE
                | sai_syntax::SyntaxKind::ENSURES_CLAUSE
        )
    }) {
        paths.extend(syntax_path_candidates(&node, file, symbols)?);
    }
    paths.sort_by_key(|path| (path.span.range.start(), path.span.range.end()));
    paths.dedup_by_key(|path| path.span);
    Ok(paths)
}

fn syntax_path_candidates(
    syntax: &sai_syntax::SyntaxNode,
    file: FileId,
    symbols: &Interner,
) -> Result<Vec<RefinedGenericSyntaxPathHead>, HirLoweringError> {
    let mut paths = Vec::new();
    for node in syntax.descendants() {
        if let Some(path) = ast::PathType::cast(node.clone())
            && let Some(name) = path.segments().next().and_then(|segment| segment.name())
            && let Some(symbol) = intern_ast_name_ref(&name, symbols)?
        {
            paths.push(RefinedGenericSyntaxPathHead {
                name: symbol,
                span: sai_diagnostics::Span::new(file, name.syntax().text_range()),
                kind: OwnerPathKind::Type,
            });
        }

        if let Some(path) = ast::PathExpr::cast(node.clone())
            && let Some(name) = path.name()
            && let Some(symbol) = intern_ast_name_ref(&name, symbols)?
        {
            paths.push(RefinedGenericSyntaxPathHead {
                name: symbol,
                span: sai_diagnostics::Span::new(file, name.syntax().text_range()),
                kind: OwnerPathKind::Expression,
            });
        }

        if let Some(effect) = ast::EffectRef::cast(node.clone())
            && let Some(name) = effect.segments().next()
            && let Some(symbol) = intern_ast_name_ref(&name, symbols)?
        {
            paths.push(RefinedGenericSyntaxPathHead {
                name: symbol,
                span: sai_diagnostics::Span::new(file, name.syntax().text_range()),
                kind: OwnerPathKind::Effect,
            });
        }

        if let Some(path) = ast::ConstPath::cast(node)
            && let Some(name) = path.segments().next()
            && let Some(symbol) = intern_ast_name_ref(&name, symbols)?
        {
            paths.push(RefinedGenericSyntaxPathHead {
                name: symbol,
                span: sai_diagnostics::Span::new(file, name.syntax().text_range()),
                kind: OwnerPathKind::Pattern,
            });
        }
    }

    paths.sort_by_key(|path| (path.span.range.start(), path.span.range.end()));
    paths.dedup_by_key(|path| path.span);
    Ok(paths)
}

fn intern_ast_name_ref(
    name: &ast::NameRef,
    symbols: &Interner,
) -> Result<Option<Symbol>, HirLoweringError> {
    let Some(token) = name.syntax().first_token() else {
        return Ok(None);
    };
    if token.has_error() {
        return Ok(None);
    }
    let written = token.text();
    let raw_name = written.strip_prefix("r#");
    let identifier = raw_name.unwrap_or(written);
    let invalid_raw = matches!(raw_name, Some("self" | "Self" | "_"));
    let reserved = raw_name.is_none() && sai_syntax::is_reserved_identifier(identifier);
    if invalid_raw || reserved {
        return Ok(None);
    }
    let normalized = sai_syntax::normalize_identifier(identifier);
    Ok(Some(symbols.intern(&normalized)?))
}

fn effect_syntax_test_only_path_candidates(
    declaration: &ast::EffectDecl,
    file: FileId,
    symbols: &Interner,
) -> Result<Vec<RefinedGenericSyntaxPathHead>, HirLoweringError> {
    let mut paths = Vec::new();
    if let Some(set) = declaration.covers().and_then(|clause| clause.set()) {
        for effect in set.effects() {
            if let Some(name) = effect.segments().next()
                && let Some(symbol) = intern_ast_name_ref(&name, symbols)?
            {
                paths.push(RefinedGenericSyntaxPathHead {
                    name: symbol,
                    span: sai_diagnostics::Span::new(file, name.syntax().text_range()),
                    kind: OwnerPathKind::Effect,
                });
            }
        }
    }
    paths.sort_by_key(|path| (path.span.range.start(), path.span.range.end()));
    paths.dedup_by_key(|path| path.span);
    Ok(paths)
}

fn intern_ast_name(
    name: &ast::Name,
    symbols: &Interner,
) -> Result<Option<Symbol>, HirLoweringError> {
    let Some(token) = name.syntax().first_token() else {
        return Ok(None);
    };
    if token.has_error() {
        return Ok(None);
    }
    let written = token.text();
    let raw_name = written.strip_prefix("r#");
    let identifier = raw_name.unwrap_or(written);
    let invalid_raw = matches!(raw_name, Some("self" | "Self" | "_"));
    let reserved = raw_name.is_none() && sai_syntax::is_reserved_identifier(identifier);
    if invalid_raw || reserved {
        return Ok(None);
    }
    let normalized = sai_syntax::normalize_identifier(identifier);
    Ok(Some(symbols.intern(&normalized)?))
}

fn world_ref_syntax_test_only_path_candidate(
    reference: &ast::WorldRef,
    file: FileId,
    symbols: &Interner,
) -> Result<Option<RefinedGenericSyntaxPathHead>, HirLoweringError> {
    if reference.package().is_some() {
        return Ok(None);
    }
    let Some(name) = reference.mod_path().and_then(|path| path.segments().next()) else {
        return Ok(None);
    };
    let Some(symbol) = intern_ast_name_ref(&name, symbols)? else {
        return Ok(None);
    };
    Ok(Some(RefinedGenericSyntaxPathHead {
        name: symbol,
        span: sai_diagnostics::Span::new(file, name.syntax().text_range()),
        kind: OwnerPathKind::Type,
    }))
}

fn world_item_test_only_kind(kind: ItemTreeKind) -> Option<WorldItemTestOnlyKind> {
    Some(match kind {
        ItemTreeKind::WorldItem { import: true } => WorldItemTestOnlyKind::Import,
        ItemTreeKind::WorldItem { import: false } => WorldItemTestOnlyKind::Export,
        ItemTreeKind::WorldInclude => WorldItemTestOnlyKind::Include,
        _ => return None,
    })
}

fn world_item_syntax_generic_parameter_names(
    entry: &ItemTreeEntry,
    world_owner: OwnerId,
    item_owner: OwnerId,
    inputs: &CurrentOwnerInputs,
    symbols: &Interner,
) -> Result<HashSet<Symbol>, OwnerControlFlowResolutionError> {
    let syntax = inputs
        .ast_ids
        .pointer(entry.ast_id)
        .and_then(|pointer| pointer.resolve(inputs.filtered_item_tree.file, &inputs.root))
        .ok_or(OwnerControlFlowResolutionError::MissingWorldItemSyntax {
            world: world_owner,
            item: item_owner,
        })?;
    let function = match entry.kind {
        ItemTreeKind::WorldItem { import: true } => ast::WorldImport::cast(syntax)
            .ok_or(OwnerControlFlowResolutionError::MissingWorldItemSyntax {
                world: world_owner,
                item: item_owner,
            })?
            .function(),
        ItemTreeKind::WorldItem { import: false } => ast::WorldExport::cast(syntax)
            .ok_or(OwnerControlFlowResolutionError::MissingWorldItemSyntax {
                world: world_owner,
                item: item_owner,
            })?
            .function(),
        _ => return Ok(HashSet::new()),
    };
    let mut names = HashSet::new();
    if let Some(generic_params) = function.and_then(|function| function.generic_params()) {
        for parameter in generic_params.type_params() {
            if let Some(name) = parameter.name()
                && let Some(symbol) = intern_ast_name(&name, symbols)
                    .map_err(OwnerControlFlowResolutionError::Lowering)?
            {
                names.insert(symbol);
            }
        }
        for parameter in generic_params.const_params() {
            if let Some(name) = parameter.name()
                && let Some(symbol) = intern_ast_name(&name, symbols)
                    .map_err(OwnerControlFlowResolutionError::Lowering)?
            {
                names.insert(symbol);
            }
        }
    }
    Ok(names)
}

fn world_function_syntax_test_only_path_candidates(
    function: &ast::FnDecl,
    file: FileId,
    symbols: &Interner,
) -> Result<
    (
        Vec<RefinedGenericSyntaxPathHead>,
        HashSet<Symbol>,
        HashSet<sai_diagnostics::Span>,
    ),
    HirLoweringError,
> {
    let mut paths = Vec::new();
    let mut generic_type_parameters = HashSet::new();
    let mut const_generic_parameters = HashSet::new();
    let mut local_value_names = HashSet::new();
    let mut signature_roots = Vec::new();

    if let Some(generic_params) = function.generic_params() {
        for parameter in generic_params.type_params() {
            if let Some(name) = parameter.name()
                && let Some(symbol) = intern_ast_name(&name, symbols)?
            {
                generic_type_parameters.insert(symbol);
            }
        }
        for parameter in generic_params.const_params() {
            if let Some(name) = parameter.name()
                && let Some(symbol) = intern_ast_name(&name, symbols)?
            {
                const_generic_parameters.insert(symbol);
                local_value_names.insert(symbol);
            }
        }
        signature_roots.push(generic_params.syntax().clone());
    }
    if let Some(parameters) = function.params() {
        for parameter in parameters.params() {
            if let Some(name) = parameter.name()
                && let Some(symbol) = intern_ast_name(&name, symbols)?
            {
                local_value_names.insert(symbol);
            }
            if let Some(ty) = parameter.ty() {
                signature_roots.push(ty.syntax().clone());
            }
        }
    }
    if let Some(ty) = function.ret_type().and_then(|ret| ret.ty()) {
        signature_roots.push(ty.syntax().clone());
    }
    if let Some(where_clause) = function.where_clause() {
        signature_roots.push(where_clause.syntax().clone());
    }
    if let Some(effects_clause) = function.effects_clause() {
        signature_roots.push(effects_clause.syntax().clone());
    }
    for clause in function.requires_clauses() {
        signature_roots.push(clause.syntax().clone());
    }
    for clause in function.ensures_clauses() {
        signature_roots.push(clause.syntax().clone());
    }
    if let Some(borrows_clause) = function.borrows_clause() {
        for provenance in borrows_clause.provenances() {
            if let Some(name) = provenance.segments().next()
                && let Some(symbol) = intern_ast_name_ref(&name, symbols)?
            {
                paths.push(RefinedGenericSyntaxPathHead {
                    name: symbol,
                    span: sai_diagnostics::Span::new(file, name.syntax().text_range()),
                    kind: OwnerPathKind::Expression,
                });
            }
        }
    }
    for root in signature_roots {
        paths.extend(syntax_path_candidates(&root, file, symbols)?);
    }
    paths.sort_by_key(|path| (path.span.range.start(), path.span.range.end()));
    paths.dedup_by_key(|path| path.span);
    let mut locally_resolved_expression_heads: HashSet<sai_diagnostics::Span> = paths
        .iter()
        .filter(|path| {
            matches!(
                path.kind,
                OwnerPathKind::Expression | OwnerPathKind::Pattern
            ) && local_value_names.contains(&path.name)
        })
        .map(|path| path.span)
        .collect();
    for arguments in function
        .syntax()
        .descendants()
        .filter_map(ast::GenericArgList::cast)
    {
        for argument in arguments.type_args() {
            let Some(path) = argument
                .ty()
                .and_then(|ty| ast::PathType::cast(ty.syntax().clone()))
            else {
                continue;
            };
            let segments = path.segments().collect::<Vec<_>>();
            let [segment] = segments.as_slice() else {
                continue;
            };
            if segment.generic_args().is_none()
                && let Some(name) = segment.name()
                && let Some(symbol) = intern_ast_name_ref(&name, symbols)?
                && const_generic_parameters.contains(&symbol)
            {
                locally_resolved_expression_heads
                    .insert(sai_diagnostics::Span::new(file, name.syntax().text_range()));
            }
        }
    }
    Ok((
        paths,
        generic_type_parameters,
        locally_resolved_expression_heads,
    ))
}

fn world_function_recovery_body_test_only_candidates(
    function: &ast::FnDecl,
    owner: OwnerId,
    inputs: &CurrentOwnerInputs,
    symbols: &Interner,
    context: &HirLoweringContext<'_, '_>,
    snapshot: &WorkspaceSnapshot,
) -> Result<
    (
        Vec<RefinedGenericSyntaxPathHead>,
        HashSet<sai_diagnostics::Span>,
    ),
    OwnerControlFlowResolutionError,
> {
    let (Some(body), source_map) = lower_interface_function_recovery_body(owner, function, context)
        .map_err(OwnerControlFlowResolutionError::Lowering)?
    else {
        return Ok((Vec::new(), HashSet::new()));
    };
    let locals = resolve_owner_locals(body, &source_map, snapshot, symbols, &HashSet::new())
        .map_err(OwnerControlFlowResolutionError::Locals)?;
    let locally_resolved_heads = local_expression_path_head_spans(&locals, &source_map, inputs);
    let mut paths = Vec::new();
    for block in function
        .syntax()
        .descendants()
        .filter(|node| node.kind() == sai_syntax::SyntaxKind::BLOCK)
    {
        paths.extend(
            syntax_path_candidates(&block, inputs.filtered_item_tree.file, symbols)
                .map_err(OwnerControlFlowResolutionError::Lowering)?,
        );
    }
    paths.sort_by_key(|path| (path.span.range.start(), path.span.range.end()));
    paths.dedup_by_key(|path| path.span);
    Ok((paths, locally_resolved_heads))
}

fn world_item_syntax_test_only_path_candidates(
    entry: &ItemTreeEntry,
    world_owner: OwnerId,
    item_owner: OwnerId,
    inputs: &CurrentOwnerInputs,
    symbols: &Interner,
    context: &HirLoweringContext<'_, '_>,
    snapshot: &WorkspaceSnapshot,
) -> Result<
    (
        Vec<RefinedGenericSyntaxPathHead>,
        HashSet<Symbol>,
        HashSet<sai_diagnostics::Span>,
    ),
    OwnerControlFlowResolutionError,
> {
    let syntax = inputs
        .ast_ids
        .pointer(entry.ast_id)
        .and_then(|pointer| pointer.resolve(inputs.filtered_item_tree.file, &inputs.root))
        .ok_or(OwnerControlFlowResolutionError::MissingWorldItemSyntax {
            world: world_owner,
            item: item_owner,
        })?;
    let mut paths = Vec::new();
    let mut generic_type_parameters = HashSet::new();
    let mut local_expression_heads = HashSet::new();
    match entry.kind {
        ItemTreeKind::WorldItem { import: true } => {
            let declaration = ast::WorldImport::cast(syntax).ok_or(
                OwnerControlFlowResolutionError::MissingWorldItemSyntax {
                    world: world_owner,
                    item: item_owner,
                },
            )?;
            if let Some(function) = declaration.function() {
                (paths, generic_type_parameters, local_expression_heads) =
                    world_function_syntax_test_only_path_candidates(
                        &function,
                        inputs.filtered_item_tree.file,
                        symbols,
                    )
                    .map_err(OwnerControlFlowResolutionError::Lowering)?;
                // The body is parser-recovered syntax and supplemental to the
                // retained signature. An unsupported body must not discard
                // diagnostics already collected from that signature.
                if let Ok((body_paths, body_local_heads)) =
                    world_function_recovery_body_test_only_candidates(
                        &function, item_owner, inputs, symbols, context, snapshot,
                    )
                {
                    paths.extend(body_paths);
                    local_expression_heads.extend(body_local_heads);
                }
            } else if let Some(reference) = declaration.reference()
                && let Some(candidate) = world_ref_syntax_test_only_path_candidate(
                    &reference,
                    inputs.filtered_item_tree.file,
                    symbols,
                )
                .map_err(OwnerControlFlowResolutionError::Lowering)?
            {
                paths.push(candidate);
            }
        }
        ItemTreeKind::WorldItem { import: false } => {
            let declaration = ast::WorldExport::cast(syntax).ok_or(
                OwnerControlFlowResolutionError::MissingWorldItemSyntax {
                    world: world_owner,
                    item: item_owner,
                },
            )?;
            if let Some(function) = declaration.function() {
                (paths, generic_type_parameters, local_expression_heads) =
                    world_function_syntax_test_only_path_candidates(
                        &function,
                        inputs.filtered_item_tree.file,
                        symbols,
                    )
                    .map_err(OwnerControlFlowResolutionError::Lowering)?;
                // The body is parser-recovered syntax and supplemental to the
                // retained signature. An unsupported body must not discard
                // diagnostics already collected from that signature.
                if let Ok((body_paths, body_local_heads)) =
                    world_function_recovery_body_test_only_candidates(
                        &function, item_owner, inputs, symbols, context, snapshot,
                    )
                {
                    paths.extend(body_paths);
                    local_expression_heads.extend(body_local_heads);
                }
            } else if let Some(reference) = declaration.reference()
                && let Some(candidate) = world_ref_syntax_test_only_path_candidate(
                    &reference,
                    inputs.filtered_item_tree.file,
                    symbols,
                )
                .map_err(OwnerControlFlowResolutionError::Lowering)?
            {
                paths.push(candidate);
            }
        }
        ItemTreeKind::WorldInclude => {
            let declaration = ast::WorldInclude::cast(syntax).ok_or(
                OwnerControlFlowResolutionError::MissingWorldItemSyntax {
                    world: world_owner,
                    item: item_owner,
                },
            )?;
            if let Some(reference) = declaration.reference()
                && let Some(candidate) = world_ref_syntax_test_only_path_candidate(
                    &reference,
                    inputs.filtered_item_tree.file,
                    symbols,
                )
                .map_err(OwnerControlFlowResolutionError::Lowering)?
            {
                paths.push(candidate);
            }
        }
        _ => {
            return Err(OwnerControlFlowResolutionError::Lowering(
                HirLoweringError::ItemTreeEntryMismatch,
            ));
        }
    }
    paths.sort_by_key(|path| (path.span.range.start(), path.span.range.end()));
    paths.dedup_by_key(|path| path.span);
    Ok((paths, generic_type_parameters, local_expression_heads))
}

fn is_builtin_effect_root(symbol: Symbol, symbols: &Interner) -> bool {
    let Ok(name) = symbols.resolve(symbol) else {
        return false;
    };
    matches!(
        name.as_ref(),
        "alloc"
            | "fs"
            | "net"
            | "clock"
            | "random"
            | "stdio"
            | "env"
            | "process"
            | "thread"
            | "host"
            | "ffi"
    )
}

fn collect_test_only_reference_diagnostics(
    owner: OwnerId,
    deferred_paths: &[DeferredPath],
    module_scope: &Phase1ModuleScopes,
    module_resolution: &mut ModuleResolution,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
) -> Result<Vec<Diagnostic>, OwnerControlFlowResolutionError> {
    let mut diagnostics = Vec::new();
    let mut candidates = deferred_paths.to_vec();
    candidates.sort_by_key(|candidate| candidate.span.range.start());
    for candidate in candidates {
        let Some(binding) = module_scope.scope.get(&candidate.name) else {
            continue;
        };
        let import_index = match binding.origin {
            BindingOrigin::Decl => continue,
            BindingOrigin::Use { import } | BindingOrigin::PubUse { import } => import,
        };
        let import = module_scope.imports.get(import_index.0 as usize).ok_or(
            OwnerControlFlowResolutionError::MissingImportBinding {
                owner,
                import: import_index,
            },
        )?;
        if !import.test_only {
            continue;
        }

        // A deferred expression path may be shadowed by an owner generic.
        // Only paths the module resolver actually claimed can refer here.
        let Some(path) = module_resolution.paths.get_mut(&candidate.hir_id) else {
            continue;
        };
        path.base = Res::Err;
        module_resolution
            .deferred_paths
            .retain(|deferred| deferred.hir_id != candidate.hir_id);

        diagnostics.push(test_only_reference_diagnostic(
            owner,
            candidate.span,
            import_index,
            import.use_ast_id,
            inputs,
            snapshot,
        )?);
    }
    Ok(diagnostics)
}

fn collect_test_only_module_head_diagnostics(
    owner: OwnerId,
    candidates: &[OwnerPathHead<'_, '_>],
    generic_parameters: &HashSet<Symbol>,
    module_scope: &Phase1ModuleScopes,
    path_resolution: &mut OwnerTestOnlyPathResolution,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
) -> Result<Vec<Diagnostic>, OwnerControlFlowResolutionError> {
    let mut diagnostics = Vec::new();
    for candidate in candidates {
        if matches!(candidate.kind, OwnerPathKind::Type | OwnerPathKind::Pattern)
            && generic_parameters.contains(&candidate.name)
        {
            continue;
        }
        if candidate.kind == OwnerPathKind::Effect
            && is_builtin_effect_root(candidate.name, symbols)
        {
            continue;
        }
        let Some(binding) = module_scope.scope.get(&candidate.name) else {
            continue;
        };
        let import_index = match binding.origin {
            BindingOrigin::Decl => continue,
            BindingOrigin::Use { import } | BindingOrigin::PubUse { import } => import,
        };
        let import = module_scope.imports.get(import_index.0 as usize).ok_or(
            OwnerControlFlowResolutionError::MissingImportBinding {
                owner,
                import: import_index,
            },
        )?;
        if !import.test_only {
            continue;
        }

        path_resolution.paths.insert(
            candidate.hir_id,
            PathRes {
                base: Res::Err,
                resolved_segments: 1,
                segment_count: candidate.segment_count,
            },
        );
        diagnostics.push(test_only_reference_diagnostic(
            owner,
            candidate.span,
            import_index,
            import.use_ast_id,
            inputs,
            snapshot,
        )?);
    }
    Ok(diagnostics)
}

fn rejected_test_only_type_path_ids(
    owner: OwnerId,
    candidates: &[OwnerPathHead<'_, '_>],
    generic_parameters: &HashSet<Symbol>,
    module_scope: &Phase1ModuleScopes,
) -> Result<HashSet<HirId>, OwnerControlFlowResolutionError> {
    let mut rejected_paths = HashSet::new();
    for candidate in candidates
        .iter()
        .filter(|candidate| candidate.kind == OwnerPathKind::Type)
    {
        if generic_parameters.contains(&candidate.name) {
            continue;
        }
        let Some(binding) = module_scope.scope.get(&candidate.name) else {
            continue;
        };
        let import_index = match binding.origin {
            BindingOrigin::Decl => continue,
            BindingOrigin::Use { import } | BindingOrigin::PubUse { import } => import,
        };
        let import = module_scope.imports.get(import_index.0 as usize).ok_or(
            OwnerControlFlowResolutionError::MissingImportBinding {
                owner,
                import: import_index,
            },
        )?;
        if import.test_only {
            rejected_paths.insert(candidate.hir_id);
        }
    }
    Ok(rejected_paths)
}

fn resolve_partial_type_owner_paths(
    owner: OwnerId,
    candidates: &[OwnerPathHead<'_, '_>],
    generic_resolutions: &HashMap<Symbol, Res>,
    primitive_prelude: &Result<Prelude, PrimitivePreludeBuildError>,
    module_scope: &Phase1ModuleScopes,
    requesting_package: PackageId,
    members: Option<&ModuleMemberIndex<'_>>,
    source_graph_packages: Option<&HashSet<PackageId>>,
) -> Result<TypeOwnerPathResolution, OwnerControlFlowResolutionError> {
    let generic_parameters = generic_resolutions.keys().copied().collect();
    let rejected_test_only_paths =
        rejected_test_only_type_path_ids(owner, candidates, &generic_parameters, module_scope)?;
    match primitive_prelude {
        Ok(primitive_prelude) => Ok(resolve_type_owner_module_paths(
            owner,
            candidates,
            generic_resolutions,
            primitive_prelude,
            &rejected_test_only_paths,
            module_scope,
            members,
            requesting_package,
            source_graph_packages,
        )),
        Err(error) => Err(OwnerControlFlowResolutionError::PrimitivePrelude(
            error.clone(),
        )),
    }
}

fn collect_refined_generic_syntax_test_only_diagnostics(
    owner: OwnerId,
    item_id: ast::ErasedAstId,
    hir_owner: &HirOwner<'_>,
    source_map: &HirSourceMap,
    generic_parameters: &HashSet<Symbol>,
    module_scope: &Phase1ModuleScopes,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
) -> Result<Vec<Diagnostic>, OwnerControlFlowResolutionError> {
    let syntax = inputs
        .ast_ids
        .pointer(item_id)
        .and_then(|pointer| pointer.resolve(inputs.filtered_item_tree.file, &inputs.root))
        .ok_or(OwnerControlFlowResolutionError::MissingRefinedTypeSyntax(
            owner,
        ))?;
    let type_decl = ast::TypeDecl::cast(syntax).ok_or(
        OwnerControlFlowResolutionError::MissingRefinedTypeSyntax(owner),
    )?;
    let candidates =
        refined_generic_syntax_path_candidates(&type_decl, inputs.filtered_item_tree.file, symbols)
            .map_err(OwnerControlFlowResolutionError::Lowering)?;
    let locally_resolved_expression_heads = if let Some(body) = hir_owner.body {
        let locals = resolve_owner_locals(body, source_map, snapshot, symbols, &HashSet::new())
            .map_err(OwnerControlFlowResolutionError::Locals)?;
        local_expression_path_head_spans(&locals, source_map, inputs)
    } else {
        HashSet::new()
    };

    collect_ast_test_only_path_diagnostics(
        owner,
        &candidates,
        generic_parameters,
        &locally_resolved_expression_heads,
        module_scope,
        symbols,
        inputs,
        snapshot,
    )
}

fn local_expression_path_head_spans(
    locals: &LocalResolution,
    source_map: &HirSourceMap,
    inputs: &CurrentOwnerInputs,
) -> HashSet<sai_diagnostics::Span> {
    locals
        .paths
        .iter()
        .filter_map(|(hir_id, resolution)| {
            matches!(resolution.base, Res::Local(_)).then_some(())?;
            let pointer = source_map.syntax_for_node(*hir_id)?;
            let syntax = pointer.resolve(inputs.filtered_item_tree.file, &inputs.root)?;
            let path = ast::PathExpr::cast(syntax)?;
            let name = path.name()?;
            Some(sai_diagnostics::Span::new(
                inputs.filtered_item_tree.file,
                name.syntax().text_range(),
            ))
        })
        .collect()
}

fn collect_ast_test_only_path_diagnostics(
    owner: OwnerId,
    candidates: &[RefinedGenericSyntaxPathHead],
    generic_parameters: &HashSet<Symbol>,
    locally_resolved_expression_heads: &HashSet<sai_diagnostics::Span>,
    module_scope: &Phase1ModuleScopes,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
) -> Result<Vec<Diagnostic>, OwnerControlFlowResolutionError> {
    let mut diagnostics = Vec::new();
    for candidate in candidates {
        if locally_resolved_expression_heads.contains(&candidate.span) {
            continue;
        }
        if matches!(
            candidate.kind,
            OwnerPathKind::Type | OwnerPathKind::Expression | OwnerPathKind::Pattern
        ) && generic_parameters.contains(&candidate.name)
        {
            continue;
        }
        if candidate.kind == OwnerPathKind::Effect
            && is_builtin_effect_root(candidate.name, symbols)
        {
            continue;
        }
        let Some(binding) = module_scope.scope.get(&candidate.name) else {
            continue;
        };
        let import_index = match binding.origin {
            BindingOrigin::Decl => continue,
            BindingOrigin::Use { import } | BindingOrigin::PubUse { import } => import,
        };
        let import = module_scope.imports.get(import_index.0 as usize).ok_or(
            OwnerControlFlowResolutionError::MissingImportBinding {
                owner,
                import: import_index,
            },
        )?;
        if !import.test_only {
            continue;
        }

        diagnostics.push(test_only_reference_diagnostic_at(
            owner,
            candidate.span,
            import_index,
            import.use_ast_id,
            inputs,
            snapshot,
        )?);
    }
    Ok(diagnostics)
}

fn test_only_reference_diagnostic(
    owner: OwnerId,
    reference_span: sai_hir::Span,
    import_index: ImportIndex,
    use_ast_id: ast::ErasedAstId,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
) -> Result<Diagnostic, OwnerControlFlowResolutionError> {
    test_only_reference_diagnostic_at(
        owner,
        sai_diagnostics::Span::new(reference_span.file, reference_span.range),
        import_index,
        use_ast_id,
        inputs,
        snapshot,
    )
}

fn test_only_reference_diagnostic_at(
    owner: OwnerId,
    reference_span: sai_diagnostics::Span,
    import_index: ImportIndex,
    use_ast_id: ast::ErasedAstId,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
) -> Result<Diagnostic, OwnerControlFlowResolutionError> {
    let reference = sai_diagnostics::Location::from_decoded_source(
        inputs.source_ref.clone(),
        reference_span,
        &inputs.source,
    )
    .ok_or(OwnerControlFlowResolutionError::InvalidSourceLocation(
        owner,
    ))?;
    let syntax = inputs
        .ast_ids
        .pointer(use_ast_id)
        .and_then(|pointer| pointer.resolve(inputs.filtered_item_tree.file, &inputs.root))
        .ok_or(OwnerControlFlowResolutionError::MissingTestOnlyUseSyntax {
            owner,
            import: import_index,
        })?;
    let use_decl = ast::UseDecl::cast(syntax).ok_or(
        OwnerControlFlowResolutionError::MissingTestOnlyUseSyntax {
            owner,
            import: import_index,
        },
    )?;
    let package_path =
        use_decl
            .package()
            .ok_or(OwnerControlFlowResolutionError::MissingTestOnlyUseSyntax {
                owner,
                import: import_index,
            })?;
    let use_location = sai_diagnostics::Location::from_decoded_source(
        inputs.source_ref.clone(),
        sai_diagnostics::Span::new(
            inputs.filtered_item_tree.file,
            package_path.syntax().text_range(),
        ),
        &inputs.source,
    )
    .ok_or(OwnerControlFlowResolutionError::InvalidSourceLocation(
        owner,
    ))?;
    let mut diagnostic = Diagnostic::new(
        sai_diagnostics::Code::TestDependencyOutsideTest,
        sai_diagnostics::Severity::Error,
        "test-only bindings may be referenced only from test or property owners",
        Some(reference),
    );
    diagnostic.primary_label = "test-only reference outside a test or property".to_owned();
    diagnostic.package = inputs.source_ref.package.clone();
    diagnostic
        .push_related(Related::DeclaredHere {
            location: use_location,
            what: "test-only use".to_owned(),
        })
        .map_err(|_| OwnerControlFlowResolutionError::InvalidSourceLocation(owner))?;
    let diagnostic = diagnostic
        .with_workspace_snapshot(snapshot)
        .map_err(|_| OwnerControlFlowResolutionError::InvalidSourceLocation(owner))?;
    Ok(diagnostic)
}

fn module_aliases_for_scope(module_scope: &Phase1ModuleScopes) -> HashSet<Symbol> {
    module_scope
        .scope
        .iter()
        .filter_map(|(name, binding)| {
            let import_index = match binding.origin {
                BindingOrigin::Decl => return None,
                BindingOrigin::Use { import } | BindingOrigin::PubUse { import } => import,
            };
            let import = module_scope.imports.get(import_index.0 as usize)?;
            if import.item_index.is_some() {
                return None;
            }

            let is_resolved_module_alias = matches!(
                binding.res,
                Res::Def(DefKind::Module | DefKind::Interface, _)
            );
            let is_unresolved_test_only_module_alias = import.test_only
                && match binding.res {
                    Res::TestOnly(res_import) => res_import == import_index,
                    // Test-only module aliases rejected because the current
                    // package cannot use test edges remain syntax-known
                    // module names even though Phase 1 stores `Res::Err`.
                    Res::Err => true,
                    Res::Def(_, _) | Res::Local(_) | Res::PrimTy(_) => false,
                };
            (is_resolved_module_alias || is_unresolved_test_only_module_alias).then_some(*name)
        })
        .collect()
}

fn owner_generic_parameters(owner: &HirOwner<'_>) -> HashSet<Symbol> {
    let generics = match owner.node {
        OwnerNode::Item(item) => match item.kind {
            ItemKind::Fn { generics, .. }
            | ItemKind::Struct { generics, .. }
            | ItemKind::Alias { generics, .. }
            | ItemKind::Enum { generics, .. }
            | ItemKind::Distinct { generics, .. }
            | ItemKind::Trait { generics, .. }
            | ItemKind::Impl { generics, .. } => generics,
            _ => return HashSet::new(),
        },
        OwnerNode::ExternItem(item) => item.generics,
        OwnerNode::TraitItem(item) => match item.kind {
            TraitItemKind::Fn { generics, .. } => generics,
            TraitItemKind::AssocType { .. } => return HashSet::new(),
        },
        OwnerNode::ImplItem(item) => match item.kind {
            ImplItemKind::Fn { generics, .. } => generics,
            ImplItemKind::AssocType { .. } => return HashSet::new(),
        },
        OwnerNode::InterfaceItem(item) => match item.kind {
            HirInterfaceItemKind::Struct { generics, .. }
            | HirInterfaceItemKind::Alias { generics, .. }
            | HirInterfaceItemKind::Enum { generics, .. }
            | HirInterfaceItemKind::Fn { generics, .. }
            | HirInterfaceItemKind::ResourceMember { generics, .. } => generics,
            HirInterfaceItemKind::Refined { .. } | HirInterfaceItemKind::Resource { .. } => {
                return HashSet::new();
            }
        },
        _ => return HashSet::new(),
    };
    generics
        .params
        .iter()
        .map(|parameter| parameter.name.sym)
        .filter(|name| !name.is_error())
        .collect()
}

fn owner_type_generic_resolutions(owner: &HirOwner<'_>) -> HashMap<Symbol, Res> {
    let generics = match owner.node {
        OwnerNode::Item(item) => match item.kind {
            ItemKind::Fn { generics, .. }
            | ItemKind::Struct { generics, .. }
            | ItemKind::Alias { generics, .. }
            | ItemKind::Enum { generics, .. }
            | ItemKind::Trait { generics, .. }
            | ItemKind::Impl { generics, .. }
            | ItemKind::Distinct { generics, .. } => generics,
            ItemKind::Resource { .. } => return HashMap::new(),
            _ => return HashMap::new(),
        },
        OwnerNode::ExternItem(item) => item.generics,
        OwnerNode::TraitItem(item) => match item.kind {
            TraitItemKind::Fn { generics, .. } => generics,
            TraitItemKind::AssocType { .. } => return HashMap::new(),
        },
        OwnerNode::ImplItem(item) => match item.kind {
            ImplItemKind::Fn { generics, .. } => generics,
            ImplItemKind::AssocType { .. } => return HashMap::new(),
        },
        OwnerNode::InterfaceItem(item) => match item.kind {
            HirInterfaceItemKind::Struct { generics, .. }
            | HirInterfaceItemKind::Alias { generics, .. }
            | HirInterfaceItemKind::Enum { generics, .. }
            | HirInterfaceItemKind::Fn { generics, .. }
            | HirInterfaceItemKind::ResourceMember { generics, .. } => generics,
            HirInterfaceItemKind::Refined { .. } | HirInterfaceItemKind::Resource { .. } => {
                return HashMap::new();
            }
        },
        _ => return HashMap::new(),
    };
    let mut resolutions = HashMap::with_capacity(generics.params.len());
    for parameter in generics.params {
        if parameter.name.is_error() {
            continue;
        }
        let kind = match parameter.kind {
            GenericParamKind::Type { .. } => DefKind::TyParam,
            GenericParamKind::Const { .. } => DefKind::ConstParam,
        };
        // Duplicate generic names are diagnosed by semantic validation. For
        // recovery, the earliest binding wins as it does in lexical ribs.
        resolutions
            .entry(parameter.name.sym)
            .or_insert(Res::Def(kind, parameter.def_id.to_def_id()));
    }
    resolutions
}

fn local_interface_impl_interfaces(
    database: &mut RootDatabase,
    collection: &Phase1PackageScopesCollection,
    snapshot: &WorkspaceSnapshot,
) -> Result<HashMap<DefId, InterfaceImplInterface>, OwnerControlFlowResolutionError> {
    let mut interfaces = HashMap::new();
    let owner_index = index_top_level_owner_descriptors(collection);
    for descriptor in collection
        .scopes
        .top_level_owners
        .iter()
        .copied()
        .filter(|descriptor| descriptor.kind == TopLevelOwnerKind::Interface)
    {
        let inputs =
            database.current_owner_inputs(snapshot, descriptor.file, &collection.target_cfg)?;
        if inputs.retained_item_kinds.get(&descriptor.item_id) != Some(&ItemTreeKind::Interface) {
            return Err(
                OwnerControlFlowResolutionError::DescriptorNotInCurrentTarget {
                    owner: descriptor.owner,
                    file: descriptor.file,
                },
            );
        }
        let def_paths = database
            .def_paths
            .get(&descriptor.owner.def_id.package())
            .cloned()
            .ok_or(OwnerControlFlowResolutionError::MissingDefPath(
                descriptor.owner,
            ))?;
        let expected_path = def_paths
            .resolve_def_id(descriptor.owner.def_id.to_def_id())
            .map_err(OwnerControlFlowResolutionError::DefPathInterner)?
            .ok_or(OwnerControlFlowResolutionError::MissingDefPath(
                descriptor.owner,
            ))?;
        let arena = HirArena::new();
        let context = HirLoweringContext::new(
            &inputs.ast_ids,
            snapshot,
            &inputs.root,
            &arena,
            &database.symbols,
            &def_paths,
        );
        let owner_descriptor = find_top_level_owner_descriptor(
            &owner_index,
            descriptor.owner,
            descriptor.file,
            descriptor.item_id,
            TopLevelOwnerKind::Interface,
        )?;
        let (hir_owner, _) = lower_top_level_owner(
            owner_descriptor,
            &expected_path,
            &inputs.filtered_item_tree,
            &inputs.retained_item_kinds,
            &context,
        )?;
        let parent_members = match hir_owner.node {
            OwnerNode::Item(item) => match item.kind {
                ItemKind::Interface { items } => items,
                _ => {
                    return Err(OwnerControlFlowResolutionError::TopLevelOwnerKindMismatch {
                        owner: descriptor.owner,
                        file: descriptor.file,
                        descriptor: TopLevelOwnerKind::Interface,
                        current: ItemTreeKind::Interface,
                    });
                }
            },
            _ => {
                return Err(
                    OwnerControlFlowResolutionError::TopLevelOwnerDescriptorMismatch {
                        owner: descriptor.owner,
                        file: descriptor.file,
                    },
                );
            }
        };
        let parent_entry = inputs
            .filtered_item_tree
            .items
            .iter()
            .find(|entry| {
                entry.ast_id == descriptor.item_id && entry.kind == ItemTreeKind::Interface
            })
            .ok_or(
                OwnerControlFlowResolutionError::DescriptorNotInCurrentTarget {
                    owner: descriptor.owner,
                    file: descriptor.file,
                },
            )?;
        let member_entries = parent_entry
            .children
            .iter()
            .filter(|entry| interface_member_kind(entry.kind).is_some())
            .collect::<Vec<_>>();
        if member_entries.len() != parent_members.len() {
            return Err(OwnerControlFlowResolutionError::Lowering(
                HirLoweringError::ItemTreeEntryMismatch,
            ));
        }
        let interface_scope = collection
            .scopes
            .interfaces
            .get(&descriptor.owner.def_id.to_def_id())
            .ok_or(OwnerControlFlowResolutionError::MissingInterfaceScope(
                descriptor.owner,
            ))?;
        let effective_members = interface_scope
            .members
            .values()
            .filter_map(|binding| match binding.res {
                Res::Def(DefKind::Fn | DefKind::Resource, def) => Some(def),
                _ => None,
            })
            .collect::<HashSet<_>>();
        let mut items = Vec::new();
        for (entry, member_owner) in member_entries
            .into_iter()
            .zip(parent_members.iter().copied())
        {
            if !effective_members.contains(&member_owner.def_id.to_def_id()) {
                continue;
            }
            let member_path = def_paths
                .resolve_def_id(member_owner.def_id.to_def_id())
                .map_err(OwnerControlFlowResolutionError::DefPathInterner)?
                .ok_or(OwnerControlFlowResolutionError::MissingDefPath(
                    member_owner,
                ))?;
            let (member_hir, _) = lower_interface_item_owner(
                member_owner,
                &member_path,
                &hir_owner,
                descriptor.item_id,
                entry.ast_id,
                &inputs.filtered_item_tree,
                &context,
            )
            .map_err(OwnerControlFlowResolutionError::Lowering)?;
            let OwnerNode::InterfaceItem(item) = member_hir.node else {
                return Err(OwnerControlFlowResolutionError::Lowering(
                    HirLoweringError::ItemTreeEntryMismatch,
                ));
            };
            if item.name.is_error() {
                continue;
            }
            let name = database
                .symbols
                .resolve(item.name.sym)
                .map_err(OwnerControlFlowResolutionError::SymbolLookup)?
                .to_string();
            let kind = match item.kind {
                HirInterfaceItemKind::Fn { sig, .. } => InterfaceImplInterfaceItemKind::Function {
                    unsupported: sig
                        .is_async
                        .then_some(InterfaceImplUnsupportedFunction::AsyncBeforeStage5),
                },
                HirInterfaceItemKind::Resource { .. } => InterfaceImplInterfaceItemKind::Resource,
                _ => continue,
            };
            items.push(InterfaceImplInterfaceItem {
                def: member_owner.def_id.to_def_id(),
                name,
                kind,
            });
        }
        interfaces.insert(
            descriptor.owner.def_id.to_def_id(),
            InterfaceImplInterface {
                def: descriptor.owner.def_id.to_def_id(),
                items,
            },
        );
    }
    Ok(interfaces)
}

fn collect_interface_resource_aliases<'hir>(
    symbols: &Interner,
    def_paths_by_package: &HashMap<PackageId, Arc<DefPathInterner>>,
    primitive_prelude: &Result<Prelude, PrimitivePreludeBuildError>,
    collection: &Phase1PackageScopesCollection,
    inputs_by_file: &'hir HashMap<FileId, CurrentOwnerInputs>,
    snapshot: &WorkspaceSnapshot,
    arena: &'hir HirArena<'hir>,
    module_members: &ModuleMemberIndex<'_>,
    source_graph_packages: &HashSet<PackageId>,
    aliases: &mut HashMap<DefId, LocalTypeAlias<'hir>>,
    path_resolutions: &mut HashMap<HirId, PathRes>,
) -> Result<(), OwnerControlFlowResolutionError> {
    let owner_index = index_top_level_owner_descriptors(collection);
    for descriptor in collection
        .scopes
        .top_level_owners
        .iter()
        .copied()
        .filter(|descriptor| descriptor.kind == TopLevelOwnerKind::Interface)
    {
        let inputs = inputs_by_file
            .get(&descriptor.file)
            .expect("interface owner inputs were collected before alias lowering");
        if inputs.retained_item_kinds.get(&descriptor.item_id) != Some(&ItemTreeKind::Interface) {
            return Err(
                OwnerControlFlowResolutionError::DescriptorNotInCurrentTarget {
                    owner: descriptor.owner,
                    file: descriptor.file,
                },
            );
        }
        let def_paths = def_paths_by_package
            .get(&descriptor.owner.def_id.package())
            .cloned()
            .ok_or(OwnerControlFlowResolutionError::MissingDefPath(
                descriptor.owner,
            ))?;
        let expected_path = def_paths
            .resolve_def_id(descriptor.owner.def_id.to_def_id())
            .map_err(OwnerControlFlowResolutionError::DefPathInterner)?
            .ok_or(OwnerControlFlowResolutionError::MissingDefPath(
                descriptor.owner,
            ))?;
        let context = HirLoweringContext::new(
            &inputs.ast_ids,
            snapshot,
            &inputs.root,
            arena,
            symbols,
            &def_paths,
        );
        let owner_descriptor = find_top_level_owner_descriptor(
            &owner_index,
            descriptor.owner,
            descriptor.file,
            descriptor.item_id,
            TopLevelOwnerKind::Interface,
        )?;
        let (interface_hir, _) = lower_top_level_owner(
            owner_descriptor,
            &expected_path,
            &inputs.filtered_item_tree,
            &inputs.retained_item_kinds,
            &context,
        )?;
        let interface_members = match interface_hir.node {
            OwnerNode::Item(item) => match item.kind {
                ItemKind::Interface { items } => items,
                _ => {
                    return Err(OwnerControlFlowResolutionError::TopLevelOwnerKindMismatch {
                        owner: descriptor.owner,
                        file: descriptor.file,
                        descriptor: TopLevelOwnerKind::Interface,
                        current: ItemTreeKind::Interface,
                    });
                }
            },
            _ => {
                return Err(
                    OwnerControlFlowResolutionError::TopLevelOwnerDescriptorMismatch {
                        owner: descriptor.owner,
                        file: descriptor.file,
                    },
                );
            }
        };
        let parent_entry = inputs
            .filtered_item_tree
            .items
            .iter()
            .find(|entry| {
                entry.ast_id == descriptor.item_id && entry.kind == ItemTreeKind::Interface
            })
            .ok_or(
                OwnerControlFlowResolutionError::DescriptorNotInCurrentTarget {
                    owner: descriptor.owner,
                    file: descriptor.file,
                },
            )?;
        let member_entries = parent_entry
            .children
            .iter()
            .filter(|entry| interface_member_kind(entry.kind).is_some())
            .collect::<Vec<_>>();
        if member_entries.len() != interface_members.len() {
            return Err(OwnerControlFlowResolutionError::Lowering(
                HirLoweringError::ItemTreeEntryMismatch,
            ));
        }
        let interface_scope = collection
            .scopes
            .interfaces
            .get(&descriptor.owner.def_id.to_def_id())
            .ok_or(OwnerControlFlowResolutionError::MissingInterfaceScope(
                descriptor.owner,
            ))?;
        let effective_aliases = interface_scope
            .members
            .values()
            .filter_map(|binding| match binding.res {
                Res::Def(DefKind::Alias, def) => Some(def),
                _ => None,
            })
            .collect::<HashSet<_>>();
        let module_scope =
            module_scope_for_file(collection, &collection.module_tree, descriptor.file)?;
        let interface_module_scope = interface_use_queries::module_scope_with_interface_members(
            module_scope,
            collection.scopes(),
            descriptor.owner,
        )?;

        for (entry, member_owner) in member_entries
            .into_iter()
            .zip(interface_members.iter().copied())
        {
            if !effective_aliases.contains(&member_owner.def_id.to_def_id()) {
                continue;
            }
            let member_path = def_paths
                .resolve_def_id(member_owner.def_id.to_def_id())
                .map_err(OwnerControlFlowResolutionError::DefPathInterner)?
                .ok_or(OwnerControlFlowResolutionError::MissingDefPath(
                    member_owner,
                ))?;
            let (member_hir, _) = lower_interface_item_owner(
                member_owner,
                &member_path,
                &interface_hir,
                descriptor.item_id,
                entry.ast_id,
                &inputs.filtered_item_tree,
                &context,
            )
            .map_err(OwnerControlFlowResolutionError::Lowering)?;
            let OwnerNode::InterfaceItem(item) = member_hir.node else {
                return Err(OwnerControlFlowResolutionError::Lowering(
                    HirLoweringError::ItemTreeEntryMismatch,
                ));
            };
            let HirInterfaceItemKind::Alias { generics, ty } = item.kind else {
                continue;
            };
            let candidates = owner_test_only_path_candidates(&member_hir);
            let generic_resolutions = owner_type_generic_resolutions(&member_hir);
            let resolution = resolve_partial_type_owner_paths(
                member_owner,
                &candidates,
                &generic_resolutions,
                primitive_prelude,
                &interface_module_scope,
                collection.module_tree.package,
                Some(module_members),
                Some(source_graph_packages),
            )?;
            path_resolutions.extend(
                resolution
                    .paths()
                    .iter()
                    .map(|(hir_id, resolution)| (*hir_id, *resolution)),
            );
            aliases.insert(
                member_owner.def_id.to_def_id(),
                LocalTypeAlias {
                    owner: member_owner,
                    params: generics.params,
                    target: ty,
                },
            );
        }
    }
    Ok(())
}

fn wit_view_interface_impl_interfaces(
    wit_view_scopes: &Phase1ActiveWitViewScopes,
) -> HashMap<DefId, InterfaceImplInterface> {
    let mut interfaces = HashMap::new();
    for foreign in wit_view_scopes.views() {
        for view_interface in foreign.view.interfaces.values() {
            let model_interface = &foreign.view.model.interfaces[view_interface.wit];
            let mut members_by_item = HashMap::with_capacity(view_interface.members.len());
            for (canonical_name, member) in &view_interface.members {
                members_by_item.insert(member.item, (canonical_name, member));
            }
            let mut items = Vec::new();
            for (item_index, _) in model_interface.items.iter_enumerated() {
                let Some((canonical_name, member)) = members_by_item.get(&item_index) else {
                    continue;
                };
                let kind = match member.kind {
                    WitViewDefKind::Fn => {
                        let unsupported = member.unsupported.map(|unsupported| match unsupported {
                            Unsupported::Async => {
                                InterfaceImplUnsupportedFunction::AsyncBeforeStage5
                            }
                            unsupported => InterfaceImplUnsupportedFunction::Wit(unsupported),
                        });
                        InterfaceImplInterfaceItemKind::Function { unsupported }
                    }
                    WitViewDefKind::Resource => InterfaceImplInterfaceItemKind::Resource,
                    _ => continue,
                };
                items.push(InterfaceImplInterfaceItem {
                    def: member.def,
                    name: (*canonical_name).clone(),
                    kind,
                });
            }
            interfaces.insert(
                view_interface.def,
                InterfaceImplInterface {
                    def: view_interface.def,
                    items,
                },
            );
        }
    }
    interfaces
}

fn interface_impl_source_location(
    owner: OwnerId,
    span: sai_hir::Span,
    inputs: &CurrentOwnerInputs,
) -> Result<sai_diagnostics::Location, OwnerControlFlowResolutionError> {
    if span.file != inputs.filtered_item_tree.file {
        return Err(OwnerControlFlowResolutionError::InvalidSourceLocation(
            owner,
        ));
    }
    sai_diagnostics::Location::from_decoded_source(
        inputs.source_ref.clone(),
        sai_diagnostics::Span::new(span.file, span.range),
        &inputs.source,
    )
    .ok_or(OwnerControlFlowResolutionError::InvalidSourceLocation(
        owner,
    ))
}

fn validate_interface_resource_bindings(
    package: &str,
    module_tree: &ModuleTree,
    collection: &Phase1PackageScopesCollection,
    external_checks: &HashMap<DefId, InterfaceResourceExternalCheck>,
    interface_impls: &mut InterfaceImpls,
) -> Vec<(sai_hir::LocalDefId, Diagnostic)> {
    let top_level_resources = collection
        .scopes
        .top_level_owners
        .iter()
        .filter(|descriptor| descriptor.kind == TopLevelOwnerKind::Resource)
        .map(|descriptor| descriptor.owner.def_id.to_def_id())
        .collect::<HashSet<_>>();
    let mut first_binding_by_type = HashMap::<sai_hir::DefId, sai_diagnostics::Location>::new();
    let mut diagnostics = Vec::new();

    for implementation in &mut interface_impls.impls {
        let is_selected_impl = implementation.interface.is_some_and(|interface| {
            interface_impls.by_interface.get(&interface) == Some(&implementation.impl_def)
        });
        let candidates = std::mem::take(&mut implementation.resource_bindings);
        if !is_selected_impl {
            continue;
        }

        for binding in candidates {
            let implementation_type = match binding.implementation_type {
                InterfaceImplTypeResolution::Unresolved => continue,
                InterfaceImplTypeResolution::NonDefinition => {
                    diagnostics.push((
                        implementation.impl_def,
                        invalid_interface_resource_binding_diagnostic(
                            package,
                            &binding,
                            "the binding target is not a resource type",
                            None,
                        ),
                    ));
                    continue;
                }
                InterfaceImplTypeResolution::Definition(def) => def,
            };

            if implementation_type.package != module_tree.package
                || !top_level_resources.contains(&implementation_type)
            {
                diagnostics.push((
                    implementation.impl_def,
                    invalid_interface_resource_binding_diagnostic(
                        package,
                        &binding,
                        "the binding target must be a module-level resource in this package",
                        None,
                    ),
                ));
                continue;
            }

            if let Some(earlier_binding) = first_binding_by_type.get(&implementation_type) {
                diagnostics.push((
                    implementation.impl_def,
                    invalid_interface_resource_binding_diagnostic(
                        package,
                        &binding,
                        "this resource is already bound to another interface resource",
                        Some(earlier_binding),
                    ),
                ));
                continue;
            }

            match external_checks.get(&binding.resource) {
                Some(InterfaceResourceExternalCheck::Occurrence(occurrence)) => {
                    let mut diagnostic = invalid_interface_resource_binding_diagnostic(
                        package,
                        &binding,
                        "the view resource occurs in a visible WIT data type",
                        None,
                    );
                    diagnostic
                        .push_child(Child {
                            kind: ChildKind::Note,
                            message: describe_wit_resource_occurrence(occurrence),
                            location: None,
                        })
                        .expect("a locationless WIT note is valid");
                    diagnostics.push((implementation.impl_def, diagnostic));
                    continue;
                }
                Some(InterfaceResourceExternalCheck::Incomplete(_)) => {
                    // An incomplete external scan cannot establish that the
                    // binding violates §16.7.3. Leave it out of `resources`
                    // so it cannot authorize a redirect, but keep the owning
                    // WIT/load diagnostic as the only proven failure.
                    continue;
                }
                Some(
                    InterfaceResourceExternalCheck::NotViewResource
                    | InterfaceResourceExternalCheck::NoOccurrence,
                )
                | None => {}
            }

            first_binding_by_type.insert(implementation_type, binding.binding_location.clone());
            implementation
                .resources
                .push(sai_resolve::InterfaceImplResource {
                    resource: binding.resource,
                    implementation_type,
                    binding_span: binding.binding_span,
                });
        }
    }
    diagnostics
}

fn order_interface_impl_diagnostics(
    impl_locations: &[(sai_hir::LocalDefId, Vec<sai_diagnostics::Location>)],
    collector_diagnostics: Vec<Diagnostic>,
    binding_diagnostics: Vec<(sai_hir::LocalDefId, Diagnostic)>,
) -> Result<Vec<Diagnostic>, Option<String>> {
    let indexes = impl_locations
        .iter()
        .enumerate()
        .map(|(index, (impl_def, _))| (*impl_def, index))
        .collect::<HashMap<_, _>>();
    let mut diagnostics_by_impl = (0..impl_locations.len())
        .map(|_| Vec::new())
        .collect::<Vec<Vec<Diagnostic>>>();

    for diagnostic in collector_diagnostics {
        let Some(primary) = diagnostic.primary() else {
            return Err(None);
        };
        let Some((index, _)) = impl_locations
            .iter()
            .enumerate()
            .find(|(_, (_, locations))| locations.iter().any(|location| location == primary))
        else {
            return Err(Some(primary.file.path.clone()));
        };
        diagnostics_by_impl[index].push(diagnostic);
    }

    for (impl_def, diagnostic) in binding_diagnostics {
        let Some(index) = indexes.get(&impl_def).copied() else {
            return Err(diagnostic
                .primary()
                .map(|primary| primary.file.path.clone()));
        };
        diagnostics_by_impl[index].push(diagnostic);
    }

    Ok(diagnostics_by_impl.into_iter().flatten().collect())
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum InterfaceResourceExternalCheck {
    NotViewResource,
    NoOccurrence,
    Occurrence(interface_impl_resource_wit::WitResourceOccurrence),
    Incomplete(String),
}

fn describe_wit_resource_occurrence(
    occurrence: &interface_impl_resource_wit::WitResourceOccurrence,
) -> String {
    let site = match &occurrence.site {
        WitResourceOccurrenceSite::RecordField { name, .. } => {
            format!("record field `{name}`")
        }
        WitResourceOccurrenceSite::VariantCase { name, .. } => {
            format!("variant payload for case `{name}`")
        }
        WitResourceOccurrenceSite::AliasTarget => "alias target".to_owned(),
        WitResourceOccurrenceSite::UsedAlias => "used alias".to_owned(),
    };
    let source = occurrence
        .item_span
        .as_ref()
        .map_or_else(String::new, |span| {
            format!(
                " in `{}` bytes {}..{}",
                span.path, span.range.start, span.range.end
            )
        });
    let occurrence_order = if occurrence.first_occurrence_known {
        "first view-resource occurrence".to_owned()
    } else {
        "view-resource occurrence (an earlier occurrence cannot be excluded)".to_owned()
    };
    format!(
        "{occurrence_order}: {site} of WIT item `{}.{}` in unit `{}`{source}",
        occurrence.interface_name,
        occurrence.item_name,
        occurrence.unit.canonical_name(),
    )
}

fn describe_wit_resource_occurrence_incomplete(
    incomplete: &WitResourceOccurrenceIncomplete,
) -> String {
    match incomplete {
        WitResourceOccurrenceIncomplete::UnsupportedType {
            unsupported,
            location,
        } => format!(
            "could not finish the WIT resource scan: `{unsupported:?}` at WIT item `{}.{}` in unit `{}` may hide a resource type",
            location.interface_name,
            location.item_name,
            location.unit.canonical_name(),
        ),
        WitResourceOccurrenceIncomplete::MissingPackage { unit } => format!(
            "could not finish the WIT resource scan: package model for `{}` is missing",
            unit.canonical_name(),
        ),
        WitResourceOccurrenceIncomplete::MissingInterface { unit, interface } => format!(
            "could not finish the WIT resource scan: interface {interface:?} is missing from `{}`",
            unit.canonical_name(),
        ),
        WitResourceOccurrenceIncomplete::MissingItem {
            unit,
            interface,
            item,
        } => format!(
            "could not finish the WIT resource scan: item {item:?} in interface {interface:?} is missing from `{}`",
            unit.canonical_name(),
        ),
    }
}

fn invalid_interface_resource_binding_diagnostic(
    package: &str,
    binding: &sai_resolve::InterfaceImplResourceBinding,
    reason: &str,
    earlier_binding: Option<&sai_diagnostics::Location>,
) -> Diagnostic {
    let mut diagnostic = Diagnostic::new(
        sai_diagnostics::Code::InvalidResourceBinding,
        sai_diagnostics::Severity::Error,
        format!("invalid resource binding: {reason}"),
        Some(binding.type_location.clone()),
    );
    diagnostic.primary_label = "invalid resource type".to_owned();
    diagnostic.package = Some(package.to_owned());
    if let Some(earlier_binding) = earlier_binding {
        diagnostic
            .push_related(Related::DeclaredHere {
                location: earlier_binding.clone(),
                what: "earlier binding of this resource".to_owned(),
            })
            .expect("unbound diagnostic accepts related locations");
    }
    diagnostic
}

fn interface_impl_target_diagnostics(
    owner: OwnerId,
    hir_owner: &HirOwner<'_>,
    paths: &TypeOwnerPathResolution,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
) -> Result<Vec<Diagnostic>, OwnerControlFlowResolutionError> {
    let target_path = match hir_owner.node {
        OwnerNode::Item(item) => match item.kind {
            ItemKind::Impl {
                kind: ImplKind::Interface { path },
                ..
            } => path,
            _ => return Ok(Vec::new()),
        },
        _ => return Ok(Vec::new()),
    };
    let Some(resolution) = paths.paths.get(&target_path.hir_id) else {
        // An unresolved target is reported by name resolution. Do not add a
        // second diagnostic when no resolved path result is available.
        return Ok(Vec::new());
    };
    if resolution.resolved_segments != resolution.segment_count {
        // A partially resolved path still belongs to the later member-path
        // diagnostic channel and cannot yet be classified by its final kind.
        return Ok(Vec::new());
    }
    match resolution.base {
        Res::Def(DefKind::Interface, _) => return Ok(Vec::new()),
        Res::Err | Res::TestOnly(_) => return Ok(Vec::new()),
        _ => {}
    }

    let location = sai_diagnostics::Location::from_decoded_source(
        inputs.source_ref.clone(),
        sai_diagnostics::Span::new(target_path.span.file, target_path.span.range),
        &inputs.source,
    )
    .ok_or(OwnerControlFlowResolutionError::InvalidSourceLocation(
        owner,
    ))?;
    let mut diagnostic = Diagnostic::new(
        sai_diagnostics::Code::ImplTargetNotInterface,
        sai_diagnostics::Severity::Error,
        "interface implementation target does not resolve to an interface",
        Some(location),
    );
    diagnostic.primary_label = "expected an interface".to_owned();
    diagnostic.package = inputs.source_ref.package.clone();
    let diagnostic = diagnostic
        .with_workspace_snapshot(snapshot)
        .map_err(|_| OwnerControlFlowResolutionError::InvalidSourceLocation(owner))?;
    Ok(vec![diagnostic])
}

fn resolve_type_owner_module_paths(
    owner: OwnerId,
    candidates: &[OwnerPathHead<'_, '_>],
    generic_resolutions: &HashMap<Symbol, Res>,
    primitive_prelude: &Prelude,
    rejected_test_only_paths: &HashSet<HirId>,
    module_scope: &Phase1ModuleScopes,
    members: Option<&ModuleMemberIndex<'_>>,
    requesting_package: PackageId,
    source_graph_packages: Option<&HashSet<PackageId>>,
) -> TypeOwnerPathResolution {
    let mut paths = HashMap::new();
    let mut deferred_paths = Vec::new();
    let mut module_path_errors = Vec::new();
    for candidate in candidates
        .iter()
        .filter(|candidate| candidate.kind == OwnerPathKind::Type)
    {
        let base = if let Some(resolution) = generic_resolutions.get(&candidate.name) {
            *resolution
        } else if rejected_test_only_paths.contains(&candidate.hir_id) {
            Res::Err
        } else if let Some(binding) = module_scope.scope.get(&candidate.name) {
            binding.res
        } else if let Some(PreludeBinding::Primitive(primitive)) =
            primitive_prelude.get(candidate.name)
        {
            Res::PrimTy(*primitive)
        } else {
            deferred_paths.push(DeferredPath {
                hir_id: candidate.hir_id,
                name: candidate.name,
                span: candidate.span,
            });
            continue;
        };
        let mut path = PathRes {
            base,
            resolved_segments: 1,
            segment_count: candidate.segment_count,
        };
        if let Some(members) = members {
            let suffix = &candidate.segments[1..];
            match resolve_module_prefix(base, suffix, requesting_package, members) {
                Ok(prefix) => {
                    path.base = prefix.base;
                    path.resolved_segments = u32::try_from(1 + prefix.consumed_segments)
                        .expect("path segment count was already checked");
                }
                Err(error) => match error {
                    ModulePathError::MissingTargetScope {
                        target,
                        segment_index,
                    } if !source_graph_packages
                        .is_some_and(|packages| packages.contains(&target.package)) =>
                    {
                        // Artifact and WIT packages have no source Phase 1
                        // scope. Leave their member suffix for those later
                        // package-scope resolvers.
                        let prefix = resolve_module_prefix(
                            base,
                            &suffix[..segment_index],
                            requesting_package,
                            members,
                        )
                        .expect("the prefix before a missing target scope was traversable");
                        path.base = prefix.base;
                        path.resolved_segments = u32::try_from(1 + prefix.consumed_segments)
                            .expect("path segment count was already checked");
                    }
                    _ => {
                        let failed_segment = module_path_error_segment_index(error);
                        path.base = Res::Err;
                        path.resolved_segments = u32::try_from(1 + failed_segment + 1)
                            .unwrap_or(candidate.segment_count);
                        module_path_errors.push(TypeOwnerModulePathError {
                            hir_id: candidate.hir_id,
                            error,
                        });
                    }
                },
            }
        }
        paths.insert(candidate.hir_id, path);
    }
    TypeOwnerPathResolution {
        owner,
        paths,
        deferred_paths,
        module_path_errors,
    }
}

fn resolve_prepared_type_owner_paths(
    prepared: &PreparedTypeOwnerPathQuery,
) -> TypeOwnerPathResolution {
    let path_segments = prepared
        .candidates
        .iter()
        .map(|candidate| {
            candidate
                .segments
                .iter()
                .map(|segment| PathSegment {
                    hir_id: segment.hir_id,
                    name: Name {
                        sym: segment.name,
                        span: segment.span,
                    },
                    args: None,
                })
                .collect::<Vec<_>>()
        })
        .collect::<Vec<_>>();
    let candidates = prepared
        .candidates
        .iter()
        .zip(&path_segments)
        .map(|(candidate, segments)| OwnerPathHead {
            hir_id: candidate.hir_id,
            name: candidate.name,
            span: candidate.span,
            segment_count: candidate.segment_count,
            kind: candidate.kind,
            segments,
        })
        .collect::<Vec<_>>();
    let members = if prepared.wit_view_closure_supplied {
        ModuleMemberIndex::new_with_wit_views(
            std::iter::once(&prepared.package_scopes).chain(&prepared.foreign_package_scopes),
            prepared.wit_views.iter().map(|view| view.as_ref()),
            &prepared.symbols,
        )
    } else {
        ModuleMemberIndex::new(
            std::iter::once(&prepared.package_scopes).chain(&prepared.foreign_package_scopes),
        )
    };
    resolve_type_owner_module_paths(
        prepared.owner,
        &candidates,
        &prepared.generic_resolutions,
        &prepared.primitive_prelude,
        &prepared.rejected_test_only_paths,
        &prepared.module_scope,
        Some(&members),
        prepared.requesting_package,
        Some(&prepared.source_graph_packages),
    )
}

fn module_path_error_segment_index(error: ModulePathError) -> usize {
    match error {
        ModulePathError::MissingMember { segment_index, .. }
        | ModulePathError::InaccessibleMember { segment_index, .. }
        | ModulePathError::MissingTargetScope { segment_index, .. } => segment_index,
    }
}

fn direct_enum_variant_ast_type_head(mut base: ast::Expr) -> bool {
    loop {
        match base {
            ast::Expr::Path(_) => return true,
            ast::Expr::Field(field) if field.generic_args().is_none() => {
                let Some(inner) = field.base() else {
                    return false;
                };
                base = inner;
            }
            _ => return false,
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn local_enum_variant_path_type_entry(
    interner: &sai_ty::ty::TyInterner,
    type_owners: &TypeOwnerResolutions,
    collection: &Phase1PackageScopesCollection,
    member_scopes: Option<&Phase1ActiveSourceMemberScopes>,
    wit_view_scopes: Option<&Phase1ActiveWitViewScopes>,
    field: HirId,
    enum_owner: OwnerId,
    enum_def: DefId,
    variant: DefId,
) -> Result<LocalEnumVariantPathTypeEntry, OwnerControlFlowResolutionError> {
    let invariant_error = || OwnerControlFlowResolutionError::LocalEnumVariantPathTypeInvariant {
        field,
        enum_owner,
        enum_def,
        variant,
    };
    if enum_owner.def_id.to_def_id() != enum_def {
        return Err(invariant_error());
    }
    let value_type = match type_owners.local_enum_variant_value_type_with_scopes(
        interner,
        collection,
        member_scopes,
        wit_view_scopes,
        enum_owner,
        variant,
    )? {
        Some(LocalEnumVariantValueTypeProjection::Supported {
            owner,
            variant: projected_variant,
            value_type,
        }) if owner == enum_owner && projected_variant == variant => value_type,
        Some(LocalEnumVariantValueTypeProjection::Supported { .. })
        | Some(LocalEnumVariantValueTypeProjection::UnsupportedEnum { .. })
        | Some(LocalEnumVariantValueTypeProjection::InvalidVariant { .. })
        | None => return Err(invariant_error()),
    };
    let has_expected_shape = match &value_type {
        sai_ty::adt::LocalEnumVariantValueType::Unit(value_type) => {
            matches!(
                value_type.kind(),
                sai_ty::ty::TyKind::Adt(definition, arguments)
                    if *definition == enum_def && arguments.is_empty()
            )
        }
        sai_ty::adt::LocalEnumVariantValueType::TupleConstructor {
            function_item,
            signature,
        } => {
            matches!(
                function_item.kind(),
                sai_ty::ty::TyKind::FnDef(definition, arguments)
                    if *definition == variant && arguments.is_empty()
            ) && signature.generic_params().is_empty()
                && matches!(
                    signature.output().kind(),
                    sai_ty::ty::TyKind::Adt(definition, arguments)
                        if *definition == enum_def && arguments.is_empty()
                )
        }
        sai_ty::adt::LocalEnumVariantValueType::RecordHasNoValueType => true,
    };
    if !has_expected_shape {
        return Err(invariant_error());
    }
    Ok(LocalEnumVariantPathTypeEntry {
        field,
        enum_owner,
        enum_def,
        variant,
        value_type,
    })
}

fn resolve_local_enum_variant_paths(
    owner: OwnerId,
    hir_owner: &HirOwner<'_>,
    body: &sai_hir::body::Body<'_>,
    source_map: &HirSourceMap,
    locals: &LocalResolution,
    type_paths: Option<&TypeOwnerPathResolution>,
    module_paths: &ModuleResolution,
    type_owners: &TypeOwnerResolutions,
    interner: &sai_ty::ty::TyInterner,
    generic_resolutions: &HashMap<Symbol, Res>,
    symbols: &Interner,
    module_scope: &Phase1ModuleScopes,
    members: Option<&ModuleMemberIndex<'_>>,
    source_graph_packages: &HashSet<PackageId>,
    collection: &Phase1PackageScopesCollection,
    member_scopes: Option<&Phase1ActiveSourceMemberScopes>,
    wit_view_scopes: Option<&Phase1ActiveWitViewScopes>,
    primitive_prelude: &Result<Prelude, PrimitivePreludeBuildError>,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
) -> Result<LocalEnumVariantPathResolution, OwnerControlFlowResolutionError> {
    let matches_member_scopes = match member_scopes {
        Some(scopes) => type_owners.matches_member_scopes(collection, scopes),
        None => {
            type_owners.matches_collection(collection)
                && type_owners.member_scope_closure_fingerprint.is_none()
        }
    };
    let matches_wit_view_scopes = match wit_view_scopes {
        Some(scopes) => type_owners.matches_wit_view_scopes(collection, scopes),
        None => {
            type_owners.matches_collection(collection)
                && type_owners.wit_view_closure_fingerprint.is_none()
        }
    };
    if owner != hir_owner.id
        || owner != body.owner
        || owner != source_map.owner()
        || owner != locals.owner
        || owner != module_paths.owner
        || !locals.matches_body_source(body, source_map, snapshot)
        || !type_owners.matches_collection(collection)
        || !matches_member_scopes
        || !matches_wit_view_scopes
    {
        return Err(OwnerControlFlowResolutionError::SnapshotMismatch);
    }

    let mut candidates = Vec::new();
    for candidate in direct_enum_variant_path_candidates(body) {
        let field = candidate.field;
        let base_path = candidate.base_path;
        let name = candidate.name;
        if base_path.root != PathRoot::Plain
            || base_path.segments.is_empty()
            || candidate
                .type_head_segments
                .iter()
                .any(|segment| segment.args.is_some())
            || locals
                .paths
                .get(&base_path.hir_id)
                .is_some_and(|resolution| matches!(resolution.base, Res::Local(_)))
            || symbols.resolve(name.sym).ok().is_none_or(|spelling| {
                sai_syntax::identifier_case_kind(&spelling) != sai_syntax::SyntaxKind::UIDENT
            })
        {
            continue;
        }
        let Some(pointer) = source_map.syntax_for_node(field.hir_id) else {
            continue;
        };
        let Some(syntax) = pointer.resolve(inputs.filtered_item_tree.file, &inputs.root) else {
            continue;
        };
        let Some(field_syntax) = ast::FieldExpr::cast(syntax) else {
            continue;
        };
        if field_syntax.generic_args().is_some()
            || !field_syntax
                .base()
                .is_some_and(direct_enum_variant_ast_type_head)
            || field_syntax.syntax().text_range() != field.span.range
            || field_syntax
                .name()
                .is_none_or(|syntax_name| syntax_name.syntax().text_range() != name.span.range)
        {
            continue;
        }
        if candidate.type_head_segments.is_empty() {
            continue;
        }
        candidates.push(candidate);
    }

    let mut result = LocalEnumVariantPathResolution {
        owner,
        entries: HashMap::new(),
        value_type_entries: HashMap::new(),
        type_dependent_defs: HashMap::new(),
        calls: HashMap::new(),
        diagnostics: Vec::new(),
        call_diagnostics: Vec::new(),
    };
    if candidates.is_empty() {
        return Ok(result);
    }
    let primitive_prelude = primitive_prelude
        .as_ref()
        .map_err(|error| OwnerControlFlowResolutionError::PrimitivePrelude(error.clone()))?;
    let heads = candidates
        .iter()
        .filter_map(|candidate| {
            let segment_count = u32::try_from(candidate.type_head_segments.len()).ok()?;
            let first = candidate.type_head_segments.first()?;
            Some(OwnerPathHead {
                hir_id: candidate.base_expression.hir_id,
                name: first.name.sym,
                span: first.name.span,
                segment_count,
                kind: OwnerPathKind::Type,
                segments: &candidate.type_head_segments,
            })
        })
        .collect::<Vec<_>>();
    let generic_parameters = generic_resolutions.keys().copied().collect();
    let rejected_test_only_paths =
        rejected_test_only_type_path_ids(owner, &heads, &generic_parameters, module_scope)?;
    let path_resolution = resolve_type_owner_module_paths(
        owner,
        &heads,
        generic_resolutions,
        primitive_prelude,
        &rejected_test_only_paths,
        module_scope,
        members,
        owner.def_id.package(),
        Some(source_graph_packages),
    );

    for candidate in candidates {
        let Some(prefix) = path_resolution.paths.get(&candidate.base_expression.hir_id) else {
            continue;
        };
        let Ok(segment_count) = u32::try_from(candidate.type_head_segments.len()) else {
            continue;
        };
        if prefix.segment_count != segment_count || prefix.resolved_segments != segment_count {
            continue;
        }
        let DirectEnumVariantPathCandidate {
            field,
            base_expression,
            base_path,
            type_head_segments,
            name,
            direct_call,
        } = candidate;
        let (outcome, enum_variants) = match prefix.base {
            Res::Def(DefKind::Enum, enum_def)
                if enum_def.package == collection.module_tree.package =>
            {
                let Some(type_owner) = type_owners
                    .owners()
                    .iter()
                    .find(|type_owner| type_owner.owner.def_id.to_def_id() == enum_def)
                else {
                    continue;
                };
                if type_owner.kind != TopLevelOwnerKind::Enum
                    || type_owner.owner.def_id.package() != collection.module_tree.package
                {
                    continue;
                }
                let Some(projection) = type_owner.local_enum_adt() else {
                    let entry = LocalEnumVariantPathEntry {
                        field: field.hir_id,
                        base_expression: base_expression.hir_id,
                        base_path: base_path.hir_id,
                        name: name.sym,
                        field_span: field.span,
                        name_span: name.span,
                        outcome: LocalEnumVariantPathOutcome::UnsupportedEnum {
                            enum_owner: type_owner.owner,
                            enum_def,
                            reason: LocalEnumVariantPathUnsupportedReason::Enum(
                                LocalEnumAdtUnsupportedReason::OwnerAnalysisFailed,
                            ),
                        },
                    };
                    result.entries.insert(entry.field, entry);
                    continue;
                };
                match projection {
                    LocalEnumAdtProjection::Supported {
                        owner: projected_owner,
                        definition,
                        ..
                    } if *projected_owner == type_owner.owner
                        && definition.payloads().owner() == enum_def =>
                    {
                        let variant_defs = definition.payloads().variants();
                        let variant_names = variant_defs
                            .iter()
                            .map(|variant| variant.name())
                            .collect::<Vec<_>>();
                        if !definition.payloads().type_params().is_empty() {
                            (
                                LocalEnumVariantPathOutcome::UnsupportedEnum {
                                    enum_owner: type_owner.owner,
                                    enum_def,
                                    reason: LocalEnumVariantPathUnsupportedReason::GenericEnum,
                                },
                                Some(variant_names),
                            )
                        } else if let Some(variant) = variant_defs
                            .iter()
                            // The language requires distinct variant names.
                            // For deterministic recovery on an invalid enum,
                            // retain the first source-ordered declaration.
                            .find(|variant| variant.name() == name.sym)
                        {
                            (
                                LocalEnumVariantPathOutcome::Resolved {
                                    enum_owner: type_owner.owner,
                                    enum_def,
                                    variant: variant.def_id(),
                                },
                                Some(variant_names),
                            )
                        } else {
                            (
                                LocalEnumVariantPathOutcome::UnknownVariant {
                                    enum_owner: type_owner.owner,
                                    enum_def,
                                    candidates: variant_names.clone(),
                                },
                                Some(variant_names),
                            )
                        }
                    }
                    LocalEnumAdtProjection::Supported { .. } => (
                        LocalEnumVariantPathOutcome::UnsupportedEnum {
                            enum_owner: type_owner.owner,
                            enum_def,
                            reason: LocalEnumVariantPathUnsupportedReason::Enum(
                                LocalEnumAdtUnsupportedReason::InvalidOwnerIdentity,
                            ),
                        },
                        None,
                    ),
                    LocalEnumAdtProjection::Unsupported {
                        owner: projected_owner,
                        reason,
                        ..
                    } if *projected_owner == type_owner.owner => (
                        LocalEnumVariantPathOutcome::UnsupportedEnum {
                            enum_owner: type_owner.owner,
                            enum_def,
                            reason: LocalEnumVariantPathUnsupportedReason::Enum(*reason),
                        },
                        None,
                    ),
                    LocalEnumAdtProjection::Unsupported { .. } => continue,
                }
            }
            Res::Def(kind, type_def)
                if type_def.package == collection.module_tree.package
                    && matches!(
                        kind,
                        DefKind::Struct | DefKind::Distinct | DefKind::Refined | DefKind::Resource
                    ) =>
            {
                let Some(type_owner) = type_owners
                    .owners()
                    .iter()
                    .find(|type_owner| type_owner.owner.def_id.to_def_id() == type_def)
                else {
                    continue;
                };
                (
                    LocalEnumVariantPathOutcome::NotEnum {
                        type_owner: type_owner.owner,
                        type_def,
                    },
                    None,
                )
            }
            _ => continue,
        };

        let type_dependent_def = match &outcome {
            LocalEnumVariantPathOutcome::Resolved { variant, .. } => {
                Some(LocalTypeDependentDef::Variant(*variant))
            }
            LocalEnumVariantPathOutcome::UnknownVariant { .. }
            | LocalEnumVariantPathOutcome::NotEnum { .. }
            | LocalEnumVariantPathOutcome::UnsupportedEnum { .. } => None,
        };
        let value_type_entry = match &outcome {
            LocalEnumVariantPathOutcome::Resolved {
                enum_owner,
                enum_def,
                variant,
            } => Some(local_enum_variant_path_type_entry(
                interner,
                type_owners,
                collection,
                member_scopes,
                wit_view_scopes,
                field.hir_id,
                *enum_owner,
                *enum_def,
                *variant,
            )?),
            LocalEnumVariantPathOutcome::UnknownVariant { .. }
            | LocalEnumVariantPathOutcome::NotEnum { .. }
            | LocalEnumVariantPathOutcome::UnsupportedEnum { .. } => None,
        };
        let entry = LocalEnumVariantPathEntry {
            field: field.hir_id,
            base_expression: base_expression.hir_id,
            base_path: base_path.hir_id,
            name: name.sym,
            field_span: field.span,
            name_span: name.span,
            outcome,
        };
        if matches!(
            &entry.outcome,
            LocalEnumVariantPathOutcome::UnknownVariant { .. }
                | LocalEnumVariantPathOutcome::NotEnum { .. }
        ) {
            result.diagnostics.push(local_enum_variant_path_diagnostic(
                owner,
                &entry,
                &type_head_segments,
                enum_variants.as_deref(),
                symbols,
                inputs,
                snapshot,
            )?);
        }
        if let (Some(call), Some(value_type_entry)) = (direct_call, value_type_entry.as_ref())
            && let Some((call_entry, diagnostics)) = local_enum_variant_call_projection(
                owner,
                hir_owner,
                body,
                locals,
                type_paths,
                &entry,
                call,
                value_type_entry,
                &collection.target_cfg,
                symbols,
                inputs,
                snapshot,
            )?
        {
            result.call_diagnostics.extend(diagnostics);
            result.calls.insert(call_entry.call, call_entry);
        }
        if let Some(value_type_entry) = value_type_entry {
            result
                .value_type_entries
                .insert(value_type_entry.field, value_type_entry);
        }
        if let Some(type_dependent_def) = type_dependent_def {
            result
                .type_dependent_defs
                .insert(entry.field, type_dependent_def);
        }
        result.entries.insert(entry.field, entry);
    }
    sort_phase1_diagnostics(&mut result.diagnostics);
    sort_phase1_diagnostics(&mut result.call_diagnostics);
    Ok(result)
}

fn local_enum_variant_call_projection(
    owner: OwnerId,
    hir_owner: &HirOwner<'_>,
    body: &sai_hir::body::Body<'_>,
    locals: &LocalResolution,
    type_paths: Option<&TypeOwnerPathResolution>,
    path: &LocalEnumVariantPathEntry,
    call: &HirExpr<'_>,
    value_type: &LocalEnumVariantPathTypeEntry,
    target_cfg: &TargetCfg,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
) -> Result<Option<(LocalEnumVariantCallEntry, Vec<Diagnostic>)>, OwnerControlFlowResolutionError> {
    let ExprKind::Call {
        callee,
        args,
        base: None,
    } = call.kind
    else {
        return Ok(None);
    };
    if callee.hir_id != path.field || value_type.field != path.field {
        return Err(OwnerControlFlowResolutionError::SnapshotMismatch);
    }
    let LocalEnumVariantPathOutcome::Resolved {
        enum_owner,
        enum_def,
        variant,
    } = path.outcome()
    else {
        return Ok(None);
    };
    if value_type.enum_owner != *enum_owner
        || value_type.enum_def != *enum_def
        || value_type.variant != *variant
    {
        return Err(OwnerControlFlowResolutionError::SnapshotMismatch);
    }

    let mut diagnostics = Vec::new();
    for argument in args {
        if argument.name.is_some() {
            diagnostics.push(local_enum_variant_named_argument_diagnostic(
                owner, argument, inputs, snapshot,
            )?);
        }
    }

    let (outcome, diagnostic) = match &value_type.value_type {
        sai_ty::adt::LocalEnumVariantValueType::Unit(_) => (
            LocalEnumVariantCallOutcome::UnitVariantCalled { found: args.len() },
            Some(local_enum_variant_call_diagnostic(
                owner,
                call,
                path.name,
                "unit variant calls do not accept an argument list",
                "unit variant cannot be called",
                symbols,
                inputs,
                snapshot,
            )?),
        ),
        sai_ty::adt::LocalEnumVariantValueType::TupleConstructor {
            function_item,
            signature,
        } => {
            if !matches!(
                function_item.kind(),
                sai_ty::ty::TyKind::FnDef(def, generic_args)
                    if *def == *variant && generic_args.is_empty()
            ) || signature.generic_params().len() != 0
                || !matches!(
                    signature.output().kind(),
                    sai_ty::ty::TyKind::Adt(def, generic_args)
                        if *def == *enum_def && generic_args.is_empty()
                )
            {
                return Err(OwnerControlFlowResolutionError::SnapshotMismatch);
            }
            for (argument, expected_type) in args.iter().zip(signature.inputs()) {
                diagnostics.extend(check_local_enum_variant_literal_argument(
                    owner,
                    expected_type,
                    &argument.expr,
                    hir_owner,
                    body,
                    locals,
                    type_paths,
                    symbols,
                    inputs,
                    snapshot,
                    target_cfg,
                )?);
            }
            let expected = signature.inputs().len();
            let found = args.len();
            if expected == found {
                (
                    LocalEnumVariantCallOutcome::TupleVariantArityMatches { expected },
                    None,
                )
            } else {
                (
                    LocalEnumVariantCallOutcome::WrongArgumentCount { expected, found },
                    Some(local_enum_variant_call_diagnostic(
                        owner,
                        call,
                        path.name,
                        &format!("tuple variant expects {expected} arguments but found {found}"),
                        "wrong number of variant arguments",
                        symbols,
                        inputs,
                        snapshot,
                    )?),
                )
            }
        }
        sai_ty::adt::LocalEnumVariantValueType::RecordHasNoValueType => return Ok(None),
    };
    if let Some(diagnostic) = diagnostic {
        diagnostics.push(diagnostic);
    }
    let entry = LocalEnumVariantCallEntry {
        call: call.hir_id,
        callee_field: path.field,
        enum_owner: *enum_owner,
        enum_def: *enum_def,
        variant: *variant,
        arguments: args.iter().map(|argument| argument.expr.hir_id).collect(),
        outcome,
    };
    Ok(Some((entry, diagnostics)))
}

fn local_enum_variant_named_argument_diagnostic(
    owner: OwnerId,
    argument: &HirArg<'_>,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
) -> Result<Diagnostic, OwnerControlFlowResolutionError> {
    let name = argument
        .name
        .ok_or(OwnerControlFlowResolutionError::SnapshotMismatch)?;
    let location = sai_diagnostics::Location::from_decoded_source(
        inputs.source_ref.clone(),
        sai_diagnostics::Span::new(name.span.file, name.span.range),
        &inputs.source,
    )
    .ok_or(OwnerControlFlowResolutionError::InvalidSourceLocation(
        owner,
    ))?;
    let mut diagnostic = Diagnostic::new(
        sai_diagnostics::Code::NamedArgumentOnFunction,
        sai_diagnostics::Severity::Error,
        "named arguments are only allowed when constructing a record",
        Some(location),
    );
    diagnostic.primary_label = "named argument is not allowed in a function call".to_owned();
    diagnostic.package = inputs.source_ref.package.clone();
    diagnostic
        .with_workspace_snapshot(snapshot)
        .map_err(|_| OwnerControlFlowResolutionError::InvalidSourceLocation(owner))
}

fn local_enum_variant_call_diagnostic(
    owner: OwnerId,
    call: &HirExpr<'_>,
    variant: Symbol,
    message: &str,
    primary_label: &str,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
) -> Result<Diagnostic, OwnerControlFlowResolutionError> {
    let variant_name = symbols
        .resolve(variant)
        .map_err(|_| OwnerControlFlowResolutionError::InvalidSourceLocation(owner))?;
    let location = sai_diagnostics::Location::from_decoded_source(
        inputs.source_ref.clone(),
        sai_diagnostics::Span::new(call.span.file, call.span.range),
        &inputs.source,
    )
    .ok_or(OwnerControlFlowResolutionError::InvalidSourceLocation(
        owner,
    ))?;
    let mut diagnostic = Diagnostic::new(
        sai_diagnostics::Code::WrongArgumentCount,
        sai_diagnostics::Severity::Error,
        format!("{variant_name}: {message}"),
        Some(location),
    );
    diagnostic.primary_label = primary_label.to_owned();
    diagnostic.package = inputs.source_ref.package.clone();
    diagnostic
        .with_workspace_snapshot(snapshot)
        .map_err(|_| OwnerControlFlowResolutionError::InvalidSourceLocation(owner))
}

fn local_enum_variant_path_diagnostic(
    owner: OwnerId,
    entry: &LocalEnumVariantPathEntry,
    type_head_segments: &[PathSegment<'_>],
    enum_variants: Option<&[Symbol]>,
    symbols: &Interner,
    inputs: &CurrentOwnerInputs,
    snapshot: &WorkspaceSnapshot,
) -> Result<Diagnostic, OwnerControlFlowResolutionError> {
    let written_name = inputs
        .source
        .text()
        .get(entry.name_span.range.start().to_usize()..entry.name_span.range.end().to_usize())
        .ok_or(OwnerControlFlowResolutionError::InvalidSourceLocation(
            owner,
        ))?;
    let base_name = type_head_segments
        .iter()
        .map(|segment| {
            symbols
                .resolve(segment.name.sym)
                .map(|name| name.to_string())
                .map_err(|_| OwnerControlFlowResolutionError::InvalidSourceLocation(owner))
        })
        .collect::<Result<Vec<_>, _>>()?
        .join(".");
    let (message, primary_label) = match &entry.outcome {
        LocalEnumVariantPathOutcome::UnknownVariant { .. } => (
            format!("enum `{base_name}` has no variant `{written_name}`"),
            "unknown enum variant",
        ),
        LocalEnumVariantPathOutcome::NotEnum { .. } => (
            format!("unknown variant `{written_name}` for type `{base_name}`"),
            "unknown variant",
        ),
        _ => {
            return Err(OwnerControlFlowResolutionError::InvalidSourceLocation(
                owner,
            ));
        }
    };
    let location = sai_diagnostics::Location::from_decoded_source(
        inputs.source_ref.clone(),
        sai_diagnostics::Span::new(entry.name_span.file, entry.name_span.range),
        &inputs.source,
    )
    .ok_or(OwnerControlFlowResolutionError::InvalidSourceLocation(
        owner,
    ))?;
    let node = name_node_id_for_span(&inputs.root, entry.name_span).ok_or(
        OwnerControlFlowResolutionError::InvalidSourceLocation(owner),
    )?;
    let mut diagnostic = Diagnostic::new(
        sai_diagnostics::Code::UnknownVariant,
        sai_diagnostics::Severity::Error,
        message,
        Some(location),
    );
    diagnostic.primary_label = primary_label.to_owned();
    diagnostic.node = Some(node);
    diagnostic.package = inputs.source_ref.package.clone();
    diagnostic.data.insert(
        "type_name".to_owned(),
        sai_diagnostics::Value::String(base_name.clone()),
    );
    diagnostic.data.insert(
        "variant".to_owned(),
        sai_diagnostics::Value::String(written_name.to_owned()),
    );
    let mut suggestions = enum_variants
        .unwrap_or_default()
        .iter()
        .enumerate()
        .filter_map(|(declaration_order, symbol)| {
            let candidate = symbols.resolve(*symbol).ok()?.to_string();
            let distance = edit_distance_at_most_two(written_name, &candidate)?;
            Some((distance, declaration_order, candidate))
        })
        .collect::<Vec<_>>();
    suggestions.sort_by_key(|(distance, declaration_order, _)| (*distance, *declaration_order));
    suggestions.truncate(5);
    let suggestion_names = suggestions
        .into_iter()
        .map(|(_, _, name)| name)
        .collect::<Vec<_>>();
    diagnostic.data.insert(
        "candidates".to_owned(),
        sai_diagnostics::Value::Array(
            suggestion_names
                .iter()
                .cloned()
                .map(sai_diagnostics::Value::String)
                .collect(),
        ),
    );
    if !suggestion_names.is_empty() {
        diagnostic
            .push_child(Child {
                kind: ChildKind::Help,
                message: format!(
                    "did you mean one of these variants?\n{}",
                    suggestion_names.join("\n")
                ),
                location: None,
            })
            .map_err(|_| OwnerControlFlowResolutionError::InvalidSourceLocation(owner))?;
    } else if matches!(&entry.outcome, LocalEnumVariantPathOutcome::NotEnum { .. }) {
        diagnostic
            .push_child(Child {
                kind: ChildKind::Note,
                message: format!("`{base_name}` is not an enum"),
                location: None,
            })
            .map_err(|_| OwnerControlFlowResolutionError::InvalidSourceLocation(owner))?;
    }
    diagnostic
        .with_workspace_snapshot(snapshot)
        .map_err(|_| OwnerControlFlowResolutionError::InvalidSourceLocation(owner))
}

fn wit_unit_package_identity(stable_key: &str) -> Option<String> {
    if let Some(package_key) = stable_key
        .strip_prefix("wit:dir:")
        .or_else(|| stable_key.strip_prefix("wit:gen:"))
    {
        return Some(
            package_key
                .split_once('#')
                .map_or(package_key, |(identity, _)| identity)
                .to_owned(),
        );
    }
    stable_key.strip_prefix("wit:wasi:").map(|canonical| {
        format!(
            "wasi:{}",
            canonical
                .split_once('@')
                .map_or(canonical, |(name, _)| name)
        )
    })
}

fn item_tree_generic_parameters(
    item_tree: &ItemTree,
    item_id: ast::ErasedAstId,
) -> HashSet<Symbol> {
    item_tree
        .items
        .iter()
        .find(|entry| entry.ast_id == item_id)
        .map(item_tree_entry_generic_parameters)
        .unwrap_or_default()
}

fn item_tree_entry_generic_parameters(entry: &ItemTreeEntry) -> HashSet<Symbol> {
    entry
        .children
        .iter()
        .filter(|entry| {
            matches!(
                entry.kind,
                ItemTreeKind::TypeParam | ItemTreeKind::ConstParam
            )
        })
        .map(|entry| entry.name)
        .filter(|name| !name.is_error())
        .collect()
}

