    #[test]
    fn module_function_inventory_collects_multiple_modules_and_stable_metadata() {
        let (database, module_tree, snapshot, collection) = collect_package_inventory_for_target(
            b"fn root_fn() {}\n",
            b"fn child_fn() {}\n",
            "wasm32-core",
        );
        let inventory = inventory_symbols(&collection);
        assert_eq!(
            inventory.coverage(),
            &sai_semantic::InventoryCoverage::Complete
        );
        assert_eq!(inventory.file().as_str(), "acme.phase1.1.jsonl");
        assert_eq!(inventory.package_node_key(), "package:acme:phase1@1.0.0");
        assert_eq!(
            inventory
                .symbols()
                .iter()
                .map(|symbol| symbol.path())
                .collect::<std::collections::BTreeSet<_>>(),
            ["acme:phase1.root_fn", "acme:phase1/child.child_fn",]
                .into_iter()
                .collect()
        );

        for (file_id, name, expected_path) in [
            (
                module_tree.modules[0].file,
                "root_fn",
                "acme:phase1.root_fn",
            ),
            (
                module_tree.modules[1].file,
                "child_fn",
                "acme:phase1/child.child_fn",
            ),
        ] {
            let symbol = inventory
                .symbols()
                .iter()
                .find(|symbol| symbol.path() == expected_path)
                .expect("the function has a canonical inventory path");
            let owner_path = collection
                .scopes()
                .function_owners
                .iter()
                .filter_map(|owner| {
                    database
                        .resolve_def_path(owner.owner.def_id.to_def_id())
                        .ok()
                        .flatten()
                })
                .find(|path| {
                    let Some(component) = path.data().last() else {
                        return false;
                    };
                    let DefPathData::ValueNs(symbol) = component.data else {
                        return false;
                    };
                    database
                        .symbols
                        .resolve(symbol)
                        .is_ok_and(|resolved| resolved.as_ref() == name)
                })
                .expect("the matching HIR owner has a canonical definition path");
            let expected_hash =
                sai_hir::DefPathHash::compute(&owner_path, &database.packages, &database.symbols)
                    .expect("the matching HIR path hashes");
            assert_eq!(
                symbol.def_path_hash(),
                sai_stable_hash::Fingerprint::new(expected_hash.raw())
            );

            let parsed = sai_syntax::parse(&snapshot, file_id).expect("module parses");
            let declaration = parsed
                .root
                .descendants()
                .find_map(sai_syntax::ast::FnDecl::cast)
                .filter(|function| {
                    function
                        .name()
                        .and_then(|name| name.token())
                        .is_some_and(|token| token.text() == name)
                })
                .expect("the module contains the expected function declaration");
            let name_token = declaration
                .name()
                .and_then(|name| name.token())
                .expect("the function has its declared name token");
            let expected_fingerprint = sai_semantic::declaration_fingerprint(
                sai_semantic::SymbolKind::Fn,
                &declaration.syntax(),
                Some(&name_token),
            )
            .expect("the declaration fingerprint is defined");
            assert_eq!(symbol.fingerprint(), expected_fingerprint);
        }
    }

    #[test]
    fn wit_function_inventory_uses_exact_version_and_public_interface_path() {
        let selected_version = "1.0.0-rc.7";
        let wit_source = b"package acme:phase1@1.0.0-rc.7;\n\
interface user-api {\n\
    get-user: func(name: string) -> string;\n\
}\n";
        let (mut database, module_tree, snapshot, package) =
            phase1_fixture(b"fn root_fn() {}\n", b"");
        database
            .set_package_graph(Some(phase1_root_graph_at_version(selected_version)))
            .expect("exact version graph is tracked");
        install_authored_wit_package(
            &mut database,
            package,
            "acme:phase1#1",
            b"package acme:phase1 @ 1.0.0-rc.7\nsource \"src\"\nwit \"wit\"\n",
            PackageRole::Root,
            &[("root.wit", wit_source)],
        );
        let target = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let collection = database
            .collect_phase1_package_scopes_collection(
                &module_tree,
                &snapshot,
                &target,
                Phase1BuildContext::default(),
            )
            .expect("Phase 1 and WIT inventory collection succeed");
        let inventory = inventory_symbols(&collection);
        assert_eq!(
            inventory.package_node_key(),
            "package:acme:phase1@1.0.0-rc.7"
        );
        assert!(matches!(
            inventory.coverage(),
            sai_semantic::InventoryCoverage::Incomplete { reason }
                if reason.contains("interface")
        ));
        let function = inventory
            .symbols()
            .iter()
            .find(|symbol| symbol.path() == "acme:phase1/user-api.get_user")
            .expect("the direct WIT function uses the public canonical path");
        assert_eq!(function.kind(), sai_semantic::SymbolKind::AssocFn);

        let name_start = std::str::from_utf8(wit_source)
            .expect("fixture WIT is UTF-8")
            .find("get-user")
            .expect("WIT function name occurs");
        let tokens = sai_wit::authored_interface_function_tokens(
            std::str::from_utf8(wit_source).expect("fixture WIT is UTF-8"),
            "user-api",
            "get-user",
            &(name_start..name_start + "get-user".len()),
        )
        .expect("the source scanner finds the exact direct declaration");
        assert_eq!(
            function.fingerprint(),
            sai_semantic::declaration_fingerprint_from_token_pairs(
                sai_semantic::SymbolKind::AssocFn,
                &tokens.token_pairs
            )
        );

        let selected = MvsPackageVersion::new(
            "acme:phase1",
            Version::parse(selected_version).expect("full selected version parses"),
        )
        .expect("selected package version is valid");
        let unit = WitUnit::dir(package, &database.packages, &selected)
            .expect("exact selected WIT unit is valid");
        let view = database
            .wit_view(&unit)
            .expect("exact selected root view is available");
        let member = view
            .interfaces
            .values()
            .next()
            .expect("the root WIT interface is present")
            .members
            .get("get_user")
            .expect("the normalized function member is present");
        let path = view
            .def_path(member.def)
            .expect("WIT view path resolves")
            .expect("WIT view path exists");
        let hash = sai_hir::DefPathHash::compute(&path, &database.packages, &database.symbols)
            .expect("WIT view path hashes");
        assert_eq!(
            function.def_path_hash(),
            sai_stable_hash::Fingerprint::new(hash.raw())
        );
    }

