    #[test]
    fn module_function_inventory_collects_generic_parameters_with_lowered_metadata() {
        let (database, module_tree, snapshot, collection) = collect_package_inventory_for_target(
            b"fn generic<T: Bound, const N: I32, U>() {}\n",
            b"",
            "wasm32-core",
        );
        let inventory = inventory_symbols(&collection);
        assert_eq!(
            inventory.coverage(),
            &sai_semantic::InventoryCoverage::Complete
        );
        assert_eq!(
            inventory
                .symbols()
                .iter()
                .map(|symbol| (symbol.path(), symbol.kind()))
                .collect::<Vec<_>>(),
            [
                ("acme:phase1.generic", sai_semantic::SymbolKind::Fn),
                (
                    "acme:phase1.generic.generic[T]",
                    sai_semantic::SymbolKind::GenericParam
                ),
                (
                    "acme:phase1.generic.generic[N]",
                    sai_semantic::SymbolKind::GenericParam
                ),
                (
                    "acme:phase1.generic.generic[U]",
                    sai_semantic::SymbolKind::GenericParam
                ),
            ]
        );

        let function_owner = collection
            .scopes()
            .function_owners
            .iter()
            .find(|owner| {
                owner.file == module_tree.modules[0].file
                    && database
                        .resolve_def_path(owner.owner.def_id.to_def_id())
                        .ok()
                        .flatten()
                        .is_some_and(|path| {
                            matches!(
                                path.data().last().map(|component| &component.data),
                                Some(DefPathData::ValueNs(name))
                                    if database.symbols.resolve(*name).is_ok_and(|name| name.as_ref() == "generic")
                            )
                        })
            })
            .expect("the function owner is present");
        let function_owner_path = database
            .resolve_def_path(function_owner.owner.def_id.to_def_id())
            .expect("function owner DefId is valid")
            .expect("function owner DefPath exists");
        let def_paths = database
            .def_paths
            .get(&module_tree.package)
            .expect("the selected package has a DefPath interner");
        let type_t = database
            .symbols
            .intern("T")
            .expect("type parameter interns");
        let const_n = database
            .symbols
            .intern("N")
            .expect("const parameter interns");
        let type_u = database
            .symbols
            .intern("U")
            .expect("type parameter interns");
        let parameter_def_ids = def_paths
            .intern_generic_params(
                function_owner.owner.def_id,
                &[(type_t, false, 0), (const_n, true, 0), (type_u, false, 0)],
            )
            .expect("HIR lowering interns function generic parameters in source order");
        let parsed = sai_syntax::parse(&snapshot, module_tree.modules[0].file)
            .expect("generic function module parses");
        let function = parsed
            .root
            .descendants()
            .find_map(ast::FnDecl::cast)
            .expect("the generic function AST exists");
        let ast_parameters = function
            .generic_params()
            .expect("generic parameter list exists")
            .params()
            .collect::<Vec<_>>();
        for (((parameter, expected_name), def_id), expected_component) in ast_parameters
            .iter()
            .zip(["T", "N", "U"])
            .zip(parameter_def_ids)
            .zip([
                DefPathData::TypeParam(type_t),
                DefPathData::ConstParam(const_n),
                DefPathData::TypeParam(type_u),
            ])
        {
            let (name_token, syntax) = match parameter {
                ast::GenericParam::Type(parameter) => (
                    parameter.name().and_then(|name| name.token()),
                    parameter.syntax().clone(),
                ),
                ast::GenericParam::Const(parameter) => (
                    parameter.name().and_then(|name| name.token()),
                    parameter.syntax().clone(),
                ),
            };
            let name_token = name_token.expect("generic parameter name token exists");
            assert_eq!(name_token.text(), expected_name);

            let from_interner = def_paths
                .resolve(def_id)
                .expect("lowered generic parameter DefId resolves")
                .expect("lowered generic parameter path exists");
            let from_database = database
                .resolve_def_path(def_id.to_def_id())
                .expect("lowered generic parameter DefId is valid")
                .expect("lowered generic parameter DefId resolves through HIR");
            assert_eq!(from_interner, from_database);
            assert_eq!(from_database.package(), module_tree.package);
            assert_eq!(
                &from_database.data()[..function_owner_path.data().len()],
                function_owner_path.data()
            );
            assert_eq!(
                from_database.data().len(),
                function_owner_path.data().len() + 1
            );
            assert!(matches!(
                from_database.data().last(),
                Some(component)
                    if component.data == expected_component && component.disambiguator == 0
            ));

            let canonical_path = format!("acme:phase1.generic.generic[{expected_name}]");
            let symbol = inventory
                .symbols()
                .iter()
                .find(|symbol| symbol.path() == canonical_path)
                .expect("the generic parameter has a canonical path");
            let expected_hash = sai_hir::DefPathHash::compute(
                &from_database,
                &database.packages,
                &database.symbols,
            )
            .expect("the HIR generic parameter path hashes");
            assert_eq!(
                symbol.def_path_hash(),
                sai_stable_hash::Fingerprint::new(expected_hash.raw())
            );
            assert_eq!(symbol.kind(), sai_semantic::SymbolKind::GenericParam);
            assert_eq!(
                symbol.fingerprint(),
                sai_semantic::declaration_fingerprint(
                    sai_semantic::SymbolKind::GenericParam,
                    &syntax,
                    Some(&name_token),
                )
                .expect("generic parameter fingerprint is defined")
            );
        }
    }

    #[test]
    fn module_function_generic_parameter_fingerprints_ignore_name_and_track_bounds_and_const_type()
    {
        let fingerprint_for = |source: &[u8]| {
            let (_, _, _, collection) =
                collect_package_inventory_for_target(source, b"", "wasm32-core");
            let inventory = inventory_symbols(&collection);
            assert_eq!(
                inventory.coverage(),
                &sai_semantic::InventoryCoverage::Complete
            );
            inventory
                .symbols()
                .iter()
                .find(|symbol| symbol.kind() == sai_semantic::SymbolKind::GenericParam)
                .expect("the generic parameter is inventoried")
                .fingerprint()
        };

        let type_original = fingerprint_for(b"fn f<T: Bound>() {}\n");
        let type_renamed = fingerprint_for(b"fn f<U: Bound>() {}\n");
        let changed_bound = fingerprint_for(b"fn f<T: Other>() {}\n");
        let const_original = fingerprint_for(b"fn f<const N: I32>() {}\n");
        let changed_const_type = fingerprint_for(b"fn f<const N: U32>() {}\n");

        assert_eq!(
            type_original, type_renamed,
            "renaming a generic parameter preserves its fingerprint"
        );
        assert_ne!(
            type_original, changed_bound,
            "a type parameter bound contributes to its fingerprint"
        );
        assert_ne!(
            const_original, changed_const_type,
            "a const parameter type contributes to its fingerprint"
        );
    }

    #[test]
    fn module_function_generic_parameter_disambiguators_preserve_duplicate_paths_as_incomplete() {
        let (database, module_tree, _, collection) =
            collect_package_inventory_for_target(b"fn duplicate<T, T>() {}\n", b"", "wasm32-core");
        let inventory = inventory_symbols(&collection);
        assert!(matches!(
            inventory.coverage(),
            sai_semantic::InventoryCoverage::Incomplete { reason }
                if reason.contains("duplicate canonical symbol path")
        ));
        let parameters = inventory
            .symbols()
            .iter()
            .filter(|symbol| symbol.kind() == sai_semantic::SymbolKind::GenericParam)
            .collect::<Vec<_>>();
        assert_eq!(parameters.len(), 2);
        assert_eq!(parameters[0].path(), "acme:phase1.duplicate.generic[T]");
        assert_eq!(parameters[1].path(), parameters[0].path());
        assert_ne!(
            parameters[0].def_path_hash(),
            parameters[1].def_path_hash(),
            "the duplicate type parameter name receives distinct HIR disambiguators"
        );

        let owner = collection
            .scopes()
            .function_owners
            .iter()
            .find(|owner| owner.file == module_tree.modules[0].file)
            .expect("the duplicate-parameter function owner exists");
        let def_paths = database
            .def_paths
            .get(&module_tree.package)
            .expect("the selected package has a DefPath interner");
        let type_t = database
            .symbols
            .intern("T")
            .expect("type parameter interns");
        let ids = def_paths
            .intern_generic_params(
                owner.owner.def_id,
                &[(type_t, false, 0), (type_t, false, 1)],
            )
            .expect("HIR lowering disambiguates equal type parameters in source order");
        for (parameter, (id, expected_disambiguator)) in
            parameters.iter().zip(ids.into_iter().zip([0, 1]))
        {
            let path = database
                .resolve_def_path(id.to_def_id())
                .expect("generic parameter DefId is valid")
                .expect("generic parameter DefPath exists");
            assert!(matches!(
                path.data().last(),
                Some(component)
                    if component.data == DefPathData::TypeParam(type_t)
                        && component.disambiguator == expected_disambiguator
            ));
            let expected_hash =
                sai_hir::DefPathHash::compute(&path, &database.packages, &database.symbols)
                    .expect("generic parameter DefPath hashes");
            assert_eq!(
                parameter.def_path_hash(),
                sai_stable_hash::Fingerprint::new(expected_hash.raw())
            );
        }
    }

    #[test]
    fn module_function_inventory_collects_traits_and_nested_generic_parameters() {
        let (database, module_tree, snapshot, collection) = collect_package_inventory_for_target(
            b"trait Store<T, const N: I32> {\ntype Item\nfn put<U, const M: I32>(self: borrow Self, item: U)\n}\n",
            b"",
            "wasm32-core",
        );
        let inventory = inventory_symbols(&collection);
        assert_eq!(
            inventory.coverage(),
            &sai_semantic::InventoryCoverage::Complete
        );
        assert_eq!(
            inventory
                .symbols()
                .iter()
                .map(|symbol| (symbol.path(), symbol.kind()))
                .collect::<Vec<_>>(),
            [
                ("acme:phase1.Store", sai_semantic::SymbolKind::Trait),
                (
                    "acme:phase1.Store.generic[T]",
                    sai_semantic::SymbolKind::GenericParam
                ),
                (
                    "acme:phase1.Store.generic[N]",
                    sai_semantic::SymbolKind::GenericParam
                ),
                (
                    "acme:phase1.Store.Item",
                    sai_semantic::SymbolKind::AssocType
                ),
                ("acme:phase1.Store.put", sai_semantic::SymbolKind::AssocFn),
                (
                    "acme:phase1.Store.put.generic[U]",
                    sai_semantic::SymbolKind::GenericParam
                ),
                (
                    "acme:phase1.Store.put.generic[M]",
                    sai_semantic::SymbolKind::GenericParam
                ),
            ]
        );

        let parsed =
            sai_syntax::parse(&snapshot, module_tree.modules[0].file).expect("trait module parses");
        let declaration = parsed
            .root
            .descendants()
            .find_map(ast::TraitDecl::cast)
            .expect("trait declaration is present");
        let trait_symbol = inventory
            .symbols()
            .iter()
            .find(|symbol| symbol.path() == "acme:phase1.Store")
            .expect("trait symbol exists");
        let trait_name = declaration
            .name()
            .and_then(|name| name.token())
            .expect("trait name token exists");
        assert_eq!(
            trait_symbol.fingerprint(),
            sai_semantic::declaration_fingerprint(
                sai_semantic::SymbolKind::Trait,
                &declaration.syntax(),
                Some(&trait_name),
            )
            .expect("trait declaration fingerprint is defined")
        );

        let item_list = declaration.items().expect("trait item list exists");
        let method = item_list
            .functions()
            .find(|method| {
                method
                    .name()
                    .and_then(|name| name.token())
                    .is_some_and(|token| token.text() == "put")
            })
            .expect("trait method exists");
        let method_name = method
            .name()
            .and_then(|name| name.token())
            .expect("method name token exists");
        let method_symbol = inventory
            .symbols()
            .iter()
            .find(|symbol| symbol.path() == "acme:phase1.Store.put")
            .expect("trait method symbol exists");
        assert_eq!(
            method_symbol.fingerprint(),
            sai_semantic::declaration_fingerprint(
                sai_semantic::SymbolKind::AssocFn,
                &method.syntax(),
                Some(&method_name),
            )
            .expect("method declaration fingerprint is defined")
        );

        let method_owner = collection
            .scopes()
            .top_level_owners
            .iter()
            .find(|owner| owner.kind == TopLevelOwnerKind::Trait)
            .expect("trait owner exists");
        let trait_owner_path = database
            .resolve_def_path(method_owner.owner.def_id.to_def_id())
            .expect("trait owner DefId is valid")
            .expect("trait owner DefPath exists");
        let def_paths = database
            .def_paths
            .get(&module_tree.package)
            .expect("trait package has a DefPath interner");
        let trait_t = database
            .symbols
            .intern("T")
            .expect("trait type parameter name interns");
        let trait_n = database
            .symbols
            .intern("N")
            .expect("trait const parameter name interns");
        let trait_parameter_def_ids = def_paths
            .intern_generic_params(
                method_owner.owner.def_id,
                &[(trait_t, false, 0), (trait_n, true, 0)],
            )
            .expect("HIR lowering interns trait generic parameters");
        for (def_id, expected_path) in trait_parameter_def_ids.into_iter().zip([
            "acme:phase1.Store.generic[T]",
            "acme:phase1.Store.generic[N]",
        ]) {
            let parameter_path = database
                .resolve_def_path(def_id.to_def_id())
                .expect("trait generic parameter DefId is valid")
                .expect("trait generic parameter DefPath exists");
            assert_eq!(
                &parameter_path.data()[..trait_owner_path.data().len()],
                trait_owner_path.data()
            );
            let expected_hash = sai_hir::DefPathHash::compute(
                &parameter_path,
                &database.packages,
                &database.symbols,
            )
            .expect("trait generic parameter DefPath hashes");
            assert_eq!(
                inventory
                    .symbols()
                    .iter()
                    .find(|symbol| symbol.path() == expected_path)
                    .expect("trait generic parameter symbol exists")
                    .def_path_hash(),
                sai_stable_hash::Fingerprint::new(expected_hash.raw())
            );
        }
        let put = database.symbols.intern("put").expect("method name interns");
        let method_def_id = def_paths
            .intern_assoc_items(method_owner.owner.def_id, &[(DefPathData::AssocFn(put), 0)])
            .expect("HIR lowering interns trait methods")
            .into_iter()
            .next()
            .expect("method DefId exists");
        let method_path = database
            .resolve_def_path(method_def_id.to_def_id())
            .expect("method DefId is valid")
            .expect("method DefPath exists");
        assert_eq!(
            &method_path.data()[..trait_owner_path.data().len()],
            trait_owner_path.data()
        );
        assert!(matches!(
            method_path.data().last(),
            Some(component)
                if component.data == DefPathData::AssocFn(put)
                    && component.disambiguator == 0
        ));
        let expected_parameter_path = def_paths
            .intern_generic_params(
                method_def_id,
                &[
                    (
                        database
                            .symbols
                            .intern("U")
                            .expect("type parameter name interns"),
                        false,
                        0,
                    ),
                    (
                        database
                            .symbols
                            .intern("M")
                            .expect("const parameter name interns"),
                        true,
                        0,
                    ),
                ],
            )
            .expect("HIR lowering interns trait-method generic parameters");
        for (def_id, expected_path) in expected_parameter_path.into_iter().zip([
            "acme:phase1.Store.put.generic[U]",
            "acme:phase1.Store.put.generic[M]",
        ]) {
            let parameter_path = database
                .resolve_def_path(def_id.to_def_id())
                .expect("generic parameter DefId is valid")
                .expect("generic parameter DefPath exists");
            let expected_parameter_hash = sai_hir::DefPathHash::compute(
                &parameter_path,
                &database.packages,
                &database.symbols,
            )
            .expect("trait-method generic parameter DefPath hashes");
            assert_eq!(
                inventory
                    .symbols()
                    .iter()
                    .find(|symbol| symbol.path() == expected_path)
                    .expect("trait-method generic parameter symbol exists")
                    .def_path_hash(),
                sai_stable_hash::Fingerprint::new(expected_parameter_hash.raw())
            );
        }
    }

    #[test]
    fn module_function_inventory_rejects_duplicate_same_name_trait_member_kinds() {
        let (database, module_tree, snapshot, collection) = collect_package_inventory_for_target(
            b"trait Duplicate {\ntype Item\ntype Item\nfn item(self: borrow Self)\nfn item(self: borrow Self)\n}\n",
            b"",
            "wasm32-core",
        );
        let parsed = sai_syntax::parse(&snapshot, module_tree.modules[0].file)
            .expect("duplicate trait fixture parses");
        assert!(
            parsed.errors.is_empty(),
            "parse errors: {:?}",
            parsed.errors
        );
        let inventory = inventory_symbols(&collection);
        assert!(
            matches!(
                inventory.coverage(),
                sai_semantic::InventoryCoverage::Incomplete { reason }
                    if reason.contains("duplicate associated item name")
            ),
            "duplicate trait member coverage: {:?}",
            inventory.coverage()
        );

        let duplicate_types = inventory
            .symbols()
            .iter()
            .filter(|symbol| {
                symbol.path() == "acme:phase1.Duplicate.Item"
                    && symbol.kind() == sai_semantic::SymbolKind::AssocType
            })
            .collect::<Vec<_>>();
        let duplicate_functions = inventory
            .symbols()
            .iter()
            .filter(|symbol| {
                symbol.path() == "acme:phase1.Duplicate.item"
                    && symbol.kind() == sai_semantic::SymbolKind::AssocFn
            })
            .collect::<Vec<_>>();
        assert_eq!(duplicate_types.len(), 2);
        assert_eq!(duplicate_functions.len(), 2);
        assert_ne!(
            duplicate_types[0].def_path_hash(),
            duplicate_types[1].def_path_hash()
        );
        assert_ne!(
            duplicate_functions[0].def_path_hash(),
            duplicate_functions[1].def_path_hash()
        );

        let trait_owner = collection
            .scopes()
            .top_level_owners
            .iter()
            .find(|owner| owner.kind == TopLevelOwnerKind::Trait)
            .expect("trait owner exists");
        let type_name = database
            .symbols
            .intern("Item")
            .expect("associated type name interns");
        let function_name = database
            .symbols
            .intern("item")
            .expect("associated function name interns");
        let expected = database
            .def_paths
            .get(&module_tree.package)
            .expect("trait package has a DefPath interner")
            .intern_assoc_items(
                trait_owner.owner.def_id,
                &[
                    (DefPathData::AssocType(type_name), 0),
                    (DefPathData::AssocType(type_name), 1),
                    (DefPathData::AssocFn(function_name), 0),
                    (DefPathData::AssocFn(function_name), 1),
                ],
            )
            .expect("HIR lowering disambiguates duplicate associated items by kind");
        let expected_hashes = expected
            .into_iter()
            .map(|id| {
                let path = database
                    .resolve_def_path(id.to_def_id())
                    .expect("associated item DefId is valid")
                    .expect("associated item DefPath exists");
                let hash =
                    sai_hir::DefPathHash::compute(&path, &database.packages, &database.symbols)
                        .expect("associated item DefPath hashes");
                (
                    path.data()
                        .last()
                        .expect("associated item has a final component")
                        .data
                        .clone(),
                    path.data()
                        .last()
                        .expect("associated item has a final component")
                        .disambiguator,
                    sai_stable_hash::Fingerprint::new(hash.raw()),
                )
            })
            .collect::<Vec<_>>();

        for (expected_component, expected_disambiguator, expected_hash) in expected_hashes {
            let expected_kind = if matches!(expected_component, DefPathData::AssocType(_)) {
                sai_semantic::SymbolKind::AssocType
            } else {
                sai_semantic::SymbolKind::AssocFn
            };
            assert!(
                inventory.symbols().iter().any(|symbol| {
                    symbol.path()
                        == if expected_kind == sai_semantic::SymbolKind::AssocType {
                            "acme:phase1.Duplicate.Item"
                        } else {
                            "acme:phase1.Duplicate.item"
                        }
                        && symbol.kind() == expected_kind
                        && symbol.def_path_hash() == expected_hash
                }),
                "inventory retains {expected_component:?} with source disambiguator {expected_disambiguator}"
            );
        }
    }

    #[test]
    fn module_function_inventory_keeps_impls_out_of_trait_slice_and_collects_interfaces() {
        let source = concat!(
            "type Widget {\n}\n",
            "trait Render {\n",
            "type Output\n",
            "fn render(self: borrow Self)\n",
            "}\n",
            "impl Render for Widget {\n",
            "type Output = Str\n",
            "fn render(self: borrow Self) {}\n",
            "}\n",
            "impl Widget {\n",
            "fn helper(self: borrow Self) {}\n",
            "}\n",
            "interface logging {\n",
            "fn write()\n",
            "}\n",
        );
        let (_, module_tree, snapshot, collection) =
            collect_package_inventory_for_target(source.as_bytes(), b"", "wasm32-core");
        let parsed = sai_syntax::parse(&snapshot, module_tree.modules[0].file)
            .expect("trait and implementation fixture parses");
        assert!(
            parsed.errors.is_empty(),
            "parse errors: {:?}",
            parsed.errors
        );

        let inventory = inventory_symbols(&collection);
        assert!(matches!(
            inventory.coverage(),
            sai_semantic::InventoryCoverage::Incomplete { reason }
                if reason.contains("Impl")
        ));
        for expected_trait_symbol in [
            ("acme:phase1.Widget", sai_semantic::SymbolKind::Record),
            ("acme:phase1.Render", sai_semantic::SymbolKind::Trait),
            (
                "acme:phase1.Render.Output",
                sai_semantic::SymbolKind::AssocType,
            ),
            (
                "acme:phase1.Render.render",
                sai_semantic::SymbolKind::AssocFn,
            ),
            ("acme:phase1.logging", sai_semantic::SymbolKind::Interface),
            (
                "acme:phase1.logging.write",
                sai_semantic::SymbolKind::AssocFn,
            ),
        ] {
            assert_eq!(
                inventory
                    .symbols()
                    .iter()
                    .filter(|symbol| {
                        (symbol.path(), symbol.kind())
                            == (expected_trait_symbol.0, expected_trait_symbol.1)
                    })
                    .count(),
                1,
                "expected one collected symbol for {:?}",
                expected_trait_symbol
            );
        }
        assert!(
            inventory.symbols().iter().all(|symbol| {
                !symbol.path().contains(".impl[") && !symbol.path().contains(".Widget.helper")
            }),
            "implementation members must not leak into the module inventory"
        );
    }

    #[test]
    fn module_interface_inventory_collects_root_nested_and_empty_interfaces() {
        let (mut database, module_tree, snapshot, collection) = collect_package_inventory_for_target(
            b"interface empty {}\ninterface codec {\nfn encode(value: U32) -> U32\nfn decode(value: U32) -> U32\n}\n",
            b"interface network {\nfn send()\n}\n",
            "wasm32-core",
        );
        let inventory = inventory_symbols(&collection);
        assert_eq!(
            inventory.coverage(),
            &sai_semantic::InventoryCoverage::Complete
        );
        assert_eq!(
            inventory
                .symbols()
                .iter()
                .map(|symbol| (symbol.path(), symbol.kind()))
                .collect::<std::collections::BTreeSet<_>>(),
            [
                ("acme:phase1.empty", sai_semantic::SymbolKind::Interface),
                ("acme:phase1.codec", sai_semantic::SymbolKind::Interface),
                (
                    "acme:phase1.codec.encode",
                    sai_semantic::SymbolKind::AssocFn
                ),
                (
                    "acme:phase1.codec.decode",
                    sai_semantic::SymbolKind::AssocFn
                ),
                (
                    "acme:phase1/child.network",
                    sai_semantic::SymbolKind::Interface
                ),
                (
                    "acme:phase1/child.network.send",
                    sai_semantic::SymbolKind::AssocFn
                ),
            ]
            .into_iter()
            .collect()
        );

        for (module_index, interface_name, function_name) in [
            (0, "codec", Some("encode")),
            (0, "codec", Some("decode")),
            (1, "network", Some("send")),
        ] {
            let file = module_tree.modules[module_index].file;
            let parsed =
                sai_syntax::parse(&snapshot, file).expect("interface source module parses");
            let interface = parsed
                .root
                .descendants()
                .filter_map(ast::InterfaceDecl::cast)
                .find(|interface| {
                    interface
                        .name()
                        .and_then(|name| name.token())
                        .is_some_and(|token| token.text() == interface_name)
                })
                .expect("the expected interface declaration exists");
            let owner = collection
                .scopes()
                .top_level_owners
                .iter()
                .find(|owner| {
                    owner.kind == TopLevelOwnerKind::Interface
                        && owner.file == file
                        && owner.item_id
                            == database
                                .ast_id_map(&snapshot, file)
                                .expect("interface AST ID map exists")
                                .ast_id(&interface)
                                .expect("interface AST ID exists")
                                .erase()
                })
                .expect("interface has its exact Phase 1 owner");
            let interface_path = database
                .resolve_def_path(owner.owner.def_id.to_def_id())
                .expect("interface DefId is valid")
                .expect("interface DefPath exists");
            assert_eq!(interface_path.package(), module_tree.package);
            let expected_module_path = if module_index == 0 {
                &[][..]
            } else {
                &["child"][..]
            };
            assert_eq!(interface_path.data().len(), expected_module_path.len() + 1);
            for (component, expected_segment) in
                interface_path.data().iter().zip(expected_module_path)
            {
                assert!(matches!(
                    &component.data,
                    DefPathData::Module(segment)
                        if database.symbols.resolve(*segment).is_ok_and(|name| name.as_ref() == *expected_segment)
                ));
                assert_eq!(component.disambiguator, 0);
            }
            assert!(matches!(
                interface_path.data().last(),
                Some(component)
                    if component.data == DefPathData::Interface(
                        database.symbols.intern(interface_name).expect("interface name interns")
                    )
                    && component.disambiguator == 0
            ));
            let interface_symbol_path = if module_index == 0 {
                format!("acme:phase1.{interface_name}")
            } else {
                format!("acme:phase1/child.{interface_name}")
            };
            let interface_symbol = inventory
                .symbols()
                .iter()
                .find(|symbol| symbol.path() == interface_symbol_path)
                .expect("interface has its canonical inventory path");
            let expected_interface_hash = sai_hir::DefPathHash::compute(
                &interface_path,
                &database.packages,
                &database.symbols,
            )
            .expect("interface DefPath hash computes");
            assert_eq!(
                interface_symbol.def_path_hash(),
                sai_stable_hash::Fingerprint::new(expected_interface_hash.raw())
            );
            let interface_name_token = interface
                .name()
                .and_then(|name| name.token())
                .expect("interface name token exists");
            assert_eq!(
                interface_symbol.fingerprint(),
                sai_semantic::declaration_fingerprint(
                    sai_semantic::SymbolKind::Interface,
                    &interface.syntax(),
                    Some(&interface_name_token),
                )
                .expect("interface fingerprint computes")
            );

            if let Some(function_name) = function_name {
                let function = interface
                    .items()
                    .expect("interface member list exists")
                    .syntax()
                    .children()
                    .filter_map(ast::FnDecl::cast)
                    .find(|function| {
                        function
                            .name()
                            .and_then(|name| name.token())
                            .is_some_and(|token| token.text() == function_name)
                    })
                    .expect("the direct interface function exists");
                let function_name_token = function
                    .name()
                    .and_then(|name| name.token())
                    .expect("interface function name token exists");
                let function_path = format!("{interface_symbol_path}.{function_name}");
                let function_symbol = inventory
                    .symbols()
                    .iter()
                    .find(|symbol| symbol.path() == function_path)
                    .expect("interface function has its canonical inventory path");
                let child_component = DefPathData::ValueNs(
                    database
                        .symbols
                        .intern(function_name)
                        .expect("function name interns"),
                );
                let function_def_id = database
                    .def_paths
                    .get(&module_tree.package)
                    .expect("package DefPath interner exists")
                    .intern_children(owner.owner.def_id, &[(child_component.clone(), 0)])
                    .expect("interface function DefPath interns")
                    .into_iter()
                    .next()
                    .expect("interface function DefId exists");
                let function_path = database
                    .resolve_def_path(function_def_id.to_def_id())
                    .expect("interface function DefId is valid")
                    .expect("interface function DefPath exists");
                assert_eq!(
                    &function_path.data()[..interface_path.data().len()],
                    interface_path.data()
                );
                assert!(matches!(
                    function_path.data().last(),
                    Some(component)
                        if component.data == child_component && component.disambiguator == 0
                ));
                let expected_function_hash = sai_hir::DefPathHash::compute(
                    &function_path,
                    &database.packages,
                    &database.symbols,
                )
                .expect("interface function DefPath hash computes");
                assert_eq!(
                    function_symbol.def_path_hash(),
                    sai_stable_hash::Fingerprint::new(expected_function_hash.raw())
                );
                assert_eq!(
                    function_symbol.fingerprint(),
                    sai_semantic::declaration_fingerprint(
                        sai_semantic::SymbolKind::AssocFn,
                        &function.syntax(),
                        Some(&function_name_token),
                    )
                    .expect("interface function fingerprint computes")
                );
            }
        }
        assert!(
            inventory
                .symbols()
                .iter()
                .any(|symbol| symbol.path() == "acme:phase1.empty"),
            "an empty interface still has one interface symbol"
        );
    }

    #[test]
    fn module_interface_inventory_fingerprints_are_stable_under_name_token_renames() {
        let (_, _, _, original) = collect_package_inventory_for_target(
            b"interface codec {\nfn encode(value: U32) -> U32\n}\n",
            b"",
            "wasm32-core",
        );
        let (_, _, _, renamed_interface) = collect_package_inventory_for_target(
            b"interface wire {\nfn encode(value: U32) -> U32\n}\n",
            b"",
            "wasm32-core",
        );
        let (_, _, _, renamed_function) = collect_package_inventory_for_target(
            b"interface codec {\nfn serialize(value: U32) -> U32\n}\n",
            b"",
            "wasm32-core",
        );
        let original = inventory_symbols(&original);
        let renamed_interface = inventory_symbols(&renamed_interface);
        let renamed_function = inventory_symbols(&renamed_function);
        let find = |inventory: &sai_semantic::PackageSymbolInventory, path: &str| {
            inventory
                .symbols()
                .iter()
                .find(|symbol| symbol.path() == path)
                .expect("the expected interface inventory symbol exists")
                .fingerprint()
        };
        assert_eq!(
            find(original, "acme:phase1.codec"),
            find(renamed_interface, "acme:phase1.wire"),
            "renaming the interface omits only the interface declaration name token"
        );
        assert_eq!(
            find(original, "acme:phase1.codec.encode"),
            find(renamed_interface, "acme:phase1.wire.encode"),
            "renaming the interface leaves the function declaration fingerprint stable"
        );
        assert_eq!(
            find(original, "acme:phase1.codec.encode"),
            find(renamed_function, "acme:phase1.codec.serialize"),
            "renaming an interface function omits its own name token"
        );
        assert_ne!(
            find(original, "acme:phase1.codec"),
            find(renamed_function, "acme:phase1.codec"),
            "the interface fingerprint still tracks its member declaration"
        );
    }

    #[test]
    fn module_interface_inventory_preserves_duplicate_canonical_paths_incomplete() {
        let (database, module_tree, _, collection) = collect_package_inventory_for_target(
            b"interface repeated {\nfn read()\nfn read()\n}\ninterface repeated {\nfn read()\n}\n",
            b"",
            "wasm32-core",
        );
        let inventory = inventory_symbols(&collection);
        assert!(matches!(
            inventory.coverage(),
            sai_semantic::InventoryCoverage::Incomplete { reason }
                if reason.contains("duplicate canonical symbol path")
        ));
        for (path, kind, expected_count) in [
            (
                "acme:phase1.repeated",
                sai_semantic::SymbolKind::Interface,
                2,
            ),
            (
                "acme:phase1.repeated.read",
                sai_semantic::SymbolKind::AssocFn,
                3,
            ),
        ] {
            let symbols = inventory
                .symbols()
                .iter()
                .filter(|symbol| symbol.path() == path && symbol.kind() == kind)
                .collect::<Vec<_>>();
            assert_eq!(
                symbols.len(),
                expected_count,
                "candidate symbols for {path}"
            );
            assert_eq!(
                symbols
                    .iter()
                    .map(|symbol| symbol.def_path_hash())
                    .collect::<std::collections::HashSet<_>>()
                    .len(),
                expected_count,
                "each same-name declaration keeps its distinct DefPath hash"
            );
        }

        let interfaces = collection
            .scopes()
            .top_level_owners
            .iter()
            .filter(|owner| {
                owner.kind == TopLevelOwnerKind::Interface
                    && owner.file == module_tree.modules[0].file
            })
            .collect::<Vec<_>>();
        let interface_disambiguators = interfaces
            .iter()
            .map(|owner| {
                database
                    .resolve_def_path(owner.owner.def_id.to_def_id())
                    .expect("interface owner DefId is valid")
                    .expect("interface owner DefPath exists")
                    .data()
                    .last()
                    .expect("interface DefPath has a terminal component")
                    .disambiguator
            })
            .collect::<Vec<_>>();
        assert_eq!(interface_disambiguators, [0, 1]);
    }

    #[test]
    fn module_interface_inventory_collects_supported_members_and_rejects_invalid_targets() {
        let (_, _, _, mixed_members) = collect_package_inventory_for_target(
            b"interface api {\ntype Record { value: U32 }\nenum State { Ready }\ntype Alias = U32\nresource Handle {\nfn close(self: borrow Self)\n}\nfn read()\n}\n",
            b"",
            "wasm32-core",
        );
        let mixed_members = inventory_symbols(&mixed_members);
        assert_eq!(
            mixed_members.coverage(),
            &sai_semantic::InventoryCoverage::Complete
        );
        assert!(mixed_members.symbols().iter().any(|symbol| {
            symbol.path() == "acme:phase1.api"
                && symbol.kind() == sai_semantic::SymbolKind::Interface
        }));
        assert!(mixed_members.symbols().iter().any(|symbol| {
            symbol.path() == "acme:phase1.api.read"
                && symbol.kind() == sai_semantic::SymbolKind::AssocFn
        }));
        assert!(mixed_members.symbols().iter().any(|symbol| {
            symbol.path() == "acme:phase1.api.Handle"
                && symbol.kind() == sai_semantic::SymbolKind::Resource
        }));
        assert!(mixed_members.symbols().iter().any(|symbol| {
            symbol.path() == "acme:phase1.api.Handle.close"
                && symbol.kind() == sai_semantic::SymbolKind::AssocFn
        }));
        assert!(mixed_members.symbols().iter().any(|symbol| {
            symbol.path() == "acme:phase1.api.Record"
                && symbol.kind() == sai_semantic::SymbolKind::Record
        }));
        assert!(mixed_members.symbols().iter().any(|symbol| {
            symbol.path() == "acme:phase1.api.Record.field[value]"
                && symbol.kind() == sai_semantic::SymbolKind::Field
        }));
        assert!(mixed_members.symbols().iter().any(|symbol| {
            symbol.path() == "acme:phase1.api.State"
                && symbol.kind() == sai_semantic::SymbolKind::Enum
        }));
        assert!(mixed_members.symbols().iter().any(|symbol| {
            symbol.path() == "acme:phase1.api.State.Ready"
                && symbol.kind() == sai_semantic::SymbolKind::Variant
        }));
        assert!(
            mixed_members.symbols().iter().any(|symbol| {
                symbol.path() == "acme:phase1.api.Alias"
                    && symbol.kind() == sai_semantic::SymbolKind::Alias
            }),
            "direct interface aliases are inventoried"
        );
        assert_eq!(
            mixed_members
                .symbols()
                .iter()
                .filter(|symbol| symbol.path() == "acme:phase1.api.close")
                .count(),
            0,
            "a resource method is not emitted as a direct interface function"
        );

        let cases: [(&str, &[u8]); 10] = [
            (
                "generic interface function",
                b"interface api { fn generic<T>(value: T) }\n",
            ),
            (
                "where clause on interface function",
                b"interface api { fn bounded<T>() where T: Copy }\n",
            ),
            (
                "async interface function",
                b"interface api { async fn later() }\n",
            ),
            (
                "unsafe interface function",
                b"interface api { unsafe fn native() }\n",
            ),
            (
                "interface function body",
                b"interface api { fn with_body() {} }\n",
            ),
            (
                "malformed interface function",
                b"interface api { fn broken(value: ) }\n",
            ),
            (
                "invalid target on interface function",
                b"interface api { @target(host) fn targeted() }\n",
            ),
            (
                "valid target on interface function",
                b"interface api { @target(\"wasm64-core\") fn targeted() }\n",
            ),
            (
                "unknown target on interface",
                b"@target(\"wasm32-linux\") interface api {}\n",
            ),
            (
                "disallowed target on interface",
                b"@target(\"wasm64-core\") interface api {}\n",
            ),
        ];
        for (case_name, source) in cases {
            let (_, _, _, collection) =
                collect_package_inventory_for_target(source, b"", "wasm32-core");
            assert!(
                matches!(
                    inventory_symbols(&collection).coverage(),
                    sai_semantic::InventoryCoverage::Incomplete { .. }
                ),
                "{case_name} must not yield complete interface coverage"
            );
        }
    }

    #[test]
    fn module_interface_resource_inventory_collects_resources_members_and_identity() {
        let (mut database, module_tree, snapshot, collection) = collect_package_inventory_for_target(
            b"interface codec {\nfn before()\nfn close()\nresource Handle {\nfn new(id: U32) -> Self\nfn parse(value: U32) -> Self\nfn close(self: borrow Self)\n}\nfn after()\nresource Empty {}\nresource Bare\n}\n",
            b"interface socket {\nresource Stream {\nfn send(self: borrow Self, value: U8)\n}\n}\n",
            "wasm32-core",
        );
        let inventory = inventory_symbols(&collection);
        assert_eq!(
            inventory.coverage(),
            &sai_semantic::InventoryCoverage::Complete
        );
        let actual = inventory
            .symbols()
            .iter()
            .map(|symbol| (symbol.path(), symbol.kind()))
            .collect::<std::collections::BTreeSet<_>>();
        assert_eq!(
            actual,
            [
                ("acme:phase1.codec", sai_semantic::SymbolKind::Interface),
                (
                    "acme:phase1.codec.before",
                    sai_semantic::SymbolKind::AssocFn
                ),
                ("acme:phase1.codec.close", sai_semantic::SymbolKind::AssocFn),
                ("acme:phase1.codec.after", sai_semantic::SymbolKind::AssocFn),
                (
                    "acme:phase1.codec.Handle",
                    sai_semantic::SymbolKind::Resource
                ),
                (
                    "acme:phase1.codec.Handle.new",
                    sai_semantic::SymbolKind::AssocFn
                ),
                (
                    "acme:phase1.codec.Handle.parse",
                    sai_semantic::SymbolKind::AssocFn
                ),
                (
                    "acme:phase1.codec.Handle.close",
                    sai_semantic::SymbolKind::AssocFn
                ),
                (
                    "acme:phase1.codec.Empty",
                    sai_semantic::SymbolKind::Resource
                ),
                ("acme:phase1.codec.Bare", sai_semantic::SymbolKind::Resource),
                (
                    "acme:phase1/child.socket",
                    sai_semantic::SymbolKind::Interface
                ),
                (
                    "acme:phase1/child.socket.Stream",
                    sai_semantic::SymbolKind::Resource
                ),
                (
                    "acme:phase1/child.socket.Stream.send",
                    sai_semantic::SymbolKind::AssocFn
                ),
            ]
            .into_iter()
            .collect()
        );
        assert_eq!(
            inventory
                .symbols()
                .iter()
                .filter(|symbol| symbol.path() == "acme:phase1.codec.close")
                .count(),
            1,
            "a resource method must not leak into the interface's direct function path"
        );

        let file = module_tree.modules[0].file;
        let parsed = sai_syntax::parse(&snapshot, file).expect("resource source parses");
        assert!(
            parsed.errors.is_empty(),
            "parse errors: {:?}",
            parsed.errors
        );
        let interface = parsed
            .root
            .descendants()
            .filter_map(ast::InterfaceDecl::cast)
            .find(|interface| {
                interface
                    .name()
                    .and_then(|name| name.token())
                    .is_some_and(|token| token.text() == "codec")
            })
            .expect("codec interface exists");
        let interface_ast_id = database
            .ast_id_map(&snapshot, file)
            .expect("AST ID map exists")
            .ast_id(&interface)
            .expect("interface AST ID exists")
            .erase();
        let interface_owner = collection
            .scopes()
            .top_level_owners
            .iter()
            .find(|owner| {
                owner.kind == TopLevelOwnerKind::Interface
                    && owner.file == file
                    && owner.item_id == interface_ast_id
            })
            .expect("interface has its exact Phase 1 owner");
        let resource = interface
            .items()
            .expect("interface item list exists")
            .syntax()
            .children()
            .filter_map(ast::IfaceResource::cast)
            .find(|resource| {
                resource
                    .name()
                    .and_then(|name| name.token())
                    .is_some_and(|token| token.text() == "Handle")
            })
            .expect("Handle resource exists");
        let handle_symbol = inventory
            .symbols()
            .iter()
            .find(|symbol| symbol.path() == "acme:phase1.codec.Handle")
            .expect("resource symbol exists");
        let handle_name_token = resource
            .name()
            .and_then(|name| name.token())
            .expect("resource name token exists");
        assert_eq!(
            handle_symbol.fingerprint(),
            sai_semantic::declaration_fingerprint(
                sai_semantic::SymbolKind::Resource,
                &resource.syntax(),
                Some(&handle_name_token),
            )
            .expect("resource fingerprint computes")
        );

        let def_path_interner = database
            .def_paths
            .get(&module_tree.package)
            .expect("package DefPath interner exists");
        let resource_name = database
            .symbols
            .intern("Handle")
            .expect("resource name interns");
        let resource_def_id = def_path_interner
            .intern_children(
                interface_owner.owner.def_id,
                &[(DefPathData::TypeNs(resource_name), 0)],
            )
            .expect("resource DefPath interns")
            .into_iter()
            .next()
            .expect("resource DefPath ID exists");
        let resource_path = database
            .resolve_def_path(resource_def_id.to_def_id())
            .expect("resource DefId is valid")
            .expect("resource DefPath exists");
        let interface_path = database
            .resolve_def_path(interface_owner.owner.def_id.to_def_id())
            .expect("interface DefId is valid")
            .expect("interface DefPath exists");
        assert_eq!(
            &resource_path.data()[..interface_path.data().len()],
            interface_path.data()
        );
        assert!(matches!(
            resource_path.data().last(),
            Some(component)
                if component.data == DefPathData::TypeNs(resource_name)
                    && component.disambiguator == 0
        ));
        let expected_resource_hash =
            sai_hir::DefPathHash::compute(&resource_path, &database.packages, &database.symbols)
                .expect("resource DefPath hash computes");
        assert_eq!(
            handle_symbol.def_path_hash(),
            sai_stable_hash::Fingerprint::new(expected_resource_hash.raw())
        );

        for member_name in ["new", "parse", "close"] {
            let function = resource
                .items()
                .expect("resource member list exists")
                .syntax()
                .children()
                .filter_map(ast::FnDecl::cast)
                .find(|function| {
                    function
                        .name()
                        .and_then(|name| name.token())
                        .is_some_and(|token| token.text() == member_name)
                })
                .expect("resource function exists");
            let function_name_token = function
                .name()
                .and_then(|name| name.token())
                .expect("resource function name token exists");
            let canonical_path = format!("acme:phase1.codec.Handle.{member_name}");
            let function_symbol = inventory
                .symbols()
                .iter()
                .find(|symbol| symbol.path() == canonical_path)
                .expect("resource function symbol exists");
            assert_eq!(
                function_symbol.fingerprint(),
                sai_semantic::declaration_fingerprint(
                    sai_semantic::SymbolKind::AssocFn,
                    &function.syntax(),
                    Some(&function_name_token),
                )
                .expect("resource function fingerprint computes")
            );

            let member_name_symbol = database
                .symbols
                .intern(member_name)
                .expect("resource member name interns");
            let member_def_id = def_path_interner
                .intern_children(
                    resource_def_id,
                    &[(DefPathData::AssocFn(member_name_symbol), 0)],
                )
                .expect("resource function DefPath interns")
                .into_iter()
                .next()
                .expect("resource function DefPath ID exists");
            let member_path = database
                .resolve_def_path(member_def_id.to_def_id())
                .expect("resource function DefId is valid")
                .expect("resource function DefPath exists");
            assert_eq!(
                &member_path.data()[..resource_path.data().len()],
                resource_path.data()
            );
            assert!(matches!(
                member_path.data().last(),
                Some(component)
                    if component.data == DefPathData::AssocFn(member_name_symbol)
                        && component.disambiguator == 0
            ));
            let expected_hash =
                sai_hir::DefPathHash::compute(&member_path, &database.packages, &database.symbols)
                    .expect("resource function DefPath hash computes");
            assert_eq!(
                function_symbol.def_path_hash(),
                sai_stable_hash::Fingerprint::new(expected_hash.raw())
            );
        }
    }

    #[test]
    fn module_interface_resource_inventory_disambiguates_duplicate_paths() {
        let (_, _, _, collection) = collect_package_inventory_for_target(
            b"interface api {\nresource Handle {\nfn close(self: borrow Self)\nfn close(self: borrow Self)\n}\nresource Handle {\nfn close(self: borrow Self)\n}\n}\n",
            b"",
            "wasm32-core",
        );
        let inventory = inventory_symbols(&collection);
        assert!(matches!(
            inventory.coverage(),
            sai_semantic::InventoryCoverage::Incomplete { reason }
                if reason.contains("duplicate canonical symbol path")
        ));
        for (path, kind, expected_count) in [
            (
                "acme:phase1.api.Handle",
                sai_semantic::SymbolKind::Resource,
                2,
            ),
            (
                "acme:phase1.api.Handle.close",
                sai_semantic::SymbolKind::AssocFn,
                3,
            ),
        ] {
            let symbols = inventory
                .symbols()
                .iter()
                .filter(|symbol| symbol.path() == path && symbol.kind() == kind)
                .collect::<Vec<_>>();
            assert_eq!(
                symbols.len(),
                expected_count,
                "candidate symbols for {path}"
            );
            assert_eq!(
                symbols
                    .iter()
                    .map(|symbol| symbol.def_path_hash())
                    .collect::<std::collections::HashSet<_>>()
                    .len(),
                expected_count,
                "duplicate canonical candidates have distinct DefPath hashes"
            );
        }
    }

    #[test]
    fn module_interface_resource_inventory_shares_type_namespace_disambiguators() {
        let (mut database, module_tree, snapshot, collection) =
            collect_package_inventory_for_target(
                b"interface api {\ntype Handle = U32\nresource Handle {}\n}\n",
                b"",
                "wasm32-core",
            );
        let inventory = inventory_symbols(&collection);
        assert!(matches!(
            inventory.coverage(),
            sai_semantic::InventoryCoverage::Incomplete { reason }
                if reason.contains("duplicate canonical symbol path")
        ));
        let alias_symbol = inventory
            .symbols()
            .iter()
            .find(|symbol| {
                symbol.path() == "acme:phase1.api.Handle"
                    && symbol.kind() == sai_semantic::SymbolKind::Alias
            })
            .expect("alias survives beside the same-named resource");
        let resource_symbol = inventory
            .symbols()
            .iter()
            .find(|symbol| {
                symbol.path() == "acme:phase1.api.Handle"
                    && symbol.kind() == sai_semantic::SymbolKind::Resource
            })
            .expect("resource survives beside the same-named alias");

        let file = module_tree.modules[0].file;
        let parsed = sai_syntax::parse(&snapshot, file)
            .expect("same-named alias and resource source parses");
        assert!(
            parsed.errors.is_empty(),
            "parse errors: {:?}",
            parsed.errors
        );
        let interface = parsed
            .root
            .descendants()
            .filter_map(ast::InterfaceDecl::cast)
            .find(|interface| {
                interface
                    .name()
                    .and_then(|name| name.token())
                    .is_some_and(|token| token.text() == "api")
            })
            .expect("api interface exists");
        let interface_ast_id = database
            .ast_id_map(&snapshot, file)
            .expect("AST ID map exists")
            .ast_id(&interface)
            .expect("interface AST ID exists")
            .erase();
        let interface_owner = collection
            .scopes()
            .top_level_owners
            .iter()
            .find(|owner| {
                owner.kind == TopLevelOwnerKind::Interface
                    && owner.file == file
                    && owner.item_id == interface_ast_id
            })
            .expect("interface has its exact Phase 1 owner");
        let def_path_interner = database
            .def_paths
            .get(&module_tree.package)
            .expect("package DefPath interner exists");
        let resource_name = database
            .symbols
            .intern("Handle")
            .expect("resource name interns");
        let alias_def_id = def_path_interner
            .intern_children(
                interface_owner.owner.def_id,
                &[(DefPathData::TypeNs(resource_name), 0)],
            )
            .expect("first same-named TypeNs DefPath interns")
            .into_iter()
            .next()
            .expect("first TypeNs DefPath ID exists");
        let resource_def_id = def_path_interner
            .intern_children(
                interface_owner.owner.def_id,
                &[(DefPathData::TypeNs(resource_name), 1)],
            )
            .expect("second same-named TypeNs DefPath interns")
            .into_iter()
            .next()
            .expect("second TypeNs DefPath ID exists");
        let alias_path = database
            .resolve_def_path(alias_def_id.to_def_id())
            .expect("alias DefId is valid")
            .expect("alias DefPath exists");
        let resource_path = database
            .resolve_def_path(resource_def_id.to_def_id())
            .expect("resource DefId is valid")
            .expect("resource DefPath exists");
        assert!(matches!(
            alias_path.data().last(),
            Some(component)
                if component.data == DefPathData::TypeNs(resource_name)
                    && component.disambiguator == 0
        ));
        assert!(matches!(
            resource_path.data().last(),
            Some(component)
                if component.data == DefPathData::TypeNs(resource_name)
                    && component.disambiguator == 1
        ));
        let expected_resource_hash =
            sai_hir::DefPathHash::compute(&resource_path, &database.packages, &database.symbols)
                .expect("resource DefPath hash computes");
        assert_eq!(
            resource_symbol.def_path_hash(),
            sai_stable_hash::Fingerprint::new(expected_resource_hash.raw())
        );
        let alias_hash =
            sai_hir::DefPathHash::compute(&alias_path, &database.packages, &database.symbols)
                .expect("alias DefPath hash computes");
        assert_ne!(
            resource_symbol.def_path_hash(),
            sai_stable_hash::Fingerprint::new(alias_hash.raw()),
            "same-named interface TypeNs items have distinct DefPath hashes"
        );
        assert_eq!(
            alias_symbol.def_path_hash(),
            sai_stable_hash::Fingerprint::new(alias_hash.raw())
        );
    }

    #[test]
    fn module_interface_alias_after_resource_uses_second_type_namespace_disambiguator() {
        let (mut database, module_tree, snapshot, collection) =
            collect_package_inventory_for_target(
                b"interface api {\nresource Handle {}\ntype Handle = U32\n}\n",
                b"",
                "wasm32-core",
            );
        let inventory = inventory_symbols(&collection);
        assert!(matches!(
            inventory.coverage(),
            sai_semantic::InventoryCoverage::Incomplete { reason }
                if reason.contains("duplicate canonical symbol path")
        ));
        let alias_symbol = inventory
            .symbols()
            .iter()
            .find(|symbol| {
                symbol.path() == "acme:phase1.api.Handle"
                    && symbol.kind() == sai_semantic::SymbolKind::Alias
            })
            .expect("alias remains visible as an incomplete candidate");
        let resource_symbol = inventory
            .symbols()
            .iter()
            .find(|symbol| {
                symbol.path() == "acme:phase1.api.Handle"
                    && symbol.kind() == sai_semantic::SymbolKind::Resource
            })
            .expect("resource remains visible as an incomplete candidate");

        let file = module_tree.modules[0].file;
        let parsed =
            sai_syntax::parse(&snapshot, file).expect("same-named resource and alias parse");
        assert!(
            parsed.errors.is_empty(),
            "parse errors: {:?}",
            parsed.errors
        );
        let interface = parsed
            .root
            .descendants()
            .filter_map(ast::InterfaceDecl::cast)
            .find(|interface| {
                interface
                    .name()
                    .and_then(|name| name.token())
                    .is_some_and(|token| token.text() == "api")
            })
            .expect("api interface exists");
        let interface_ast_id = database
            .ast_id_map(&snapshot, file)
            .expect("current snapshot AST ID map exists")
            .ast_id(&interface)
            .expect("interface AST ID exists")
            .erase();
        let interface_owner = collection
            .scopes()
            .top_level_owners
            .iter()
            .find(|owner| {
                owner.kind == TopLevelOwnerKind::Interface
                    && owner.file == file
                    && owner.item_id == interface_ast_id
            })
            .expect("interface owner matches the exact AST declaration");
        let def_path_interner = database
            .def_paths
            .get(&module_tree.package)
            .expect("package DefPath interner exists");
        let name = database.symbols.intern("Handle").expect("name interns");
        let resource_def_id = def_path_interner
            .intern_children(
                interface_owner.owner.def_id,
                &[(DefPathData::TypeNs(name), 0)],
            )
            .expect("first TypeNs path interns")
            .into_iter()
            .next()
            .expect("resource DefPath ID exists");
        let alias_def_id = def_path_interner
            .intern_children(
                interface_owner.owner.def_id,
                &[(DefPathData::TypeNs(name), 1)],
            )
            .expect("second TypeNs path interns")
            .into_iter()
            .next()
            .expect("alias DefPath ID exists");
        let resource_path = database
            .resolve_def_path(resource_def_id.to_def_id())
            .expect("resource DefId resolves")
            .expect("resource DefPath exists");
        let alias_path = database
            .resolve_def_path(alias_def_id.to_def_id())
            .expect("alias DefId resolves")
            .expect("alias DefPath exists");
        assert!(matches!(
            resource_path.data().last(),
            Some(component)
                if component.data == DefPathData::TypeNs(name)
                    && component.disambiguator == 0
        ));
        assert!(matches!(
            alias_path.data().last(),
            Some(component)
                if component.data == DefPathData::TypeNs(name)
                    && component.disambiguator == 1
        ));
        let expected_resource_hash =
            sai_hir::DefPathHash::compute(&resource_path, &database.packages, &database.symbols)
                .expect("resource DefPath hash computes");
        let expected_alias_hash =
            sai_hir::DefPathHash::compute(&alias_path, &database.packages, &database.symbols)
                .expect("alias DefPath hash computes");
        assert_eq!(
            resource_symbol.def_path_hash(),
            sai_stable_hash::Fingerprint::new(expected_resource_hash.raw())
        );
        assert_eq!(
            alias_symbol.def_path_hash(),
            sai_stable_hash::Fingerprint::new(expected_alias_hash.raw())
        );
        assert_ne!(
            resource_symbol.def_path_hash(),
            alias_symbol.def_path_hash()
        );
    }

    #[test]
    fn module_interface_resource_inventory_leaves_boundary_type_checks_to_interface_check() {
        let (_, _, _, collection) = collect_package_inventory_for_target(
            b"interface api {\nresource Handle {\nfn count(self: Self) -> USize\n}\n}\n",
            b"",
            "wasm32-core",
        );
        let inventory = inventory_symbols(&collection);
        assert_eq!(
            inventory.coverage(),
            &sai_semantic::InventoryCoverage::Complete
        );
        assert!(
            inventory.symbols().iter().any(|symbol| {
                symbol.path() == "acme:phase1.api.Handle.count"
                    && symbol.kind() == sai_semantic::SymbolKind::AssocFn
            }),
            "a structurally identified declaration stays inventoried for interface_check"
        );
    }

    #[test]
    fn module_interface_resource_inventory_fails_closed_without_leaking_unsupported_members() {
        let cases: [(&str, &[u8]); 6] = [
            (
                "valid resource target predicate is not applied to nested members",
                b"interface api {\n@target(\"wasm64-core\") resource Handle {\nfn read(self: borrow Self)\n}\n}\n",
            ),
            (
                "invalid resource target predicate",
                b"interface api {\n@target(wasm32-linux) resource Handle {}\n}\n",
            ),
            (
                "valid resource function target predicate is not applied",
                b"interface api {\nresource Handle {\n@target(\"wasm64-core\") fn read(self: borrow Self)\n}\n}\n",
            ),
            (
                "invalid resource function attribute",
                b"interface api {\nresource Handle {\n@deprecated(1) fn read(self: borrow Self)\n}\n}\n",
            ),
            (
                "malformed resource function",
                b"interface api {\nresource Handle {\nfn read(self: borrow Self\n}\n}\n",
            ),
            (
                "unsupported nested associated type",
                b"interface api {\nresource Handle {\ntype Output = U32\nfn read(self: borrow Self)\n}\n}\n",
            ),
        ];
        for (case_name, source) in cases {
            let (_, _, _, collection) =
                collect_package_inventory_for_target(source, b"", "wasm32-core");
            let inventory = inventory_symbols(&collection);
            assert!(
                matches!(
                    inventory.coverage(),
                    sai_semantic::InventoryCoverage::Incomplete { .. }
                ),
                "{case_name} must not yield complete interface-resource coverage"
            );
            assert!(
                inventory.symbols().iter().all(|symbol| {
                    !symbol.path().contains(".Handle.Output")
                        && !symbol.path().contains(".Handle.Assoc")
                }),
                "{case_name} must not leak unsupported nested members"
            );
        }
    }

    #[test]
    fn module_interface_alias_inventory_keeps_forbidden_generic_candidates_incomplete() {
        let (mut database, module_tree, snapshot, collection) =
            collect_package_inventory_for_target(
                b"interface codec {\ntype Word = U64\ntype Identity<T, const N: I32> = T\n}\n",
                b"interface identity {\ntype Key = U32\n}\n",
                "wasm32-core",
            );
        let inventory = inventory_symbols(&collection);
        assert!(matches!(
            inventory.coverage(),
            sai_semantic::InventoryCoverage::Incomplete { reason }
                if reason.contains("GENERIC_INTERFACE_ITEM")
        ));
        let actual = inventory
            .symbols()
            .iter()
            .map(|symbol| (symbol.path(), symbol.kind()))
            .collect::<std::collections::BTreeSet<_>>();
        assert_eq!(
            actual,
            [
                ("acme:phase1.codec", sai_semantic::SymbolKind::Interface),
                ("acme:phase1.codec.Word", sai_semantic::SymbolKind::Alias),
                (
                    "acme:phase1.codec.Identity",
                    sai_semantic::SymbolKind::Alias
                ),
                (
                    "acme:phase1.codec.Identity.generic[T]",
                    sai_semantic::SymbolKind::GenericParam
                ),
                (
                    "acme:phase1.codec.Identity.generic[N]",
                    sai_semantic::SymbolKind::GenericParam
                ),
                (
                    "acme:phase1/child.identity",
                    sai_semantic::SymbolKind::Interface
                ),
                (
                    "acme:phase1/child.identity.Key",
                    sai_semantic::SymbolKind::Alias
                ),
            ]
            .into_iter()
            .collect()
        );

        let root_file = module_tree.modules[0].file;
        let parsed = sai_syntax::parse(&snapshot, root_file).expect("alias source parses");
        assert!(
            parsed.errors.is_empty(),
            "parse errors: {:?}",
            parsed.errors
        );
        let interface = parsed
            .root
            .descendants()
            .filter_map(ast::InterfaceDecl::cast)
            .find(|interface| {
                interface
                    .name()
                    .and_then(|name| name.token())
                    .is_some_and(|token| token.text() == "codec")
            })
            .expect("codec interface exists");
        let alias = interface
            .items()
            .expect("interface item list exists")
            .syntax()
            .children()
            .filter_map(ast::TypeDecl::cast)
            .find(|declaration| {
                declaration
                    .name()
                    .and_then(|name| name.token())
                    .is_some_and(|token| token.text() == "Identity")
            })
            .expect("Identity alias exists");
        let alias_name_token = alias
            .name()
            .and_then(|name| name.token())
            .expect("alias name token exists");
        let identity_symbol = inventory
            .symbols()
            .iter()
            .find(|symbol| {
                symbol.path() == "acme:phase1.codec.Identity"
                    && symbol.kind() == sai_semantic::SymbolKind::Alias
            })
            .expect("Identity alias symbol exists");
        assert_eq!(
            identity_symbol.fingerprint(),
            sai_semantic::declaration_fingerprint(
                sai_semantic::SymbolKind::Alias,
                &alias.syntax(),
                Some(&alias_name_token),
            )
            .expect("interface alias fingerprint computes from its actual name token")
        );

        let interface_ast_id = database
            .ast_id_map(&snapshot, root_file)
            .expect("current snapshot AST ID map exists")
            .ast_id(&interface)
            .expect("interface AST ID exists")
            .erase();
        let interface_owner = collection
            .scopes()
            .top_level_owners
            .iter()
            .find(|owner| {
                owner.kind == TopLevelOwnerKind::Interface
                    && owner.file == root_file
                    && owner.item_id == interface_ast_id
            })
            .expect("interface owner matches the exact source declaration");
        let def_path_interner = database
            .def_paths
            .get(&module_tree.package)
            .expect("package DefPath interner exists");
        let alias_name_symbol = database
            .symbols
            .intern("Identity")
            .expect("alias name interns");
        let alias_def_id = def_path_interner
            .intern_children(
                interface_owner.owner.def_id,
                &[(DefPathData::TypeNs(alias_name_symbol), 0)],
            )
            .expect("interface alias DefPath interns")
            .into_iter()
            .next()
            .expect("interface alias DefPath ID exists");
        let interface_path = database
            .resolve_def_path(interface_owner.owner.def_id.to_def_id())
            .expect("interface owner DefId is valid")
            .expect("interface owner DefPath exists");
        let alias_path = database
            .resolve_def_path(alias_def_id.to_def_id())
            .expect("interface alias DefId is valid")
            .expect("interface alias DefPath exists");
        assert_eq!(
            &alias_path.data()[..interface_path.data().len()],
            interface_path.data()
        );
        assert!(matches!(
            alias_path.data().last(),
            Some(component)
                if component.data == DefPathData::TypeNs(alias_name_symbol)
                    && component.disambiguator == 0
        ));
        let expected_alias_hash =
            sai_hir::DefPathHash::compute(&alias_path, &database.packages, &database.symbols)
                .expect("interface alias DefPath hash computes");
        assert_eq!(
            identity_symbol.def_path_hash(),
            sai_stable_hash::Fingerprint::new(expected_alias_hash.raw())
        );

        let generic_name = database.symbols.intern("T").expect("generic name interns");
        let const_generic_name = database
            .symbols
            .intern("N")
            .expect("const generic name interns");
        let generic_def_id = def_path_interner
            .intern_generic_params(
                alias_def_id,
                &[(generic_name, false, 0), (const_generic_name, true, 0)],
            )
            .expect("interface alias generic DefPath interns")
            .into_iter()
            .next()
            .expect("interface alias generic DefPath ID exists");
        let generic_path = database
            .resolve_def_path(generic_def_id.to_def_id())
            .expect("generic DefId is valid")
            .expect("generic DefPath exists");
        assert_eq!(
            &generic_path.data()[..alias_path.data().len()],
            alias_path.data()
        );
        assert!(matches!(
            generic_path.data().last(),
            Some(component)
                if component.data == DefPathData::TypeParam(generic_name)
                    && component.disambiguator == 0
        ));
        let expected_generic_hash =
            sai_hir::DefPathHash::compute(&generic_path, &database.packages, &database.symbols)
                .expect("generic DefPath hash computes");
        let generic_symbol = inventory
            .symbols()
            .iter()
            .find(|symbol| {
                symbol.path() == "acme:phase1.codec.Identity.generic[T]"
                    && symbol.kind() == sai_semantic::SymbolKind::GenericParam
            })
            .expect("interface alias generic symbol exists");
        assert_eq!(
            generic_symbol.def_path_hash(),
            sai_stable_hash::Fingerprint::new(expected_generic_hash.raw())
        );
        let const_generic_def_id = def_path_interner
            .intern_generic_params(alias_def_id, &[(const_generic_name, true, 0)])
            .expect("interface alias const generic DefPath interns")
            .into_iter()
            .next()
            .expect("interface alias const generic DefPath ID exists");
        let const_generic_path = database
            .resolve_def_path(const_generic_def_id.to_def_id())
            .expect("const generic DefId is valid")
            .expect("const generic DefPath exists");
        assert_eq!(
            &const_generic_path.data()[..alias_path.data().len()],
            alias_path.data()
        );
        assert!(matches!(
            const_generic_path.data().last(),
            Some(component)
                if component.data == DefPathData::ConstParam(const_generic_name)
                    && component.disambiguator == 0
        ));
        let expected_const_generic_hash = sai_hir::DefPathHash::compute(
            &const_generic_path,
            &database.packages,
            &database.symbols,
        )
        .expect("const generic DefPath hash computes");
        let const_generic_symbol = inventory
            .symbols()
            .iter()
            .find(|symbol| {
                symbol.path() == "acme:phase1.codec.Identity.generic[N]"
                    && symbol.kind() == sai_semantic::SymbolKind::GenericParam
            })
            .expect("interface alias const generic symbol exists");
        assert_eq!(
            const_generic_symbol.def_path_hash(),
            sai_stable_hash::Fingerprint::new(expected_const_generic_hash.raw())
        );
    }

    #[test]
    fn module_interface_record_inventory_collects_root_nested_fields_and_identity() {
        let (mut database, module_tree, snapshot, collection) =
            collect_package_inventory_for_target(
            b"interface codec {\ntype Message { header: U32\npayload: U64 }\ntype Empty {}\n}\n",
            b"interface geometry {\ntype Point { x: U32\ny: U32 }\n}\n",
                "wasm32-core",
            );
        let inventory = inventory_symbols(&collection);
        assert_eq!(
            inventory.coverage(),
            &sai_semantic::InventoryCoverage::Complete
        );
        let actual = inventory
            .symbols()
            .iter()
            .map(|symbol| (symbol.path(), symbol.kind()))
            .collect::<std::collections::BTreeSet<_>>();
        for expected in [
            (
                "acme:phase1.codec.Message",
                sai_semantic::SymbolKind::Record,
            ),
            (
                "acme:phase1.codec.Message.field[header]",
                sai_semantic::SymbolKind::Field,
            ),
            (
                "acme:phase1.codec.Message.field[payload]",
                sai_semantic::SymbolKind::Field,
            ),
            ("acme:phase1.codec.Empty", sai_semantic::SymbolKind::Record),
            (
                "acme:phase1/child.geometry",
                sai_semantic::SymbolKind::Interface,
            ),
            (
                "acme:phase1/child.geometry.Point",
                sai_semantic::SymbolKind::Record,
            ),
            (
                "acme:phase1/child.geometry.Point.field[x]",
                sai_semantic::SymbolKind::Field,
            ),
            (
                "acme:phase1/child.geometry.Point.field[y]",
                sai_semantic::SymbolKind::Field,
            ),
        ] {
            assert!(actual.contains(&expected), "missing symbol {expected:?}");
        }

        let file = module_tree.modules[0].file;
        let parsed = sai_syntax::parse(&snapshot, file).expect("record source parses");
        assert!(
            parsed.errors.is_empty(),
            "parse errors: {:?}",
            parsed.errors
        );
        let interface = parsed
            .root
            .descendants()
            .filter_map(ast::InterfaceDecl::cast)
            .find(|interface| {
                interface
                    .name()
                    .and_then(|name| name.token())
                    .is_some_and(|token| token.text() == "codec")
            })
            .expect("codec interface exists");
        let record = interface
            .items()
            .expect("interface item list exists")
            .syntax()
            .children()
            .filter_map(ast::TypeDecl::cast)
            .find(|declaration| {
                declaration
                    .name()
                    .and_then(|name| name.token())
                    .is_some_and(|token| token.text() == "Message")
            })
            .expect("Message record exists");
        let record_name_token = record
            .name()
            .and_then(|name| name.token())
            .expect("record name token exists");
        let interface_ast_id = database
            .ast_id_map(&snapshot, file)
            .expect("current AST ID map exists")
            .ast_id(&interface)
            .expect("interface AST ID exists")
            .erase();
        let interface_owner = collection
            .scopes()
            .top_level_owners
            .iter()
            .find(|owner| {
                owner.kind == TopLevelOwnerKind::Interface
                    && owner.file == file
                    && owner.item_id == interface_ast_id
            })
            .expect("interface has its exact Phase 1 owner");
        let def_paths = database
            .def_paths
            .get(&module_tree.package)
            .expect("package DefPath interner exists");
        let message = database
            .symbols
            .intern("Message")
            .expect("record name interns");
        let record_def_id = def_paths
            .intern_children(
                interface_owner.owner.def_id,
                &[(DefPathData::TypeNs(message), 0)],
            )
            .expect("record DefPath interns")
            .into_iter()
            .next()
            .expect("record DefPath ID exists");
        let record_def_path = database
            .resolve_def_path(record_def_id.to_def_id())
            .expect("record DefId is valid")
            .expect("record DefPath exists");
        let record_symbol = inventory
            .symbols()
            .iter()
            .find(|symbol| symbol.path() == "acme:phase1.codec.Message")
            .expect("record symbol exists");
        let expected_record_hash =
            sai_hir::DefPathHash::compute(&record_def_path, &database.packages, &database.symbols)
                .expect("record DefPath hash computes");
        assert_eq!(
            record_symbol.def_path_hash(),
            sai_stable_hash::Fingerprint::new(expected_record_hash.raw())
        );
        assert_eq!(
            record_symbol.fingerprint(),
            sai_semantic::declaration_fingerprint(
                sai_semantic::SymbolKind::Record,
                &record.syntax(),
                Some(&record_name_token),
            )
            .expect("record fingerprint uses its actual name token")
        );

        let fields = record
            .struct_def()
            .and_then(|definition| definition.fields())
            .expect("Message field list exists")
            .fields()
            .collect::<Vec<_>>();
        for (field, name) in fields.iter().zip(["header", "payload"]) {
            let field_name_token = field
                .name()
                .and_then(|name| name.token())
                .expect("field name token exists");
            let field_name = database.symbols.intern(name).expect("field name interns");
            let field_def_id = def_paths
                .intern_fields(record_def_id, &[(field_name, 0)])
                .expect("field DefPath interns")
                .into_iter()
                .next()
                .expect("field DefPath ID exists");
            let field_def_path = database
                .resolve_def_path(field_def_id.to_def_id())
                .expect("field DefId is valid")
                .expect("field DefPath exists");
            let expected_field_hash = sai_hir::DefPathHash::compute(
                &field_def_path,
                &database.packages,
                &database.symbols,
            )
            .expect("field DefPath hash computes");
            let field_symbol = inventory
                .symbols()
                .iter()
                .find(|symbol| symbol.path() == format!("acme:phase1.codec.Message.field[{name}]"))
                .expect("field symbol exists");
            assert_eq!(
                field_symbol.def_path_hash(),
                sai_stable_hash::Fingerprint::new(expected_field_hash.raw())
            );
            assert_eq!(
                field_symbol.fingerprint(),
                sai_semantic::declaration_fingerprint(
                    sai_semantic::SymbolKind::Field,
                    &field.syntax(),
                    Some(&field_name_token),
                )
                .expect("field fingerprint uses its actual name token")
            );
        }
    }

    #[test]
    fn module_interface_record_inventory_keeps_forbidden_generic_candidates_incomplete() {
        let (mut database, module_tree, snapshot, collection) =
            collect_package_inventory_for_target(
                b"interface api {\ntype Buffer<T, const N: I32> { value: T }\n}\n",
                b"",
                "wasm32-core",
            );
        let inventory = inventory_symbols(&collection);
        assert!(matches!(
            inventory.coverage(),
            sai_semantic::InventoryCoverage::Incomplete { reason }
                if reason.contains("GENERIC_INTERFACE_ITEM")
        ));
        for (path, kind) in [
            ("acme:phase1.api.Buffer", sai_semantic::SymbolKind::Record),
            (
                "acme:phase1.api.Buffer.generic[T]",
                sai_semantic::SymbolKind::GenericParam,
            ),
            (
                "acme:phase1.api.Buffer.generic[N]",
                sai_semantic::SymbolKind::GenericParam,
            ),
            (
                "acme:phase1.api.Buffer.field[value]",
                sai_semantic::SymbolKind::Field,
            ),
        ] {
            assert!(
                inventory
                    .symbols()
                    .iter()
                    .any(|symbol| symbol.path() == path && symbol.kind() == kind),
                "missing structurally valid forbidden candidate {path}"
            );
        }

        let file = module_tree.modules[0].file;
        let parsed = sai_syntax::parse(&snapshot, file).expect("generic record source parses");
        assert!(
            parsed.errors.is_empty(),
            "parse errors: {:?}",
            parsed.errors
        );
        let interface = parsed
            .root
            .descendants()
            .filter_map(ast::InterfaceDecl::cast)
            .next()
            .expect("interface exists");
        let record = interface
            .items()
            .expect("interface item list exists")
            .syntax()
            .children()
            .filter_map(ast::TypeDecl::cast)
            .next()
            .expect("Buffer record exists");
        let record_name = database
            .symbols
            .intern("Buffer")
            .expect("record name interns");
        let interface_ast_id = database
            .ast_id_map(&snapshot, file)
            .expect("current AST ID map exists")
            .ast_id(&interface)
            .expect("interface AST ID exists")
            .erase();
        let interface_owner = collection
            .scopes()
            .top_level_owners
            .iter()
            .find(|owner| {
                owner.kind == TopLevelOwnerKind::Interface
                    && owner.file == file
                    && owner.item_id == interface_ast_id
            })
            .expect("interface has its exact Phase 1 owner");
        let def_paths = database
            .def_paths
            .get(&module_tree.package)
            .expect("package DefPath interner exists");
        let record_def_id = def_paths
            .intern_children(
                interface_owner.owner.def_id,
                &[(DefPathData::TypeNs(record_name), 0)],
            )
            .expect("record DefPath interns")
            .into_iter()
            .next()
            .expect("record DefPath ID exists");
        let record_def_path = database
            .resolve_def_path(record_def_id.to_def_id())
            .expect("record DefId is valid")
            .expect("record DefPath exists");
        let record_symbol = inventory
            .symbols()
            .iter()
            .find(|symbol| symbol.path() == "acme:phase1.api.Buffer")
            .expect("record candidate exists");
        let expected_record_hash =
            sai_hir::DefPathHash::compute(&record_def_path, &database.packages, &database.symbols)
                .expect("record DefPath hash computes");
        assert_eq!(
            record_symbol.def_path_hash(),
            sai_stable_hash::Fingerprint::new(expected_record_hash.raw())
        );
        let generic_ids = def_paths
            .intern_generic_params(
                record_def_id,
                &[
                    (
                        database
                            .symbols
                            .intern("T")
                            .expect("type parameter interns"),
                        false,
                        0,
                    ),
                    (
                        database
                            .symbols
                            .intern("N")
                            .expect("const parameter interns"),
                        true,
                        0,
                    ),
                ],
            )
            .expect("generic parameter DefPaths intern");
        let generic_params = record
            .generic_params()
            .expect("generic parameter list exists")
            .params()
            .collect::<Vec<_>>();
        for (((parameter, path), def_id), expected_const) in generic_params
            .iter()
            .zip(["T", "N"])
            .zip(generic_ids)
            .zip([false, true])
        {
            let (name_token, is_const) = match parameter {
                ast::GenericParam::Type(parameter) => (
                    parameter
                        .name()
                        .and_then(|name| name.token())
                        .expect("name token exists"),
                    false,
                ),
                ast::GenericParam::Const(parameter) => (
                    parameter
                        .name()
                        .and_then(|name| name.token())
                        .expect("name token exists"),
                    true,
                ),
            };
            assert_eq!(is_const, expected_const);
            let generic_def_path = database
                .resolve_def_path(def_id.to_def_id())
                .expect("generic DefId is valid")
                .expect("generic DefPath exists");
            let expected_hash = sai_hir::DefPathHash::compute(
                &generic_def_path,
                &database.packages,
                &database.symbols,
            )
            .expect("generic DefPath hash computes");
            let path = format!("acme:phase1.api.Buffer.generic[{path}]");
            let generic_symbol = inventory
                .symbols()
                .iter()
                .find(|symbol| symbol.path() == path)
                .expect("generic parameter candidate exists");
            assert_eq!(
                generic_symbol.def_path_hash(),
                sai_stable_hash::Fingerprint::new(expected_hash.raw())
            );
            assert_eq!(
                generic_symbol.fingerprint(),
                sai_semantic::declaration_fingerprint(
                    sai_semantic::SymbolKind::GenericParam,
                    &parameter.syntax(),
                    Some(&name_token),
                )
                .expect("generic fingerprint uses its actual name token")
            );
        }
    }

    #[test]
    fn module_interface_record_inventory_uses_shared_type_namespace_source_order() {
        let cases: [(&str, &[u8], u32); 4] = [
            (
                "record then alias and resource",
                b"interface api {\ntype Shared { value: U32 }\ntype Shared = U32\nresource Shared {}\n}\n",
                0,
            ),
            (
                "resource then alias and record",
                b"interface api {\nresource Shared {}\ntype Shared = U32\ntype Shared { value: U32 }\n}\n",
                2,
            ),
            (
                "alias then resource and record",
                b"interface api {\ntype Shared = U32\nresource Shared {}\ntype Shared { value: U32 }\n}\n",
                2,
            ),
            (
                "enum and alias before record",
                b"interface api {\nenum Shared { Ready }\ntype Shared = U32\ntype Shared { value: U32 }\n}\n",
                2,
            ),
        ];
        for (case_name, source, expected_disambiguator) in cases {
            let (mut database, module_tree, snapshot, collection) =
                collect_package_inventory_for_target(source, b"", "wasm32-core");
            let inventory = inventory_symbols(&collection);
            assert!(
                matches!(
                    inventory.coverage(),
                    sai_semantic::InventoryCoverage::Incomplete { .. }
                ),
                "{case_name} contains unsupported or duplicate TypeNs members"
            );
            let record_symbol = inventory
                .symbols()
                .iter()
                .find(|symbol| {
                    symbol.path() == "acme:phase1.api.Shared"
                        && symbol.kind() == sai_semantic::SymbolKind::Record
                })
                .unwrap_or_else(|| panic!("{case_name} retains the record candidate"));
            let file = module_tree.modules[0].file;
            let parsed = sai_syntax::parse(&snapshot, file).expect("collision source parses");
            assert!(
                parsed.errors.is_empty(),
                "parse errors: {:?}",
                parsed.errors
            );
            let interface = parsed
                .root
                .descendants()
                .filter_map(ast::InterfaceDecl::cast)
                .next()
                .expect("interface exists");
            let interface_ast_id = database
                .ast_id_map(&snapshot, file)
                .expect("current AST ID map exists")
                .ast_id(&interface)
                .expect("interface AST ID exists")
                .erase();
            let interface_owner = collection
                .scopes()
                .top_level_owners
                .iter()
                .find(|owner| {
                    owner.kind == TopLevelOwnerKind::Interface
                        && owner.file == file
                        && owner.item_id == interface_ast_id
                })
                .expect("interface has its exact Phase 1 owner");
            let shared = database.symbols.intern("Shared").expect("name interns");
            let def_id = database
                .def_paths
                .get(&module_tree.package)
                .expect("package DefPath interner exists")
                .intern_children(
                    interface_owner.owner.def_id,
                    &[(DefPathData::TypeNs(shared), expected_disambiguator)],
                )
                .expect("record DefPath interns")
                .into_iter()
                .next()
                .expect("record DefPath ID exists");
            let def_path = database
                .resolve_def_path(def_id.to_def_id())
                .expect("record DefId is valid")
                .expect("record DefPath exists");
            assert!(matches!(
                def_path.data().last(),
                Some(component)
                    if component.data == DefPathData::TypeNs(shared)
                        && component.disambiguator == expected_disambiguator
            ));
            let expected_hash =
                sai_hir::DefPathHash::compute(&def_path, &database.packages, &database.symbols)
                    .expect("record DefPath hash computes");
            assert_eq!(
                record_symbol.def_path_hash(),
                sai_stable_hash::Fingerprint::new(expected_hash.raw()),
                "{case_name} counts every TypeNs sibling before the record"
            );
            if case_name == "enum and alias before record" {
                let enum_symbol = inventory
                    .symbols()
                    .iter()
                    .find(|symbol| {
                        symbol.path() == "acme:phase1.api.Shared"
                            && symbol.kind() == sai_semantic::SymbolKind::Enum
                    })
                    .expect("the supported enum sibling retains a candidate");
                let enum_name = database.symbols.intern("Shared").expect("name interns");
                let enum_def_id = database
                    .def_paths
                    .get(&module_tree.package)
                    .expect("package DefPath interner exists")
                    .intern_children(
                        interface_owner.owner.def_id,
                        &[(DefPathData::TypeNs(enum_name), 0)],
                    )
                    .expect("enum DefPath interns")
                    .into_iter()
                    .next()
                    .expect("enum DefPath ID exists");
                let enum_path = database
                    .resolve_def_path(enum_def_id.to_def_id())
                    .expect("enum DefId is valid")
                    .expect("enum DefPath exists");
                let expected_enum_hash = sai_hir::DefPathHash::compute(
                    &enum_path,
                    &database.packages,
                    &database.symbols,
                )
                .expect("enum DefPath hash computes");
                assert_eq!(
                    enum_symbol.def_path_hash(),
                    sai_stable_hash::Fingerprint::new(expected_enum_hash.raw()),
                    "the supported enum shares the TypeNs namespace with later siblings"
                );
            }
        }
    }

    #[test]
    fn module_interface_record_inventory_fails_closed_for_malformed_and_invalid_shapes() {
        let cases: [(&str, &[u8], &str); 4] = [
            (
                "malformed record field",
                b"interface api {\ntype Broken { value: }\n}\n",
                "Broken",
            ),
            (
                "record with an invalid attribute",
                b"interface api {\n@deprecated(1) type Invalid { value: U32 }\n}\n",
                "Invalid",
            ),
            (
                "record with an invalid target predicate",
                b"interface api {\n@target(\"wasm64-core\") type Filtered { value: U32 }\n}\n",
                "Filtered",
            ),
            (
                "refined alias remains outside the record inventory",
                b"interface api {\ntype Positive = U32 where self > 0\n}\n",
                "Positive",
            ),
        ];
        for (case_name, source, unsupported_name) in cases {
            let (_, _, _, collection) =
                collect_package_inventory_for_target(source, b"", "wasm32-core");
            let inventory = inventory_symbols(&collection);
            assert!(
                matches!(
                    inventory.coverage(),
                    sai_semantic::InventoryCoverage::Incomplete { .. }
                ),
                "{case_name} must not yield complete interface-record coverage"
            );
            assert!(
                inventory.symbols().iter().all(|symbol| {
                    symbol.path() != format!("acme:phase1.api.{unsupported_name}")
                        && !symbol
                            .path()
                            .starts_with(&format!("acme:phase1.api.{unsupported_name}."))
                }),
                "{case_name} must not leak a malformed or unsupported member candidate"
            );
        }
    }

    #[test]
    fn module_interface_enum_inventory_collects_root_nested_variants_and_tuple_fields() {
        let (mut database, module_tree, snapshot, collection) =
            collect_package_inventory_for_target(
                b"interface codec {\nenum State { Ready, Busy(U32) }\n}\n",
                b"interface geometry {\nenum Direction { North, South }\n}\n",
                "wasm32-core",
            );
        let inventory = inventory_symbols(&collection);
        assert_eq!(
            inventory.coverage(),
            &sai_semantic::InventoryCoverage::Complete
        );
        let actual = inventory
            .symbols()
            .iter()
            .map(|symbol| (symbol.path(), symbol.kind()))
            .collect::<std::collections::BTreeSet<_>>();
        for expected in [
            ("acme:phase1.codec", sai_semantic::SymbolKind::Interface),
            ("acme:phase1.codec.State", sai_semantic::SymbolKind::Enum),
            (
                "acme:phase1.codec.State.Ready",
                sai_semantic::SymbolKind::Variant,
            ),
            (
                "acme:phase1.codec.State.Busy",
                sai_semantic::SymbolKind::Variant,
            ),
            (
                "acme:phase1.codec.State.Busy.field[0]",
                sai_semantic::SymbolKind::Field,
            ),
            (
                "acme:phase1/child.geometry",
                sai_semantic::SymbolKind::Interface,
            ),
            (
                "acme:phase1/child.geometry.Direction",
                sai_semantic::SymbolKind::Enum,
            ),
            (
                "acme:phase1/child.geometry.Direction.North",
                sai_semantic::SymbolKind::Variant,
            ),
            (
                "acme:phase1/child.geometry.Direction.South",
                sai_semantic::SymbolKind::Variant,
            ),
        ] {
            assert!(actual.contains(&expected), "missing symbol {expected:?}");
        }

        for (module_index, interface_name, enum_name, expected_module, expected_enum_path) in [
            (0, "codec", "State", None, "acme:phase1.codec.State"),
            (
                1,
                "geometry",
                "Direction",
                Some("child"),
                "acme:phase1/child.geometry.Direction",
            ),
        ] {
            let file = module_tree.modules[module_index].file;
            let parsed = sai_syntax::parse(&snapshot, file).expect("interface source parses");
            assert!(
                parsed.errors.is_empty(),
                "parse errors: {:?}",
                parsed.errors
            );
            let interface = parsed
                .root
                .descendants()
                .filter_map(ast::InterfaceDecl::cast)
                .find(|interface| {
                    interface
                        .name()
                        .and_then(|name| name.token())
                        .is_some_and(|token| token.text() == interface_name)
                })
                .expect("the interface AST exists");
            let enum_declaration = interface
                .items()
                .expect("the interface has an item list")
                .syntax()
                .children()
                .filter_map(ast::EnumDecl::cast)
                .find(|declaration| {
                    declaration
                        .name()
                        .and_then(|name| name.token())
                        .is_some_and(|token| token.text() == enum_name)
                })
                .expect("the interface enum AST exists");
            let interface_ast_id = database
                .ast_id_map(&snapshot, file)
                .expect("the current AST ID map exists")
                .ast_id(&interface)
                .expect("the interface AST ID exists")
                .erase();
            let def_paths = database
                .def_paths
                .get(&module_tree.package)
                .expect("the package has a DefPath interner");
            let interface_owner = collection
                .scopes()
                .top_level_owners
                .iter()
                .find(|owner| {
                    owner.kind == TopLevelOwnerKind::Interface
                        && owner.file == file
                        && owner.item_id == interface_ast_id
                })
                .expect("the exact interface owner exists");
            let interface_def_path = database
                .resolve_def_path(interface_owner.owner.def_id.to_def_id())
                .expect("interface DefId is valid")
                .expect("interface DefPath exists");
            assert_eq!(interface_def_path.package(), module_tree.package);
            if let Some(expected_module) = expected_module {
                assert!(matches!(
                    interface_def_path.data().first(),
                    Some(component)
                        if component.data == DefPathData::Module(
                            database.symbols.intern(expected_module).expect("module name interns")
                        ) && component.disambiguator == 0
                ));
            } else {
                assert_eq!(interface_def_path.data().len(), 1);
            }
            assert!(matches!(
                interface_def_path.data().last(),
                Some(component)
                    if component.data == DefPathData::Interface(
                        database.symbols.intern(interface_name).expect("interface name interns")
                    ) && component.disambiguator == 0
            ));

            let enum_name_symbol = database
                .symbols
                .intern(enum_name)
                .expect("enum name interns");
            let enum_def_id = def_paths
                .intern_children(
                    interface_owner.owner.def_id,
                    &[(DefPathData::TypeNs(enum_name_symbol), 0)],
                )
                .expect("interface enum DefPath interns")[0];
            let enum_def_path = database
                .resolve_def_path(enum_def_id.to_def_id())
                .expect("enum DefId is valid")
                .expect("enum DefPath exists");
            assert_eq!(enum_def_path.package(), module_tree.package);
            assert_eq!(
                &enum_def_path.data()[..interface_def_path.data().len()],
                interface_def_path.data()
            );
            let enum_hash = sai_hir::DefPathHash::compute(
                &enum_def_path,
                &database.packages,
                &database.symbols,
            )
            .expect("enum DefPath hash computes");
            let enum_symbol = inventory
                .symbols()
                .iter()
                .find(|symbol| symbol.path() == expected_enum_path)
                .expect("enum inventory symbol exists");
            assert_eq!(
                enum_symbol.def_path_hash(),
                sai_stable_hash::Fingerprint::new(enum_hash.raw())
            );
            let enum_name_token = enum_declaration
                .name()
                .and_then(|name| name.token())
                .expect("enum has its own name token");
            assert_eq!(
                enum_symbol.fingerprint(),
                sai_semantic::declaration_fingerprint(
                    sai_semantic::SymbolKind::Enum,
                    &enum_declaration.syntax(),
                    Some(&enum_name_token),
                )
                .expect("enum fingerprint is defined")
            );

            let variants = enum_declaration
                .variants()
                .expect("enum has a variant list")
                .variants()
                .collect::<Vec<_>>();
            let variant_id_paths = variants
                .iter()
                .map(|variant| {
                    let name = variant
                        .name()
                        .and_then(|name| name.token())
                        .expect("variant has a name token")
                        .text()
                        .to_owned();
                    (
                        database
                            .symbols
                            .intern(&name)
                            .expect("variant name interns"),
                        variant,
                        name,
                    )
                })
                .collect::<Vec<_>>();
            let variant_ids = def_paths
                .intern_variants(
                    enum_def_id,
                    &variant_id_paths
                        .iter()
                        .map(|(name, _, _)| (*name, 0))
                        .collect::<Vec<_>>(),
                )
                .expect("interface enum variant DefPaths intern");
            for ((variant_def_id, (_, variant, variant_name)), expected_suffix) in variant_ids
                .iter()
                .zip(&variant_id_paths)
                .zip(if enum_name == "State" {
                    vec!["Ready", "Busy"]
                } else {
                    vec!["North", "South"]
                })
            {
                let variant_def_path = database
                    .resolve_def_path(variant_def_id.to_def_id())
                    .expect("variant DefId is valid")
                    .expect("variant DefPath exists");
                assert_eq!(
                    &variant_def_path.data()[..enum_def_path.data().len()],
                    enum_def_path.data()
                );
                let expected_path = format!("{expected_enum_path}.{expected_suffix}");
                let variant_symbol = inventory
                    .symbols()
                    .iter()
                    .find(|symbol| symbol.path() == expected_path)
                    .expect("variant inventory symbol exists");
                let variant_hash = sai_hir::DefPathHash::compute(
                    &variant_def_path,
                    &database.packages,
                    &database.symbols,
                )
                .expect("variant DefPath hash computes");
                assert_eq!(
                    variant_symbol.def_path_hash(),
                    sai_stable_hash::Fingerprint::new(variant_hash.raw())
                );
                let variant_name_token = variant
                    .name()
                    .and_then(|name| name.token())
                    .expect("variant has its own name token");
                assert_eq!(
                    variant_symbol.fingerprint(),
                    sai_semantic::declaration_fingerprint(
                        sai_semantic::SymbolKind::Variant,
                        &variant.syntax(),
                        Some(&variant_name_token),
                    )
                    .expect("variant fingerprint is defined")
                );
                assert_eq!(variant_name.as_str(), expected_suffix);
            }

            if enum_name == "State" {
                let busy_id = variant_ids[1];
                let tuple_type = variants[1]
                    .tuple_shape()
                    .expect("Busy has a tuple payload")
                    .types()
                    .next()
                    .expect("Busy has its first payload type");
                let tuple_index = database.symbols.intern("0").expect("tuple index interns");
                let tuple_field_id = def_paths
                    .intern_fields_for_parents(&[(busy_id, tuple_index, 0)])
                    .expect("tuple payload DefPath interns")[0];
                let tuple_field_path = database
                    .resolve_def_path(tuple_field_id.to_def_id())
                    .expect("tuple payload DefId is valid")
                    .expect("tuple payload DefPath exists");
                let tuple_hash = sai_hir::DefPathHash::compute(
                    &tuple_field_path,
                    &database.packages,
                    &database.symbols,
                )
                .expect("tuple payload DefPath hash computes");
                let tuple_field_symbol = inventory
                    .symbols()
                    .iter()
                    .find(|symbol| symbol.path() == "acme:phase1.codec.State.Busy.field[0]")
                    .expect("tuple payload field symbol exists");
                assert_eq!(
                    tuple_field_symbol.def_path_hash(),
                    sai_stable_hash::Fingerprint::new(tuple_hash.raw())
                );
                assert_eq!(
                    tuple_field_symbol.fingerprint(),
                    sai_semantic::declaration_fingerprint(
                        sai_semantic::SymbolKind::Field,
                        &tuple_type.syntax(),
                        None,
                    )
                    .expect("tuple payload fingerprint is defined")
                );
            }
        }
    }

    #[test]
    fn module_interface_enum_inventory_uses_shared_type_namespace_order() {
        let (mut database, module_tree, snapshot, collection) = collect_package_inventory_for_target(
            b"interface api {\ntype Shared = U32\nresource Shared {}\nenum Shared { Same, Same }\n}\n",
            b"",
            "wasm32-core",
        );
        let inventory = inventory_symbols(&collection);
        assert!(matches!(
            inventory.coverage(),
            sai_semantic::InventoryCoverage::Incomplete { .. }
        ));
        let enum_symbol = inventory
            .symbols()
            .iter()
            .find(|symbol| {
                symbol.path() == "acme:phase1.api.Shared"
                    && symbol.kind() == sai_semantic::SymbolKind::Enum
            })
            .expect("the enum candidate is retained");
        let file = module_tree.modules[0].file;
        let interface_ast_id = database
            .ast_id_map(&snapshot, file)
            .expect("current AST ID map exists")
            .ast_id(
                &sai_syntax::parse(&snapshot, file)
                    .expect("interface parses")
                    .root
                    .descendants()
                    .find_map(ast::InterfaceDecl::cast)
                    .expect("interface exists"),
            )
            .expect("interface AST ID exists")
            .erase();
        let interface_owner = collection
            .scopes()
            .top_level_owners
            .iter()
            .find(|owner| {
                owner.kind == TopLevelOwnerKind::Interface
                    && owner.file == file
                    && owner.item_id == interface_ast_id
            })
            .expect("exact interface owner exists");
        let shared = database.symbols.intern("Shared").expect("Shared interns");
        let enum_def_id = database
            .def_paths
            .get(&module_tree.package)
            .expect("package DefPath interner exists")
            .intern_children(
                interface_owner.owner.def_id,
                &[(DefPathData::TypeNs(shared), 2)],
            )
            .expect("the enum's third TypeNs DefPath interns")[0];
        let enum_def_path = database
            .resolve_def_path(enum_def_id.to_def_id())
            .expect("enum DefId is valid")
            .expect("enum DefPath exists");
        assert!(matches!(
            enum_def_path.data().last(),
            Some(component)
                if component.data == DefPathData::TypeNs(shared)
                    && component.disambiguator == 2
        ));
        let expected_hash =
            sai_hir::DefPathHash::compute(&enum_def_path, &database.packages, &database.symbols)
                .expect("enum DefPath hash computes");
        assert_eq!(
            enum_symbol.def_path_hash(),
            sai_stable_hash::Fingerprint::new(expected_hash.raw())
        );
        let duplicate_variants = inventory
            .symbols()
            .iter()
            .filter(|symbol| {
                symbol.path() == "acme:phase1.api.Shared.Same"
                    && symbol.kind() == sai_semantic::SymbolKind::Variant
            })
            .collect::<Vec<_>>();
        assert_eq!(duplicate_variants.len(), 2);
        assert_ne!(
            duplicate_variants[0].def_path_hash(),
            duplicate_variants[1].def_path_hash()
        );
    }

    #[test]
    fn module_interface_enum_inventory_keeps_invalid_semantic_candidates_incomplete() {
        for (source, expected_reason, expected_paths) in [
            (
                &b"interface api {\nenum Generic<T> { Item(T) }\n}\n"[..],
                "GENERIC_INTERFACE_ITEM",
                vec![
                    ("acme:phase1.api.Generic", sai_semantic::SymbolKind::Enum),
                    (
                        "acme:phase1.api.Generic.generic[T]",
                        sai_semantic::SymbolKind::GenericParam,
                    ),
                    (
                        "acme:phase1.api.Generic.Item",
                        sai_semantic::SymbolKind::Variant,
                    ),
                    (
                        "acme:phase1.api.Generic.Item.field[0]",
                        sai_semantic::SymbolKind::Field,
                    ),
                ],
            ),
            (
                &b"interface api {\nenum Empty {}\n}\n"[..],
                "WIT_EMPTY_TYPE",
                vec![("acme:phase1.api.Empty", sai_semantic::SymbolKind::Enum)],
            ),
            (
                &b"interface api {\n@derive(Clone) enum Derived { Item }\n}\n"[..],
                "attribute-validation error",
                vec![],
            ),
            (
                &b"interface api {\n@flags enum Bits { Read, Write }\n}\n"[..],
                "attribute-validation error",
                vec![],
            ),
            (
                &b"interface api {\nenum Invalid { Item(U32, U64) }\n}\n"[..],
                "WIT_INCOMPATIBLE_TYPE",
                vec![
                    ("acme:phase1.api.Invalid", sai_semantic::SymbolKind::Enum),
                    (
                        "acme:phase1.api.Invalid.Item",
                        sai_semantic::SymbolKind::Variant,
                    ),
                    (
                        "acme:phase1.api.Invalid.Item.field[0]",
                        sai_semantic::SymbolKind::Field,
                    ),
                    (
                        "acme:phase1.api.Invalid.Item.field[1]",
                        sai_semantic::SymbolKind::Field,
                    ),
                ],
            ),
        ] {
            let (_, _, _, collection) =
                collect_package_inventory_for_target(source, b"", "wasm32-core");
            let inventory = inventory_symbols(&collection);
            assert!(
                matches!(
                    inventory.coverage(),
                    sai_semantic::InventoryCoverage::Incomplete { reason }
                        if reason.contains(expected_reason)
                ),
                "{source:?}: {:#?}",
                inventory.coverage()
            );
            for (path, kind) in expected_paths {
                assert!(
                    inventory
                        .symbols()
                        .iter()
                        .any(|symbol| symbol.path() == path && symbol.kind() == kind),
                    "{source:?} should retain structurally valid candidate {path}"
                );
            }
        }
    }

    #[test]
    fn module_local_flags_inventory_collects_consts_with_real_variant_identity() {
        let collect = |source: &[u8]| {
            let (_, _, _, collection) =
                collect_package_inventory_with_accepted_flags_for_test(source);
            collection
        };
        let original = collect(b"interface api {\n@flags enum Permissions { Read, Write }\n}\n");
        let relocated = collect(b"// shift the flag declarations' source spans\ninterface api {\n@flags enum Permissions { Read, Write }\n}\n");
        assert_ne!(
            original.interface_uses_fingerprint(),
            relocated.interface_uses_fingerprint(),
            "the public fingerprint covers source spans exposed by FlagsDef"
        );
        let original_inventory = inventory_symbols(&original);
        let original_read = original_inventory
            .symbols()
            .iter()
            .find(|symbol| symbol.path() == "acme:phase1.api.Permissions.Read")
            .expect("the accepted flags case is inventoried");
        assert_eq!(original_read.kind(), sai_semantic::SymbolKind::Const);
        assert!(original_inventory.symbols().iter().any(|symbol| {
            symbol.path() == "acme:phase1.api.Permissions.Write"
                && symbol.kind() == sai_semantic::SymbolKind::Const
        }));
        assert!(
            original_inventory.symbols().iter().all(|symbol| {
                !(symbol.path() == "acme:phase1.api.Permissions.Read"
                    && symbol.kind() == sai_semantic::SymbolKind::Variant)
            }),
            "accepted flags cases must not also be emitted as variants"
        );
        assert!(matches!(
            original_inventory.coverage(),
            sai_semantic::InventoryCoverage::Incomplete { reason }
                if reason.contains("synthetic associated functions")
        ));

        let renamed = collect(b"interface api {\n@flags enum Permissions { Inspect, Write }\n}\n");
        let renamed_inspect = inventory_symbols(&renamed)
            .symbols()
            .iter()
            .find(|symbol| symbol.path() == "acme:phase1.api.Permissions.Inspect")
            .expect("the renamed flags case is inventoried");
        assert_ne!(
            original_read.def_path_hash(),
            renamed_inspect.def_path_hash()
        );
        assert_eq!(original_read.fingerprint(), renamed_inspect.fingerprint());

        let reordered = collect(b"interface api {\n@flags enum Permissions { Write, Read }\n}\n");
        let reordered_read = inventory_symbols(&reordered)
            .symbols()
            .iter()
            .find(|symbol| symbol.path() == "acme:phase1.api.Permissions.Read")
            .expect("the reordered flags case is inventoried");
        assert_eq!(
            original_read.def_path_hash(),
            reordered_read.def_path_hash()
        );
        assert_ne!(original_read.fingerprint(), reordered_read.fingerprint());
    }

    #[test]
    fn module_local_flags_inventory_falls_back_to_enum_candidates_for_invalid_shapes() {
        let too_many_cases = (0..33)
            .map(|index| format!("Flag{index}"))
            .collect::<Vec<_>>()
            .join(", ");
        let too_many_source =
            format!("interface api {{\n@flags enum TooMany {{ {too_many_cases} }}\n}}\n");
        for (source, enum_name, expected_case, expected_reason) in [
            (
                &b"interface api {\n@flags enum Empty {}\n}\n"[..],
                "Empty",
                None,
                "WIT_EMPTY_TYPE",
            ),
            (
                &b"interface api {\n@flags enum Payload { Item(U32) }\n}\n"[..],
                "Payload",
                Some("Item"),
                "INVALID_FLAGS_ENUM",
            ),
            (
                &b"interface api {\n@flags enum Discriminant { Read = 1, Write }\n}\n"[..],
                "Discriminant",
                Some("Read"),
                "INVALID_FLAGS_ENUM",
            ),
            (
                too_many_source.as_bytes(),
                "TooMany",
                Some("Flag0"),
                "INVALID_FLAGS_ENUM",
            ),
            (
                &b"interface api {\n@flags enum Duplicate { Same, Same }\n}\n"[..],
                "Duplicate",
                Some("Same"),
                "duplicate variant name",
            ),
        ] {
            let (_, _, _, collection) =
                collect_package_inventory_with_accepted_flags_for_test(source);
            let inventory = inventory_symbols(&collection);
            let enum_path = format!("acme:phase1.api.{enum_name}");
            assert!(inventory.symbols().iter().any(|symbol| {
                symbol.path() == enum_path && symbol.kind() == sai_semantic::SymbolKind::Enum
            }));
            assert!(
                matches!(
                    inventory.coverage(),
                    sai_semantic::InventoryCoverage::Incomplete { reason }
                        if reason.contains(expected_reason)
                ),
                "{source:?}: {:#?}",
                inventory.coverage()
            );
            assert!(
                inventory.symbols().iter().all(|symbol| {
                    !(symbol.path().starts_with(&format!("{enum_path}."))
                        && symbol.kind() == sai_semantic::SymbolKind::Const)
                }),
                "{source:?} must not emit a flags constant"
            );
            if let Some(case_name) = expected_case {
                let case_path = format!("{enum_path}.{case_name}");
                assert!(
                    inventory.symbols().iter().any(|symbol| {
                        symbol.path() == case_path
                            && symbol.kind() == sai_semantic::SymbolKind::Variant
                    }),
                    "{source:?} must retain its ordinary enum variant"
                );
            }
            if enum_name == "Discriminant" {
                assert!(matches!(
                    inventory.coverage(),
                    sai_semantic::InventoryCoverage::Incomplete { reason }
                        if !reason.contains("WIT_EXPLICIT_DISCRIMINANT")
                ));
            }
        }
    }

    #[test]
    fn phase1_collection_exposes_flags_only_adt_with_owned_synthetic_def_paths() {
        let source = b"interface api {\n@flags enum Permissions { Read, Write }\n}\n";
        let (mut database, module_tree, snapshot, collection) =
            collect_package_inventory_with_accepted_flags_for_test(source);
        let permissions = database
            .symbols
            .intern("Permissions")
            .expect("flags item name interns");
        let owner = collection
            .scopes()
            .interfaces
            .values()
            .find_map(|scope| {
                scope
                    .members
                    .get(&permissions)
                    .and_then(|binding| match binding.res {
                        sai_resolve::package_scopes::Res::Def(
                            sai_resolve::package_scopes::DefKind::Enum,
                            owner,
                        ) => Some(owner),
                        _ => None,
                    })
            })
            .expect("the flags declaration keeps its enum source owner");
        let flags = collection
            .local_flags_adt_def(&snapshot, owner)
            .expect("the accessor accepts its creating snapshot")
            .expect("the valid local flags declaration has an ADT projection");
        let adt = flags.adt_def();
        assert_eq!(adt.def_id(), owner);
        assert_eq!(adt.kind(), sai_ty::adt::AdtKind::Flags);
        assert_eq!(adt.variants().len(), 1);

        let variant = &adt.variants()[0];
        assert_eq!(variant.name(), database.symbols.intern("$flags").unwrap());
        assert_eq!(variant.discr(), 0);
        assert_eq!(variant.fields().len(), 1);
        let field = &variant.fields()[0];
        assert_eq!(field.name(), database.symbols.intern("$bits").unwrap());
        assert_eq!(field.visibility(), Visibility::Private);
        assert_eq!(field.ty(), sai_ty::adt::Ty::Int(sai_ty::adt::IntTy::U8));

        let owner_path = database
            .resolve_def_path(owner)
            .expect("flags owner path resolves")
            .expect("flags owner path exists");
        let variant_path = database
            .resolve_def_path(variant.def_id())
            .expect("synthetic variant path resolves")
            .expect("synthetic variant path exists");
        let field_path = database
            .resolve_def_path(field.def_id())
            .expect("synthetic field path resolves")
            .expect("synthetic field path exists");
        assert_eq!(variant.def_id().package, owner.package);
        assert_eq!(field.def_id().package, owner.package);
        assert_ne!(variant.def_id(), owner);
        assert_ne!(field.def_id(), owner);
        assert_ne!(variant.def_id(), field.def_id());
        assert_eq!(variant_path.package(), owner.package);
        assert_eq!(field_path.package(), owner.package);
        assert_eq!(
            &variant_path.data()[..owner_path.data().len()],
            owner_path.data()
        );
        assert!(matches!(
            variant_path.data().last(),
            Some(sai_hir::DisambiguatedDefPathData {
                data: sai_hir::DefPathData::Variant(name),
                disambiguator: 0,
            }) if database.symbols.resolve(*name).is_ok_and(|name| name.as_ref() == "$flags")
        ));
        assert_eq!(
            &field_path.data()[..variant_path.data().len()],
            variant_path.data()
        );
        assert!(matches!(
            field_path.data().last(),
            Some(sai_hir::DisambiguatedDefPathData {
                data: sai_hir::DefPathData::Field(name),
                disambiguator: 0,
            }) if database.symbols.resolve(*name).is_ok_and(|name| name.as_ref() == "$bits")
        ));
        assert_eq!(
            flags
                .flags_def()
                .flags()
                .iter()
                .map(|(name, _)| database.symbols.resolve(*name).unwrap().to_string())
                .collect::<Vec<_>>(),
            ["Read", "Write"]
        );

        let target = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let repeated = database
            .collect_phase1_package_scopes_with_accepted_flags_for_test(
                &module_tree,
                &snapshot,
                &target,
                Phase1BuildContext::default(),
            )
            .expect("repeat collection succeeds");
        assert_eq!(
            repeated
                .local_flags_adt_def(&snapshot, owner)
                .expect("repeat collection remains snapshot-bound"),
            Some(flags),
            "the source interner retains the same real child identities"
        );
        assert_eq!(
            repeated.interface_uses_fingerprint(),
            collection.interface_uses_fingerprint(),
            "the tracked package projection has a stable semantic fingerprint"
        );
    }

    #[test]
    fn phase1_flags_adt_projection_rejects_stale_snapshots_and_keeps_fallback_enums() {
        let source = concat!(
            "interface api {\n",
            "@flags enum Good { Read, Write }\n",
            "@flags enum Empty {}\n",
            "@flags enum Payload { Item(U32) }\n",
            "@flags enum Explicit { Read = 1, Write }\n",
            "}\n",
        );
        let (database, _, snapshot, collection) =
            collect_package_inventory_with_accepted_flags_for_test(source.as_bytes());
        let owner_named = |wanted: &str| {
            collection
                .scopes()
                .interfaces
                .values()
                .find_map(|scope| {
                    scope.members.iter().find_map(|(name, binding)| {
                        (database
                            .symbols
                            .resolve(*name)
                            .is_ok_and(|name| name.as_ref() == wanted))
                        .then_some(binding.res)
                    })
                })
                .and_then(|res| match res {
                    sai_resolve::package_scopes::Res::Def(
                        sai_resolve::package_scopes::DefKind::Enum,
                        owner,
                    ) => Some(owner),
                    _ => None,
                })
                .unwrap_or_else(|| panic!("source enum `{wanted}` remains in interface scope"))
        };
        let good = owner_named("Good");
        let good_flags = collection
            .local_flags_adt_def(&snapshot, good)
            .expect("fresh snapshot is accepted")
            .expect("valid flags declaration is represented");
        assert_eq!(good_flags.adt_def().kind(), sai_ty::adt::AdtKind::Flags);
        for name in ["Empty", "Payload", "Explicit"] {
            let enum_owner = owner_named(name);
            assert!(
                collection
                    .local_flags_adt_def(&snapshot, enum_owner)
                    .expect("fresh snapshot is accepted")
                    .is_none(),
                "invalid or empty `{name}` remains outside the flags-only projection"
            );
        }
        let stale_snapshot = snapshot_with_version(&snapshot, 77);
        assert_eq!(
            collection.local_flags_adt_def(&stale_snapshot, good),
            Err(Phase1CollectionError::SnapshotIdentityMismatch)
        );
        let diagnostics = collection.interface_check_diagnostics();
        assert!(
            diagnostics
                .iter()
                .any(|diagnostic| { diagnostic.code == sai_diagnostics::Code::WitEmptyType })
        );
        assert!(
            diagnostics
                .iter()
                .filter(|diagnostic| { diagnostic.code == sai_diagnostics::Code::InvalidFlagsEnum })
                .count()
                >= 2,
            "payload and explicit-discriminant markers fail flags validation"
        );
    }

    #[test]
    fn phase1_local_interface_enum_projection_covers_unit_flags_and_unsupported_forms() {
        let source = concat!(
            "interface api {\n",
            "enum State { Ready, Waiting, Done }\n",
            "@flags enum Permissions { Read, Write }\n",
            "@flags enum Empty {}\n",
            "@flags enum Explicit { Read = 1, Write }\n",
            "enum Generic<T> { Item }\n",
            "enum Payload { Item(U32) }\n",
            "@repr(U8) enum Repr { Ready }\n",
            "enum Bounds { Minimum = -9223372036854775808, Maximum = 9223372036854775807 }\n",
            "enum TooWide { Value = 9223372036854775808 }\n",
            "enum RepeatedDiscriminant { First = 5, Second = 5 }\n",
            "type Record { value: U32 }\n",
            "}\n",
        );
        let (database, _, snapshot, collection) =
            collect_package_inventory_with_accepted_flags_for_test(source.as_bytes());
        let owner_named = |wanted: &str| {
            collection
                .scopes()
                .interfaces
                .values()
                .find_map(|scope| {
                    scope.members.iter().find_map(|(name, binding)| {
                        (database
                            .symbols
                            .resolve(*name)
                            .is_ok_and(|name| name.as_ref() == wanted))
                        .then_some(binding.res)
                    })
                })
                .and_then(|res| match res {
                    sai_resolve::package_scopes::Res::Def(
                        sai_resolve::package_scopes::DefKind::Enum,
                        owner,
                    ) => Some(owner),
                    _ => None,
                })
                .unwrap_or_else(|| panic!("source enum `{wanted}` remains in interface scope"))
        };
        let projection_for = |name: &str| {
            let owner = owner_named(name);
            let projection = collection
                .local_interface_enum_adt_projection(&snapshot, owner)
                .expect("fresh snapshot is accepted")
                .unwrap_or_else(|| panic!("interface enum `{name}` has a projection outcome"));
            (owner, projection)
        };

        let (state_owner, state_projection) = projection_for("State");
        let LocalInterfaceEnumAdtProjection::Unit(state) = state_projection else {
            panic!("ordinary unit enum projects as Unit");
        };
        let state_adt = state.adt_def();
        assert_eq!(state_adt.def_id(), state_owner);
        assert_eq!(state_adt.kind(), sai_ty::adt::AdtKind::Enum);
        assert_eq!(state_adt.discr_ty(), sai_ty::adt::IntTy::I64);
        assert_eq!(
            state_adt
                .variants()
                .iter()
                .map(|variant| (
                    database
                        .symbols
                        .resolve(variant.name())
                        .unwrap()
                        .to_string(),
                    variant.discr(),
                    variant.fields().len(),
                ))
                .collect::<Vec<_>>(),
            [
                ("Ready".to_owned(), 0, 0),
                ("Waiting".to_owned(), 1, 0),
                ("Done".to_owned(), 2, 0),
            ]
        );
        let owner_path = database
            .resolve_def_path(state_owner)
            .expect("enum owner path resolves")
            .expect("enum owner path exists");
        for variant in state_adt.variants() {
            assert_eq!(variant.def_id().package, state_owner.package);
            assert_ne!(variant.def_id(), state_owner);
            let path = database
                .resolve_def_path(variant.def_id())
                .expect("variant path resolves")
                .expect("variant path exists");
            assert_eq!(path.package(), owner_path.package());
            assert_eq!(&path.data()[..owner_path.data().len()], owner_path.data());
            assert!(matches!(
                path.data().last(),
                Some(sai_hir::DisambiguatedDefPathData {
                    data: sai_hir::DefPathData::Variant(name),
                    disambiguator: 0,
                }) if *name == variant.name()
            ));
        }

        let (permissions_owner, permissions_projection) = projection_for("Permissions");
        assert_eq!(
            permissions_projection,
            &LocalInterfaceEnumAdtProjection::Flags {
                owner: permissions_owner
            }
        );
        assert!(
            collection
                .local_flags_adt_def(&snapshot, permissions_owner)
                .expect("fresh snapshot is accepted")
                .is_some()
        );

        let (empty_owner, empty_projection) = projection_for("Empty");
        let LocalInterfaceEnumAdtProjection::Unit(empty) = empty_projection else {
            panic!("empty flags fallback remains an ordinary empty enum");
        };
        assert_eq!(empty.adt_def().def_id(), empty_owner);
        assert!(empty.adt_def().variants().is_empty());
        assert!(
            collection
                .local_flags_adt_def(&snapshot, empty_owner)
                .expect("fresh snapshot is accepted")
                .is_none()
        );

        let (explicit_owner, explicit_projection) = projection_for("Explicit");
        let LocalInterfaceEnumAdtProjection::Unit(explicit) = explicit_projection else {
            panic!("invalid flags fallback remains an ordinary enum");
        };
        assert_eq!(
            explicit
                .adt_def()
                .variants()
                .iter()
                .map(|variant| variant.discr())
                .collect::<Vec<_>>(),
            [1, 2]
        );
        assert!(
            collection
                .local_flags_adt_def(&snapshot, explicit_owner)
                .expect("fresh snapshot is accepted")
                .is_none()
        );

        for (name, expected_reason) in [
            (
                "Generic",
                sai_ty::adt::LocalEnumAdtUnsupportedReason::GenericParameters,
            ),
            (
                "Payload",
                sai_ty::adt::LocalEnumAdtUnsupportedReason::Payload,
            ),
            (
                "Repr",
                sai_ty::adt::LocalEnumAdtUnsupportedReason::UnvalidatedRepresentation,
            ),
            (
                "TooWide",
                sai_ty::adt::LocalEnumAdtUnsupportedReason::DiscriminantOutOfRange,
            ),
            (
                "RepeatedDiscriminant",
                sai_ty::adt::LocalEnumAdtUnsupportedReason::DuplicateDiscriminant,
            ),
        ] {
            let (owner, projection) = projection_for(name);
            assert_eq!(
                projection,
                &LocalInterfaceEnumAdtProjection::Unsupported {
                    owner,
                    reason: expected_reason,
                },
                "unsupported enum `{name}` is distinguished from a missing ADT result"
            );
        }

        let (_, bounds_projection) = projection_for("Bounds");
        let LocalInterfaceEnumAdtProjection::Unit(bounds) = bounds_projection else {
            panic!("I64 boundary discriminants remain representable");
        };
        assert_eq!(
            bounds
                .adt_def()
                .variants()
                .iter()
                .map(|variant| variant.discr())
                .collect::<Vec<_>>(),
            [i64::MIN as i128, i64::MAX as i128]
        );

        let record_owner = collection
            .scopes()
            .interfaces
            .values()
            .find_map(|scope| {
                scope.members.iter().find_map(|(name, binding)| {
                    (database
                        .symbols
                        .resolve(*name)
                        .is_ok_and(|name| name.as_ref() == "Record"))
                    .then_some(binding.res)
                })
            })
            .and_then(|res| match res {
                sai_resolve::package_scopes::Res::Def(
                    sai_resolve::package_scopes::DefKind::Struct,
                    owner,
                ) => Some(owner),
                _ => None,
            })
            .expect("record owner remains in interface scope");
        assert!(
            collection
                .local_interface_enum_adt_projection(&snapshot, record_owner)
                .expect("fresh snapshot is accepted")
                .is_none(),
            "None means no local interface enum projection, not non-ADT"
        );
        let stale_snapshot = snapshot_with_version(&snapshot, 88);
        assert_eq!(
            collection.local_interface_enum_adt_projection(&stale_snapshot, state_owner),
            Err(Phase1CollectionError::SnapshotIdentityMismatch)
        );
    }

    #[test]
    fn phase1_does_not_project_unaccepted_valid_raw_flags_as_a_unit_enum() {
        let source = concat!(
            "interface api {\n",
            "@flags enum Gated { Read, Write }\n",
            "@flags(1) enum InvalidAttribute { Read, Write }\n",
            "@flags enum Empty {}\n",
            "@flags enum InvalidFlags { Read = 1, Write }\n",
            "}\n",
        );
        let (database, _, snapshot, collection) =
            collect_package_inventory_for_target(source.as_bytes(), b"", "wasm32-core");
        let owner_named = |wanted: &str| {
            collection
                .scopes()
                .interfaces
                .values()
                .find_map(|scope| {
                    scope.members.iter().find_map(|(name, binding)| {
                        (database
                            .symbols
                            .resolve(*name)
                            .is_ok_and(|name| name.as_ref() == wanted))
                        .then_some(binding.res)
                    })
                })
                .and_then(|res| match res {
                    sai_resolve::package_scopes::Res::Def(
                        sai_resolve::package_scopes::DefKind::Enum,
                        owner,
                    ) => Some(owner),
                    _ => None,
                })
                .unwrap_or_else(|| panic!("source enum `{wanted}` remains in interface scope"))
        };
        let projection_for = |name: &str| {
            let owner = owner_named(name);
            let projection = collection
                .local_interface_enum_adt_projection(&snapshot, owner)
                .expect("fresh snapshot is accepted")
                .unwrap_or_else(|| panic!("interface enum `{name}` has a projection outcome"));
            (owner, projection)
        };

        let (gated_owner, gated) = projection_for("Gated");
        assert_eq!(
            gated,
            &LocalInterfaceEnumAdtProjection::Unsupported {
                owner: gated_owner,
                reason: sai_ty::adt::LocalEnumAdtUnsupportedReason::InterfaceItemCheckFailed,
            },
            "a syntactically valid raw marker cannot be suppressed with a false acceptance token"
        );
        assert!(
            collection
                .local_flags_adt_def(&snapshot, gated_owner)
                .expect("fresh snapshot is accepted")
                .is_none(),
            "the unaccepted Stage 4 marker does not create a Flags ADT"
        );

        for name in ["InvalidAttribute", "Empty", "InvalidFlags"] {
            let (_, projection) = projection_for(name);
            assert!(
                matches!(projection, LocalInterfaceEnumAdtProjection::Unit(_)),
                "invalid or empty `{name}` keeps the ordinary enum fallback"
            );
        }
    }

    #[test]
    fn module_interface_enum_inventory_fails_closed_for_malformed_and_invalid_attributes() {
        for (source, expected_reason, name) in [
            (
                &b"interface api {\nenum Broken { Ready( }\n}\n"[..],
                "recovery or parse errors",
                "Broken",
            ),
            (
                &b"interface api {\n@deprecated(1) enum Invalid { Ready }\n}\n"[..],
                "attribute-validation error",
                "Invalid",
            ),
            (
                &b"interface api {\n@target(\"wasm64-core\") enum Filtered { Ready }\n}\n"[..],
                "attribute-validation error",
                "Filtered",
            ),
        ] {
            let (_, _, _, collection) =
                collect_package_inventory_for_target(source, b"", "wasm32-core");
            let inventory = inventory_symbols(&collection);
            assert!(
                matches!(
                    inventory.coverage(),
                    sai_semantic::InventoryCoverage::Incomplete { reason }
                        if reason.contains(expected_reason)
                ),
                "{source:?}: {:#?}",
                inventory.coverage()
            );
            assert!(inventory.symbols().iter().all(|symbol| {
                symbol.path() != format!("acme:phase1.api.{name}")
                    && !symbol
                        .path()
                        .starts_with(&format!("acme:phase1.api.{name}."))
            }));
        }
    }

