    #[test]
    fn module_function_inventory_fails_closed_for_generic_parameter_parser_diagnostics() {
        let (mut database, module_tree, snapshot, collection) =
            collect_package_inventory_for_target(
                b"fn invalid<@target(\"wasm64-core\") T>() {}\n",
                b"",
                "wasm32-core",
            );
        let file_id = module_tree.modules[0].file;
        let parsed = sai_syntax::parse(&snapshot, file_id)
            .expect("the generic-parameter fixture parses with a diagnostic");
        assert!(parsed.parser_diagnostics().iter().any(|diagnostic| {
            diagnostic.code == sai_diagnostics::Code::InvalidAttributeTarget
        }));
        assert!(matches!(
            inventory_symbols(&collection).coverage(),
            sai_semantic::InventoryCoverage::Incomplete { reason }
                if reason.contains("generic-parameter list has a parser diagnostic")
        ));

        let ast_ids = database
            .ast_id_map(&snapshot, file_id)
            .expect("module AST ID map is available");
        let item_tree = database
            .def_collector(&snapshot, file_id)
            .expect("the module ItemTree is available");
        let source = snapshot
            .file(file_id)
            .expect("module snapshot file exists")
            .source()
            .text();
        let filtered = item_tree
            .filter_for_target(
                source,
                &parsed.root,
                &ast_ids,
                &database.symbols,
                &snapshot,
                &target_cfg_for_check("wasm32-core").expect("target config is valid"),
            )
            .expect("target filtering keeps the invalid generic parameter");
        assert!(
            filtered
                .diagnostics
                .iter()
                .all(|diagnostic| diagnostic.code != sai_diagnostics::Code::InvalidAttributeTarget),
            "the regression fixture must stay outside filtered-item diagnostics"
        );
    }

    #[test]
    fn module_symbol_inventory_collects_functions_constants_and_effects_with_stable_metadata() {
        let (database, module_tree, snapshot, collection) = collect_package_inventory_for_target(
            b"fn root_fn() {}\nconst ROOT_VALUE: I32 = 7\neffect audit\n",
            b"const CHILD_VALUE: I32 = 13\neffect telemetry\n",
            "wasm32-core",
        );
        let inventory = inventory_symbols(&collection);
        assert_eq!(
            inventory.coverage(),
            &sai_semantic::InventoryCoverage::Complete
        );
        assert_eq!(
            inventory
                .symbols()
                .iter()
                .map(|symbol| (symbol.path(), symbol.kind()))
                .collect::<std::collections::BTreeSet<_>>(),
            [
                ("acme:phase1.root_fn", sai_semantic::SymbolKind::Fn),
                ("acme:phase1.ROOT_VALUE", sai_semantic::SymbolKind::Const),
                (
                    "acme:phase1/child.CHILD_VALUE",
                    sai_semantic::SymbolKind::Const
                ),
                ("acme:phase1.audit", sai_semantic::SymbolKind::Effect),
                (
                    "acme:phase1/child.telemetry",
                    sai_semantic::SymbolKind::Effect
                ),
            ]
            .into_iter()
            .collect()
        );

        for (file_id, name, expected_path, kind, owner_kind) in [
            (
                module_tree.modules[0].file,
                "root_fn",
                "acme:phase1.root_fn",
                sai_semantic::SymbolKind::Fn,
                TopLevelOwnerKind::Function,
            ),
            (
                module_tree.modules[0].file,
                "ROOT_VALUE",
                "acme:phase1.ROOT_VALUE",
                sai_semantic::SymbolKind::Const,
                TopLevelOwnerKind::Const,
            ),
            (
                module_tree.modules[0].file,
                "audit",
                "acme:phase1.audit",
                sai_semantic::SymbolKind::Effect,
                TopLevelOwnerKind::Effect,
            ),
            (
                module_tree.modules[1].file,
                "CHILD_VALUE",
                "acme:phase1/child.CHILD_VALUE",
                sai_semantic::SymbolKind::Const,
                TopLevelOwnerKind::Const,
            ),
            (
                module_tree.modules[1].file,
                "telemetry",
                "acme:phase1/child.telemetry",
                sai_semantic::SymbolKind::Effect,
                TopLevelOwnerKind::Effect,
            ),
        ] {
            let symbol = inventory
                .symbols()
                .iter()
                .find(|symbol| symbol.path() == expected_path)
                .expect("the declaration has a canonical inventory path");
            assert_eq!(symbol.kind(), kind);

            let owner_path = collection
                .scopes()
                .top_level_owners
                .iter()
                .filter(|owner| owner.file == file_id && owner.kind == owner_kind)
                .filter_map(|owner| {
                    database
                        .resolve_def_path(owner.owner.def_id.to_def_id())
                        .ok()
                        .flatten()
                })
                .find(|path| {
                    let Some(component) = path.data().last() else {
                        return false;
                    };
                    let symbol = match (kind, &component.data) {
                        (
                            sai_semantic::SymbolKind::Fn | sai_semantic::SymbolKind::Const,
                            DefPathData::ValueNs(symbol),
                        )
                        | (sai_semantic::SymbolKind::Effect, DefPathData::Effect(symbol)) => {
                            *symbol
                        }
                        _ => return false,
                    };
                    database
                        .symbols
                        .resolve(symbol)
                        .is_ok_and(|resolved| resolved.as_ref() == name)
                })
                .expect("the matching HIR owner has a canonical definition path");
            let expected_hash =
                sai_hir::DefPathHash::compute(&owner_path, &database.packages, &database.symbols)
                    .expect("the matching HIR path hashes");
            assert_eq!(
                symbol.def_path_hash(),
                sai_stable_hash::Fingerprint::new(expected_hash.raw())
            );

            let parsed = sai_syntax::parse(&snapshot, file_id).expect("module parses");
            let (declaration, name_token) = match kind {
                sai_semantic::SymbolKind::Fn => {
                    let declaration = parsed
                        .root
                        .descendants()
                        .find_map(ast::FnDecl::cast)
                        .filter(|function| {
                            function
                                .name()
                                .and_then(|name| name.token())
                                .is_some_and(|token| token.text() == name)
                        })
                        .expect("the module contains the expected function declaration");
                    let name_token = declaration
                        .name()
                        .and_then(|name| name.token())
                        .expect("the function has its declared name token");
                    (declaration.syntax().clone(), name_token)
                }
                sai_semantic::SymbolKind::Const => {
                    let declaration = parsed
                        .root
                        .descendants()
                        .find_map(ast::ConstDecl::cast)
                        .filter(|constant| {
                            constant
                                .name()
                                .and_then(|name| name.token())
                                .is_some_and(|token| token.text() == name)
                        })
                        .expect("the module contains the expected constant declaration");
                    let name_token = declaration
                        .name()
                        .and_then(|name| name.token())
                        .expect("the constant has its declared name token");
                    (declaration.syntax().clone(), name_token)
                }
                sai_semantic::SymbolKind::Effect => {
                    let declaration = parsed
                        .root
                        .descendants()
                        .find_map(ast::EffectDecl::cast)
                        .filter(|effect| {
                            effect
                                .name()
                                .and_then(|name| name.token())
                                .is_some_and(|token| token.text() == name)
                        })
                        .expect("the module contains the expected effect declaration");
                    let name_token = declaration
                        .name()
                        .and_then(|name| name.token())
                        .expect("the effect has its declared name token");
                    (declaration.syntax().clone(), name_token)
                }
                _ => unreachable!("the mixed fixture contains supported module-level symbols"),
            };
            let expected_fingerprint =
                sai_semantic::declaration_fingerprint(kind, &declaration, Some(&name_token))
                    .expect("the declaration fingerprint is defined");
            assert_eq!(symbol.fingerprint(), expected_fingerprint);
        }
    }

    #[test]
    fn module_resource_inventory_collects_nested_resources_and_named_fields() {
        let (database, module_tree, snapshot, collection) = collect_package_inventory_for_target(
            b"pub resource File {\n    pub r#match: USize\n    handle: String\n}\nresource Empty {}\n",
            "pub resource Café {\n    pub valeur: USize\n}\n".as_bytes(),
            "wasm32-core",
        );
        let inventory = inventory_symbols(&collection);
        assert_eq!(
            inventory.coverage(),
            &sai_semantic::InventoryCoverage::Complete
        );
        assert_eq!(
            inventory
                .symbols()
                .iter()
                .map(|symbol| (symbol.path(), symbol.kind()))
                .collect::<Vec<_>>(),
            [
                ("acme:phase1.File", sai_semantic::SymbolKind::Resource),
                (
                    "acme:phase1.File.field[match]",
                    sai_semantic::SymbolKind::Field
                ),
                (
                    "acme:phase1.File.field[handle]",
                    sai_semantic::SymbolKind::Field
                ),
                ("acme:phase1.Empty", sai_semantic::SymbolKind::Resource),
                ("acme:phase1/child.Café", sai_semantic::SymbolKind::Resource),
                (
                    "acme:phase1/child.Café.field[valeur]",
                    sai_semantic::SymbolKind::Field
                ),
            ]
        );

        let resource_owners = collection
            .scopes()
            .top_level_owners
            .iter()
            .filter(|owner| owner.kind == TopLevelOwnerKind::Resource)
            .collect::<Vec<_>>();
        assert_eq!(resource_owners.len(), 3);
        let def_paths = database
            .def_paths
            .get(&module_tree.package)
            .expect("the selected package has a DefPath interner");

        for (owner, expected_name, module_index, expected_path, field_names) in [
            (
                resource_owners[0],
                "File",
                0,
                "acme:phase1.File",
                vec!["match", "handle"],
            ),
            (resource_owners[1], "Empty", 0, "acme:phase1.Empty", vec![]),
            (
                resource_owners[2],
                "Café",
                1,
                "acme:phase1/child.Café",
                vec!["valeur"],
            ),
        ] {
            assert_eq!(owner.file, module_tree.modules[module_index].file);
            let def_path = database
                .resolve_def_path(owner.owner.def_id.to_def_id())
                .expect("resource owner DefId is valid")
                .expect("resource owner has a DefPath");
            assert_eq!(def_path.package(), module_tree.package);
            let expected_modules: &[&str] = if module_index == 0 { &[] } else { &["child"] };
            assert_eq!(def_path.data().len(), expected_modules.len() + 1);
            for (component, expected_module) in def_path.data().iter().zip(expected_modules.iter())
            {
                assert!(matches!(
                    &component.data,
                    DefPathData::Module(segment)
                        if component.disambiguator == 0
                            && database.symbols.resolve(*segment).is_ok_and(|name| name.as_ref() == *expected_module)
                ));
            }
            let resource_name = database
                .symbols
                .intern(expected_name)
                .expect("resource name interns");
            assert!(matches!(
                def_path.data().last(),
                Some(component)
                    if component.data == DefPathData::TypeNs(resource_name)
                        && component.disambiguator == 0
            ));
            let resource_symbol = inventory
                .symbols()
                .iter()
                .find(|symbol| symbol.path() == expected_path)
                .expect("resource declaration has an inventory record");
            let expected_hash =
                sai_hir::DefPathHash::compute(&def_path, &database.packages, &database.symbols)
                    .expect("resource DefPath hash is defined");
            assert_eq!(
                resource_symbol.def_path_hash(),
                sai_stable_hash::Fingerprint::new(expected_hash.raw())
            );

            let parsed = sai_syntax::parse(&snapshot, owner.file).expect("module parses");
            let declaration = parsed
                .root
                .descendants()
                .filter_map(ast::ResourceDecl::cast)
                .find(|resource| {
                    resource
                        .name()
                        .and_then(|name| name.token())
                        .is_some_and(|token| {
                            sai_syntax::normalize_identifier(
                                token.text().strip_prefix("r#").unwrap_or(token.text()),
                            ) == expected_name
                        })
                })
                .expect("the matching ResourceDecl is in the AST");
            let name_token = declaration
                .name()
                .and_then(|name| name.token())
                .expect("resource AST has a name token");
            assert_eq!(
                resource_symbol.fingerprint(),
                sai_semantic::declaration_fingerprint(
                    sai_semantic::SymbolKind::Resource,
                    &declaration.syntax(),
                    Some(&name_token),
                )
                .expect("resource fingerprint is defined")
            );

            let ast_fields = declaration
                .fields()
                .map(|fields| fields.fields().collect::<Vec<_>>())
                .unwrap_or_default();
            assert_eq!(
                ast_fields
                    .iter()
                    .map(|field| {
                        let token = field
                            .name()
                            .and_then(|name| name.token())
                            .expect("resource field has a name token");
                        sai_syntax::normalize_identifier(
                            token.text().strip_prefix("r#").unwrap_or(token.text()),
                        )
                    })
                    .collect::<Vec<_>>(),
                field_names
                    .iter()
                    .map(|name| (*name).to_owned())
                    .collect::<Vec<_>>()
            );
            let mut name_disambiguators = std::collections::HashMap::new();
            let field_ids = field_names
                .iter()
                .map(|name| {
                    let symbol = database.symbols.intern(name).expect("field name interns");
                    let disambiguator = name_disambiguators.entry(symbol).or_insert(0_u32);
                    let current = *disambiguator;
                    *disambiguator += 1;
                    (symbol, current)
                })
                .collect::<Vec<_>>();
            let field_def_ids = def_paths
                .intern_fields(owner.owner.def_id, &field_ids)
                .expect("resource field DefPaths are interned");
            for ((field, field_def_id), field_name) in
                ast_fields.iter().zip(field_def_ids).zip(field_names)
            {
                let field_token = field
                    .name()
                    .and_then(|name| name.token())
                    .expect("resource field has a name token");
                let field_path = format!("{expected_path}.field[{field_name}]");
                let field_symbol = inventory
                    .symbols()
                    .iter()
                    .find(|symbol| symbol.path() == field_path)
                    .expect("named resource field has an inventory record");
                let field_def_path = database
                    .resolve_def_path(field_def_id.to_def_id())
                    .expect("field DefId is valid")
                    .expect("field DefPath is present");
                let expected_field_hash = sai_hir::DefPathHash::compute(
                    &field_def_path,
                    &database.packages,
                    &database.symbols,
                )
                .expect("resource field DefPath hash is defined");
                assert_eq!(
                    field_symbol.def_path_hash(),
                    sai_stable_hash::Fingerprint::new(expected_field_hash.raw())
                );
                assert_eq!(
                    field_symbol.fingerprint(),
                    sai_semantic::declaration_fingerprint(
                        sai_semantic::SymbolKind::Field,
                        &field.syntax(),
                        Some(&field_token),
                    )
                    .expect("resource field fingerprint is defined")
                );
            }
        }
    }

    #[test]
    fn module_resource_inventory_preserves_duplicate_def_path_disambiguators() {
        let (database, module_tree, _, collection) = collect_package_inventory_for_target(
            b"type Duplicate {}\nresource Duplicate {\n    item: I32\n    item: Bool\n}\nresource Duplicate {\n    other: U32\n}\n",
            b"",
            "wasm32-core",
        );
        let inventory = inventory_symbols(&collection);
        assert!(matches!(
            inventory.coverage(),
            sai_semantic::InventoryCoverage::Incomplete { reason }
                if reason.contains("duplicate canonical symbol path")
        ));
        let owners = collection
            .scopes()
            .top_level_owners
            .iter()
            .filter(|owner| {
                owner.kind == TopLevelOwnerKind::Resource
                    && owner.file == module_tree.modules[0].file
            })
            .collect::<Vec<_>>();
        assert_eq!(owners.len(), 2);
        let owner_paths = owners
            .iter()
            .map(|owner| {
                database
                    .resolve_def_path(owner.owner.def_id.to_def_id())
                    .expect("resource owner DefId is valid")
                    .expect("resource owner DefPath exists")
            })
            .collect::<Vec<_>>();
        for (path, expected_disambiguator) in owner_paths.iter().zip([1, 2]) {
            assert!(matches!(
                path.data().last(),
                Some(component)
                    if component.data == DefPathData::TypeNs(
                        database.symbols.intern("Duplicate").expect("name interns")
                    )
                        && component.disambiguator == expected_disambiguator
            ));
        }

        let duplicate_fields = inventory
            .symbols()
            .iter()
            .filter(|symbol| symbol.path() == "acme:phase1.Duplicate.field[item]")
            .collect::<Vec<_>>();
        assert_eq!(duplicate_fields.len(), 2);
        assert_ne!(
            duplicate_fields[0].def_path_hash(),
            duplicate_fields[1].def_path_hash(),
            "same-name resource fields retain source-order DefPath disambiguators"
        );
    }

    #[test]
    fn module_resource_inventory_keeps_unsupported_resource_shapes_incomplete() {
        for source in [
            &b"resource Generic<T> {}\n"[..],
            &b"resource Tuple(U32)\n"[..],
            &b"resource WithMethod { fn close() {} }\n"[..],
        ] {
            let (_, _, _, collection) =
                collect_package_inventory_for_target(source, b"", "wasm32-core");
            assert!(
                matches!(
                    inventory_symbols(&collection).coverage(),
                    sai_semantic::InventoryCoverage::Incomplete { .. }
                ),
                "unsupported resource shape must remain incomplete: {}",
                String::from_utf8_lossy(source)
            );
        }
    }

    #[test]
    fn module_resource_inventory_tracks_visibility_and_attribute_boundaries() {
        let fingerprint = |source: &[u8], kind: sai_semantic::SymbolKind, path: &str| {
            let (_, _, _, collection) =
                collect_package_inventory_for_target(source, b"", "wasm32-core");
            inventory_symbols(&collection)
                .symbols()
                .iter()
                .find(|symbol| symbol.path() == path && symbol.kind() == kind)
                .expect("symbol is present")
                .fingerprint()
        };
        assert_ne!(
            fingerprint(
                b"pub resource Item {\n    pub value: U32\n}\n",
                sai_semantic::SymbolKind::Resource,
                "acme:phase1.Item",
            ),
            fingerprint(
                b"resource Item {\n    value: U32\n}\n",
                sai_semantic::SymbolKind::Resource,
                "acme:phase1.Item",
            ),
            "resource visibility participates in its declaration fingerprint"
        );
        assert_ne!(
            fingerprint(
                b"pub resource Item {\n    pub value: U32\n}\n",
                sai_semantic::SymbolKind::Field,
                "acme:phase1.Item.field[value]",
            ),
            fingerprint(
                b"resource Item {\n    value: U32\n}\n",
                sai_semantic::SymbolKind::Field,
                "acme:phase1.Item.field[value]",
            ),
            "field visibility participates in its declaration fingerprint"
        );

        let (_, _, _, target_filtered) = collect_package_inventory_for_target(
            b"@target(\"wasm64-core\")\nresource Only64 {}\n",
            b"",
            "wasm32-core",
        );
        assert_eq!(
            inventory_symbols(&target_filtered).coverage(),
            &sai_semantic::InventoryCoverage::Complete
        );
        assert!(inventory_symbols(&target_filtered).symbols().is_empty());

        let (_, _, _, invalid_target) = collect_package_inventory_for_target(
            b"@target(\"wasm32-linux\")\nresource InvalidTarget {}\n",
            b"",
            "wasm32-core",
        );
        assert!(matches!(
            inventory_symbols(&invalid_target).coverage(),
            sai_semantic::InventoryCoverage::Incomplete { reason }
                if reason.contains("target-selection error")
        ));

        let (_, _, _, derived) = collect_package_inventory_for_target(
            b"@derive(Clone)\nresource Derived {}\n",
            b"",
            "wasm32-core",
        );
        assert!(matches!(
            inventory_symbols(&derived).coverage(),
            sai_semantic::InventoryCoverage::Incomplete { reason }
                if reason.contains("attribute or target-selection error")
                    || reason.contains("rejected @derive")
        ));

        let (_, module_tree, snapshot, invalid_field_target) = collect_package_inventory_for_target(
            b"resource InvalidFieldTarget { @target(\"wasm64-core\")\n    field: U32\n}\n",
            b"",
            "wasm32-core",
        );
        let parsed = sai_syntax::parse(&snapshot, module_tree.modules[0].file)
            .expect("resource field target fixture parses");
        assert!(
            invalid_field_target
                .scopes()
                .diagnostics
                .iter()
                .any(|diagnostic| diagnostic.code == sai_diagnostics::Code::InvalidAttributeTarget)
        );
        assert!(
            parsed
                .errors
                .iter()
                .all(|diagnostic| diagnostic.code != sai_diagnostics::Code::InvalidAttributeTarget),
            "field @target validation is surfaced during HIR collection"
        );
        assert!(matches!(
            inventory_symbols(&invalid_field_target).coverage(),
            sai_semantic::InventoryCoverage::Incomplete { .. }
        ));
    }

    #[test]
    fn module_extern_function_inventory_collects_verified_module_symbols() {
        let (database, module_tree, snapshot, collection) = collect_package_inventory_for_target(
            b"extern \"wasm\" module \"env\" {\n    fn read(value: U32) -> U32\n    fn write(value: U32)\n}\nextern \"wasm\" module \"clock\" {\n    fn now() -> U64\n}\n",
            b"extern \"wasm\" module \"env\" {\n    fn read(value: U32) -> U32\n}\n",
            "wasm32-core",
        );
        let inventory = inventory_symbols(&collection);
        assert_eq!(
            inventory.coverage(),
            &sai_semantic::InventoryCoverage::Complete
        );
        assert_eq!(
            inventory
                .symbols()
                .iter()
                .map(|symbol| (symbol.path(), symbol.kind()))
                .collect::<Vec<_>>(),
            [
                ("acme:phase1.read", sai_semantic::SymbolKind::ExternFn),
                ("acme:phase1.write", sai_semantic::SymbolKind::ExternFn),
                ("acme:phase1.now", sai_semantic::SymbolKind::ExternFn),
                ("acme:phase1/child.read", sai_semantic::SymbolKind::ExternFn),
            ],
            "symbols: {:?}; extern-function owners: {:?}",
            inventory
                .symbols()
                .iter()
                .map(|symbol| symbol.path())
                .collect::<Vec<_>>(),
            collection.scopes().extern_function_owners
        );

        let blocks = collection
            .scopes()
            .top_level_owners
            .iter()
            .filter(|owner| owner.kind == TopLevelOwnerKind::ExternBlock)
            .collect::<Vec<_>>();
        assert_eq!(blocks.len(), 3);
        assert_eq!(collection.scopes().extern_function_owners.len(), 4);
        for function in &collection.scopes().extern_function_owners {
            let block = blocks
                .iter()
                .find(|block| {
                    block.owner == function.block_owner
                        && block.file == function.file
                        && block.item_id == function.block_item_id
                })
                .expect("extern-function descriptor names its exact top-level block");
            let block_path = database
                .resolve_def_path(block.owner.def_id.to_def_id())
                .expect("block owner DefId is valid")
                .expect("extern block has a structural DefPath");
            let function_path = database
                .resolve_def_path(function.owner.def_id.to_def_id())
                .expect("function owner DefId is valid")
                .expect("extern function has a structural DefPath");
            assert_eq!(function_path.package(), module_tree.package);
            assert_eq!(function_path.data().len(), block_path.data().len() + 1);
            assert_eq!(
                &function_path.data()[..block_path.data().len()],
                block_path.data()
            );
            let expected_hash = sai_hir::DefPathHash::compute(
                &function_path,
                &database.packages,
                &database.symbols,
            )
            .expect("extern-function DefPath hash is defined");
            let expected_fingerprint = sai_stable_hash::Fingerprint::new(expected_hash.raw());
            assert!(
                inventory.symbols().iter().any(|symbol| {
                    symbol.kind() == sai_semantic::SymbolKind::ExternFn
                        && symbol.def_path_hash() == expected_fingerprint
                }),
                "the owner DefPath hash is present in the inventory"
            );
        }

        let parsed =
            sai_syntax::parse(&snapshot, module_tree.modules[0].file).expect("root parses");
        let read = parsed
            .root
            .descendants()
            .filter_map(ast::FnDecl::cast)
            .find(|function| {
                function
                    .name()
                    .and_then(|name| name.token())
                    .is_some_and(|name| name.text() == "read")
            })
            .expect("root read import is present");
        let name_token = read
            .name()
            .and_then(|name| name.token())
            .expect("extern-function name token is present");
        let expected_fingerprint = sai_semantic::declaration_fingerprint(
            sai_semantic::SymbolKind::ExternFn,
            read.syntax(),
            Some(&name_token),
        )
        .expect("extern-function fingerprint is defined");
        assert!(
            inventory
                .symbols()
                .iter()
                .filter(|symbol| symbol.path() == "acme:phase1.read")
                .all(|symbol| symbol.fingerprint() == expected_fingerprint)
        );
    }

    #[test]
    fn module_extern_function_inventory_preserves_block_and_child_disambiguators() {
        let (database, _, _, collection) = collect_package_inventory_for_target(
            b"extern \"wasm\" module \"env\" {\n    fn same()\n    fn same()\n}\nextern \"wasm\" module \"env\" {\n    fn same()\n}\nextern \"wasm\" module \"clock\" {\n    fn same()\n}\n",
            b"",
            "wasm32-core",
        );
        let inventory = inventory_symbols(&collection);
        assert!(matches!(
            inventory.coverage(),
            sai_semantic::InventoryCoverage::Incomplete { reason }
                if reason.contains("duplicate canonical symbol path")
        ));
        let functions = &collection.scopes().extern_function_owners;
        assert_eq!(functions.len(), 4);
        let paths = functions
            .iter()
            .map(|function| {
                database
                    .resolve_def_path(function.owner.def_id.to_def_id())
                    .expect("extern-function owner is valid")
                    .expect("extern function has a DefPath")
            })
            .collect::<Vec<_>>();
        assert_eq!(
            paths
                .iter()
                .map(|path| path
                    .data()
                    .last()
                    .expect("extern function DefPath has a terminal component")
                    .disambiguator)
                .collect::<Vec<_>>(),
            [0, 1, 0, 0],
            "same-name child DefPath disambiguators follow source order within each block"
        );
        assert_ne!(
            paths[0], paths[1],
            "same-block functions have distinct paths"
        );
        assert_ne!(paths[0], paths[2], "same-header blocks have distinct paths");
        let block_disambiguators = collection
            .scopes()
            .top_level_owners
            .iter()
            .filter(|owner| owner.kind == TopLevelOwnerKind::ExternBlock)
            .map(|owner| {
                database
                    .resolve_def_path(owner.owner.def_id.to_def_id())
                    .expect("extern-block owner is valid")
                    .expect("extern block has a DefPath")
                    .data()
                    .last()
                    .expect("extern-block DefPath has a terminal component")
                    .disambiguator
            })
            .collect::<Vec<_>>();
        assert_eq!(
            block_disambiguators,
            [0, 1, 0],
            "same-header block DefPath disambiguators follow source order"
        );
        assert_eq!(
            inventory
                .symbols()
                .iter()
                .filter(|symbol| symbol.path() == "acme:phase1.same")
                .count(),
            4,
            "the canonical module path collides even across distinct extern blocks"
        );
    }

    #[test]
    fn module_extern_function_inventory_filters_targeted_blocks_and_rejects_unsupported_forms() {
        let (_, _, _, filtered) = collect_package_inventory_for_target(
            b"@target(\"wasm64-core\")\nextern \"wasm\" module \"hidden\" { fn hidden() }\nextern \"wasm\" module \"env\" { fn visible() }\n",
            b"",
            "wasm32-core",
        );
        let inventory = inventory_symbols(&filtered);
        assert_eq!(
            inventory.coverage(),
            &sai_semantic::InventoryCoverage::Complete
        );
        assert_eq!(
            inventory
                .symbols()
                .iter()
                .map(|symbol| symbol.path())
                .collect::<Vec<_>>(),
            ["acme:phase1.visible"]
        );
        assert_eq!(filtered.scopes().extern_function_owners.len(), 1);

        for source in [
            &b"extern \"wasm\" module \"env\" { fn generic<T>(value: T) -> T }\n"[..],
            &b"extern \"wasm\" module \"env\" { async fn later() }\n"[..],
            &b"extern \"wasm\" module \"env\" { fn receiver(self: borrow Self) }\n"[..],
            &b"extern \"wasm\" module \"env\" { fn bounded<T>(value: T) where T: Bound }\n"[..],
            &b"extern \"wasm\" module \"env\" { fn borrowed(value: U32) borrows {} }\n"[..],
            &b"extern \"wasm\" module \"env\" { fn with_body() {} }\n"[..],
            &b"extern \"wasm\" module \"env\" { @target(host) fn targeted_child() }\n"[..],
            &b"unsafe extern \"C\" { fn native(value: I32) -> I32 }\n"[..],
            &b"extern \"other\" module \"env\" { fn unknown() }\n"[..],
            &b"extern \"wasm\" { fn missing_module() }\n"[..],
        ] {
            let (_, _, _, collection) =
                collect_package_inventory_for_target(source, b"", "wasm32-core");
            assert!(
                matches!(
                    inventory_symbols(&collection).coverage(),
                    sai_semantic::InventoryCoverage::Incomplete { .. }
                ),
                "unsupported extern form must remain incomplete: {}",
                String::from_utf8_lossy(source)
            );
        }
    }

