    #[test]
    fn module_distinct_inventory_collects_root_nested_and_mixed_generic_symbols() {
        let (database, module_tree, snapshot, collection) = collect_package_inventory_for_target(
            b"distinct UserId = U64\ndistinct Matrix<T, const ROWS: USize, U, const COLS: USize> = Array<T, ROWS>\n",
            b"distinct ChildKey = U32\n",
            "wasm32-core",
        );
        let inventory = inventory_symbols(&collection);
        assert_eq!(
            inventory.coverage(),
            &sai_semantic::InventoryCoverage::Complete
        );
        assert_eq!(
            inventory
                .symbols()
                .iter()
                .map(|symbol| (symbol.path(), symbol.kind()))
                .collect::<BTreeSet<_>>(),
            [
                ("acme:phase1.UserId", sai_semantic::SymbolKind::Distinct),
                ("acme:phase1.Matrix", sai_semantic::SymbolKind::Distinct),
                (
                    "acme:phase1.Matrix.generic[T]",
                    sai_semantic::SymbolKind::GenericParam,
                ),
                (
                    "acme:phase1.Matrix.generic[ROWS]",
                    sai_semantic::SymbolKind::GenericParam,
                ),
                (
                    "acme:phase1.Matrix.generic[U]",
                    sai_semantic::SymbolKind::GenericParam,
                ),
                (
                    "acme:phase1.Matrix.generic[COLS]",
                    sai_semantic::SymbolKind::GenericParam,
                ),
                (
                    "acme:phase1/child.ChildKey",
                    sai_semantic::SymbolKind::Distinct,
                ),
            ]
            .into_iter()
            .collect()
        );

        for (file_id, name, path) in [
            (module_tree.modules[0].file, "UserId", "acme:phase1.UserId"),
            (module_tree.modules[0].file, "Matrix", "acme:phase1.Matrix"),
            (
                module_tree.modules[1].file,
                "ChildKey",
                "acme:phase1/child.ChildKey",
            ),
        ] {
            let owner = collection
                .scopes()
                .top_level_owners
                .iter()
                .find(|owner| {
                    owner.file == file_id
                        && owner.kind == TopLevelOwnerKind::Distinct
                        && database
                            .resolve_def_path(owner.owner.def_id.to_def_id())
                            .ok()
                            .flatten()
                            .is_some_and(|owner_path| {
                                matches!(
                                    owner_path.data().last().map(|component| &component.data),
                                    Some(DefPathData::TypeNs(symbol))
                                        if database.symbols.resolve(*symbol).is_ok_and(|resolved| resolved.as_ref() == name)
                                )
                            })
                })
                .expect("the distinct declaration has its exact top-level owner");
            let owner_path = database
                .resolve_def_path(owner.owner.def_id.to_def_id())
                .expect("distinct owner DefId is valid")
                .expect("distinct owner DefPath exists");
            assert_eq!(owner_path.package(), module_tree.package);
            assert!(
                owner_path
                    .data()
                    .iter()
                    .all(|component| component.disambiguator == 0),
                "the unique module path and distinct name use zero disambiguators"
            );
            let expected_hash =
                sai_hir::DefPathHash::compute(&owner_path, &database.packages, &database.symbols)
                    .expect("the distinct owner DefPath hashes");
            let symbol = inventory
                .symbols()
                .iter()
                .find(|symbol| symbol.path() == path)
                .expect("the distinct has its canonical inventory path");
            assert_eq!(symbol.kind(), sai_semantic::SymbolKind::Distinct);
            assert_eq!(
                symbol.def_path_hash(),
                sai_stable_hash::Fingerprint::new(expected_hash.raw())
            );

            let parsed = sai_syntax::parse(&snapshot, file_id).expect("distinct module parses");
            let declaration = parsed
                .root
                .descendants()
                .filter_map(ast::DistinctDecl::cast)
                .find(|declaration| {
                    declaration
                        .name()
                        .and_then(|name| name.token())
                        .is_some_and(|token| token.text() == name)
                })
                .expect("the distinct declaration is present in its source file");
            let name_token = declaration
                .name()
                .and_then(|name| name.token())
                .expect("the distinct declaration has its name token");
            assert_eq!(
                symbol.fingerprint(),
                sai_semantic::declaration_fingerprint(
                    sai_semantic::SymbolKind::Distinct,
                    declaration.syntax(),
                    Some(&name_token),
                )
                .expect("the distinct declaration fingerprint is defined")
            );
        }

        let owner = collection
            .scopes()
            .top_level_owners
            .iter()
            .find(|owner| {
                owner.file == module_tree.modules[0].file
                    && owner.kind == TopLevelOwnerKind::Distinct
                    && database
                        .resolve_def_path(owner.owner.def_id.to_def_id())
                        .ok()
                        .flatten()
                        .is_some_and(|path| {
                            matches!(
                                path.data().last().map(|component| &component.data),
                                Some(DefPathData::TypeNs(name))
                                    if database.symbols.resolve(*name).is_ok_and(|name| name.as_ref() == "Matrix")
                            )
                        })
            })
            .expect("the generic distinct owner exists");
        let def_paths = database
            .def_paths
            .get(&module_tree.package)
            .expect("the package DefPath interner exists");
        let t = database.symbols.intern("T").expect("T interns");
        let rows = database.symbols.intern("ROWS").expect("ROWS interns");
        let u = database.symbols.intern("U").expect("U interns");
        let cols = database.symbols.intern("COLS").expect("COLS interns");
        let parameter_ids = def_paths
            .intern_generic_params(
                owner.owner.def_id,
                &[
                    (t, false, 0),
                    (rows, true, 0),
                    (u, false, 0),
                    (cols, true, 0),
                ],
            )
            .expect("mixed type and const parameters have exact HIR paths");
        let owner_path = database
            .resolve_def_path(owner.owner.def_id.to_def_id())
            .expect("generic distinct owner DefId is valid")
            .expect("generic distinct owner DefPath exists");
        let expected_components = [
            DefPathData::TypeParam(t),
            DefPathData::ConstParam(rows),
            DefPathData::TypeParam(u),
            DefPathData::ConstParam(cols),
        ];
        let parsed = sai_syntax::parse(&snapshot, module_tree.modules[0].file)
            .expect("generic distinct module parses");
        let declaration = parsed
            .root
            .descendants()
            .filter_map(ast::DistinctDecl::cast)
            .find(|declaration| {
                declaration
                    .name()
                    .and_then(|name| name.token())
                    .is_some_and(|token| token.text() == "Matrix")
            })
            .expect("generic distinct AST exists");
        let params = declaration
            .generic_params()
            .expect("generic parameter list exists")
            .params()
            .collect::<Vec<_>>();
        for (((parameter, def_id), expected_component), parameter_name) in params
            .iter()
            .zip(parameter_ids)
            .zip(expected_components)
            .zip(["T", "ROWS", "U", "COLS"])
        {
            let (name_token, syntax) = match parameter {
                ast::GenericParam::Type(parameter) => (
                    parameter.name().and_then(|name| name.token()),
                    parameter.syntax(),
                ),
                ast::GenericParam::Const(parameter) => (
                    parameter.name().and_then(|name| name.token()),
                    parameter.syntax(),
                ),
            };
            let name_token = name_token.expect("generic parameter name token exists");
            assert_eq!(name_token.text(), parameter_name);
            let param_path = database
                .resolve_def_path(def_id.to_def_id())
                .expect("generic DefId is valid")
                .expect("generic DefPath exists");
            assert_eq!(param_path.package(), module_tree.package);
            assert_eq!(
                &param_path.data()[..owner_path.data().len()],
                owner_path.data()
            );
            assert!(matches!(
                param_path.data().last(),
                Some(component)
                    if component.data == expected_component && component.disambiguator == 0
            ));
            let symbol = inventory
                .symbols()
                .iter()
                .find(|symbol| {
                    symbol.path() == format!("acme:phase1.Matrix.generic[{parameter_name}]")
                })
                .expect("the parameter has its canonical inventory path");
            let expected_hash =
                sai_hir::DefPathHash::compute(&param_path, &database.packages, &database.symbols)
                    .expect("generic parameter DefPath hashes");
            assert_eq!(
                symbol.def_path_hash(),
                sai_stable_hash::Fingerprint::new(expected_hash.raw())
            );
            assert_eq!(
                symbol.fingerprint(),
                sai_semantic::declaration_fingerprint(
                    sai_semantic::SymbolKind::GenericParam,
                    syntax,
                    Some(&name_token),
                )
                .expect("generic parameter fingerprint is defined")
            );
        }
    }

    #[test]
    fn module_distinct_fingerprints_ignore_names_and_track_base_and_generic_changes() {
        let fingerprint_for = |source: &[u8], kind: sai_semantic::SymbolKind| {
            let (_, _, _, collection) =
                collect_package_inventory_for_target(source, b"", "wasm32-core");
            let inventory = inventory_symbols(&collection);
            assert_eq!(
                inventory.coverage(),
                &sai_semantic::InventoryCoverage::Complete
            );
            inventory
                .symbols()
                .iter()
                .find(|symbol| symbol.kind() == kind)
                .expect("the requested distinct symbol is inventoried")
                .fingerprint()
        };
        let distinct_original = fingerprint_for(
            b"distinct UserId = U64\n",
            sai_semantic::SymbolKind::Distinct,
        );
        let distinct_renamed = fingerprint_for(
            b"distinct AccountId = U64\n",
            sai_semantic::SymbolKind::Distinct,
        );
        let distinct_changed_base = fingerprint_for(
            b"distinct UserId = U32\n",
            sai_semantic::SymbolKind::Distinct,
        );
        let generic_original = fingerprint_for(
            b"distinct Wrapper<T: Copy> = T\n",
            sai_semantic::SymbolKind::GenericParam,
        );
        let generic_renamed = fingerprint_for(
            b"distinct Wrapper<U: Copy> = U\n",
            sai_semantic::SymbolKind::GenericParam,
        );
        let generic_changed_bound = fingerprint_for(
            b"distinct Wrapper<T: Clone> = T\n",
            sai_semantic::SymbolKind::GenericParam,
        );

        assert_eq!(
            distinct_original, distinct_renamed,
            "renaming a distinct type preserves its fingerprint"
        );
        assert_ne!(
            distinct_original, distinct_changed_base,
            "changing the distinct base type changes its fingerprint"
        );
        assert_eq!(
            generic_original, generic_renamed,
            "renaming a generic parameter preserves its fingerprint"
        );
        assert_ne!(
            generic_original, generic_changed_bound,
            "changing a generic parameter bound changes its fingerprint"
        );
    }

    #[test]
    fn module_distinct_inventory_checks_target_parser_and_derive_coverage() {
        let source = b"@target(\"wasm64-core\")\ndistinct Only64 = U64\n";
        let (_, _, _, wasm32) = collect_package_inventory_for_target(source, b"", "wasm32-core");
        assert_eq!(
            inventory_symbols(&wasm32).coverage(),
            &sai_semantic::InventoryCoverage::Complete
        );
        assert!(inventory_symbols(&wasm32).symbols().is_empty());
        let (_, _, _, wasm64) = collect_package_inventory_for_target(source, b"", "wasm64-core");
        assert_eq!(
            inventory_symbols(&wasm64).coverage(),
            &sai_semantic::InventoryCoverage::Complete
        );
        assert_eq!(
            inventory_symbols(&wasm64)
                .symbols()
                .iter()
                .map(|symbol| symbol.path())
                .collect::<Vec<_>>(),
            ["acme:phase1.Only64"]
        );

        for (source, expected_reason) in [
            (
                &b"@target(\"wasm32-linux\")\ndistinct Uncertain = U64\n"[..],
                "target-selection error",
            ),
            (
                &b"distinct Malformed<T:> = T\n"[..],
                "syntax tree contains recovery or parse errors",
            ),
            (
                &b"distinct Invalid<@target(\"wasm64-core\") T> = T\n"[..],
                "parser diagnostic",
            ),
        ] {
            let (_, _, _, collection) =
                collect_package_inventory_for_target(source, b"", "wasm32-core");
            assert!(
                matches!(
                    inventory_symbols(&collection).coverage(),
                    sai_semantic::InventoryCoverage::Incomplete { reason }
                        if reason.contains(expected_reason)
                ),
                "unexpected inventory coverage for {source:?}"
            );
        }

        let (_, _, _, derived) = collect_package_inventory_for_target(
            b"@derive(Clone)\ndistinct Derived = U32\n",
            b"",
            "wasm32-core",
        );
        assert!(matches!(
            inventory_symbols(&derived).coverage(),
            sai_semantic::InventoryCoverage::Incomplete { reason }
                if reason.contains("derived impl symbols outside the supported inventory")
        ));
        assert!(
            inventory_symbols(&derived)
                .symbols()
                .iter()
                .any(|symbol| symbol.kind() == sai_semantic::SymbolKind::Distinct),
            "the declared distinct remains inspectable while derive-generated symbols are uncovered"
        );
    }

    #[test]
    fn module_distinct_inventory_rejects_refined_distincts_and_wrong_type_disambiguators() {
        for source in [
            &b"distinct Refined = U32 where self > 0\n"[..],
            &b"distinct Refined<T> = T where self > 0\n"[..],
        ] {
            let (_, _, _, refined) =
                collect_package_inventory_for_target(source, b"", "wasm32-core");
            assert!(matches!(
                inventory_symbols(&refined).coverage(),
                sai_semantic::InventoryCoverage::Incomplete { reason }
                    if reason.contains("refined distinct type is outside the supported distinct inventory")
            ));
            assert!(
                inventory_symbols(&refined).symbols().iter().all(|symbol| {
                    symbol.kind() != sai_semantic::SymbolKind::Distinct
                        && symbol.kind() != sai_semantic::SymbolKind::GenericParam
                }),
                "refined distincts contribute neither the parent nor generic-parameter symbols"
            );
        }

        let (database, module_tree, _, duplicate) = collect_package_inventory_for_target(
            b"type SameName = I32\ndistinct SameName = U32\n",
            b"",
            "wasm32-core",
        );
        let inventory = inventory_symbols(&duplicate);
        assert!(matches!(
            inventory.coverage(),
            sai_semantic::InventoryCoverage::Incomplete { .. }
        ));
        let owner = duplicate
            .scopes()
            .top_level_owners
            .iter()
            .find(|owner| owner.kind == TopLevelOwnerKind::Distinct)
            .expect("distinct owner exists despite the duplicate name");
        let owner_path = database
            .resolve_def_path(owner.owner.def_id.to_def_id())
            .expect("distinct owner DefId is valid")
            .expect("distinct owner DefPath exists");
        assert!(matches!(
            owner_path.data().last(),
            Some(component)
                if matches!(component.data, DefPathData::TypeNs(_))
                    && component.disambiguator == 1
        ));
        let expected_hash =
            sai_hir::DefPathHash::compute(&owner_path, &database.packages, &database.symbols)
                .expect("the duplicate distinct owner path hashes");
        let symbol = inventory
            .symbols()
            .iter()
            .find(|symbol| {
                symbol.kind() == sai_semantic::SymbolKind::Distinct
                    && symbol.path() == "acme:phase1.SameName"
            })
            .expect("the distinct candidate remains inspectable");
        assert_eq!(
            symbol.def_path_hash(),
            sai_stable_hash::Fingerprint::new(expected_hash.raw())
        );
        assert_eq!(owner.file, module_tree.modules[0].file);
    }

    #[test]
    fn module_record_inventory_collects_root_nested_empty_and_generic_records() {
        let (database, module_tree, _, collection) = collect_package_inventory_for_target(
            b"type Marker {}\ntype Pair<T, const N: I32, U> {\n    left: T\n    right: U\n}\n",
            b"type ChildMarker {}\ntype ChildValue {\n    pub value: U32\n}\n",
            "wasm32-core",
        );
        let inventory = inventory_symbols(&collection);
        assert_eq!(
            inventory.coverage(),
            &sai_semantic::InventoryCoverage::Complete
        );
        assert_eq!(
            inventory
                .symbols()
                .iter()
                .map(|symbol| (symbol.path(), symbol.kind()))
                .collect::<BTreeSet<_>>(),
            [
                ("acme:phase1.Marker", sai_semantic::SymbolKind::Record),
                ("acme:phase1.Pair", sai_semantic::SymbolKind::Record),
                (
                    "acme:phase1.Pair.generic[T]",
                    sai_semantic::SymbolKind::GenericParam
                ),
                (
                    "acme:phase1.Pair.generic[N]",
                    sai_semantic::SymbolKind::GenericParam
                ),
                (
                    "acme:phase1.Pair.generic[U]",
                    sai_semantic::SymbolKind::GenericParam
                ),
                (
                    "acme:phase1.Pair.field[left]",
                    sai_semantic::SymbolKind::Field
                ),
                (
                    "acme:phase1.Pair.field[right]",
                    sai_semantic::SymbolKind::Field
                ),
                (
                    "acme:phase1/child.ChildMarker",
                    sai_semantic::SymbolKind::Record
                ),
                (
                    "acme:phase1/child.ChildValue",
                    sai_semantic::SymbolKind::Record
                ),
                (
                    "acme:phase1/child.ChildValue.field[value]",
                    sai_semantic::SymbolKind::Field
                ),
            ]
            .into_iter()
            .collect()
        );

        let def_paths = database
            .def_paths
            .get(&module_tree.package)
            .expect("the selected package has a DefPath interner");
        for (module_index, record_name, record_path, fields, generic_params) in [
            (
                0,
                "Pair",
                "acme:phase1.Pair",
                vec!["left", "right"],
                vec![("T", false), ("N", true), ("U", false)],
            ),
            (
                1,
                "ChildValue",
                "acme:phase1/child.ChildValue",
                vec!["value"],
                vec![],
            ),
            (0, "Marker", "acme:phase1.Marker", vec![], vec![]),
            (
                1,
                "ChildMarker",
                "acme:phase1/child.ChildMarker",
                vec![],
                vec![],
            ),
        ] {
            let owner = collection
                .scopes()
                .top_level_owners
                .iter()
                .find(|owner| {
                    owner.file == module_tree.modules[module_index].file
                        && owner.kind == TopLevelOwnerKind::Struct
                        && database
                            .resolve_def_path(owner.owner.def_id.to_def_id())
                            .ok()
                            .flatten()
                            .is_some_and(|path| {
                                matches!(
                                    path.data().last().map(|component| &component.data),
                                    Some(DefPathData::TypeNs(name))
                                        if database.symbols.resolve(*name).is_ok_and(|name| name.as_ref() == record_name)
                                )
                            })
                })
                .expect("each record has exactly its top-level HIR owner");
            let record_def_path = database
                .resolve_def_path(owner.owner.def_id.to_def_id())
                .expect("record owner DefId is valid")
                .expect("record owner DefPath exists");
            let record_symbol = inventory
                .symbols()
                .iter()
                .find(|symbol| symbol.path() == record_path)
                .expect("the record has a canonical inventory symbol");
            let expected_record_hash = sai_hir::DefPathHash::compute(
                &record_def_path,
                &database.packages,
                &database.symbols,
            )
            .expect("record DefPath hashes");
            assert_eq!(
                record_symbol.def_path_hash(),
                Fingerprint::new(expected_record_hash.raw())
            );
            for field_name in &fields {
                let field_symbol = database
                    .symbols
                    .intern(field_name)
                    .expect("field name interns");
                let field_id = def_paths
                    .intern_fields(owner.owner.def_id, &[(field_symbol, 0)])
                    .expect("HIR interns fields below their record owner")
                    .into_iter()
                    .next()
                    .expect("one field definition is returned");
                let field_def_path = database
                    .resolve_def_path(field_id.to_def_id())
                    .expect("field DefId is valid")
                    .expect("field DefPath exists");
                assert_eq!(
                    &field_def_path.data()[..record_def_path.data().len()],
                    record_def_path.data()
                );
                assert_eq!(
                    field_def_path.data().last(),
                    Some(&sai_hir::DisambiguatedDefPathData {
                        data: DefPathData::Field(field_symbol),
                        disambiguator: 0,
                    })
                );
                let field_symbol = inventory
                    .symbols()
                    .iter()
                    .find(|symbol| symbol.path() == format!("{record_path}.field[{field_name}]"))
                    .expect("the field has a canonical inventory path");
                let expected_field_hash = sai_hir::DefPathHash::compute(
                    &field_def_path,
                    &database.packages,
                    &database.symbols,
                )
                .expect("field DefPath hashes");
                assert_eq!(
                    field_symbol.def_path_hash(),
                    Fingerprint::new(expected_field_hash.raw())
                );
            }
            let generic_path_params = generic_params
                .iter()
                .map(|(name, is_const)| {
                    (
                        database.symbols.intern(name).expect("generic name interns"),
                        *is_const,
                        0,
                    )
                })
                .collect::<Vec<_>>();
            let generic_ids = def_paths
                .intern_generic_params(owner.owner.def_id, &generic_path_params)
                .expect("HIR interns generic parameters below their record owner");
            for ((name, _), generic_id) in generic_params.iter().zip(generic_ids) {
                let generic_path = database
                    .resolve_def_path(generic_id.to_def_id())
                    .expect("generic DefId is valid")
                    .expect("generic DefPath exists");
                assert_eq!(
                    &generic_path.data()[..record_def_path.data().len()],
                    record_def_path.data()
                );
                let generic_symbol = inventory
                    .symbols()
                    .iter()
                    .find(|symbol| symbol.path() == format!("{record_path}.generic[{name}]"))
                    .expect("the generic parameter has its canonical path");
                let expected_generic_hash = sai_hir::DefPathHash::compute(
                    &generic_path,
                    &database.packages,
                    &database.symbols,
                )
                .expect("generic DefPath hashes");
                assert_eq!(
                    generic_symbol.def_path_hash(),
                    Fingerprint::new(expected_generic_hash.raw())
                );
            }
        }
    }

    #[test]
    fn module_record_and_field_fingerprints_ignore_renames_and_track_content() {
        let fingerprints_for = |source: &[u8]| {
            let (_, _, _, collection) =
                collect_package_inventory_for_target(source, b"", "wasm32-core");
            let inventory = inventory_symbols(&collection);
            assert_eq!(
                inventory.coverage(),
                &sai_semantic::InventoryCoverage::Complete
            );
            let record = inventory
                .symbols()
                .iter()
                .find(|symbol| symbol.kind() == sai_semantic::SymbolKind::Record)
                .expect("the record is inventoried")
                .fingerprint();
            let field = inventory
                .symbols()
                .iter()
                .find(|symbol| symbol.kind() == sai_semantic::SymbolKind::Field)
                .expect("the record field is inventoried")
                .fingerprint();
            (record, field)
        };
        let original = fingerprints_for(b"type Original { first: U32 }\n");
        let renamed_record = fingerprints_for(b"type Renamed { first: U32 }\n");
        let renamed_field = fingerprints_for(b"type Original { second: U32 }\n");
        let changed_field_type = fingerprints_for(b"type Original { first: U64 }\n");

        assert_eq!(
            original.0, renamed_record.0,
            "renaming the record preserves its declaration fingerprint"
        );
        assert_eq!(
            original.1, renamed_record.1,
            "an unchanged field preserves its declaration fingerprint"
        );
        assert_eq!(
            original.1, renamed_field.1,
            "renaming the field preserves its declaration fingerprint"
        );
        assert_ne!(
            original.0, renamed_field.0,
            "the field name contributes to the parent record fingerprint"
        );
        assert_ne!(
            original.0, changed_field_type.0,
            "field type changes contribute to the record fingerprint"
        );
        assert_ne!(
            original.1, changed_field_type.1,
            "field type changes contribute to the field fingerprint"
        );
    }

    #[test]
    fn module_record_inventory_filters_record_targets_and_rejects_field_targets() {
        let (_, _, _, wasm32) = collect_package_inventory_for_target(
            b"@target(\"wasm64-core\")\ntype Targeted { value: U32 }\n",
            b"",
            "wasm32-core",
        );
        assert_eq!(
            inventory_symbols(&wasm32).coverage(),
            &sai_semantic::InventoryCoverage::Complete
        );
        assert!(inventory_symbols(&wasm32).symbols().is_empty());

        let (_, _, _, wasm64) = collect_package_inventory_for_target(
            b"@target(\"wasm64-core\")\ntype Targeted { value: U32 }\n",
            b"",
            "wasm64-core",
        );
        assert_eq!(
            inventory_symbols(&wasm64).coverage(),
            &sai_semantic::InventoryCoverage::Complete
        );
        assert_eq!(
            inventory_symbols(&wasm64)
                .symbols()
                .iter()
                .map(|symbol| symbol.path())
                .collect::<Vec<_>>(),
            ["acme:phase1.Targeted", "acme:phase1.Targeted.field[value]"]
        );

        let (_, _, _, invalid_record_target) = collect_package_inventory_for_target(
            b"@target(\"wasm32-linux\")\ntype Uncertain {}\n",
            b"",
            "wasm32-core",
        );
        assert!(matches!(
            inventory_symbols(&invalid_record_target).coverage(),
            sai_semantic::InventoryCoverage::Incomplete { reason }
                if reason.contains("target-selection error")
        ));

        let (_, _, _, invalid_field_target) = collect_package_inventory_for_target(
            b"type InvalidField { @target(\"wasm64-core\")\n    value: U32 }\n",
            b"",
            "wasm32-core",
        );
        assert!(
            invalid_field_target
                .scopes()
                .diagnostics
                .iter()
                .any(|diagnostic| diagnostic.code == sai_diagnostics::Code::InvalidAttributeTarget),
            "field @target must remain an attribute-target diagnostic"
        );
        assert!(matches!(
            inventory_symbols(&invalid_field_target).coverage(),
            sai_semantic::InventoryCoverage::Incomplete { reason }
                if reason.contains("attribute or target-selection error")
        ));
    }

    #[test]
    fn module_record_inventory_fails_closed_for_bad_children_and_unsupported_symbols() {
        for source in [
            &b"type Malformed<T:> { value: U32 }\n"[..],
            &b"type MissingFieldName { : U32 }\n"[..],
            &b"type DuplicateFields { value: U32\n    value: U64 }\n"[..],
            &b"type WithImpl {}\nimpl WithImpl { fn method() {} }\n"[..],
            &b"@derive(Clone)\ntype Derived {}\n"[..],
        ] {
            let (_, _, _, collection) =
                collect_package_inventory_for_target(source, b"", "wasm32-core");
            assert!(
                matches!(
                    inventory_symbols(&collection).coverage(),
                    sai_semantic::InventoryCoverage::Incomplete { .. }
                ),
                "unsupported or malformed record fixture must remain incomplete: {}",
                String::from_utf8_lossy(source)
            );
        }

        let (_, _, _, duplicate_fields) = collect_package_inventory_for_target(
            b"type DuplicateFields { value: U32\n    value: U64 }\n",
            b"",
            "wasm32-core",
        );
        assert!(matches!(
            inventory_symbols(&duplicate_fields).coverage(),
            sai_semantic::InventoryCoverage::Incomplete { reason }
                if reason.contains("duplicate field name")
                    || reason.contains("duplicate canonical symbol path")
        ));
    }

    #[test]
    fn module_alias_fingerprints_ignore_names_and_track_the_target_type() {
        let fingerprint_for = |source: &[u8]| {
            let (_, _, _, collection) =
                collect_package_inventory_for_target(source, b"", "wasm32-core");
            let inventory = inventory_symbols(&collection);
            assert_eq!(
                inventory.coverage(),
                &sai_semantic::InventoryCoverage::Complete
            );
            inventory
                .symbols()
                .iter()
                .find(|symbol| symbol.kind() == sai_semantic::SymbolKind::Alias)
                .expect("the fixture alias is inventoried")
                .fingerprint()
        };
        let original = fingerprint_for(b"type Original<T: Bound> = (T,)\n");
        let renamed_alias = fingerprint_for(b"type Renamed<T: Bound> = (T,)\n");
        let changed_target = fingerprint_for(b"type Original<T: Bound> = T\n");

        assert_eq!(
            original, renamed_alias,
            "renaming the alias preserves its declaration fingerprint"
        );
        assert_ne!(
            original, changed_target,
            "the aliased type contributes to the declaration fingerprint"
        );
    }

    #[test]
    fn module_alias_inventory_filters_targets_and_fails_closed_for_duplicates_or_unsupported_forms()
    {
        let source = b"@target(\"wasm64-core\")\ntype Only64<T> = T\n";
        let (_, _, _, wasm32) = collect_package_inventory_for_target(source, b"", "wasm32-core");
        assert_eq!(
            inventory_symbols(&wasm32).coverage(),
            &sai_semantic::InventoryCoverage::Complete
        );
        assert!(inventory_symbols(&wasm32).symbols().is_empty());

        let (_, _, _, wasm64) = collect_package_inventory_for_target(source, b"", "wasm64-core");
        assert_eq!(
            inventory_symbols(&wasm64).coverage(),
            &sai_semantic::InventoryCoverage::Complete
        );
        assert_eq!(
            inventory_symbols(&wasm64)
                .symbols()
                .iter()
                .map(|symbol| symbol.path())
                .collect::<Vec<_>>(),
            ["acme:phase1.Only64", "acme:phase1.Only64.generic[T]"]
        );

        for (source, expected_reason) in [
            (
                &b"type Duplicate = I32\ntype Duplicate = U32\n"[..],
                "duplicate canonical symbol path",
            ),
            (
                &b"type Duplicate<T, T> = T\n"[..],
                "duplicate canonical symbol path",
            ),
        ] {
            let (_, _, _, collection) =
                collect_package_inventory_for_target(source, b"", "wasm32-core");
            let inventory = inventory_symbols(&collection);
            assert!(
                matches!(
                    inventory.coverage(),
                    sai_semantic::InventoryCoverage::Incomplete { reason }
                        if reason.contains(expected_reason)
                ),
                "expected incomplete reason containing {expected_reason:?}, got {:?}",
                inventory.coverage()
            );
        }

        let (_, _, _, malformed) =
            collect_package_inventory_for_target(b"type Malformed<T:> = T\n", b"", "wasm32-core");
        assert!(matches!(
            inventory_symbols(&malformed).coverage(),
            sai_semantic::InventoryCoverage::Incomplete { reason }
                if reason.contains("syntax tree contains recovery or parse errors")
        ));
    }

    #[test]
    fn module_function_inventory_filters_by_target_and_rejects_target_errors() {
        let (_, _, _, wasm32) = collect_package_inventory_for_target(
            b"@target(\"wasm64-core\")\nfn target_only() {}\n@target(\"wasm64-core\")\nconst TARGET_VALUE: Bool = true\n@target(\"wasm64-core\")\neffect target_audit\n",
            b"",
            "wasm32-core",
        );
        let wasm32_inventory = inventory_symbols(&wasm32);
        assert_eq!(
            wasm32_inventory.coverage(),
            &sai_semantic::InventoryCoverage::Complete
        );
        assert!(wasm32_inventory.symbols().is_empty());

        let (_, _, _, wasm64) = collect_package_inventory_for_target(
            b"@target(\"wasm64-core\")\nfn target_only() {}\n@target(\"wasm64-core\")\nconst TARGET_VALUE: Bool = true\n@target(\"wasm64-core\")\neffect target_audit\n",
            b"",
            "wasm64-core",
        );
        let wasm64_inventory = inventory_symbols(&wasm64);
        assert_eq!(
            wasm64_inventory.coverage(),
            &sai_semantic::InventoryCoverage::Complete
        );
        assert_eq!(
            wasm64_inventory
                .symbols()
                .iter()
                .map(|symbol| symbol.path())
                .collect::<Vec<_>>(),
            [
                "acme:phase1.target_only",
                "acme:phase1.TARGET_VALUE",
                "acme:phase1.target_audit"
            ]
        );
        assert_eq!(
            wasm64_inventory
                .symbols()
                .iter()
                .find(|symbol| symbol.path() == "acme:phase1.TARGET_VALUE")
                .expect("the target-selected constant is inventoried")
                .kind(),
            sai_semantic::SymbolKind::Const
        );
        assert_eq!(
            wasm64_inventory
                .symbols()
                .iter()
                .find(|symbol| symbol.path() == "acme:phase1.target_audit")
                .expect("the target-selected effect is inventoried")
                .kind(),
            sai_semantic::SymbolKind::Effect
        );

        let (_, _, _, invalid_target) = collect_package_inventory_for_target(
            b"@target(\"wasm32-linux\")\neffect uncertain_audit\n",
            b"",
            "wasm32-core",
        );
        let incomplete = inventory_symbols(&invalid_target);
        assert!(matches!(
            incomplete.coverage(),
            sai_semantic::InventoryCoverage::Incomplete { reason }
                if reason.contains("target-selection error")
        ));
    }

    #[test]
    fn module_enum_inventory_collects_root_and_nested_generic_variants_and_fields() {
        let (database, module_tree, _, collection) = collect_package_inventory_for_target(
            b"enum Maybe<T, const N: U32> { Nothing, Some(value: T) }\n",
            b"enum Nested<const M: U32> { Empty, Sized(value: U32) }\n",
            "wasm32-core",
        );
        let inventory = inventory_symbols(&collection);
        assert_eq!(
            inventory.coverage(),
            &sai_semantic::InventoryCoverage::Complete
        );
        assert_eq!(
            inventory
                .symbols()
                .iter()
                .map(|symbol| (symbol.path(), symbol.kind()))
                .collect::<Vec<_>>(),
            [
                ("acme:phase1.Maybe", sai_semantic::SymbolKind::Enum),
                (
                    "acme:phase1.Maybe.generic[T]",
                    sai_semantic::SymbolKind::GenericParam
                ),
                (
                    "acme:phase1.Maybe.generic[N]",
                    sai_semantic::SymbolKind::GenericParam
                ),
                (
                    "acme:phase1.Maybe.Nothing",
                    sai_semantic::SymbolKind::Variant
                ),
                ("acme:phase1.Maybe.Some", sai_semantic::SymbolKind::Variant),
                (
                    "acme:phase1.Maybe.Some.field[value]",
                    sai_semantic::SymbolKind::Field
                ),
                ("acme:phase1/child.Nested", sai_semantic::SymbolKind::Enum),
                (
                    "acme:phase1/child.Nested.generic[M]",
                    sai_semantic::SymbolKind::GenericParam
                ),
                (
                    "acme:phase1/child.Nested.Empty",
                    sai_semantic::SymbolKind::Variant
                ),
                (
                    "acme:phase1/child.Nested.Sized",
                    sai_semantic::SymbolKind::Variant
                ),
                (
                    "acme:phase1/child.Nested.Sized.field[value]",
                    sai_semantic::SymbolKind::Field
                ),
            ]
        );

        let def_paths = database
            .def_paths
            .get(&module_tree.package)
            .expect("the package has a DefPath interner");
        let root_file = module_tree.modules[0].file;
        let enum_owner = collection
            .scopes()
            .top_level_owners
            .iter()
            .find(|owner| {
                owner.file == root_file
                    && owner.kind == TopLevelOwnerKind::Enum
                    && database
                        .resolve_def_path(owner.owner.def_id.to_def_id())
                        .ok()
                        .flatten()
                        .is_some_and(|path| {
                            matches!(
                                path.data().last().map(|component| &component.data),
                                Some(DefPathData::TypeNs(name))
                                    if database.symbols.resolve(*name).is_ok_and(|name| name.as_ref() == "Maybe")
                            )
                        })
            })
            .expect("the exact enum owner descriptor exists");
        let enum_path = database
            .resolve_def_path(enum_owner.owner.def_id.to_def_id())
            .expect("enum DefId is valid")
            .expect("enum DefPath exists");
        assert_eq!(enum_path.package(), module_tree.package);
        assert!(matches!(
            enum_path.data().last(),
            Some(component)
                if component.data == DefPathData::TypeNs(database.symbols.intern("Maybe").unwrap())
                    && component.disambiguator == 0
        ));
        let maybe = inventory
            .symbols()
            .iter()
            .find(|symbol| symbol.path() == "acme:phase1.Maybe")
            .expect("the enum symbol exists");
        let enum_hash =
            sai_hir::DefPathHash::compute(&enum_path, &database.packages, &database.symbols)
                .expect("the enum owner path hashes");
        assert_eq!(
            maybe.def_path_hash(),
            sai_stable_hash::Fingerprint::new(enum_hash.raw())
        );

        let type_t = database.symbols.intern("T").expect("T interns");
        let const_n = database.symbols.intern("N").expect("N interns");
        let generics = def_paths
            .intern_generic_params(
                enum_owner.owner.def_id,
                &[(type_t, false, 0), (const_n, true, 0)],
            )
            .expect("generic enum parameters were lowered");
        for (id, component, name) in [
            (generics[0], DefPathData::TypeParam(type_t), "T"),
            (generics[1], DefPathData::ConstParam(const_n), "N"),
        ] {
            let path = database
                .resolve_def_path(id.to_def_id())
                .expect("generic parameter DefId is valid")
                .expect("generic parameter DefPath exists");
            assert_eq!(path.package(), module_tree.package);
            assert_eq!(&path.data()[..enum_path.data().len()], enum_path.data());
            assert!(matches!(
                path.data().last(),
                Some(last) if last.data == component && last.disambiguator == 0
            ));
            let expected_hash =
                sai_hir::DefPathHash::compute(&path, &database.packages, &database.symbols)
                    .expect("generic parameter path hashes");
            let symbol = inventory
                .symbols()
                .iter()
                .find(|symbol| symbol.path() == format!("acme:phase1.Maybe.generic[{name}]"))
                .expect("generic parameter symbol exists");
            assert_eq!(
                symbol.def_path_hash(),
                sai_stable_hash::Fingerprint::new(expected_hash.raw())
            );
        }

        let nothing = database.symbols.intern("Nothing").expect("Nothing interns");
        let some = database.symbols.intern("Some").expect("Some interns");
        let variants = def_paths
            .intern_variants(enum_owner.owner.def_id, &[(nothing, 0), (some, 0)])
            .expect("enum variants were lowered");
        for (id, component, expected_path) in [
            (
                variants[0],
                DefPathData::Variant(nothing),
                "acme:phase1.Maybe.Nothing",
            ),
            (
                variants[1],
                DefPathData::Variant(some),
                "acme:phase1.Maybe.Some",
            ),
        ] {
            let path = database
                .resolve_def_path(id.to_def_id())
                .expect("variant DefId is valid")
                .expect("variant DefPath exists");
            assert_eq!(path.package(), module_tree.package);
            assert_eq!(&path.data()[..enum_path.data().len()], enum_path.data());
            assert!(matches!(
                path.data().last(),
                Some(last) if last.data == component && last.disambiguator == 0
            ));
            let expected_hash =
                sai_hir::DefPathHash::compute(&path, &database.packages, &database.symbols)
                    .expect("variant path hashes");
            let symbol = inventory
                .symbols()
                .iter()
                .find(|symbol| symbol.path() == expected_path)
                .expect("variant symbol exists");
            assert_eq!(
                symbol.def_path_hash(),
                sai_stable_hash::Fingerprint::new(expected_hash.raw())
            );
        }
        let value = database.symbols.intern("value").expect("value interns");
        let field_id = def_paths
            .intern_fields_for_parents(&[(variants[1], value, 0)])
            .expect("record variant field was lowered")[0];
        let field_path = database
            .resolve_def_path(field_id.to_def_id())
            .expect("field DefId is valid")
            .expect("field DefPath exists");
        assert_eq!(field_path.package(), module_tree.package);
        let variant_path = database
            .resolve_def_path(variants[1].to_def_id())
            .expect("variant DefId is valid")
            .expect("variant DefPath exists");
        assert_eq!(
            &field_path.data()[..variant_path.data().len()],
            variant_path.data()
        );
        assert!(matches!(
            field_path.data().last(),
            Some(last)
                if last.data == DefPathData::Field(value) && last.disambiguator == 0
        ));
        let field_hash =
            sai_hir::DefPathHash::compute(&field_path, &database.packages, &database.symbols)
                .expect("field path hashes");
        assert_eq!(
            inventory
                .symbols()
                .iter()
                .find(|symbol| symbol.path() == "acme:phase1.Maybe.Some.field[value]")
                .expect("record variant field symbol exists")
                .def_path_hash(),
            sai_stable_hash::Fingerprint::new(field_hash.raw())
        );
    }

    #[test]
    fn module_enum_inventory_collects_tuple_payload_fields_and_exact_def_paths() {
        let (database, module_tree, snapshot, collection) = collect_package_inventory_for_target(
            b"enum Packet { Unit, Pair(U8, U32), Named(code: U16) }\n",
            b"enum Nested { Tuple(U64, U8) }\n",
            "wasm32-core",
        );
        for module in &module_tree.modules {
            let parsed = sai_syntax::parse(&snapshot, module.file)
                .expect("the enum fixture has a parse snapshot");
            assert!(
                parsed.parser_diagnostics().is_empty(),
                "the tuple enum fixture must parse cleanly: {:#?}",
                parsed.parser_diagnostics()
            );
        }
        let inventory = inventory_symbols(&collection);
        assert_eq!(
            inventory.coverage(),
            &sai_semantic::InventoryCoverage::Complete
        );
        for path in [
            "acme:phase1.Packet",
            "acme:phase1.Packet.Unit",
            "acme:phase1.Packet.Pair",
            "acme:phase1.Packet.Pair.field[0]",
            "acme:phase1.Packet.Pair.field[1]",
            "acme:phase1.Packet.Named",
            "acme:phase1.Packet.Named.field[code]",
            "acme:phase1/child.Nested",
            "acme:phase1/child.Nested.Tuple",
            "acme:phase1/child.Nested.Tuple.field[0]",
            "acme:phase1/child.Nested.Tuple.field[1]",
        ] {
            assert!(
                inventory
                    .symbols()
                    .iter()
                    .any(|symbol| symbol.path() == path),
                "missing tuple-enum inventory path {path}"
            );
        }
        for path in [
            "acme:phase1.Packet.Pair.field[0]",
            "acme:phase1.Packet.Pair.field[1]",
            "acme:phase1/child.Nested.Tuple.field[0]",
            "acme:phase1/child.Nested.Tuple.field[1]",
        ] {
            assert_eq!(
                inventory
                    .symbols()
                    .iter()
                    .find(|symbol| symbol.path() == path)
                    .expect("tuple payload field is inventoried")
                    .kind(),
                sai_semantic::SymbolKind::Field
            );
        }

        let def_paths = database
            .def_paths
            .get(&module_tree.package)
            .expect("the package has a DefPath interner");
        let packet_owner = collection
            .scopes()
            .top_level_owners
            .iter()
            .find(|owner| {
                owner.kind == TopLevelOwnerKind::Enum
                    && database
                        .resolve_def_path(owner.owner.def_id.to_def_id())
                        .ok()
                        .flatten()
                        .is_some_and(|path| {
                            matches!(
                                path.data().last().map(|component| &component.data),
                                Some(DefPathData::TypeNs(name))
                                    if database.symbols.resolve(*name).is_ok_and(|name| name.as_ref() == "Packet")
                            )
                        })
            })
            .expect("the Packet enum owner exists");
        let packet_path = database
            .resolve_def_path(packet_owner.owner.def_id.to_def_id())
            .expect("enum DefId is valid")
            .expect("enum DefPath exists");
        let pair = database.symbols.intern("Pair").expect("Pair interns");
        let pair_id = def_paths
            .intern_variants(packet_owner.owner.def_id, &[(pair, 0)])
            .expect("the tuple variant DefPath is interned")[0];
        let pair_path = database
            .resolve_def_path(pair_id.to_def_id())
            .expect("variant DefId is valid")
            .expect("variant DefPath exists");
        assert_eq!(
            &pair_path.data()[..packet_path.data().len()],
            packet_path.data()
        );
        assert!(matches!(
            pair_path.data().last(),
            Some(last) if last.data == DefPathData::Variant(pair) && last.disambiguator == 0
        ));
        let tuple_fields = [
            database.symbols.intern("0").expect("field 0 interns"),
            database.symbols.intern("1").expect("field 1 interns"),
        ];
        let tuple_field_ids = def_paths
            .intern_fields_for_parents(&[
                (pair_id, tuple_fields[0], 0),
                (pair_id, tuple_fields[1], 0),
            ])
            .expect("tuple field DefPaths are interned");
        for (index, (field_id, field_name)) in tuple_field_ids.iter().zip(tuple_fields).enumerate()
        {
            let field_path = database
                .resolve_def_path(field_id.to_def_id())
                .expect("field DefId is valid")
                .expect("field DefPath exists");
            assert_eq!(field_path.package(), module_tree.package);
            assert_eq!(
                &field_path.data()[..pair_path.data().len()],
                pair_path.data()
            );
            assert!(matches!(
                field_path.data().last(),
                Some(last) if last.data == DefPathData::Field(field_name) && last.disambiguator == 0
            ));
            let expected_hash =
                sai_hir::DefPathHash::compute(&field_path, &database.packages, &database.symbols)
                    .expect("tuple field DefPath hash is computable");
            let symbol = inventory
                .symbols()
                .iter()
                .find(|symbol| symbol.path() == format!("acme:phase1.Packet.Pair.field[{index}]"))
                .expect("tuple field symbol exists");
            assert_eq!(
                symbol.def_path_hash(),
                sai_stable_hash::Fingerprint::new(expected_hash.raw())
            );
        }
    }

    #[test]
    fn module_enum_inventory_fingerprints_ignore_renames_and_track_discriminants_and_payloads() {
        let fingerprint = |source: &[u8], kind: sai_semantic::SymbolKind| {
            let (_, _, _, collection) =
                collect_package_inventory_for_target(source, b"", "wasm32-core");
            let inventory = inventory_symbols(&collection);
            assert_eq!(
                inventory.coverage(),
                &sai_semantic::InventoryCoverage::Complete
            );
            inventory
                .symbols()
                .iter()
                .find(|symbol| symbol.kind() == kind)
                .expect("the requested symbol kind is inventoried")
                .fingerprint()
        };

        let enum_original =
            fingerprint(b"enum First { A = 1, B }\n", sai_semantic::SymbolKind::Enum);
        let enum_renamed = fingerprint(
            b"enum Renamed { A = 1, B }\n",
            sai_semantic::SymbolKind::Enum,
        );
        let enum_discriminant =
            fingerprint(b"enum First { A = 2, B }\n", sai_semantic::SymbolKind::Enum);
        assert_eq!(enum_original, enum_renamed);
        assert_ne!(enum_original, enum_discriminant);

        let variant_original =
            fingerprint(b"enum E { A = 1 }\n", sai_semantic::SymbolKind::Variant);
        let variant_renamed = fingerprint(b"enum E { B = 1 }\n", sai_semantic::SymbolKind::Variant);
        let variant_discriminant =
            fingerprint(b"enum E { A = 2 }\n", sai_semantic::SymbolKind::Variant);
        assert_eq!(variant_original, variant_renamed);
        assert_ne!(variant_original, variant_discriminant);

        let variant_payload = fingerprint(
            b"enum E { Data(value: I32) }\n",
            sai_semantic::SymbolKind::Variant,
        );
        let variant_payload_changed = fingerprint(
            b"enum E { Data(value: U32) }\n",
            sai_semantic::SymbolKind::Variant,
        );
        let field_original = fingerprint(
            b"enum E { Data(value: I32) }\n",
            sai_semantic::SymbolKind::Field,
        );
        let field_renamed = fingerprint(
            b"enum E { Data(item: I32) }\n",
            sai_semantic::SymbolKind::Field,
        );
        let field_payload_changed = fingerprint(
            b"enum E { Data(value: U32) }\n",
            sai_semantic::SymbolKind::Field,
        );
        assert_ne!(variant_payload, variant_payload_changed);
        assert_eq!(field_original, field_renamed);
        assert_ne!(field_original, field_payload_changed);

        let tuple_field_fingerprint = |source: &[u8], index: usize| {
            let (_, _, _, collection) =
                collect_package_inventory_for_target(source, b"", "wasm32-core");
            let inventory = inventory_symbols(&collection);
            assert_eq!(
                inventory.coverage(),
                &sai_semantic::InventoryCoverage::Complete
            );
            let suffix = format!(".field[{index}]");
            inventory
                .symbols()
                .iter()
                .find(|symbol| {
                    symbol.kind() == sai_semantic::SymbolKind::Field
                        && symbol.path().ends_with(&suffix)
                })
                .expect("the tuple payload field is inventoried")
                .fingerprint()
        };
        let tuple_field_0 = tuple_field_fingerprint(b"enum E { Data(I32, U32) }\n", 0);
        let tuple_field_0_renamed = tuple_field_fingerprint(b"enum E { Changed(I32, U32) }\n", 0);
        let tuple_field_0_sibling_changed =
            tuple_field_fingerprint(b"enum E { Data(I32, U16) }\n", 0);
        let tuple_field_1 = tuple_field_fingerprint(b"enum E { Data(I32, U32) }\n", 1);
        let tuple_field_1_changed = tuple_field_fingerprint(b"enum E { Data(I32, U16) }\n", 1);
        assert_eq!(tuple_field_0, tuple_field_0_renamed);
        assert_eq!(tuple_field_0, tuple_field_0_sibling_changed);
        assert_ne!(tuple_field_1, tuple_field_1_changed);
    }

    #[test]
    fn module_enum_inventory_rejects_duplicate_variant_and_field_paths() {
        for source in [
            &b"enum Duplicate { Same, Same(value: I32) }\n"[..],
            &b"enum Duplicate { Data(value: I32, value: U32) }\n"[..],
        ] {
            let (_, _, _, collection) =
                collect_package_inventory_for_target(source, b"", "wasm32-core");
            let inventory = inventory_symbols(&collection);
            assert!(matches!(
                inventory.coverage(),
                sai_semantic::InventoryCoverage::Incomplete { reason }
                    if reason.contains("duplicate canonical symbol path")
            ));
            let duplicate_paths = inventory.symbols().iter().fold(
                HashMap::<&str, usize>::new(),
                |mut counts, symbol| {
                    *counts.entry(symbol.path()).or_default() += 1;
                    counts
                },
            );
            assert!(
                duplicate_paths.values().any(|count| *count > 1),
                "the incomplete inventory retains both candidate declarations"
            );
        }
    }

    #[test]
    fn module_enum_inventory_fails_closed_for_malformed_and_invalid_member_attributes() {
        for (source, expected_reason, expect_parser_diagnostic) in [
            (
                &b"enum Malformed<T:> { Ready }\n"[..],
                "syntax tree contains recovery or parse errors",
                false,
            ),
            (
                &b"enum InvalidGenericAttribute<@target(\"wasm64-core\") T> { Ready }\n"[..],
                "enum syntax node has a parser diagnostic",
                true,
            ),
            (
                &b"enum InvalidVariantAttribute { @cold Ready }\n"[..],
                "target-filtered module has an attribute or target-selection error",
                false,
            ),
            (
                &b"enum InvalidFieldAttribute { Item(@field value: I32) }\n"[..],
                "enum syntax node has a parser diagnostic",
                true,
            ),
            (
                &b"enum InvalidMemberTarget { @target(\"wasm32-core\") Ready }\n"[..],
                "target-filtered module has an attribute or target-selection error",
                false,
            ),
        ] {
            let (_, module_tree, snapshot, collection) =
                collect_package_inventory_for_target(source, b"", "wasm32-core");
            if expect_parser_diagnostic {
                let parsed = sai_syntax::parse(&snapshot, module_tree.modules[0].file)
                    .expect("the invalid attribute fixture parses with a diagnostic");
                let enum_syntax = parsed
                    .root
                    .descendants()
                    .find_map(sai_syntax::ast::EnumDecl::cast)
                    .expect("the diagnostic fixture has an enum declaration");
                let enum_range = enum_syntax.syntax().text_range();
                assert!(
                    parsed.parser_diagnostics().iter().any(|diagnostic| {
                        diagnostic.code == sai_diagnostics::Code::InvalidAttributeTarget
                            && diagnostic.primary().is_some_and(|primary| {
                                primary.span.range.start() <= enum_range.end()
                                    && enum_range.start() <= primary.span.range.end()
                            })
                    }),
                    "the parser diagnostic must overlap the enclosing enum owner syntax"
                );
            }
            assert!(
                matches!(
                    inventory_symbols(&collection).coverage(),
                    sai_semantic::InventoryCoverage::Incomplete { reason }
                        if reason.contains(expected_reason)
                ),
                "{source:?}: {:#?}",
                inventory_symbols(&collection).coverage()
            );
        }

        let (_, _, _, invalid_target) = collect_package_inventory_for_target(
            b"@target(\"wasm32-linux\")\nenum Uncertain { Ready }\n",
            b"",
            "wasm32-core",
        );
        assert!(matches!(
            inventory_symbols(&invalid_target).coverage(),
            sai_semantic::InventoryCoverage::Incomplete { reason }
                if reason.contains("target-selection error")
        ));
    }

