    #[test]
    fn function_owner_adapter_resolves_locals_with_each_modules_aliases() {
        let root = concat!(
            "use acme:phase1/child as child_alias\n",
            "@target(\"wasm64-core\")\n",
            "use acme:phase1/child as hidden_alias\n",
            "fn root_fn(child_alias: Bool) { let next = child_alias; next }\n",
            "fn filtered_fn(hidden_alias: Bool) { hidden_alias }\n",
        );
        let child = "pub fn child_fn(child_alias: Bool) { child_alias }\n";
        let (mut database, module_tree, snapshot, _) =
            phase1_fixture(root.as_bytes(), child.as_bytes());
        let target_cfg = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let collection = database
            .collect_phase1_package_scopes_collection(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
            )
            .expect("current-snapshot Phase 1 collection succeeds");

        let resolved = database
            .resolve_function_owner_analyses(&collection, &module_tree, &snapshot)
            .expect("function owner analyses succeed");
        assert_eq!(resolved.owners().len(), 3);
        assert!(
            resolved.owners().iter().all(|owner| owner
                .module_path_diagnostics()
                .expect("package-local calls retain their own typed path channel")
                .is_none()),
            "package-local calls do not construct snapshot-bound member diagnostics"
        );

        let root_local = resolved.owners()[0]
            .local_resolution()
            .expect("root local resolution succeeds")
            .expect("root function has a body");
        assert_eq!(root_local.paths.len(), 2);
        assert_eq!(root_local.bindings.len(), 2);
        assert!(
            root_local
                .paths
                .values()
                .all(|path| matches!(path.base, Res::Local(_)))
        );
        assert_eq!(
            root_local
                .diagnostics
                .iter()
                .filter(|diagnostic| diagnostic.code == sai_diagnostics::Code::ShadowsModule)
                .count(),
            1,
            "the root module alias shadows the first function's parameter"
        );

        let filtered_local = resolved.owners()[1]
            .local_resolution()
            .expect("filtered local resolution succeeds")
            .expect("filtered function has a body");
        assert_eq!(filtered_local.paths.len(), 1);
        assert!(
            !filtered_local
                .diagnostics
                .iter()
                .any(|diagnostic| diagnostic.code == sai_diagnostics::Code::ShadowsModule),
            "a target-filtered module alias is absent from the module scope"
        );

        let child_local = resolved.owners()[2]
            .local_resolution()
            .expect("child local resolution succeeds")
            .expect("child function has a body");
        assert_eq!(child_local.paths.len(), 1);
        assert!(
            !child_local
                .diagnostics
                .iter()
                .any(|diagnostic| diagnostic.code == sai_diagnostics::Code::ShadowsModule),
            "the root module's alias does not leak into the child module"
        );
    }

    #[test]
    fn function_body_type_check_accepts_only_a_direct_parameter_tail() {
        let root = concat!(
            "pub fn identity(value: I32) -> I32 { value }\n",
            "pub fn mismatch(value: I32) -> Bool { value }\n",
            "pub fn discard(value: I32) { value }\n",
            "pub fn discard_explicit(value: I32) -> () { value }\n",
            "pub fn computed(value: I32) -> I32 { value + 1 }\n",
            "pub fn self_param(self: I32) -> I32 { self }\n",
            "pub fn string_parameter_return(value: Str) -> Str { \"text\" }\n",
            "pub fn local_str_return() -> Str {\n    let value = \"text\"\n    value\n}\n",
            "pub fn str_param_to_integer(value: Str) -> I32 { value }\n",
            "pub fn integer_param_to_str(value: I32) -> Str { value }\n",
            "pub fn str_param_to_unit(value: Str) -> () { value }\n",
            "pub fn str_param_without_return(value: Str) { value }\n",
            "pub fn mutable_str_identity(var value: Str) -> Str { value }\n",
            "pub fn self_str_identity(self: Str) -> Str { self }\n",
            "pub fn multi_str_identity(value: Str, other: Str) -> Str { other }\n",
            "type Text = Str\n",
            "pub fn alias_str_identity(value: Text) -> Text { value }\n",
            "pub fn raw_str_identity(value: r#Str) -> r#Str { value }\n",
            "type Str = I32\n",
            "pub fn shadowed_str_identity(value: Str) -> Str { value }\n",
            "pub fn local_str_copy(value: Str) -> Str {\n    let copied = value\n    copied\n}\n",
            "pub fn computed_str(value: Str) -> Str { value + \"\" }\n",
            "pub fn generic_str_identity<T>(value: Str) -> Str { value }\n",
            concat!(
                "type StrOwner { marker: Bool }\n",
                "impl StrOwner {\n",
                "    fn string_identity(self: borrow Self) -> Str { \"text\" }\n",
                "}\n",
            ),
            "pub fn mutable_identity(var value: I32) -> I32 { value }\n",
            "pub fn identityValue(value: I32) -> I32 { value }\n",
            "pub fn parameter_case(valueItem: I32) -> I32 { valueItem }\n",
            "pub fn identité(value: I32) -> I32 { value }\n",
            "pub fn non_ascii_param(valué: I32) -> I32 { valué }\n",
            "pub fn r#raw_function(value: I32) -> I32 { value }\n",
            "pub fn raw_parameter(r#value: I32) -> I32 { r#value }\n",
            "pub fn raw_tail(value: I32) -> I32 { r#value }\n",
            "pub fn raw_type(value: r#I32) -> r#I32 { value }\n",
        );
        let (mut database, module_tree, snapshot, _) = phase1_fixture(root.as_bytes(), b"");
        let target_cfg = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let collection = database
            .collect_phase1_package_scopes_collection(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
            )
            .expect("current-snapshot Phase 1 collection succeeds");
        let resolved = database
            .resolve_function_owner_analyses(&collection, &module_tree, &snapshot)
            .expect("function owner analyses succeed");

        assert_eq!(resolved.owners().len(), 30);
        assert!(matches!(
            resolved.owners()[0]
                .body_type_check()
                .expect("identity body check succeeds"),
            FunctionBodyTypeCheck::Supported { diagnostics } if diagnostics.is_empty()
        ));

        let mismatch = resolved.owners()[1]
            .body_type_check()
            .expect("mismatched body check succeeds");
        let FunctionBodyTypeCheck::Supported { diagnostics } = mismatch else {
            panic!("primitive parameter tail is in the supported checking slice");
        };
        assert_eq!(diagnostics.len(), 1);
        assert_eq!(diagnostics[0].code, sai_diagnostics::Code::TypeMismatch);
        assert_eq!(diagnostics[0].message, "expected `Bool`, found `I32`");
        let value_start = root
            .find("pub fn mismatch(value: I32) -> Bool { ")
            .expect("mismatched body exists") as u32
            + "pub fn mismatch(value: I32) -> Bool { ".len() as u32;
        assert_eq!(
            diagnostics[0]
                .primary()
                .expect("type mismatch points at the body tail")
                .span
                .range,
            sai_diagnostics::TextRange::new(
                sai_diagnostics::TextSize::new(value_start),
                sai_diagnostics::TextSize::new(value_start + "value".len() as u32),
            )
            .expect("body tail range is ordered")
        );

        for owner in &resolved.owners()[2..4] {
            assert!(matches!(
                owner
                    .body_type_check()
                    .expect("unit-returning body check succeeds"),
                FunctionBodyTypeCheck::Supported { diagnostics } if diagnostics.is_empty()
            ));
        }

        for owner in &resolved.owners()[4..] {
            assert!(matches!(
                owner
                    .body_type_check()
                    .expect("unsupported body check succeeds"),
                FunctionBodyTypeCheck::Unsupported
            ));
        }
    }

