    #[test]
    fn function_owner_adapter_resolves_module_paths_after_locals_and_generics() {
        let root = concat!(
            "use acme:phase1/child as child_alias\n",
            "use acme:phase1/child.{child_fn}\n",
            "const RootValue: Bool = true\n",
            "fn helper() {}\n",
            "fn same_module() { helper }\n",
            "fn imported() { child_fn }\n",
            "fn constant() { RootValue }\n",
            "fn qualified() { child_alias.child_fn() }\n",
            "fn local(helper: Bool) { helper }\n",
            "fn generic<RootValue>() { RootValue }\n",
            "fn unresolved() -> Bool requires { contract_missing } ",
            "{ not_in_scope + also_missing }\n",
        );
        let child = "pub fn child_fn() { RootValue }\n";
        let (mut database, module_tree, snapshot, _) =
            phase1_fixture(root.as_bytes(), child.as_bytes());
        let target_cfg = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let collection = database
            .collect_phase1_package_scopes_collection(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
            )
            .expect("function module scopes collect");

        let root_scope = collection
            .scopes()
            .module(ModuleId::ROOT)
            .expect("root module scope exists");
        let binding_for = |name: &str| {
            root_scope
                .scope
                .iter()
                .find_map(|(symbol, binding)| {
                    (database.resolve_symbol(*symbol).ok()?.as_ref() == name).then_some(binding.res)
                })
                .unwrap_or_else(|| panic!("root module contains `{name}`"))
        };
        let helper = binding_for("helper");
        let imported = binding_for("child_fn");
        let child_alias = binding_for("child_alias");
        let root_value = binding_for("RootValue");
        let root_value_symbol = root_scope
            .scope
            .keys()
            .copied()
            .find(|symbol| {
                database
                    .resolve_symbol(*symbol)
                    .is_ok_and(|name| name.as_ref() == "RootValue")
            })
            .expect("RootValue symbol is in the root module scope");

        let resolved = database
            .resolve_function_owner_analyses(&collection, &module_tree, &snapshot)
            .expect("function owner analysis resolves local and module paths");
        assert_eq!(resolved.owners().len(), 9);
        assert_eq!(
            resolved.owners()[1]
                .module_resolution()
                .expect("same-module fallback succeeds")
                .expect("helper body has a module result")
                .paths
                .values()
                .map(|path| path.base)
                .collect::<Vec<_>>(),
            [helper]
        );
        assert_eq!(
            resolved.owners()[2]
                .module_resolution()
                .expect("item-import fallback succeeds")
                .expect("imported body has a module result")
                .paths
                .values()
                .map(|path| path.base)
                .collect::<Vec<_>>(),
            [imported]
        );
        assert_eq!(
            resolved.owners()[3]
                .module_resolution()
                .expect("constant fallback succeeds")
                .expect("constant body has a module result")
                .paths
                .values()
                .map(|path| path.base)
                .collect::<Vec<_>>(),
            [root_value]
        );
        assert_eq!(
            resolved.owners()[4]
                .module_resolution()
                .expect("module-alias fallback succeeds")
                .expect("qualified body has a module result")
                .paths
                .values()
                .map(|path| path.base)
                .collect::<Vec<_>>(),
            [child_alias]
        );
        assert!(
            matches!(helper, Res::Def(DefKind::Fn, _))
                && matches!(imported, Res::Def(DefKind::Fn, _))
                && matches!(child_alias, Res::Def(DefKind::Module, _))
                && matches!(root_value, Res::Def(DefKind::Const, _))
        );

        let local_owner = &resolved.owners()[5];
        let local = local_owner
            .local_resolution()
            .expect("local lookup succeeds")
            .expect("local owner has a body");
        assert!(
            local
                .paths
                .values()
                .all(|path| matches!(path.base, Res::Local(_)))
        );
        assert!(
            local_owner
                .module_resolution()
                .expect("module fallback succeeds")
                .expect("local owner has a module result")
                .paths
                .is_empty(),
            "a local binding wins before the same-spelled module function"
        );

        let generic_owner = resolved.owners()[6]
            .module_resolution()
            .expect("generic-shadowed module lookup succeeds")
            .expect("generic owner has a module result");
        assert!(generic_owner.paths.is_empty());
        assert!(
            generic_owner
                .deferred_paths
                .iter()
                .any(|path| path.name == root_value_symbol),
            "an in-scope generic is left for generic lookup instead of being captured by the constant"
        );

        let unresolved_owner = resolved.owners()[7]
            .module_resolution()
            .expect("module miss remains a successful partial pass")
            .expect("unresolved owner has a module result");
        assert!(unresolved_owner.paths.is_empty());
        let unresolved_names = unresolved_owner
            .deferred_paths
            .iter()
            .map(|path| {
                database
                    .resolve_symbol(path.name)
                    .expect("deferred name belongs to this symbol interner")
                    .to_string()
            })
            .collect::<Vec<_>>();
        assert_eq!(
            unresolved_names,
            [
                "contract_missing".to_owned(),
                "not_in_scope".to_owned(),
                "also_missing".to_owned()
            ],
            "contract and body misses remain deferred in source order"
        );

        let mut errored_scope = root_scope.clone();
        let diagnosed_candidate = unresolved_owner.deferred_paths[0];
        errored_scope.scope.insert(
            diagnosed_candidate.name,
            sai_resolve::package_scopes::Binding {
                res: Res::Err,
                name_span: sai_diagnostics::Span::new(
                    diagnosed_candidate.span.file,
                    diagnosed_candidate.span.range,
                ),
                origin: BindingOrigin::Decl,
                visibility: sai_hir::Visibility::Private,
            },
        );
        let local_resolution = resolved.owners()[7]
            .local_resolution()
            .expect("local resolution succeeds")
            .expect("unresolved function has a local result");
        let error_binding_resolution = resolve_owner_module_paths(
            local_resolution,
            &errored_scope,
            &std::collections::HashSet::new(),
        );
        assert_eq!(
            error_binding_resolution
                .paths
                .get(&diagnosed_candidate.hir_id)
                .map(|path| path.base),
            Some(Res::Err),
            "already-diagnosed module names resolve to the error sentinel"
        );
        let remaining_misses = error_binding_resolution
            .deferred_paths
            .iter()
            .map(|path| {
                database
                    .resolve_symbol(path.name)
                    .expect("deferred name belongs to this symbol interner")
                    .to_string()
            })
            .collect::<Vec<_>>();
        assert_eq!(
            remaining_misses,
            ["not_in_scope".to_owned(), "also_missing".to_owned()]
        );

        let child_owner = resolved.owners()[8]
            .module_resolution()
            .expect("child module lookup succeeds")
            .expect("child owner has a module result");
        assert!(child_owner.paths.is_empty());
        assert_eq!(
            child_owner.deferred_paths.len(),
            1,
            "a name from the root module does not leak into a child module's unqualified scope"
        );
        assert_eq!(child_owner.deferred_paths[0].name, root_value_symbol);
    }

    #[test]
    fn function_owner_adapter_resolves_type_path_heads_separately() {
        let root = concat!(
            "use acme:phase1/child as child_alias\n",
            "type Array<T> = T\n",
            "fn typed<T, const Count: U32>(value: T, optional: Option<T>, ",
            "qualified: child_alias.Widget, ",
            "interface_member: child_alias.api.Request.Associated, ",
            "missing_member: child_alias.MissingType) -> U32 { let local: U32 = 0; child_alias }\n",
            "fn const_type_shadow<const U32: Bool>(value: U32) {}\n",
            "fn module_type_shadow(value: Array<U32>) {}\n",
            "fn bodyless<T>(value: T) -> U32\n",
        );
        let child = concat!(
            "pub type Widget = U32\n",
            "pub interface api {\n",
            "  type Request = U32\n",
            "}\n",
            "pub fn child_fn() {}\n",
        );
        let (mut database, module_tree, snapshot, _) =
            phase1_fixture(root.as_bytes(), child.as_bytes());
        let target_cfg = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let collection = database
            .collect_phase1_package_scopes_collection(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
            )
            .expect("function module scopes collect");
        let root_scope = collection
            .scopes()
            .module(ModuleId::ROOT)
            .expect("root module scope exists");
        let symbol = |name: &str| {
            root_scope
                .scope
                .keys()
                .copied()
                .find(|symbol| {
                    database
                        .resolve_symbol(*symbol)
                        .is_ok_and(|resolved| resolved.as_ref() == name)
                })
                .unwrap_or_else(|| panic!("root module contains `{name}`"))
        };
        let child_alias = root_scope
            .scope
            .get(&symbol("child_alias"))
            .expect("child alias has a binding")
            .res;
        let child_module_scope = collection
            .scopes()
            .module(ModuleId::from_raw(1))
            .expect("child module scope exists");
        let widget_name = database
            .symbols
            .intern("Widget")
            .expect("Widget name is interned");
        let widget_binding = child_module_scope
            .members
            .get(&widget_name)
            .expect("child Widget alias is declared");
        let api_name = database
            .symbols
            .intern("api")
            .expect("api name is interned");
        let request_name = database
            .symbols
            .intern("Request")
            .expect("Request name is interned");
        let request_binding = collection
            .scopes()
            .interfaces
            .iter()
            .find_map(|(def_id, interface)| {
                (child_module_scope
                    .members
                    .get(&api_name)
                    .is_some_and(|binding| binding.res == Res::Def(DefKind::Interface, *def_id)))
                .then(|| interface.members.get(&request_name))
                .flatten()
            })
            .expect("interface api declares Request");

        let resolved = database
            .resolve_function_owner_analyses(&collection, &module_tree, &snapshot)
            .expect("function owner analysis resolves type path heads");
        let generic_def_id = |owner: OwnerId, name: &str, is_const: bool| {
            let name = database
                .symbols
                .intern(name)
                .expect("generic name is interned");
            database
                .def_paths
                .get(&owner.def_id.package())
                .expect("package definition paths are available")
                .intern_generic_params(owner.def_id, &[(name, is_const, 0)])
                .expect("function generic has a stable definition identity")[0]
                .to_def_id()
        };
        let typed = &resolved.owners()[0];
        let type_generic = generic_def_id(typed.owner(), "T", false);
        let type_paths = typed
            .type_path_resolution()
            .expect("type path analysis succeeds")
            .expect("typed function has a type path result");
        assert!(
            type_paths
                .paths()
                .values()
                .any(|path| path.base == Res::Def(DefKind::TyParam, type_generic)),
            "function type parameters resolve in signature type paths"
        );
        assert_eq!(
            type_paths
                .paths()
                .values()
                .filter(|path| path.base == Res::PrimTy(sai_resolve::prelude::PrimTy::U32))
                .count(),
            3,
            "primitive type heads resolve in the const parameter, return type, and body annotation"
        );
        assert!(
            type_paths.paths().values().any(|path| {
                path.base == widget_binding.res
                    && path.resolved_segments == 2
                    && path.segment_count == 2
            }),
            "qualified local module prefixes resolve through their first type member"
        );
        assert!(
            type_paths.paths().values().any(|path| {
                path.base == request_binding.res
                    && path.resolved_segments == 3
                    && path.segment_count == 4
            }),
            "interface members resolve after a local module prefix and leave type-relative suffixes"
        );
        assert_eq!(
            type_paths.module_path_errors().len(),
            1,
            "only the missing local member produces a qualified-path error"
        );
        let missing_offset = root
            .find("child_alias.MissingType")
            .expect("missing type member path exists");
        let missing_error = type_paths
            .module_path_errors()
            .iter()
            .find_map(|path_error| match path_error.error() {
                ModulePathError::MissingMember {
                    name,
                    segment_index,
                    span,
                    ..
                } if database
                    .resolve_symbol(name)
                    .is_ok_and(|name| name.as_ref() == "MissingType") =>
                {
                    Some((*path_error, segment_index, span))
                }
                _ => None,
            })
            .expect("unknown local member is retained as a typed path error");
        assert_eq!(missing_error.1, 0);
        let missing_start = missing_offset + "child_alias.".len();
        assert_eq!(missing_error.2.file, module_tree.modules[0].file);
        assert_eq!(
            missing_error.2.range.start().to_usize(),
            missing_start,
            "the missing-member error starts at the exact suffix segment"
        );
        assert_eq!(
            missing_error.2.range.end().to_usize(),
            missing_start + "MissingType".len(),
            "the missing-member error covers only the exact suffix segment"
        );
        assert_eq!(
            type_paths.paths().get(&missing_error.0.hir_id()),
            Some(&PathRes {
                base: Res::Err,
                resolved_segments: 2,
                segment_count: 2,
            }),
            "the missing member path resolves to an error sentinel through that segment"
        );
        assert!(
            type_paths.deferred_paths().iter().any(|path| {
                database
                    .resolve_symbol(path.name)
                    .is_ok_and(|name| name.as_ref() == "Option")
            }),
            "non-primitive Prelude candidates remain deferred"
        );
        let module_paths = typed
            .module_resolution()
            .expect("expression module analysis succeeds")
            .expect("typed function has a module result");
        assert_eq!(module_paths.paths.len(), 1);
        assert_eq!(
            module_paths.paths.values().next().map(|path| path.base),
            Some(child_alias),
            "type candidates stay out of expression module resolution"
        );

        let const_type_shadow = &resolved.owners()[1];
        let const_generic = generic_def_id(const_type_shadow.owner(), "U32", true);
        let const_type_paths = const_type_shadow
            .type_path_resolution()
            .expect("const generic type analysis succeeds")
            .expect("const generic function has a type path result");
        assert!(
            const_type_paths
                .paths()
                .values()
                .any(|path| path.base == Res::Def(DefKind::ConstParam, const_generic)),
            "const generic names retain their definition kind in type position"
        );

        let module_type_shadow = &resolved.owners()[2];
        let module_type_paths = module_type_shadow
            .type_path_resolution()
            .expect("module type shadow analysis succeeds")
            .expect("module type shadow function has a type path result");
        assert!(
            module_type_paths
                .paths()
                .values()
                .any(|path| matches!(path.base, Res::Def(DefKind::Alias, _))),
            "the exact module binding takes precedence over a primitive Prelude entry"
        );

        let bodyless = &resolved.owners()[3];
        assert!(
            bodyless
                .type_path_resolution()
                .expect("bodyless function signature type analysis succeeds")
                .is_some(),
            "signature type paths resolve even when the function has no body"
        );
        assert!(
            bodyless
                .local_resolution()
                .expect("bodyless local result succeeds")
                .is_none(),
            "bodyless functions continue to have no local body result"
        );
    }

    #[test]
    fn function_owner_test_only_diagnostics_follow_module_origins() {
        let root = concat!(
            "use acme:test-support/fixtures as fixture\n",
            "use acme:test-support/fixtures as fs\n",
            "use acme:test-support/fixtures.{Fixture}\n",
            "use acme:test-support/fixtures.{flag}\n",
            "fn repeated() { fixture && fixture }\n",
            "fn imported_item() { flag }\n",
            "fn generic<Fixture>() { Fixture }\n",
            "fn local() { let fixture = true; fixture }\n",
            "fn signature<T: Fixture>(fixture: Fixture, nested: Container<Fixture>, callback: fn() effects { fixture.read }) -> fixture.Type where T: Fixture effects { fixture.write } { let typed: Fixture = fixture as Fixture; identity<Fixture>(typed) }\n",
            "fn generic_type<Fixture>(value: Fixture) { Fixture }\n",
            "fn builtin_effect_root() effects { fs.read } { true }\n",
        );
        let (mut database, module_tree, snapshot, _) = phase1_fixture(root.as_bytes(), b"");
        let target_cfg = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let manifest = Arc::<[u8]>::from(
            &b"package acme:phase1 @ 1.0.0\n\
              requires test { acme:test-support @ ^1 }\n"[..],
        );
        let mut collection = database
            .collect_phase1_package_scopes_with_manifest_and_foreign_scopes(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
                manifest,
                PackageRole::Root,
                &[],
            )
            .expect("test-only imports are retained for ordinary function analysis");
        let (
            fixture_symbol,
            fixture_import_index,
            generic_symbol,
            generic_import_index,
            item_import_index,
        ) = {
            let module_scope = collection
                .scopes()
                .module(ModuleId::ROOT)
                .expect("root module scope exists");
            let symbol_named = |expected: &str| {
                module_scope
                    .scope
                    .keys()
                    .copied()
                    .find(|symbol| {
                        database
                            .resolve_symbol(*symbol)
                            .is_ok_and(|name| name.as_ref() == expected)
                    })
                    .unwrap_or_else(|| panic!("module scope contains `{expected}`"))
            };
            let import_index_for = |symbol| match module_scope
                .scope
                .get(&symbol)
                .expect("requested module binding exists")
                .origin
            {
                BindingOrigin::Decl => panic!("`{symbol:?}` comes from a use binding"),
                BindingOrigin::Use { import } | BindingOrigin::PubUse { import } => {
                    import.0 as usize
                }
            };
            let fixture_symbol = symbol_named("fixture");
            let builtin_root_symbol = symbol_named("fs");
            let generic_symbol = symbol_named("Fixture");
            let item_symbol = symbol_named("flag");
            let fixture_import_index = import_index_for(fixture_symbol);
            let builtin_root_import_index = import_index_for(builtin_root_symbol);
            let generic_import_index = import_index_for(generic_symbol);
            let item_import_index = import_index_for(item_symbol);
            assert!(module_scope.imports[fixture_import_index].test_only);
            assert!(matches!(
                module_scope.imports[fixture_import_index].res,
                Res::TestOnly(_)
            ));
            assert!(module_scope.imports[builtin_root_import_index].test_only);
            assert!(module_scope.imports[generic_import_index].test_only);
            assert!(module_scope.imports[item_import_index].test_only);
            (
                fixture_symbol,
                fixture_import_index,
                generic_symbol,
                generic_import_index,
                item_import_index,
            )
        };

        let results = database
            .resolve_function_owner_analyses(&collection, &module_tree, &snapshot)
            .expect("top-level function owners resolve");
        assert_eq!(results.owners().len(), 7);
        let repeated = &results.owners()[0];
        assert_eq!(
            repeated
                .module_resolution()
                .expect("module lookup succeeds")
                .expect("repeated function has a module result")
                .paths
                .values()
                .map(|path| path.base)
                .collect::<Vec<_>>(),
            [Res::Err, Res::Err],
            "each out-of-test module reference is changed to the error sentinel"
        );
        let repeated_diagnostics = repeated
            .test_only_diagnostics()
            .expect("reference diagnostics are collected");
        assert_eq!(repeated_diagnostics.len(), 2);
        let repeated_start = root
            .find("fn repeated() { fixture")
            .expect("repeated function exists") as u32
            + "fn repeated() { ".len() as u32;
        let repeated_spans = repeated_diagnostics
            .iter()
            .map(|diagnostic| {
                diagnostic
                    .primary()
                    .expect("reference has a primary location")
                    .span
                    .clone()
            })
            .collect::<Vec<_>>();
        assert_eq!(
            repeated_spans,
            [
                sai_diagnostics::Span::new(
                    module_tree.modules[0].file,
                    sai_diagnostics::TextRange::new(
                        sai_diagnostics::TextSize::new(repeated_start),
                        sai_diagnostics::TextSize::new(
                            repeated_start + "fixture".len() as u32,
                        ),
                    )
                    .expect("first reference range is ordered"),
                ),
                sai_diagnostics::Span::new(
                    module_tree.modules[0].file,
                    sai_diagnostics::TextRange::new(
                        sai_diagnostics::TextSize::new(
                            repeated_start + "fixture && ".len() as u32,
                        ),
                        sai_diagnostics::TextSize::new(
                            repeated_start + "fixture && fixture".len() as u32,
                        ),
                    )
                    .expect("second reference range is ordered"),
                ),
            ]
        );
        let first_use_start = root
            .find("acme:test-support/fixtures")
            .expect("alias use path exists") as u32;
        let first_use_span = sai_diagnostics::Span::new(
            module_tree.modules[0].file,
            sai_diagnostics::TextRange::new(
                sai_diagnostics::TextSize::new(first_use_start),
                sai_diagnostics::TextSize::new(
                    first_use_start + "acme:test-support/fixtures".len() as u32,
                ),
            )
            .expect("alias package path range is ordered"),
        );
        assert!(repeated_diagnostics.iter().all(|diagnostic| {
            diagnostic.code == sai_diagnostics::Code::TestDependencyOutsideTest
                && diagnostic.related().iter().any(|related| {
                    matches!(
                        related,
                        Related::DeclaredHere { location, .. }
                            if location.span == first_use_span
                    )
                })
        }));

        let imported_item = &results.owners()[1];
        assert_eq!(
            imported_item
                .module_resolution()
                .expect("item module lookup succeeds")
                .expect("item function has a module result")
                .paths
                .values()
                .map(|path| path.base)
                .collect::<Vec<_>>(),
            [Res::Err]
        );
        let item_diagnostics = imported_item
            .test_only_diagnostics()
            .expect("item reference diagnostics are collected");
        assert_eq!(item_diagnostics.len(), 1);
        assert_eq!(
            item_diagnostics[0].code,
            sai_diagnostics::Code::TestDependencyOutsideTest
        );
        let second_use_start = root
            .find("acme:test-support/fixtures.{flag}")
            .expect("item use path exists") as u32;
        let second_use_span = sai_diagnostics::Span::new(
            module_tree.modules[0].file,
            sai_diagnostics::TextRange::new(
                sai_diagnostics::TextSize::new(second_use_start),
                sai_diagnostics::TextSize::new(
                    second_use_start + "acme:test-support/fixtures".len() as u32,
                ),
            )
            .expect("item package path range is ordered"),
        );
        assert!(item_diagnostics[0].related().iter().any(|related| matches!(
            related,
            Related::DeclaredHere { location, .. } if location.span == second_use_span
        )));

        let generic = &results.owners()[2];
        let generic_module = generic
            .module_resolution()
            .expect("generic lookup succeeds")
            .expect("generic function has a module result");
        assert!(
            generic_module.paths.is_empty(),
            "same-named generic was resolved through module scope: {generic_module:#?}"
        );
        assert_eq!(
            generic_module.deferred_paths.len(),
            1,
            "a same-named generic remains deferred for generic resolution"
        );
        let deferred_generic_name = database
            .resolve_symbol(generic_module.deferred_paths[0].name)
            .expect("deferred generic name is interned");
        let imported_generic_name = database
            .resolve_symbol(generic_symbol)
            .expect("generic module alias name is interned");
        assert_eq!(
            deferred_generic_name.as_ref(),
            imported_generic_name.as_ref(),
            "the generic and imported module alias have the same name"
        );
        assert!(
            generic
                .test_only_diagnostics()
                .expect("generic reference diagnostics are collected")
                .is_empty(),
            "the generic must not be mistaken for the test-only module alias"
        );

        let local = &results.owners()[3];
        assert!(
            local
                .local_resolution()
                .expect("local lookup succeeds")
                .expect("local function has a local result")
                .paths
                .values()
                .all(|path| matches!(path.base, Res::Local(_))),
            "local shadowing wins before the test-only module import"
        );
        assert!(
            local
                .test_only_diagnostics()
                .expect("local diagnostics are collected")
                .is_empty()
        );

        let signature = &results.owners()[4];
        let signature_diagnostics = signature
            .test_only_diagnostics()
            .expect("signature test-only references are diagnosed");
        assert_eq!(
            signature_diagnostics.len(),
            10,
            "signature and body type paths, nested effect references, and a qualified head are checked: {:?}",
            signature_diagnostics
                .iter()
                .map(|diagnostic| diagnostic.primary().map(|primary| primary.span.clone()))
                .collect::<Vec<_>>()
        );
        let signature_text_start = root
            .find("fn signature")
            .expect("signature function exists");
        let signature_text_end = signature_text_start
            + root[signature_text_start..]
                .find('\n')
                .expect("signature line ends with a newline");
        let signature_text = &root[signature_text_start..signature_text_end];
        let signature_body_start = signature_text
            .find("{ let typed:")
            .expect("function body follows its signature and effects clauses");
        let signature_types_text = &signature_text[..signature_body_start];
        let span_for = |start: u32, text: &str| {
            sai_diagnostics::Span::new(
                module_tree.modules[0].file,
                sai_diagnostics::TextRange::new(
                    sai_diagnostics::TextSize::new(start),
                    sai_diagnostics::TextSize::new(start + text.len() as u32),
                )
                .expect("reference range is ordered"),
            )
        };
        let mut expected_signature_spans = signature_types_text
            .match_indices("Fixture")
            .map(|(offset, name)| span_for((signature_text_start + offset) as u32, name))
            .collect::<Vec<_>>();
        expected_signature_spans.extend(
            signature_types_text
                .match_indices("fixture.")
                .map(|(offset, _)| span_for((signature_text_start + offset) as u32, "fixture")),
        );
        expected_signature_spans.extend(
            signature_text[signature_body_start..]
                .match_indices("Fixture")
                .map(|(offset, name)| {
                    span_for(
                        (signature_text_start + signature_body_start + offset) as u32,
                        name,
                    )
                }),
        );
        expected_signature_spans.sort_by_key(|span| span.range.start());
        assert_eq!(
            signature_diagnostics
                .iter()
                .map(|diagnostic| diagnostic
                    .primary()
                    .expect("reference has a primary location")
                    .span
                    .clone())
                .collect::<Vec<_>>(),
            expected_signature_spans,
            "signature, body type, and body expression diagnostics use the path-head span in source order"
        );
        let fixture_type_use_start =
            root.find("acme:test-support/fixtures.{Fixture}")
                .expect("test-only type import path exists") as u32;
        let fixture_type_use_span = span_for(fixture_type_use_start, "acme:test-support/fixtures");
        for diagnostic in signature_diagnostics {
            let primary = diagnostic
                .primary()
                .expect("reference has a primary location");
            let reference = &root[primary.span.range.start().raw() as usize
                ..primary.span.range.end().raw() as usize];
            let expected_use_span = if reference == "Fixture" {
                &fixture_type_use_span
            } else {
                &first_use_span
            };
            assert!(diagnostic.related().iter().any(|related| matches!(
                related,
                Related::DeclaredHere { location, .. }
                    if &location.span == expected_use_span
            )));
        }

        let signature_types = signature
            .test_only_path_resolution()
            .expect("non-expression path lookup succeeds")
            .expect("function has test-only non-expression path results");
        assert_eq!(signature_types.owner(), signature.owner());
        assert_eq!(signature_types.paths().len(), 10);
        assert!(
            signature_types
                .paths()
                .values()
                .all(|path| path.base == Res::Err && path.resolved_segments == 1)
        );
        assert_eq!(
            signature_types
                .paths()
                .values()
                .filter(|path| path.segment_count == 2)
                .count(),
            3,
            "qualified type and effect paths resolve only their diagnosed module heads"
        );
        let signature_type_paths = signature
            .type_path_resolution()
            .expect("ordinary type path lookup succeeds")
            .expect("function has an ordinary type path result");
        assert!(
            signature_type_paths
                .paths()
                .values()
                .any(|path| path.base == Res::Err),
            "rejected test-only type heads remain error paths and do not fall through to the Prelude"
        );
        assert!(
            signature_type_paths.module_path_errors().is_empty(),
            "a rejected test-only head suppresses qualified member lookup"
        );
        assert!(
            signature
                .local_resolution()
                .expect("function body local lookup succeeds")
                .expect("function has a body")
                .paths
                .values()
                .all(|path| matches!(path.base, Res::Local(_))),
            "a value parameter with the module alias name wins only in the body, not in type position"
        );

        let generic_type = &results.owners()[5];
        let generic_type_name = database
            .symbols
            .intern("Fixture")
            .expect("generic type name is interned");
        let generic_type_def_id = database
            .def_paths
            .get(&generic_type.owner().def_id.package())
            .expect("package definition paths are available")
            .intern_generic_params(
                generic_type.owner().def_id,
                &[(generic_type_name, false, 0)],
            )
            .expect("function generic keeps its definition identity")[0]
            .to_def_id();
        assert!(
            generic_type
                .test_only_diagnostics()
                .expect("generic signature diagnostics are collected")
                .is_empty(),
            "generic type parameters also shadow same-named test-only type imports"
        );
        assert!(
            generic_type
                .test_only_path_resolution()
                .expect("generic path lookup succeeds")
                .expect("generic function has path results")
                .paths()
                .is_empty(),
            "same-named generic type paths are not rewritten as imported test-only types"
        );
        assert!(
            generic_type
                .type_path_resolution()
                .expect("ordinary generic type path lookup succeeds")
                .expect("generic function has an ordinary type path result")
                .paths()
                .values()
                .any(|path| path.base == Res::Def(DefKind::TyParam, generic_type_def_id)),
            "function type generic resolution wins before a same-named test-only import"
        );

        let builtin_effect_root = &results.owners()[6];
        assert!(
            builtin_effect_root
                .test_only_diagnostics()
                .expect("built-in effect lookup succeeds")
                .is_empty(),
            "built-in effect roots take precedence over same-named test-only module aliases"
        );
        assert!(
            builtin_effect_root
                .test_only_path_resolution()
                .expect("built-in effect path lookup succeeds")
                .expect("function has an auxiliary path result")
                .paths()
                .is_empty(),
            "built-in effect references are not rewritten as test-only module paths"
        );

        // Origin, rather than the current Res, is the test-only authority.
        let resolved_def = Res::Def(
            DefKind::Fn,
            collection.scopes.function_owners[0]
                .owner
                .def_id
                .to_def_id(),
        );
        {
            let module_scope = &mut collection.scopes.modules[ModuleId::ROOT.raw() as usize];
            module_scope.imports[fixture_import_index].res = resolved_def;
            module_scope
                .scope
                .get_mut(&fixture_symbol)
                .expect("alias binding exists")
                .res = resolved_def;
            module_scope.imports[generic_import_index].res = resolved_def;
            module_scope
                .scope
                .get_mut(&generic_symbol)
                .expect("type binding exists")
                .res = resolved_def;
        }
        let resolved_import_results = database
            .resolve_function_owner_analyses(&collection, &module_tree, &snapshot)
            .expect("resolved test-only bindings remain diagnosable");
        assert_eq!(
            resolved_import_results.owners()[0]
                .module_resolution()
                .expect("module lookup succeeds")
                .expect("repeated function has a module result")
                .paths
                .values()
                .map(|path| path.base)
                .collect::<Vec<_>>(),
            [Res::Err, Res::Err]
        );
        assert_eq!(
            resolved_import_results.owners()[0]
                .test_only_diagnostics()
                .expect("origin-based diagnostics succeed")
                .len(),
            2
        );
        assert_eq!(
            resolved_import_results.owners()[4]
                .test_only_diagnostics()
                .expect("resolved signature imports remain diagnosable")
                .len(),
            10,
            "all non-expression diagnostics follow test-only binding origins even when their Res is Def"
        );

        {
            let module_scope = &mut collection.scopes.modules[ModuleId::ROOT.raw() as usize];
            module_scope.imports[fixture_import_index].res = Res::Err;
            module_scope
                .scope
                .get_mut(&fixture_symbol)
                .expect("alias binding exists")
                .res = Res::Err;
            module_scope.imports[generic_import_index].res = Res::Err;
            module_scope
                .scope
                .get_mut(&generic_symbol)
                .expect("type binding exists")
                .res = Res::Err;
        }
        let diagnosed_import_results = database
            .resolve_function_owner_analyses(&collection, &module_tree, &snapshot)
            .expect("diagnosed test-only bindings remain diagnosable");
        assert_eq!(
            diagnosed_import_results.owners()[4]
                .test_only_diagnostics()
                .expect("diagnosed imports retain origin-based diagnostics")
                .len(),
            10,
            "all non-expression diagnostics follow test-only binding origins even when their Res is Err"
        );

        // Ordinary failed signature imports keep their existing error without
        // a test-only diagnostic cascade.
        {
            let module_scope = &mut collection.scopes.modules[ModuleId::ROOT.raw() as usize];
            module_scope.imports[generic_import_index].test_only = false;
            module_scope.imports[generic_import_index].res = Res::Err;
            module_scope
                .scope
                .get_mut(&generic_symbol)
                .expect("type binding exists")
                .res = Res::Err;
        }
        let ordinary_type_error_results = database
            .resolve_function_owner_analyses(&collection, &module_tree, &snapshot)
            .expect("ordinary failed type imports stay in their own diagnostic channel");
        assert_eq!(
            ordinary_type_error_results.owners()[4]
                .test_only_diagnostics()
                .expect("non-expression diagnostics still succeed")
                .len(),
            3,
            "only the still-test-only qualified type and effect heads are diagnosed"
        );
        assert_eq!(
            ordinary_type_error_results.owners()[4]
                .test_only_path_resolution()
                .expect("non-expression path lookup succeeds")
                .expect("function path results are present")
                .paths()
                .values()
                .count(),
            3,
            "ordinary Res::Err type bindings are left to their own diagnostic"
        );

        // An unrelated failed import remains an error but does not cascade.
        {
            let module_scope = &mut collection.scopes.modules[ModuleId::ROOT.raw() as usize];
            let imported_item_name = module_scope.imports[item_import_index].name;
            module_scope.imports[item_import_index].test_only = false;
            module_scope.imports[item_import_index].res = Res::Err;
            module_scope
                .scope
                .get_mut(&imported_item_name)
                .expect("item binding exists")
                .res = Res::Err;
        }
        let ordinary_error_results = database
            .resolve_function_owner_analyses(&collection, &module_tree, &snapshot)
            .expect("ordinary import errors stay in their own diagnostic channel");
        assert!(
            ordinary_error_results.owners()[1]
                .test_only_diagnostics()
                .expect("item diagnostic collection succeeds")
                .is_empty()
        );
        assert_eq!(
            ordinary_error_results.owners()[1]
                .module_resolution()
                .expect("module lookup succeeds")
                .expect("item function has a module result")
                .paths
                .values()
                .map(|path| path.base)
                .collect::<Vec<_>>(),
            [Res::Err]
        );
    }

    #[test]
    fn const_owner_paths_use_target_filtered_exact_file_scopes() {
        let root = concat!(
            "type RootOnly = Bool\n",
            "const BASE: Bool = true\n",
            "const COPY: Bool = BASE\n",
            "@target(\"wasm64-core\")\n",
            "const FILTERED: Bool = true\n",
        );
        let child = concat!(
            "type LocalType = Bool\n",
            "const LOCAL: Bool = false\n",
            "const LOCAL_COPY: Bool = LOCAL\n",
            "const CHILD_COPY: Bool = BASE\n",
            "const LOCAL_TYPED: LocalType = false\n",
            "const ROOT_TYPE_MISS: RootOnly = false\n",
        );
        let (mut database, module_tree, snapshot, _) =
            phase1_fixture(root.as_bytes(), child.as_bytes());
        let target_cfg = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let collection = database
            .collect_phase1_package_scopes_collection(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
            )
            .expect("const package scopes collect");
        let root_scope = collection
            .scopes()
            .module(ModuleId::ROOT)
            .expect("root module scope exists");
        let binding_for = |scope: &Phase1ModuleScopes, name: &str| {
            scope
                .scope
                .iter()
                .find_map(|(symbol, binding)| {
                    (database.resolve_symbol(*symbol).ok()?.as_ref() == name).then_some(binding.res)
                })
                .unwrap_or_else(|| panic!("module scope contains `{name}`"))
        };
        let base = binding_for(root_scope, "BASE");
        let child_scope = collection
            .scopes()
            .module(ModuleId::from_raw(1))
            .expect("child module scope exists");
        let child_local = binding_for(child_scope, "LOCAL");
        let child_local_type = binding_for(child_scope, "LocalType");
        let base_symbol = root_scope
            .scope
            .keys()
            .copied()
            .find(|symbol| {
                database
                    .resolve_symbol(*symbol)
                    .is_ok_and(|name| name.as_ref() == "BASE")
            })
            .expect("BASE has an interned symbol");

        let results = database
            .resolve_const_owner_paths(&collection, &module_tree, &snapshot)
            .expect("const owners resolve");
        assert!(results.matches_collection(&collection));
        assert_eq!(
            results.owners().len(),
            7,
            "the target-excluded const is absent from the current owner list"
        );
        let copied_root_value = results.owners()[1]
            .module_resolution()
            .expect("root module lookup succeeds")
            .expect("COPY has a module result");
        assert_eq!(
            copied_root_value
                .paths
                .values()
                .map(|path| path.base)
                .collect::<Vec<_>>(),
            [base],
            "a const initializer resolves an unqualified const in its module"
        );

        let copied_child_value = results.owners()[3]
            .module_resolution()
            .expect("child module lookup succeeds")
            .expect("LOCAL_COPY has a module result");
        assert_eq!(
            copied_child_value
                .paths
                .values()
                .map(|path| path.base)
                .collect::<Vec<_>>(),
            [child_local],
            "a child const resolves a sibling const from the child file scope"
        );

        let child_root_miss = results.owners()[4]
            .module_resolution()
            .expect("child module miss remains a successful partial pass")
            .expect("CHILD_COPY has a module result");
        assert!(child_root_miss.paths.is_empty());
        assert_eq!(child_root_miss.deferred_paths.len(), 1);
        assert_eq!(
            child_root_miss.deferred_paths[0].name, base_symbol,
            "a root-file const is not exposed in the child module's unqualified scope"
        );

        let child_local_type_resolution = results.owners()[5]
            .type_path_resolution()
            .expect("child type lookup succeeds")
            .expect("LOCAL_TYPED has a type path result");
        assert_eq!(
            child_local_type_resolution
                .paths()
                .values()
                .map(|path| path.base)
                .collect::<Vec<_>>(),
            [child_local_type],
            "a child const resolves a sibling type alias from the child file scope"
        );

        let root_only_symbol = root_scope
            .scope
            .keys()
            .copied()
            .find(|symbol| {
                database
                    .resolve_symbol(*symbol)
                    .is_ok_and(|name| name.as_ref() == "RootOnly")
            })
            .expect("RootOnly has an interned symbol");
        let child_root_type_miss = results.owners()[6]
            .type_path_resolution()
            .expect("child type lookup remains a successful partial pass")
            .expect("ROOT_TYPE_MISS has a type path result");
        assert!(child_root_type_miss.paths().is_empty());
        assert_eq!(child_root_type_miss.deferred_paths().len(), 1);
        assert_eq!(
            child_root_type_miss.deferred_paths()[0].name,
            root_only_symbol,
            "a root-file type alias is not exposed in the child module's unqualified scope"
        );
    }

    #[test]
    fn const_owner_resolves_primitive_and_module_type_path_heads() {
        let root = concat!(
            "use acme:phase1/child as child_alias\n",
            "type Array<T> = T\n",
            "const VALUE: Bool = true\n",
            "const MODULE: Array<U32> = VALUE\n",
            "const PRIMITIVE: U32 = 0\n",
            "const DEFERRED: Option<U32> = 0\n",
            "const QUALIFIED: child_alias.Widget = 0\n",
            "const NESTED: child_alias.api.Request.Associated = 0\n",
            "const MISSING: child_alias.MissingType = 0\n",
            "const BODY: Bool = { let local: U32 = 0; true }\n",
        );
        let child = concat!(
            "pub type Widget = U32\n",
            "pub interface api {\n",
            "  type Request = U32\n",
            "}\n",
            "pub fn child_fn() {}\n",
        );
        let (mut database, module_tree, snapshot, _) =
            phase1_fixture(root.as_bytes(), child.as_bytes());
        let target_cfg = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let collection = database
            .collect_phase1_package_scopes_collection(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
            )
            .expect("const package scopes collect");
        let root_scope = collection
            .scopes()
            .module(ModuleId::ROOT)
            .expect("root module scope exists");
        let binding_for = |name: &str| {
            root_scope
                .scope
                .iter()
                .find_map(|(symbol, binding)| {
                    (database.resolve_symbol(*symbol).ok()?.as_ref() == name).then_some(binding.res)
                })
                .unwrap_or_else(|| panic!("module scope contains `{name}`"))
        };
        let array = binding_for("Array");
        let value = binding_for("VALUE");
        let child_module_scope = collection
            .scopes()
            .module(ModuleId::from_raw(1))
            .expect("child module scope exists");
        let widget_name = database
            .symbols
            .intern("Widget")
            .expect("Widget name is interned");
        let widget_binding = child_module_scope
            .members
            .get(&widget_name)
            .expect("child Widget alias is declared");
        let api_name = database
            .symbols
            .intern("api")
            .expect("api name is interned");
        let request_name = database
            .symbols
            .intern("Request")
            .expect("Request name is interned");
        let request_binding = collection
            .scopes()
            .interfaces
            .iter()
            .find_map(|(def_id, interface)| {
                (child_module_scope
                    .members
                    .get(&api_name)
                    .is_some_and(|binding| binding.res == Res::Def(DefKind::Interface, *def_id)))
                .then(|| interface.members.get(&request_name))
                .flatten()
            })
            .expect("interface api declares Request");

        let resolved = database
            .resolve_const_owner_paths(&collection, &module_tree, &snapshot)
            .expect("const owners resolve type path heads");
        assert_eq!(resolved.owners().len(), 8);
        assert!(
            resolved.owners().iter().all(|owner| owner
                .module_path_diagnostics()
                .expect("package-local const calls keep their typed path channel")
                .is_none()),
            "package-local const calls do not construct snapshot-bound member diagnostics"
        );

        let module_type = resolved.owners()[1]
            .type_path_resolution()
            .expect("module type resolution succeeds")
            .expect("const has a type path result");
        assert!(
            module_type
                .paths()
                .values()
                .any(|path| path.base == array && matches!(path.base, Res::Def(DefKind::Alias, _))),
            "a valid module type alias shadows the primitive Array entry"
        );
        assert!(
            module_type
                .paths()
                .values()
                .any(|path| path.base == Res::PrimTy(sai_resolve::prelude::PrimTy::U32)),
            "primitive heads resolve inside const generic type arguments"
        );
        let module_expression = resolved.owners()[1]
            .module_resolution()
            .expect("initializer expression lookup succeeds")
            .expect("const has a module result");
        assert_eq!(module_expression.paths.len(), 1);
        assert_eq!(
            module_expression
                .paths
                .values()
                .next()
                .map(|path| path.base),
            Some(value),
            "the type annotation stays out of the initializer expression result"
        );

        let primitive = resolved.owners()[2]
            .type_path_resolution()
            .expect("primitive const type lookup succeeds")
            .expect("const has a type path result");
        assert_eq!(
            primitive
                .paths()
                .values()
                .map(|path| path.base)
                .collect::<Vec<_>>(),
            [Res::PrimTy(sai_resolve::prelude::PrimTy::U32)]
        );

        let deferred = resolved.owners()[3]
            .type_path_resolution()
            .expect("deferred const type lookup succeeds")
            .expect("const has a type path result");
        assert!(
            deferred.deferred_paths().iter().any(|path| {
                database
                    .resolve_symbol(path.name)
                    .is_ok_and(|name| name.as_ref() == "Option")
            }),
            "canonical non-primitive names remain deferred without standard package scopes"
        );

        let qualified = resolved.owners()[4]
            .type_path_resolution()
            .expect("qualified const type lookup succeeds")
            .expect("const has a type path result");
        assert!(
            qualified.paths().values().any(|path| {
                path.base == widget_binding.res
                    && path.resolved_segments == 2
                    && path.segment_count == 2
            }),
            "qualified const types resolve through a local module's type member"
        );

        let nested = resolved.owners()[5]
            .type_path_resolution()
            .expect("nested qualified const type lookup succeeds")
            .expect("nested const has a type path result");
        assert!(
            nested.paths().values().any(|path| {
                path.base == request_binding.res
                    && path.resolved_segments == 3
                    && path.segment_count == 4
            }),
            "module-to-interface traversal stops at the first type member"
        );

        let missing = resolved.owners()[6]
            .type_path_resolution()
            .expect("missing qualified const type lookup succeeds")
            .expect("missing const has a type path result");
        assert_eq!(missing.module_path_errors().len(), 1);
        let missing_offset = root
            .find("child_alias.MissingType")
            .expect("missing type member path exists");
        let missing_error = &missing.module_path_errors()[0];
        let (missing_name, missing_segment, missing_span) = match missing_error.error() {
            ModulePathError::MissingMember {
                name,
                segment_index,
                span,
                ..
            } => (name, segment_index, span),
            error => panic!("expected a missing-member error, got {error:?}"),
        };
        assert!(
            database
                .resolve_symbol(missing_name)
                .is_ok_and(|name| name.as_ref() == "MissingType")
        );
        assert_eq!(missing_segment, 0);
        let missing_start = missing_offset + "child_alias.".len();
        assert_eq!(missing_span.file, module_tree.modules[0].file);
        assert_eq!(missing_span.range.start().to_usize(), missing_start);
        assert_eq!(
            missing_span.range.end().to_usize(),
            missing_start + "MissingType".len()
        );
        assert_eq!(
            missing.paths().get(&missing_error.hir_id()),
            Some(&PathRes {
                base: Res::Err,
                resolved_segments: 2,
                segment_count: 2,
            }),
            "a missing local member records an error through that exact path segment"
        );

        let body = resolved.owners()[7]
            .type_path_resolution()
            .expect("initializer body type lookup succeeds")
            .expect("const has a type path result");
        assert!(
            body.paths()
                .values()
                .any(|path| path.base == Res::PrimTy(sai_resolve::prelude::PrimTy::U32)),
            "initializer body annotations participate in type-head resolution"
        );
    }

    #[test]
    fn const_primitive_literal_check_uses_resolved_types_and_hir_literals() {
        use sai_resolve::prelude::PrimTy;

        let root = concat!(
            "pub type Alias = U8\n",
            "pub const BOOL_TRUE: Bool = true\n",
            "pub const BOOL_FALSE: Bool = false\n",
            "pub const I8_MIN: I8 = -128\n",
            "pub const I8_MAX: I8 = 127\n",
            "pub const I8_LOW: I8 = -129\n",
            "pub const I8_HIGH: I8 = 128\n",
            "pub const U8_MAX: U8 = 255\n",
            "pub const U8_HIGH: U8 = 256\n",
            "pub const U8_NEG_ZERO: U8 = -0\n",
            "pub const U8_NEG_ONE: U8 = -1\n",
            "pub const BOOL_MISMATCH: Bool = 1\n",
            "pub const INT_MISMATCH: I16 = false\n",
            "pub const INT64_HIGH: I64 = 9223372036854775808\n",
            "pub const UINT64_MAX: U64 = 18446744073709551615\n",
            "pub const UINT64_HIGH: U64 = 18446744073709551616\n",
            "pub const TOO_WIDE: I64 = 340282366920938463463374607431768211456\n",
            "pub const ALIAS_TYPE: Alias = 1\n",
            "pub const BLOCK: Bool = { true }\n",
            "const PRIVATE: Bool = true\n",
            "pub const INT_MIN: Int = -9223372036854775808\n",
            "pub const UINT_MAX: UInt = 18446744073709551615\n",
            "pub const INT_HIGH: Int = 9223372036854775808\n",
            "pub const UINT_HIGH: UInt = 18446744073709551616\n",
            "pub const Max_size: I8 = 1\n",
            "pub const r#READY: Bool = true\n",
        );
        let (mut database, module_tree, snapshot, _) = phase1_fixture(root.as_bytes(), b"");
        let target_cfg = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let collection = database
            .collect_phase1_package_scopes_collection(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
            )
            .expect("const package scopes collect");

        let resolved = database
            .resolve_const_owner_paths(&collection, &module_tree, &snapshot)
            .expect("const owners resolve");
        let checks = resolved
            .owners()
            .iter()
            .map(|owner| {
                owner
                    .literal_check()
                    .expect("literal checks use the current owner snapshot")
            })
            .collect::<Vec<_>>();
        assert_eq!(checks.len(), 25);
        for index in [0, 1, 2, 3, 6, 8, 13, 19, 20] {
            assert!(
                checks[index].is_valid(),
                "const at owner index {index} is a supported valid literal: {:?}",
                checks[index]
            );
        }
        assert_eq!(
            checks[0],
            &ConstLiteralCheck::Supported {
                primitive: PrimTy::Bool,
                diagnostics: Vec::new(),
            }
        );
        assert_eq!(
            checks[2],
            &ConstLiteralCheck::Supported {
                primitive: PrimTy::I8,
                diagnostics: Vec::new(),
            },
            "the direct negative literal `-128` lowers to a signed literal value"
        );
        assert_eq!(
            checks[8],
            &ConstLiteralCheck::Supported {
                primitive: PrimTy::U8,
                diagnostics: Vec::new(),
            },
            "negative zero is the mathematical value zero"
        );

        for (index, code) in [
            (4, sai_diagnostics::Code::LiteralOutOfRange),
            (5, sai_diagnostics::Code::LiteralOutOfRange),
            (7, sai_diagnostics::Code::LiteralOutOfRange),
            (9, sai_diagnostics::Code::LiteralOutOfRange),
            (10, sai_diagnostics::Code::TypeMismatch),
            (11, sai_diagnostics::Code::TypeMismatch),
            (12, sai_diagnostics::Code::LiteralOutOfRange),
            (14, sai_diagnostics::Code::LiteralOutOfRange),
            (15, sai_diagnostics::Code::LiteralOutOfRange),
            (21, sai_diagnostics::Code::LiteralOutOfRange),
            (22, sai_diagnostics::Code::LiteralOutOfRange),
        ] {
            let ConstLiteralCheck::Supported { diagnostics, .. } = checks[index] else {
                panic!("owner index {index} should be supported");
            };
            assert_eq!(diagnostics.len(), 1, "owner index {index}");
            assert_eq!(diagnostics[0].code, code, "owner index {index}");
            assert!(
                diagnostics[0].has_workspace_snapshot(),
                "owner index {index} diagnostic is bound to the current snapshot"
            );
            assert!(
                diagnostics[0].primary().is_some(),
                "owner index {index} diagnostic points to the literal"
            );
        }
        for index in [16, 17, 18, 23, 24] {
            assert_eq!(
                checks[index],
                &ConstLiteralCheck::Unsupported,
                "aliases, non-literal expressions, private consts, raw identifiers and names outside the supported ASCII UPPER_SNAKE_CASE convention remain gated"
            );
        }
    }

    #[test]
    fn const_pointer_sized_integer_literals_use_the_selected_target_width() {
        use sai_resolve::prelude::PrimTy;

        for (
            target,
            signed_min,
            signed_max,
            unsigned_max,
            signed_below,
            signed_above,
            unsigned_above,
        ) in [
            (
                "wasm32-core",
                "-2147483648",
                "2147483647",
                "4294967295",
                "-2147483649",
                "2147483648",
                "4294967296",
            ),
            (
                "wasm64-core",
                "-9223372036854775808",
                "9223372036854775807",
                "18446744073709551615",
                "-9223372036854775809",
                "9223372036854775808",
                "18446744073709551616",
            ),
        ] {
            let root = format!(
                concat!(
                    "pub const SIGNED_MIN: ISize = {}\n",
                    "pub const SIGNED_MAX: ISize = {}\n",
                    "pub const UNSIGNED_MAX: USize = {}\n",
                    "pub const SIGNED_BELOW: ISize = {}\n",
                    "pub const SIGNED_ABOVE: ISize = {}\n",
                    "pub const UNSIGNED_ABOVE: USize = {}\n",
                    "pub const UNSIGNED_NEG_ZERO: USize = -0\n",
                    "pub const UNSIGNED_NEG_ONE: USize = -1\n",
                    "pub const SIGNED_TOO_WIDE: ISize = 340282366920938463463374607431768211456\n",
                    "pub const UNSIGNED_TOO_WIDE: USize = 340282366920938463463374607431768211456\n",
                ),
                signed_min, signed_max, unsigned_max, signed_below, signed_above, unsigned_above,
            );
            let (mut database, module_tree, snapshot, _) = phase1_fixture(root.as_bytes(), b"");
            let target_cfg = target_cfg_for_check(target).expect("target config is valid");
            let expected_width = if target == "wasm32-core" { 32 } else { 64 };
            assert_eq!(target_cfg.pointer_width(), expected_width, "{target}");
            let collection = database
                .collect_phase1_package_scopes_collection(
                    &module_tree,
                    &snapshot,
                    &target_cfg,
                    Phase1BuildContext::default(),
                )
                .expect("const package scopes collect");
            let resolved = database
                .resolve_const_owner_paths(&collection, &module_tree, &snapshot)
                .expect("const owners resolve");
            let checks = resolved
                .owners()
                .iter()
                .map(|owner| {
                    owner
                        .literal_check()
                        .expect("literal checks use the current owner snapshot")
                })
                .collect::<Vec<_>>();

            assert_eq!(checks.len(), 10, "{target}");
            for (index, primitive) in [
                (0, PrimTy::ISize),
                (1, PrimTy::ISize),
                (2, PrimTy::USize),
                (6, PrimTy::USize),
            ] {
                assert_eq!(
                    checks[index],
                    &ConstLiteralCheck::Supported {
                        primitive,
                        diagnostics: Vec::new(),
                    },
                    "pointer-sized boundary at owner index {index} should fit on {target}"
                );
            }
            for index in [3, 4, 5, 7, 8, 9] {
                let ConstLiteralCheck::Supported {
                    primitive,
                    diagnostics,
                } = checks[index]
                else {
                    panic!("out-of-range pointer literal at {index} should be checked on {target}");
                };
                assert_eq!(
                    *primitive,
                    if matches!(index, 3 | 4 | 8) {
                        PrimTy::ISize
                    } else {
                        PrimTy::USize
                    },
                    "owner index {index} on {target}"
                );
                assert_eq!(diagnostics.len(), 1, "owner index {index} on {target}");
                assert_eq!(
                    diagnostics[0].code,
                    sai_diagnostics::Code::LiteralOutOfRange,
                    "owner index {index} on {target}"
                );
                assert!(diagnostics[0].has_workspace_snapshot());
                assert!(diagnostics[0].primary().is_some());
            }
        }
    }

    #[test]
    fn const_char_byte_literal_check_uses_decoded_unicode_and_byte_values() {
        use sai_resolve::prelude::PrimTy;

        let root = concat!(
            "pub const CHAR_ASCII: Char = 'a'\n",
            "pub const CHAR_NULL: Char = '\\0'\n",
            "pub const CHAR_POST_SURROGATE: Char = '\\u{e000}'\n",
            "pub const CHAR_MAX: Char = '\\u{10ffff}'\n",
            "pub const BYTE_ASCII: Byte = b'z'\n",
            "pub const BYTE_MIN: Byte = b'\\x00'\n",
            "pub const BYTE_MAX: Byte = b'\\xff'\n",
            "pub const CHAR_BYTE_MISMATCH: Char = b'a'\n",
            "pub const BYTE_CHAR_MISMATCH: Byte = 'a'\n",
            "pub const BYTE_INT_MISMATCH: Byte = 255\n",
            "pub const CHAR_STRING_MISMATCH: Char = \"a\"\n",
            "pub const BYTE_STRING_MISMATCH: Byte = b\"a\"\n",
            "pub const TEXT: Str = \"text\"\n",
            "pub const BORROWED: &Bool = &true\n",
        );
        let (mut database, module_tree, snapshot, _) = phase1_fixture(root.as_bytes(), b"");
        let target_cfg = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let collection = database
            .collect_phase1_package_scopes_collection(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
            )
            .expect("const package scopes collect");
        let resolved = database
            .resolve_const_owner_paths(&collection, &module_tree, &snapshot)
            .expect("const owners resolve");
        let checks = resolved
            .owners()
            .iter()
            .map(|owner| {
                owner
                    .literal_check()
                    .expect("literal checks use the current owner snapshot")
            })
            .collect::<Vec<_>>();

        assert_eq!(checks.len(), 14);
        for (index, primitive) in [
            (0, PrimTy::Char),
            (1, PrimTy::Char),
            (2, PrimTy::Char),
            (3, PrimTy::Char),
            (4, PrimTy::Byte),
            (5, PrimTy::Byte),
            (6, PrimTy::Byte),
        ] {
            assert_eq!(
                checks[index],
                &ConstLiteralCheck::Supported {
                    primitive,
                    diagnostics: Vec::new(),
                },
                "decoded literal at owner index {index} should fit its exact primitive"
            );
        }
        for index in 7..=11 {
            let ConstLiteralCheck::Supported {
                primitive,
                diagnostics,
            } = checks[index]
            else {
                panic!("mismatched literal at owner index {index} should be diagnosed");
            };
            assert_eq!(diagnostics.len(), 1, "owner index {index}");
            assert_eq!(
                diagnostics[0].code,
                sai_diagnostics::Code::TypeMismatch,
                "owner index {index}"
            );
            assert_eq!(
                *primitive,
                match index {
                    7 | 10 => PrimTy::Char,
                    _ => PrimTy::Byte,
                },
                "owner index {index}"
            );
            assert!(diagnostics[0].has_workspace_snapshot());
            assert!(diagnostics[0].primary().is_some());
        }
        assert_eq!(
            checks[12],
            &ConstLiteralCheck::SupportedStr {
                diagnostics: Vec::new(),
            },
            "a direct canonical Str literal is supported"
        );
        assert_eq!(
            checks[13],
            &ConstLiteralCheck::Unsupported,
            "references remain outside the literal slice"
        );
    }

    #[test]
    fn const_str_literal_check_accepts_only_deferred_canonical_str_paths() {
        let root = concat!(
            "pub const EMPTY: Str = \"\"\n",
            "pub const ESCAPED: Str = \"line\\nfeed\"\n",
            "pub const RAW: Str = r#\"raw { text }\"#\n",
            "pub const MULTILINE: Str = \"\"\"\n",
            "    first\n",
            "    second\n",
            "    \"\"\"\n",
            "pub const UNICODE: Str = \"こんにちは\"\n",
            "pub const BOOL_MISMATCH: Str = true\n",
            "pub const BYTE_STRING_MISMATCH: Str = b\"bytes\"\n",
            "pub const INTEGER_MISMATCH: I8 = \"text\"\n",
            "pub const FORMAT: Str = f\"text\"\n",
            "pub const BLOCK: Str = { \"text\" }\n",
            "pub const ALIAS: UserStr = \"text\"\n",
            "pub const RAW_TYPE: r#Str = \"text\"\n",
        );
        let (mut database, module_tree, snapshot, _) = phase1_fixture(root.as_bytes(), b"");
        let target_cfg = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let collection = database
            .collect_phase1_package_scopes_collection(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
            )
            .expect("const package scopes collect");
        let resolved = database
            .resolve_const_owner_paths(&collection, &module_tree, &snapshot)
            .expect("const owners resolve");
        let checks = resolved
            .owners()
            .iter()
            .map(|owner| {
                owner
                    .literal_check()
                    .expect("literal checks use the current owner snapshot")
            })
            .collect::<Vec<_>>();

        assert_eq!(checks.len(), 12);
        for index in 0..5 {
            assert_eq!(
                checks[index],
                &ConstLiteralCheck::SupportedStr {
                    diagnostics: Vec::new(),
                },
                "direct string literal at owner index {index} is supported"
            );
        }
        for index in [5, 6] {
            let ConstLiteralCheck::SupportedStr { diagnostics } = checks[index] else {
                panic!("Str mismatch at owner index {index} should be diagnosed");
            };
            assert_eq!(diagnostics.len(), 1, "owner index {index}");
            assert_eq!(
                diagnostics[0].code,
                sai_diagnostics::Code::TypeMismatch,
                "owner index {index}"
            );
            assert!(diagnostics[0].has_workspace_snapshot());
            assert!(diagnostics[0].primary().is_some());
        }
        let ConstLiteralCheck::Supported {
            primitive,
            diagnostics,
        } = checks[7]
        else {
            panic!("integer-typed string literal should have a type mismatch");
        };
        assert_eq!(*primitive, sai_resolve::prelude::PrimTy::I8);
        assert_eq!(diagnostics.len(), 1);
        assert_eq!(diagnostics[0].code, sai_diagnostics::Code::TypeMismatch);
        for index in [8, 9, 10, 11] {
            assert_eq!(
                checks[index],
                &ConstLiteralCheck::Unsupported,
                "unsupported string form or noncanonical type at owner index {index}"
            );
        }

        let shadowed = concat!(
            "pub type Str = U8\n",
            "pub const SHADOWED: Str = \"text\"\n",
        );
        let (mut database, module_tree, snapshot, _) = phase1_fixture(shadowed.as_bytes(), b"");
        let target_cfg = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let collection = database
            .collect_phase1_package_scopes_collection(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
            )
            .expect("shadowing const package scopes collect");
        let resolved = database
            .resolve_const_owner_paths(&collection, &module_tree, &snapshot)
            .expect("shadowing const owners resolve");
        assert_eq!(
            resolved.owners()[0]
                .literal_check()
                .expect("literal checks use the current owner snapshot"),
            &ConstLiteralCheck::Unsupported,
            "a source type binding named Str must not use the canonical prelude fallback"
        );
    }

