    #[test]
    fn trait_impl_header_test_only_paths_cover_direct_headers_only() {
        let root = concat!(
            "use acme:test-support/fixtures as fixture\n",
            "use acme:test-support/fixtures.{Fixture}\n",
            "use acme:test-support/fixtures.{Fixture as Fn}\n",
            "use acme:test-support/fixtures.{Fixture as FnMut}\n",
            "use acme:test-support/fixtures as fs\n",
            "fn local_function() {}\n",
            "@target(\"wasm64-core\") trait Filtered: fixture.Filtered {}\n",
            "trait Header<T: Fn(Fixture), ",
            "const N: fixture.ConstType>: fixture.Super ",
            "where T: (FnMut() -> Bool effects { fs.read, fixture.effect }) + fixture.Where {\n",
            "  type Associated: fixture.Associated\n",
            "  fn method() -> fixture.Returned\n",
            "}\n",
            "trait Shadow<Fixture> where Fixture: fixture.ShadowBound {}\n",
            "impl<T: fixture.ImplBound, const N: fixture.ImplSize> ",
            "fixture.Trait<T> for fixture.SelfType where T: fixture.ImplWhere {}\n",
            "impl fixture.Api {}\n",
        );
        let (mut database, module_tree, snapshot, _) = phase1_fixture(root.as_bytes(), b"");
        let target_cfg = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let manifest = Arc::<[u8]>::from(
            &b"package acme:phase1 @ 1.0.0\n\
              requires test { acme:test-support @ ^1 }\n"[..],
        );
        let collection = database
            .collect_phase1_package_scopes_with_manifest_and_foreign_scopes(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
                manifest,
                PackageRole::Root,
                &[],
            )
            .expect("test-only header imports are retained");
        let results = database
            .resolve_trait_impl_header_test_only_paths(&collection, &module_tree, &snapshot)
            .expect("trait and impl headers resolve");
        assert!(results.matches_collection(&collection));
        assert_eq!(
            results
                .owners()
                .iter()
                .map(|owner| owner.kind())
                .collect::<Vec<_>>(),
            [
                TopLevelOwnerKind::Trait,
                TopLevelOwnerKind::Trait,
                TopLevelOwnerKind::Impl,
                TopLevelOwnerKind::Impl,
            ],
            "the target-excluded trait has no current owner descriptor"
        );

        let span_for = |start: usize, text: &str| {
            sai_diagnostics::Span::new(
                module_tree.modules[0].file,
                sai_diagnostics::TextRange::new(
                    sai_diagnostics::TextSize::new(start as u32),
                    sai_diagnostics::TextSize::new((start + text.len()) as u32),
                )
                .expect("reference range is ordered"),
            )
        };
        let span_of = |needle: &str, offset: usize| {
            let start = root
                .find(needle)
                .unwrap_or_else(|| panic!("reference text `{needle}` exists"))
                + offset;
            let suffix = &root[start..];
            let head_len = suffix
                .find(|character: char| !character.is_alphanumeric() && character != '_')
                .unwrap_or(suffix.len());
            span_for(start, &suffix[..head_len])
        };
        let package_path_span = |occurrence: usize| {
            let start = root
                .match_indices("acme:test-support/fixtures")
                .nth(occurrence)
                .expect("expected import path exists")
                .0;
            span_for(start, "acme:test-support/fixtures")
        };
        fn diagnostics_for(owner: &TraitImplHeaderResolution) -> &[Diagnostic] {
            owner
                .test_only_diagnostics()
                .expect("header diagnostics succeed")
        }
        let diagnostic_spans = |diagnostics: &[Diagnostic]| {
            diagnostics
                .iter()
                .map(|diagnostic| {
                    diagnostic
                        .primary()
                        .expect("test-only header path has a primary span")
                        .span
                        .clone()
                })
                .collect::<Vec<_>>()
        };
        let fixture_package_path = package_path_span(0);
        let type_package_path = package_path_span(1);
        let assert_import_note = |diagnostic: &Diagnostic, expected: &sai_diagnostics::Span| {
            assert!(diagnostic.related().iter().any(|related| matches!(
                related,
                Related::DeclaredHere { location, .. } if &location.span == expected
            )));
        };

        let trait_diagnostics = diagnostics_for(&results.owners()[0]);
        assert_eq!(
            diagnostic_spans(trait_diagnostics),
            [
                span_of("Fn(Fixture)", "Fn(".len()),
                span_of("fixture.ConstType", 0),
                span_of("fixture.Super", 0),
                span_of("fixture.effect", 0),
                span_of("fixture.Where", 0),
            ],
            "trait generic bounds, nested Fn type/effect paths, const parameter types, supertraits, and where bounds are checked"
        );
        assert!(
            trait_diagnostics
                .iter()
                .all(|diagnostic| diagnostic.code
                    == sai_diagnostics::Code::TestDependencyOutsideTest)
        );
        for diagnostic in trait_diagnostics {
            let reference = &root[diagnostic
                .primary()
                .expect("trait header diagnostic has a primary span")
                .span
                .range
                .start()
                .raw() as usize
                ..diagnostic
                    .primary()
                    .expect("trait header diagnostic has a primary span")
                    .span
                    .range
                    .end()
                    .raw() as usize];
            assert_import_note(
                diagnostic,
                if reference == "Fixture" {
                    &type_package_path
                } else {
                    &fixture_package_path
                },
            );
        }
        assert_eq!(
            results.owners()[0]
                .test_only_path_resolution()
                .expect("trait non-expression paths resolve")
                .paths()
                .len(),
            5
        );
        assert!(
            !trait_diagnostics.iter().any(|diagnostic| {
                let span = &diagnostic.primary().expect("diagnostic has a span").span;
                span == &span_of("fixture.Associated", 0) || span == &span_of("fixture.Returned", 0)
            }),
            "associated declarations remain outside the direct trait header pass"
        );

        let shadow_diagnostics = diagnostics_for(&results.owners()[1]);
        assert_eq!(
            diagnostic_spans(shadow_diagnostics),
            [span_of("fixture.ShadowBound", 0)],
            "the generic Fixture suppresses its same-named imported type path"
        );
        assert_import_note(&shadow_diagnostics[0], &fixture_package_path);

        let impl_diagnostics = diagnostics_for(&results.owners()[2]);
        assert_eq!(
            diagnostic_spans(impl_diagnostics),
            [
                span_of("fixture.ImplBound", 0),
                span_of("fixture.ImplSize", 0),
                span_of("fixture.Trait", 0),
                span_of("fixture.SelfType", 0),
                span_of("fixture.ImplWhere", 0),
            ],
            "impl generics, where bounds, trait target, and self type are checked"
        );
        let interface_impl_diagnostics = diagnostics_for(&results.owners()[3]);
        assert_eq!(
            diagnostic_spans(interface_impl_diagnostics),
            [span_of("fixture.Api", 0)],
            "interface implementation targets are checked"
        );
        for diagnostic in impl_diagnostics
            .iter()
            .chain(interface_impl_diagnostics.iter())
        {
            assert_import_note(diagnostic, &fixture_package_path);
        }
        assert!(
            !trait_diagnostics.iter().any(|diagnostic| {
                diagnostic.primary().is_some_and(|primary| {
                    &root[primary.span.range.start().raw() as usize
                        ..primary.span.range.end().raw() as usize]
                        == "Fn"
                        || &root[primary.span.range.start().raw() as usize
                            ..primary.span.range.end().raw() as usize]
                            == "FnMut"
                        || &root[primary.span.range.start().raw() as usize
                            ..primary.span.range.end().raw() as usize]
                            == "fs"
                })
            }),
            "Fn and FnMut sugar plus the built-in fs effect root take precedence over imported names"
        );

        // Source declarations provide valid DefIds for the already-resolved
        // import entries. Test-only classification follows import provenance.
        let fixture_symbol = collection
            .scopes()
            .module(ModuleId::ROOT)
            .expect("root scope exists")
            .scope
            .keys()
            .copied()
            .find(|symbol| {
                database
                    .resolve_symbol(*symbol)
                    .is_ok_and(|name| name.as_ref() == "fixture")
            })
            .expect("fixture alias exists");
        let type_symbol = collection
            .scopes()
            .module(ModuleId::ROOT)
            .expect("root scope exists")
            .scope
            .keys()
            .copied()
            .find(|symbol| {
                database
                    .resolve_symbol(*symbol)
                    .is_ok_and(|name| name.as_ref() == "Fixture")
            })
            .expect("Fixture type import exists");
        let import_index = |symbol| match collection
            .scopes()
            .module(ModuleId::ROOT)
            .expect("root scope exists")
            .scope
            .get(&symbol)
            .expect("module binding exists")
            .origin
        {
            BindingOrigin::Use { import } | BindingOrigin::PubUse { import } => import,
            BindingOrigin::Decl => panic!("test-only name comes from an import"),
        };
        let fixture_import = import_index(fixture_symbol);
        let type_import = import_index(type_symbol);
        let function_def = collection.scopes.function_owners[0]
            .owner
            .def_id
            .to_def_id();
        let mut resolved_import_collection = collection.clone();
        {
            let root_scope =
                &mut resolved_import_collection.scopes.modules[ModuleId::ROOT.raw() as usize];
            for (symbol, import, resolution) in [
                (
                    fixture_symbol,
                    fixture_import,
                    Res::Def(DefKind::Fn, function_def),
                ),
                (
                    type_symbol,
                    type_import,
                    Res::Def(DefKind::Fn, function_def),
                ),
            ] {
                assert!(root_scope.imports[import.0 as usize].test_only);
                root_scope.imports[import.0 as usize].res = resolution;
                root_scope
                    .scope
                    .get_mut(&symbol)
                    .expect("test-only binding exists")
                    .res = resolution;
            }
        }
        let resolved_imports = database
            .resolve_trait_impl_header_test_only_paths(
                &resolved_import_collection,
                &module_tree,
                &snapshot,
            )
            .expect("resolved test-only header imports remain diagnosable");
        assert_eq!(
            resolved_imports.owners()[0]
                .test_only_diagnostics()
                .expect("resolved trait header diagnostics succeed")
                .len(),
            5
        );
        assert!(
            resolved_imports.owners()[0]
                .test_only_path_resolution()
                .expect("resolved trait path results succeed")
                .paths()
                .values()
                .all(|path| path.base == Res::Err),
            "resolved test-only trait paths are rewritten to the error sentinel"
        );
        let resolved_trait_types = resolved_imports.owners()[0]
            .type_path_resolution()
            .expect("resolved trait type heads remain available");
        assert!(
            resolved_trait_types
                .paths()
                .values()
                .any(|path| path.base == Res::Err),
            "ordinary type lookup rejects test-only imported heads even when their imports have resolutions"
        );
        assert!(
            resolved_trait_types
                .paths()
                .values()
                .all(|path| path.base != Res::Def(DefKind::Fn, function_def)),
            "trait type lookup never captures a test-only import resolution"
        );
        assert_eq!(
            resolved_imports.owners()[2]
                .test_only_diagnostics()
                .expect("resolved impl header diagnostics succeed")
                .len(),
            5
        );
        for owner in resolved_imports.owners() {
            for diagnostic in diagnostics_for(owner) {
                let primary = diagnostic
                    .primary()
                    .expect("resolved header diagnostic has a primary span");
                let reference = &root[primary.span.range.start().raw() as usize
                    ..primary.span.range.end().raw() as usize];
                assert_import_note(
                    diagnostic,
                    if reference == "Fixture" {
                        &type_package_path
                    } else {
                        &fixture_package_path
                    },
                );
            }
            assert!(
                owner
                    .test_only_path_resolution()
                    .expect("resolved header path results succeed")
                    .paths()
                    .values()
                    .all(|path| path.base == Res::Err),
                "resolved test-only header paths are rewritten to the error sentinel"
            );
            assert!(
                owner
                    .type_path_resolution()
                    .expect("resolved header type paths succeed")
                    .paths()
                    .values()
                    .all(|path| path.base != Res::Def(DefKind::Fn, function_def)),
                "ordinary header type lookup never captures test-only import resolutions"
            );
        }

        let mut ordinary_collection = collection.clone();
        ordinary_collection.scopes.modules[ModuleId::ROOT.raw() as usize].imports
            [fixture_import.0 as usize]
            .test_only = false;
        let ordinary_results = database
            .resolve_trait_impl_header_test_only_paths(
                &ordinary_collection,
                &module_tree,
                &snapshot,
            )
            .expect("ordinary header imports remain resolvable");
        assert_eq!(
            diagnostic_spans(diagnostics_for(&ordinary_results.owners()[0])),
            [span_of("Fn(Fixture)", "Fn(".len())],
            "ordinary module-alias imports are not diagnosed but the test-only Fixture import is"
        );
        assert!(
            ordinary_results
                .owners()
                .iter()
                .skip(1)
                .all(|owner| diagnostics_for(owner).is_empty()),
            "ordinary imports do not receive test-only diagnostics"
        );

        // A malformed descriptor fails only its own owner; later direct
        // trait and impl header owners still complete.
        let mut broken_collection = collection.clone();
        let header_owner = results.owners()[0].owner();
        let shadow_owner = results.owners()[1].owner();
        let header_index = broken_collection
            .scopes
            .top_level_owners
            .iter()
            .position(|descriptor| descriptor.owner == header_owner)
            .expect("trait descriptor exists");
        let shadow_item = broken_collection
            .scopes
            .top_level_owners
            .iter()
            .find(|descriptor| descriptor.owner == shadow_owner)
            .expect("shadow trait descriptor exists")
            .item_id;
        broken_collection.scopes.top_level_owners[header_index].item_id = shadow_item;
        let isolated = database
            .resolve_trait_impl_header_test_only_paths(&broken_collection, &module_tree, &snapshot)
            .expect("header descriptor failures remain isolated");
        assert!(
            isolated.owners()[0].test_only_diagnostics().is_err(),
            "the malformed header descriptor reports an owner-local failure"
        );
        assert!(
            isolated
                .owners()
                .iter()
                .skip(1)
                .all(|owner| owner.test_only_diagnostics().is_ok()),
            "subsequent trait and impl headers continue resolving"
        );
    }

    #[test]
    fn interface_impl_target_kind_diagnostics_skip_interfaces_and_unresolved_paths() {
        let source = concat!(
            "use acme:phase1/child as child_alias\n",
            "interface api {}\n",
            "impl api {}\n",
            "impl child_alias.not_interface {}\n",
            "impl missing {}\n",
        );
        let (mut database, module_tree, snapshot, _) =
            phase1_fixture(source.as_bytes(), b"fn not_interface() {}\n");
        let target_cfg = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let collection = database
            .collect_phase1_package_scopes_collection(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
            )
            .expect("Phase 1 scopes collect");
        let results = database
            .resolve_trait_impl_header_test_only_paths(&collection, &module_tree, &snapshot)
            .expect("impl targets resolve");
        assert_eq!(results.owners().len(), 3);

        let diagnostic_owners = results
            .owners()
            .iter()
            .map(|owner| {
                owner
                    .interface_impl_target_diagnostics()
                    .expect("interface target diagnostic analysis succeeds")
            })
            .collect::<Vec<_>>();
        assert!(diagnostic_owners[0].is_empty(), "interface target passes");
        assert_eq!(diagnostic_owners[1].len(), 1);
        let diagnostic = &diagnostic_owners[1][0];
        assert_eq!(
            diagnostic.code,
            sai_diagnostics::Code::ImplTargetNotInterface
        );
        assert_eq!(
            diagnostic.primary().map(|location| location.span.range),
            Some(
                sai_diagnostics::TextRange::new(
                    sai_diagnostics::TextSize::new(
                        source.find("child_alias.not_interface").unwrap() as u32,
                    ),
                    sai_diagnostics::TextSize::new(
                        (source.find("child_alias.not_interface").unwrap()
                            + "child_alias.not_interface".len()) as u32,
                    ),
                )
                .expect("target span is ordered")
            ),
            "the primary span covers the complete non-interface target path"
        );
        assert!(diagnostic.has_workspace_snapshot());
        assert!(
            diagnostic_owners[2].is_empty(),
            "unresolved target does not cascade"
        );

        let stale_snapshot = phase1_snapshot_from_vfs(&mut database, &module_tree, 18);
        assert!(matches!(
            database.resolve_trait_impl_header_test_only_paths(
                &collection,
                &module_tree,
                &stale_snapshot,
            ),
            Err(OwnerControlFlowResolutionError::SnapshotMismatch)
        ));
    }

    #[test]
    fn interface_impl_collection_matches_local_items_and_keeps_target_diagnostics_single_owned() {
        let source = concat!(
            "interface api {\n",
            "  fn run()\n",
            "  fn stop()\n",
            "}\n",
            "fn not_interface() {}\n",
            "impl api {\n",
            "  fn run() {}\n",
            "  fn run() {}\n",
            "  fn extra() {}\n",
            "}\n",
            "impl api {}\n",
            "impl not_interface { fn should_skip() {} }\n",
            "impl missing { fn should_skip() {} }\n",
        );
        let (mut database, module_tree, snapshot, _) = phase1_fixture(source.as_bytes(), b"");
        let target_cfg = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let graph = phase1_root_only_graph();
        database
            .set_package_graph(Some(graph.clone()))
            .expect("active package graph is recorded");
        let collection = database
            .collect_phase1_package_scopes_collection(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
            )
            .expect("local interface impl source collects");
        let member_scopes = database
            .collect_active_source_member_scopes(&collection, &graph, &[])
            .expect("empty source member closure validates");
        let header_resolutions = database
            .resolve_trait_impl_header_test_only_paths_with_member_scopes(
                &collection,
                &module_tree,
                &snapshot,
                &member_scopes,
            )
            .expect("local impl targets resolve");
        let member_resolutions = database
            .resolve_trait_impl_member_test_only_paths_with_member_scopes(
                &collection,
                &module_tree,
                &snapshot,
                &member_scopes,
            )
            .expect("impl associated types resolve");

        let collected = database
            .collect_interface_impls_with_header_resolutions(
                &collection,
                &module_tree,
                &snapshot,
                &member_scopes,
                None,
                &header_resolutions,
                &member_resolutions,
            )
            .expect("interface impl items collect");

        assert_eq!(collected.impls.len(), 4);
        assert_eq!(collected.by_interface.len(), 1);
        assert_eq!(
            collected
                .impls
                .iter()
                .map(|implementation| implementation.interface.is_some())
                .collect::<Vec<_>>(),
            [true, true, false, false],
            "wrong-kind and unresolved targets preserve records without item matching"
        );
        assert_eq!(
            collected
                .diagnostics
                .iter()
                .map(|diagnostic| diagnostic.code)
                .collect::<Vec<_>>(),
            [
                sai_diagnostics::Code::InterfaceImplExtraItem,
                sai_diagnostics::Code::InterfaceImplExtraItem,
                sai_diagnostics::Code::InterfaceImplMissingItem,
                sai_diagnostics::Code::DuplicateInterfaceImpl,
            ],
            "repeated, extra, missing, and duplicate diagnostics follow source/spec order"
        );
        assert!(
            collected
                .diagnostics
                .iter()
                .all(|diagnostic| diagnostic.has_workspace_snapshot()),
            "collector diagnostics are rebound to the active workspace snapshot"
        );
        let repeated_start = source.match_indices("run").nth(2).unwrap().0;
        assert_eq!(
            collected.diagnostics[0]
                .primary()
                .map(|location| location.span.range.start()),
            Some(sai_diagnostics::TextSize::new(repeated_start as u32)),
            "the repeated-item primary location points at the later name"
        );
        let extra_start = source.find("extra").expect("extra item exists");
        assert_eq!(
            collected.diagnostics[1]
                .primary()
                .map(|location| location.span.range.start()),
            Some(sai_diagnostics::TextSize::new(extra_start as u32))
        );
        let first_target_start = source.find("impl api").unwrap() + "impl ".len();
        assert_eq!(
            collected.diagnostics[2]
                .primary()
                .map(|location| location.span.range.start()),
            Some(sai_diagnostics::TextSize::new(first_target_start as u32)),
            "missing items point at the full implementation target"
        );
        let second_target_start = source[first_target_start + 1..]
            .find("impl api")
            .map(|offset| first_target_start + 1 + offset + "impl ".len())
            .expect("second interface impl target exists");
        assert_eq!(
            collected.diagnostics[3]
                .primary()
                .map(|location| location.span.range.start()),
            Some(sai_diagnostics::TextSize::new(second_target_start as u32)),
            "duplicate target diagnostic points at the later target"
        );
        match &collected.diagnostics[3].related()[0] {
            sai_diagnostics::Related::DeclaredHere { location, .. } => assert_eq!(
                location.span.range.start(),
                sai_diagnostics::TextSize::new(first_target_start as u32),
                "duplicate target relates to the first target"
            ),
            other => panic!("duplicate target has an unexpected related fact: {other:?}"),
        }

        let target_diagnostics = header_resolutions
            .owners()
            .iter()
            .flat_map(|owner| {
                owner
                    .interface_impl_target_diagnostics()
                    .expect("header target-kind diagnostics resolve")
                    .iter()
            })
            .filter(|diagnostic| diagnostic.code == sai_diagnostics::Code::ImplTargetNotInterface)
            .collect::<Vec<_>>();
        assert_eq!(target_diagnostics.len(), 1);
        assert_eq!(
            target_diagnostics[0]
                .primary()
                .map(|location| location.span.range.start()),
            Some(sai_diagnostics::TextSize::new(
                (source.find("impl not_interface").unwrap() + "impl ".len()) as u32
            )),
            "IR-619 alone diagnoses the resolved wrong-kind target"
        );
        assert!(
            collected
                .diagnostics
                .iter()
                .all(|diagnostic| diagnostic.code != sai_diagnostics::Code::ImplTargetNotInterface),
            "the collector does not create a duplicate target-kind diagnostic"
        );

        let stale_snapshot = phase1_snapshot_from_vfs(&mut database, &module_tree, 18);
        assert!(matches!(
            database.collect_interface_impls_with_header_resolutions(
                &collection,
                &module_tree,
                &stale_snapshot,
                &member_scopes,
                None,
                &header_resolutions,
                &member_resolutions,
            ),
            Err(OwnerControlFlowResolutionError::SnapshotMismatch)
        ));
    }

    #[test]
    fn interface_impl_collection_rejects_generic_function_restrictions_at_exact_spans() {
        let source = concat!(
            "interface api {\n",
            "  fn run()\n",
            "}\n",
            "impl api {\n",
            "  fn run<T>() where T: Copy {}\n",
            "}\n",
        );
        let (mut database, module_tree, snapshot, _) = phase1_fixture(source.as_bytes(), b"");
        let target_cfg = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let graph = phase1_root_only_graph();
        database
            .set_package_graph(Some(graph.clone()))
            .expect("active package graph is recorded");
        let collection = database
            .collect_phase1_package_scopes_collection(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
            )
            .expect("local interface impl source collects");
        let member_scopes = database
            .collect_active_source_member_scopes(&collection, &graph, &[])
            .expect("empty source member closure validates");
        let header_resolutions = database
            .resolve_trait_impl_header_test_only_paths_with_member_scopes(
                &collection,
                &module_tree,
                &snapshot,
                &member_scopes,
            )
            .expect("local impl targets resolve");
        let member_resolutions = database
            .resolve_trait_impl_member_test_only_paths_with_member_scopes(
                &collection,
                &module_tree,
                &snapshot,
                &member_scopes,
            )
            .expect("impl associated items resolve");

        let collected = database
            .collect_interface_impls_with_header_resolutions(
                &collection,
                &module_tree,
                &snapshot,
                &member_scopes,
                None,
                &header_resolutions,
                &member_resolutions,
            )
            .expect("interface impl items collect");

        assert_eq!(
            collected
                .diagnostics
                .iter()
                .map(|diagnostic| diagnostic.code)
                .collect::<Vec<_>>(),
            [
                sai_diagnostics::Code::GenericInterfaceItem,
                sai_diagnostics::Code::GenericInterfaceItem,
            ]
        );
        let generic_start = source.find("<T>").expect("generic parameters exist");
        let where_start = source.find("where T: Copy").expect("where clause exists");
        assert_eq!(
            collected.diagnostics[0]
                .primary()
                .map(|location| location.span.range),
            Some(
                sai_diagnostics::TextRange::new(
                    sai_diagnostics::TextSize::new(generic_start as u32),
                    sai_diagnostics::TextSize::new((generic_start + "<T>".len()) as u32),
                )
                .expect("generic span is ordered")
            )
        );
        assert_eq!(
            collected.diagnostics[1]
                .primary()
                .map(|location| location.span.range),
            Some(
                sai_diagnostics::TextRange::new(
                    sai_diagnostics::TextSize::new(where_start as u32),
                    sai_diagnostics::TextSize::new((where_start + "where T: Copy".len()) as u32),
                )
                .expect("where span is ordered")
            )
        );
        assert!(
            !collected.impls[0].fns[0].compare_signature,
            "the collected function pair carries the conformance skip state"
        );
        assert!(
            collected
                .diagnostics
                .iter()
                .all(Diagnostic::has_workspace_snapshot),
            "generic conformance diagnostics use the active snapshot"
        );
    }

    #[test]
    fn interface_impl_collection_records_resolved_resource_bindings() {
        let source = concat!(
            "resource Concrete {}\n",
            "resource AliasConcrete {}\n",
            "resource TopAliasConcrete {}\n",
            "resource GenericConcrete {}\n",
            "resource ConstGenericConcrete {}\n",
            "type Direct = TopAliasConcrete\n",
            "type Identity<T> = T\n",
            "type Through<T> = Identity<T>\n",
            "type ConstThrough<const N: U8> = ConstGenericConcrete\n",
            "interface api {\n",
            "  resource Handle {}\n",
            "  resource AliasHandle {}\n",
            "  resource TopAliasHandle {}\n",
            "  resource GenericHandle {}\n",
            "  resource ConstGenericHandle {}\n",
            "  type ConcreteAlias = AliasConcrete\n",
            "}\n",
            "impl api {\n",
            "  type Handle = Concrete\n",
            "  type AliasHandle = api.ConcreteAlias\n",
            "  type TopAliasHandle = Direct\n",
            "  type GenericHandle = Through<GenericConcrete>\n",
            "  type ConstGenericHandle = ConstThrough<1>\n",
            "}\n",
            "interface unresolved_api { resource Thing {} }\n",
            "impl unresolved_api { type Thing = missing }\n",
        );
        let (mut database, module_tree, snapshot, _) = phase1_fixture(source.as_bytes(), b"");
        let target_cfg = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let graph = phase1_root_only_graph();
        database
            .set_package_graph(Some(graph.clone()))
            .expect("active package graph is recorded");
        let collection = database
            .collect_phase1_package_scopes_collection(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
            )
            .expect("local resource binding source collects");
        let member_scopes = database
            .collect_active_source_member_scopes(&collection, &graph, &[])
            .expect("empty source member closure validates");
        let header_resolutions = database
            .resolve_trait_impl_header_test_only_paths_with_member_scopes(
                &collection,
                &module_tree,
                &snapshot,
                &member_scopes,
            )
            .expect("interface targets resolve");
        let member_resolutions = database
            .resolve_trait_impl_member_test_only_paths_with_member_scopes(
                &collection,
                &module_tree,
                &snapshot,
                &member_scopes,
            )
            .expect("associated type RHS paths resolve");

        let collected = database
            .collect_interface_impls_with_header_resolutions(
                &collection,
                &module_tree,
                &snapshot,
                &member_scopes,
                None,
                &header_resolutions,
                &member_resolutions,
            )
            .expect("resolved binding identities are collected");

        assert_eq!(collected.impls.len(), 2);
        let api_symbol = database
            .symbols
            .intern("api")
            .expect("interface name interns");
        let resource_symbol = database
            .symbols
            .intern("Handle")
            .expect("abstract resource name interns");
        let concrete_symbol = database
            .symbols
            .intern("Concrete")
            .expect("implementation resource name interns");
        let alias_concrete_symbol = database
            .symbols
            .intern("AliasConcrete")
            .expect("aliased implementation resource name interns");
        let top_alias_concrete_symbol = database
            .symbols
            .intern("TopAliasConcrete")
            .expect("top-level aliased resource name interns");
        let generic_concrete_symbol = database
            .symbols
            .intern("GenericConcrete")
            .expect("generic implementation resource name interns");
        let const_generic_concrete_symbol = database
            .symbols
            .intern("ConstGenericConcrete")
            .expect("const generic implementation resource name interns");
        let top_alias_handle_symbol = database
            .symbols
            .intern("TopAliasHandle")
            .expect("top-level alias resource name interns");
        let module_scope = &collection.scopes.modules[0].scope;
        let interface_def = match module_scope
            .get(&api_symbol)
            .expect("local interface binding exists")
            .res
        {
            Res::Def(DefKind::Interface, def) => def,
            other => panic!("api resolves to a local interface, got {other:?}"),
        };
        let interface_resource = match collection.scopes.interfaces[&interface_def]
            .members
            .get(&resource_symbol)
            .expect("interface resource binding exists")
            .res
        {
            Res::Def(DefKind::Resource, def) => def,
            other => panic!("Handle resolves to an interface resource, got {other:?}"),
        };
        let implementation_type = match module_scope
            .get(&concrete_symbol)
            .expect("local implementation resource binding exists")
            .res
        {
            Res::Def(DefKind::Resource, def) => def,
            other => panic!("Concrete resolves to a top-level resource, got {other:?}"),
        };
        let alias_implementation_type = match module_scope
            .get(&alias_concrete_symbol)
            .expect("aliased resource binding exists")
            .res
        {
            Res::Def(DefKind::Resource, def) => def,
            other => panic!("AliasConcrete resolves to a resource, got {other:?}"),
        };
        let top_alias_implementation_type = match module_scope
            .get(&top_alias_concrete_symbol)
            .expect("top-level aliased resource binding exists")
            .res
        {
            Res::Def(DefKind::Resource, def) => def,
            other => panic!("TopAliasConcrete resolves to a resource, got {other:?}"),
        };
        let generic_implementation_type = match module_scope
            .get(&generic_concrete_symbol)
            .expect("generic aliased resource binding exists")
            .res
        {
            Res::Def(DefKind::Resource, def) => def,
            other => panic!("GenericConcrete resolves to a resource, got {other:?}"),
        };
        let const_generic_implementation_type = match module_scope
            .get(&const_generic_concrete_symbol)
            .expect("const generic aliased resource binding exists")
            .res
        {
            Res::Def(DefKind::Resource, def) => def,
            other => panic!("ConstGenericConcrete resolves to a resource, got {other:?}"),
        };
        let top_alias_resource = match collection.scopes.interfaces[&interface_def]
            .members
            .get(&top_alias_handle_symbol)
            .expect("top-level alias resource binding exists")
            .res
        {
            Res::Def(DefKind::Resource, def) => def,
            other => panic!("TopAliasHandle resolves to a resource, got {other:?}"),
        };
        assert_eq!(collected.impls[0].resources.len(), 5);
        assert_eq!(collected.impls[0].resources[0].resource, interface_resource);
        assert_eq!(
            collected.impls[0].resources[0].implementation_type,
            implementation_type
        );
        assert_eq!(
            collected.impls[0].resources[1].implementation_type, alias_implementation_type,
            "a transparent non-generic alias expands to its resource"
        );
        assert_eq!(
            collected.impls[0].resources[2].implementation_type, top_alias_implementation_type,
            "a top-level alias can target a local resource"
        );
        assert_eq!(
            collected.impls[0].resources[2].resource, top_alias_resource,
            "interface aliases retain their abstract resource identity"
        );
        assert_eq!(
            collected.impls[0].resources[3].implementation_type, generic_implementation_type,
            "generic alias applications substitute their type arguments"
        );
        assert_eq!(
            collected.impls[0].resources[4].implementation_type, const_generic_implementation_type,
            "const generic alias arguments preserve their resource target"
        );
        let binding_start = source.find("type Handle = Concrete").unwrap();
        assert_eq!(
            collected.impls[0].resources[0].binding_span.range.start(),
            sai_diagnostics::TextSize::new(binding_start as u32),
            "the resource record retains the full binding span"
        );
        assert!(
            collected.impls[1].resources.is_empty(),
            "an unresolved RHS does not invent a resource identity"
        );
        assert!(
            collected.diagnostics.is_empty(),
            "an unresolved RHS still satisfies item-name matching without a missing-item cascade"
        );
    }

    #[test]
    fn interface_resource_bindings_expand_foreign_source_aliases() {
        let mut database = RootDatabase::new().expect("driver initializes");
        let (_, root_tree, mut snapshot_files) = multi_package_fixture(
            &mut database,
            "acme:root#1",
            "acme:root@1.0.0",
            &[(
                "lib.sai",
                b"use acme:dep as dep\n\
                  resource Concrete {}\n\
                  resource AnotherConcrete {}\n\
                  interface api {\n\
                    resource TopLevelAlias {}\n\
                    resource InterfaceAlias {}\n\
                    resource IncompleteAlias {}\n\
                  }\n\
                  impl api {\n\
                    type TopLevelAlias = dep.Through<Concrete>\n\
                    type InterfaceAlias = dep.types.Identity<AnotherConcrete>\n\
                    type IncompleteAlias = dep.Broken<Concrete>\n\
                  }\n",
            )],
        );
        let (_, dependency_tree, dependency_snapshot_files) = multi_package_fixture(
            &mut database,
            "acme:dep#1",
            "acme:dep@1.0.0",
            &[(
                "lib.sai",
                b"pub type Identity<T> = T\n\
                  pub type Through<T> = Identity<T>\n\
                  pub type Broken<T> = Missing<T>\n\
                  pub interface types { type Identity<T> = T }\n",
            )],
        );
        snapshot_files.extend(dependency_snapshot_files);
        let snapshot =
            WorkspaceSnapshot::new(snapshot_files).expect("multi-package snapshot is valid");
        let root_manifest: Arc<[u8]> = Arc::from(
            &b"package acme:root @ 1.0.0\n\
              requires { acme:dep @ ^1 }\n"[..],
        );
        let dependency_manifest: Arc<[u8]> = Arc::from(&b"package acme:dep @ 1.0.0\n"[..]);
        let graph = PackageGraph::new(
            Version::parse("1.8.2").expect("toolchain version is valid"),
            [
                graph_node(
                    "acme:root#1",
                    "acme:root",
                    "1.0.0",
                    PackageGraphRole::Root,
                    vec![graph_edge("acme:dep#1", "acme:dep")],
                ),
                graph_node(
                    "acme:dep#1",
                    "acme:dep",
                    "1.0.0",
                    PackageGraphRole::Dependency,
                    Vec::new(),
                ),
            ],
        )
        .expect("source dependency graph is valid");
        database
            .set_package_graph(Some(graph.clone()))
            .expect("active package graph is recorded");
        let target_cfg = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let dependency_collection = database
            .collect_phase1_package_scopes_with_manifest_and_foreign_scopes(
                &dependency_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext {
                    is_root_package: false,
                    ..Phase1BuildContext::default()
                },
                dependency_manifest,
                PackageRole::Dependency,
                &[],
            )
            .expect("source dependency scopes collect");
        let dependency_member_package = dependency_collection.module_member_scope_package();
        let root_collection = database
            .collect_phase1_package_scopes_with_manifest_and_foreign_scopes(
                &root_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
                root_manifest,
                PackageRole::Root,
                &[dependency_member_package.as_foreign_package_scopes("acme:dep")],
            )
            .expect("root can resolve source dependency aliases");
        let member_scopes = database
            .collect_active_source_member_scopes(
                &root_collection,
                &graph,
                &[dependency_member_package],
            )
            .expect("source dependency closure validates");
        let header_resolutions = database
            .resolve_trait_impl_header_test_only_paths_with_member_scopes(
                &root_collection,
                &root_tree,
                &snapshot,
                &member_scopes,
            )
            .expect("interface targets resolve");
        let member_resolutions = database
            .resolve_trait_impl_member_test_only_paths_with_member_scopes(
                &root_collection,
                &root_tree,
                &snapshot,
                &member_scopes,
            )
            .expect("associated type RHS paths resolve");

        let collected = database
            .collect_interface_impls_with_header_resolutions(
                &root_collection,
                &root_tree,
                &snapshot,
                &member_scopes,
                None,
                &header_resolutions,
                &member_resolutions,
            )
            .expect("foreign transparent aliases are expanded");

        let concrete = ["Concrete", "AnotherConcrete"]
            .into_iter()
            .map(|name| {
                let symbol = database
                    .symbols
                    .intern(name)
                    .expect("resource name interns");
                match root_collection.scopes.modules[0]
                    .scope
                    .get(&symbol)
                    .expect("root resource binding exists")
                    .res
                {
                    Res::Def(DefKind::Resource, def) => def,
                    other => panic!("{name} resolves to a resource, got {other:?}"),
                }
            })
            .collect::<HashSet<_>>();
        assert_eq!(collected.impls.len(), 1);
        assert_eq!(collected.impls[0].resources.len(), 2);
        assert!(
            collected.impls[0]
                .resources
                .iter()
                .all(|resource| concrete.contains(&resource.implementation_type)),
            "both source-package aliases resolve to the caller's resource"
        );
        assert!(
            collected.diagnostics.is_empty(),
            "an incomplete foreign alias body defers instead of reporting a false invalid binding"
        );
    }

