    #[test]
    fn inherent_method_body_type_check_reports_unknown_primitive_self_fields() {
        let root = concat!(
            "type User { name: I32 }\n",
            "impl User {\n",
            "  pub fn read_name(self: borrow Self) -> I32 {\n",
            "    let error_literal = 1 + self.naem\n",
            "    let copied_literal_error = error_literal\n",
            "    let copied_literal_error_again = copied_literal_error\n",
            "    let error_source = self.naem\n",
            "    let copied_error = error_source\n",
            "    let propagated = copied_error + 1\n",
            "    let name = self.name\n",
            "    name\n",
            "  }\n",
            "}\n",
        );
        let (mut database, module_tree, snapshot, _) = phase1_fixture(root.as_bytes(), b"");
        let target_cfg = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let collection = database
            .collect_phase1_package_scopes_collection(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
            )
            .expect("single inherent method collects");
        let results = database
            .resolve_trait_impl_member_test_only_paths(&collection, &module_tree, &snapshot)
            .expect("associated owner analysis succeeds");
        let method = &results.owners()[0].members()[0];
        assert!(
            method
                .local_resolution()
                .expect("method locals resolve")
                .is_some_and(|locals| locals.diagnostics.is_empty()),
            "the unsupported result must come from body checking rather than local resolution"
        );
        assert!(
            method.lowering_diagnostics().is_empty(),
            "unknown fields in a supported local initializer must not produce lowering diagnostics: {:#?}",
            method.lowering_diagnostics()
        );
        assert!(
            method.type_path_resolution().is_ok(),
            "the field diagnostic must not make type-path resolution fail"
        );
        assert!(
            method
                .test_only_diagnostics()
                .expect("test-only diagnostics resolve")
                .is_empty(),
            "the field diagnostic must not alter test-only path analysis"
        );
        let check = method
            .body_type_check()
            .expect("method body check has an independent result");
        let FunctionBodyTypeCheck::Supported { diagnostics } = check else {
            panic!("a direct unknown self-field initializer should be checked: {check:#?}");
        };
        assert_eq!(diagnostics.len(), 2, "{diagnostics:#?}");
        assert!(
            diagnostics
                .iter()
                .all(|diagnostic| diagnostic.code == sai_diagnostics::Code::UnknownField),
            "{diagnostics:#?}"
        );
        let type_results = method
            .primitive_body_type_results()
            .expect("unknown-field errors keep the partial projection")
            .expect("the method body publishes trustworthy independent results");
        assert_primitive_type_result_parity(&database, type_results);
        let local_resolution = method
            .local_resolution()
            .expect("method locals remain available");
        let locals = local_resolution
            .as_ref()
            .expect("the method body has resolved locals");
        let binding_named = |expected_name: &str| {
            locals
                .bindings
                .iter()
                .find_map(|(binding, local)| {
                    local.name.and_then(|symbol| {
                        database
                            .symbols
                            .resolve(symbol)
                            .ok()
                            .filter(|resolved_name| resolved_name.as_ref() == expected_name)
                            .map(|_| *binding)
                    })
                })
                .unwrap_or_else(|| panic!("binding {expected_name} exists"))
        };
        for name in [
            "error_literal",
            "copied_literal_error",
            "copied_literal_error_again",
            "error_source",
            "copied_error",
            "propagated",
        ] {
            assert_eq!(
                type_results.binding_type(binding_named(name)),
                None,
                "unknown-field recovery taint propagates through aliases and operators: {name}"
            );
            assert!(
                type_results
                    .partial_results()
                    .canonical_binding_type(binding_named(name))
                    .is_none(),
                "tainted bindings cannot acquire canonical facts: {name}"
            );
            let binding = binding_named(name);
            let dependent_paths = locals
                .paths
                .iter()
                .filter_map(|(hir_id, resolution)| {
                    (resolution.base == sai_resolve::package_scopes::Res::Local(binding))
                        .then_some(*hir_id)
                })
                .collect::<Vec<_>>();
            assert!(
                dependent_paths
                    .iter()
                    .all(|hir_id| type_results.expression_type(*hir_id).is_none()),
                "tainted local path results are omitted by exact HIR ID: {name}"
            );
            assert!(
                dependent_paths.iter().all(|hir_id| {
                    type_results
                        .partial_results()
                        .canonical_expression_type(*hir_id)
                        .is_none()
                }),
                "tainted HIR paths cannot acquire canonical facts: {name}"
            );
        }
        assert_eq!(
            type_results.binding_type(binding_named("name")),
            Some(sai_resolve::prelude::PrimTy::I32),
            "a valid sibling retains its concrete result beside the field error"
        );
        assert!(
            type_results
                .partial_results()
                .canonical_binding_type(binding_named("name"))
                .is_some(),
            "a valid sibling keeps its canonical type beside field errors"
        );
    }

