    #[test]
    fn interface_use_resolution_prefers_interface_members_over_module_imports() {
        let root = concat!(
            "use b::Request\n",
            "interface a {\n",
            "  type Request = Bool\n",
            "  type UsesRequest = Request\n",
            "}\n",
            "interface b {\n",
            "  type Request = Bool\n",
            "  type UsesA = a.Request\n",
            "}\n",
        );
        let (mut database, module_tree, snapshot, _) = phase1_fixture(root.as_bytes(), b"");
        let target = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let collection = database
            .collect_phase1_package_scopes_collection(
                &module_tree,
                &snapshot,
                &target,
                Phase1BuildContext::default(),
            )
            .expect("Phase 1 interface scopes collect");
        let interfaces = collection
            .scopes()
            .top_level_owners
            .iter()
            .filter(|owner| owner.kind == TopLevelOwnerKind::Interface)
            .map(|owner| owner.owner.def_id)
            .collect::<Vec<_>>();
        assert_eq!(interfaces.len(), 2);
        let [a, b] = interfaces.as_slice() else {
            unreachable!("the fixture declares interfaces a and b in source order");
        };
        let (a, b) = (*a, *b);
        let uses = collection.interface_uses();

        assert!(
            uses.uses[&a].is_empty(),
            "the interface-local Request shadows the imported b.Request"
        );
        assert_eq!(uses.uses[&b].len(), 1);
        assert_eq!(uses.uses[&b][0].0, a);
        assert!(
            uses.cyclic.is_empty(),
            "the module import must not create a false a → b → a cycle"
        );

        let adapter = database
            .resolve_interface_test_only_paths(&collection, &module_tree, &snapshot)
            .expect("the direct interface path adapter succeeds");
        assert_eq!(
            adapter
                .interface_uses()
                .expect("adapter graph succeeds")
                .uses,
            uses.uses
        );
        assert_eq!(
            adapter
                .interface_uses()
                .expect("adapter graph succeeds")
                .cyclic,
            uses.cyclic
        );
        let request = database
            .symbols
            .intern("Request")
            .expect("Request symbol interns");
        let local_request = collection.scopes().interfaces[&a.to_def_id()].members[&request].res;
        let a_owner = adapter
            .owners()
            .iter()
            .find(|owner| owner.owner().def_id == a)
            .expect("interface a's adapter result exists");
        let uses_request = a_owner
            .members()
            .iter()
            .find(|member| {
                member.type_path_resolution().is_ok_and(|resolution| {
                    resolution
                        .paths()
                        .values()
                        .any(|path| path.base == local_request)
                })
            })
            .expect("UsesRequest resolves through a's interface-member rib");
        assert!(
            uses_request
                .type_path_resolution()
                .expect("interface member path resolution succeeds")
                .paths()
                .values()
                .any(|path| path.base == local_request)
        );
    }

    #[test]
    fn interface_use_resolution_includes_local_module_alias_expansions() {
        let root = concat!(
            "type AliasA = b.Record\n",
            "type AliasB = a.Record\n",
            "interface a {\n",
            "  type Record = U32\n",
            "  type ThroughAlias = AliasA\n",
            "}\n",
            "interface b {\n",
            "  type Record = U32\n",
            "  type ThroughAlias = AliasB\n",
            "}\n",
        );
        let (mut database, module_tree, snapshot, _) = phase1_fixture(root.as_bytes(), b"");
        let target = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let collection = database
            .collect_phase1_package_scopes_collection(
                &module_tree,
                &snapshot,
                &target,
                Phase1BuildContext::default(),
            )
            .expect("Phase 1 interface scopes collect");
        let interfaces = collection
            .scopes()
            .top_level_owners
            .iter()
            .filter(|owner| owner.kind == TopLevelOwnerKind::Interface)
            .map(|owner| owner.owner.def_id)
            .collect::<Vec<_>>();
        let [a, b] = interfaces.as_slice() else {
            panic!("the fixture declares interfaces a and b");
        };
        let uses = collection.interface_uses();

        assert!(
            uses.cyclic.contains(a),
            "alias expansion records a → b: {uses:?}; diagnostics: {:?}",
            collection.interface_check_diagnostics()
        );
        assert!(
            uses.cyclic.contains(b),
            "alias expansion records b → a: {uses:?}"
        );
        assert_eq!(uses.uses[a].len(), 1);
        assert_eq!(uses.uses[a][0].0, *b);
        assert_eq!(uses.uses[b].len(), 1);
        assert_eq!(uses.uses[b][0].0, *a);
        for reference in uses.uses.values().flatten() {
            let start = reference.1.range.start().to_usize();
            let end = reference.1.range.end().to_usize();
            assert!(
                matches!(root.get(start..end), Some("AliasA" | "AliasB")),
                "the hidden edge is anchored at the module alias use: {reference:?}"
            );
        }
    }

