    #[test]
    fn interface_test_only_paths_use_file_scopes_and_isolate_failures() {
        let root = concat!(
            "use acme:test-support/fixtures as fixture\n",
            "use acme:test-support/fixtures.{Fixture}\n",
            "type Shared<T> = T\n",
            "interface root_api {\n",
            "  type Bad = Shared<fixture.RootType>\n",
            "  type Good = Fixture\n",
            "}\n",
        );
        let child = concat!(
            "use acme:test-support/fixtures as fixture\n",
            "type Shared<T> = T\n",
            "interface child_api { type Child = Shared<fixture.ChildType> }\n",
        );
        let (mut database, module_tree, snapshot, _) =
            phase1_fixture(root.as_bytes(), child.as_bytes());
        let target_cfg = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let manifest = Arc::<[u8]>::from(
            &b"package acme:phase1 @ 1.0.0\n\
              requires test { acme:test-support @ ^1 }\n"[..],
        );
        let collection = database
            .collect_phase1_package_scopes_with_manifest_and_foreign_scopes(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
                manifest,
                PackageRole::Root,
                &[],
            )
            .expect("test-only interface imports collect in each file");
        let mut broken_collection = collection.clone();
        let root_scope = &mut broken_collection.scopes.modules[ModuleId::ROOT.raw() as usize];
        let fixture_symbol = root_scope
            .scope
            .keys()
            .copied()
            .find(|symbol| {
                database
                    .resolve_symbol(*symbol)
                    .is_ok_and(|name| name.as_ref() == "fixture")
            })
            .expect("root interface module alias exists");
        let fixture_import = match root_scope
            .scope
            .get(&fixture_symbol)
            .expect("module alias binding exists")
            .origin
        {
            BindingOrigin::Use { import } | BindingOrigin::PubUse { import } => import,
            BindingOrigin::Decl => panic!("fixture alias comes from a use"),
        };
        root_scope.imports[fixture_import.0 as usize].use_ast_id = ast::ErasedAstId::new(u32::MAX);

        let results = database
            .resolve_interface_test_only_paths(&broken_collection, &module_tree, &snapshot)
            .expect("interface path failures remain isolated by child owner");
        let shared_symbol = database
            .symbols
            .intern("Shared")
            .expect("Shared symbol is interned");
        let root_shared = collection
            .scopes()
            .module(ModuleId::ROOT)
            .expect("root module scope exists")
            .scope
            .get(&shared_symbol)
            .expect("root module Shared alias exists")
            .res;
        let child_shared = collection
            .scopes()
            .module(ModuleId::from_raw(1))
            .expect("child module scope exists")
            .scope
            .get(&shared_symbol)
            .expect("child module Shared alias exists")
            .res;
        assert_ne!(root_shared, child_shared);
        assert_eq!(results.owners().len(), 2);
        assert!(results.owners().iter().all(|owner| owner.error().is_none()));
        assert!(
            results.owners()[0].members()[0]
                .test_only_diagnostics()
                .is_err(),
            "the broken import note is isolated to the child that uses it"
        );
        assert!(
            results.owners()[0].members()[0]
                .type_path_resolution()
                .expect("type heads survive broken test-only diagnostic metadata")
                .paths()
                .values()
                .any(|path| path.base == root_shared),
            "the exact-file module binding remains in the type result after diagnostic failure"
        );
        assert!(
            results.owners()[0].members()[0]
                .type_path_resolution()
                .expect("type heads survive broken test-only diagnostic metadata")
                .paths()
                .values()
                .any(|path| path.base == Res::Err),
            "test-only type heads are rejected before diagnostic-note construction fails"
        );
        assert!(
            results.owners()[0].members()[1]
                .type_path_resolution()
                .expect("sibling member type heads resolve")
                .paths()
                .values()
                .any(|path| path.base == Res::Err),
            "a sibling member still resolves its rejected test-only type heads"
        );
        assert_eq!(
            results.owners()[0].members()[1]
                .test_only_diagnostics()
                .expect("sibling member diagnostics succeed")
                .len(),
            1,
            "the sibling continues through its valid item import"
        );
        assert_eq!(
            results.owners()[1].members()[0]
                .test_only_diagnostics()
                .expect("child module diagnostics succeed")
                .len(),
            1,
            "the other interface uses its own source file module scope"
        );
        assert!(
            results.owners()[1].members()[0]
                .type_path_resolution()
                .expect("child interface type heads resolve")
                .paths()
                .values()
                .any(|path| path.base == child_shared),
            "the child interface uses its own same-named alias"
        );
        assert!(
            !results.owners()[1].members()[0]
                .type_path_resolution()
                .expect("child interface type heads resolve")
                .paths()
                .values()
                .any(|path| path.base == root_shared),
            "a root-only alias never leaks into a child interface type result"
        );

        let mut broken_parent = collection.clone();
        let first_owner = results.owners()[0].owner();
        let descriptor_index = broken_parent
            .scopes
            .top_level_owners
            .iter()
            .position(|descriptor| descriptor.owner == first_owner)
            .expect("root interface descriptor exists");
        broken_parent.scopes.top_level_owners[descriptor_index].item_id =
            ast::ErasedAstId::new(u32::MAX);
        let isolated = database
            .resolve_interface_test_only_paths(&broken_parent, &module_tree, &snapshot)
            .expect("a bad interface descriptor does not stop other interfaces");
        assert!(isolated.owners()[0].error().is_some());
        assert!(isolated.owners()[0].members().is_empty());
        assert!(isolated.owners()[1].error().is_none());
        assert_eq!(
            isolated.owners()[1].members()[0]
                .test_only_diagnostics()
                .expect("other interface remains available")
                .len(),
            1
        );
    }

    #[test]
    fn extern_function_adapter_diagnoses_test_only_signature_and_contract_paths() {
        let root = concat!(
            "use acme:test-support/fixtures as fixture\n",
            "use acme:test-support/fixtures.{Fixture}\n",
            "use acme:test-support/fixtures.{flag}\n",
            "fn real_definition() {}\n",
            "unsafe extern \"wasm\" module \"env\" {\n",
            "  fn bodyless(value: Fixture) -> Fixture;\n",
            "  fn generic<Fixture>(value: Fixture) -> Fixture;\n",
            "  fn contracted(value: Bool) requires { let fixture = true; fixture && flag } ",
            "ensures { flag }\n",
            "}\n",
        );
        let (mut database, module_tree, snapshot, _) = phase1_fixture(root.as_bytes(), b"");
        let target_cfg = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let manifest = Arc::<[u8]>::from(
            &b"package acme:phase1 @ 1.0.0\n\
              requires test { acme:test-support @ ^1 }\n"[..],
        );
        let mut collection = database
            .collect_phase1_package_scopes_with_manifest_and_foreign_scopes(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
                manifest,
                PackageRole::Root,
                &[],
            )
            .expect("test-only extern imports are retained");
        assert_eq!(collection.scopes().extern_function_owners.len(), 3);

        let resolved = database
            .resolve_extern_function_predicates(&collection, &module_tree, &snapshot)
            .expect("extern function references resolve");
        assert!(resolved.matches_collection(&collection));
        assert_eq!(resolved.owners().len(), 3);

        let span_for = |start: usize, text: &str| {
            sai_diagnostics::Span::new(
                module_tree.modules[0].file,
                sai_diagnostics::TextRange::new(
                    sai_diagnostics::TextSize::new(start as u32),
                    sai_diagnostics::TextSize::new((start + text.len()) as u32),
                )
                .expect("reference range is ordered"),
            )
        };
        let package_path_span = |occurrence: usize| {
            let start = root
                .match_indices("acme:test-support/fixtures")
                .nth(occurrence)
                .expect("expected import path exists")
                .0;
            span_for(start, "acme:test-support/fixtures")
        };
        let diagnostic_spans = |diagnostics: &[Diagnostic]| {
            diagnostics
                .iter()
                .map(|diagnostic| {
                    diagnostic
                        .primary()
                        .expect("test-only reference has a primary span")
                        .span
                        .clone()
                })
                .collect::<Vec<_>>()
        };
        let assert_import_note =
            |diagnostic: &Diagnostic, expected_span: &sai_diagnostics::Span| {
                assert!(diagnostic.related().iter().any(|related| matches!(
                    related,
                    Related::DeclaredHere { location, .. } if &location.span == expected_span
                )));
            };

        let bodyless = &resolved.owners()[0];
        let bodyless_diagnostics = bodyless
            .test_only_diagnostics()
            .expect("bodyless signature diagnostics succeed")
            .expect("extern adapter runs signature diagnostics");
        assert_eq!(bodyless_diagnostics.len(), 2);
        let bodyless_start = root
            .find("fn bodyless")
            .expect("bodyless declaration exists");
        let first_type_start = root[bodyless_start..]
            .find("Fixture")
            .expect("parameter type exists")
            + bodyless_start;
        let second_type_start = root[first_type_start + "Fixture".len()..]
            .find("Fixture")
            .expect("return type exists")
            + first_type_start
            + "Fixture".len();
        assert_eq!(
            diagnostic_spans(bodyless_diagnostics),
            [
                span_for(first_type_start, "Fixture"),
                span_for(second_type_start, "Fixture"),
            ],
            "bodyless extern signatures retain exact, source-ordered type-head spans"
        );
        let fixture_package_path = package_path_span(1);
        for diagnostic in bodyless_diagnostics {
            assert_eq!(
                diagnostic.code,
                sai_diagnostics::Code::TestDependencyOutsideTest
            );
            assert_import_note(diagnostic, &fixture_package_path);
        }
        let bodyless_paths = bodyless
            .test_only_path_resolution()
            .expect("bodyless signature path lookup succeeds")
            .expect("bodyless adapter runs signature path lookup");
        assert_eq!(bodyless_paths.owner(), bodyless.owner());
        assert_eq!(bodyless_paths.paths().len(), 2);
        assert!(
            bodyless_paths
                .paths()
                .values()
                .all(|path| path.base == Res::Err && path.resolved_segments == 1)
        );
        assert!(
            bodyless
                .local_resolution()
                .expect("bodyless local lookup succeeds")
                .is_none(),
            "bodyless extern signatures still receive path diagnostics without a local body"
        );
        let bodyless_type_paths = bodyless
            .type_path_resolution()
            .expect("bodyless type path lookup succeeds")
            .expect("bodyless extern signatures retain type path results");
        assert_eq!(bodyless_type_paths.paths().len(), 2);
        assert!(
            bodyless_type_paths
                .paths()
                .values()
                .all(|path| path.base == Res::Err),
            "test-only signature type heads stay rejected in the ordinary type result"
        );

        let generic = &resolved.owners()[1];
        assert!(
            generic
                .test_only_diagnostics()
                .expect("generic signature diagnostics succeed")
                .expect("extern adapter runs the generic signature pass")
                .is_empty(),
            "a generic parameter shadows an imported test-only type of the same name"
        );
        assert!(
            generic
                .test_only_path_resolution()
                .expect("generic path lookup succeeds")
                .expect("generic signature path results exist")
                .paths()
                .is_empty()
        );
        let generic_type_paths = generic
            .type_path_resolution()
            .expect("generic type path lookup succeeds")
            .expect("generic extern signatures retain type path results");
        let generic_fixture = database
            .symbols
            .intern("Fixture")
            .expect("generic name is interned");
        let generic_fixture_def = database
            .def_paths
            .get(&generic.owner().def_id.package())
            .expect("package definition paths are available")
            .intern_generic_params(generic.owner().def_id, &[(generic_fixture, false, 0)])
            .expect("extern type generic has a stable definition identity")[0]
            .to_def_id();
        assert!(
            generic_type_paths
                .paths()
                .values()
                .any(|path| { path.base == Res::Def(DefKind::TyParam, generic_fixture_def) }),
            "the generic type binding wins over the same-spelled test-only import"
        );

        let contracted = &resolved.owners()[2];
        let contract_diagnostics = contracted
            .test_only_diagnostics()
            .expect("extern contract diagnostics succeed")
            .expect("extern adapter runs the test-only contract pass");
        assert_eq!(contract_diagnostics.len(), 2);
        let requires_start = root
            .find("fixture && flag")
            .expect("requires expression has an imported reference")
            + "fixture && ".len();
        let ensures_start = root
            .find("ensures { flag }")
            .expect("ensures expression has an imported reference")
            + "ensures { ".len();
        assert_eq!(
            diagnostic_spans(contract_diagnostics),
            [
                span_for(requires_start, "flag"),
                span_for(ensures_start, "flag"),
            ],
            "requires and ensures references are both diagnosed in source order"
        );
        let flag_package_path = package_path_span(2);
        for diagnostic in contract_diagnostics {
            assert_eq!(
                diagnostic.code,
                sai_diagnostics::Code::TestDependencyOutsideTest
            );
            assert_import_note(diagnostic, &flag_package_path);
        }
        let contracted_locals = contracted
            .local_resolution()
            .expect("contract local resolution succeeds")
            .expect("contract expressions form an extern owner body");
        assert!(
            contracted_locals
                .paths
                .values()
                .any(|path| matches!(path.base, Res::Local(_))),
            "a contract local wins before the same-spelled test-only module alias"
        );
        let contract_module_paths = contracted
            .module_resolution()
            .expect("contract module lookup succeeds")
            .expect("contract expressions form an extern owner body");
        assert_eq!(contract_module_paths.paths.len(), 2);
        assert!(
            contract_module_paths
                .paths
                .values()
                .all(|path| path.base == Res::Err),
            "test-only `flag` paths are rejected after contract-local resolution"
        );
        assert!(
            contracted
                .type_path_resolution()
                .expect("contract signature type lookup succeeds")
                .expect("extern contract owner has a type path result")
                .paths()
                .values()
                .any(|path| path.base == Res::PrimTy(sai_resolve::prelude::PrimTy::Bool)),
            "ordinary signature type heads remain available beside contract diagnostics"
        );

        // Simulate an incorrectly paired source item on one descriptor. The
        // failed owner must not suppress independent extern owners in the
        // same file.
        let mut broken_collection = collection.clone();
        let second_item = broken_collection.scopes.extern_function_owners[1].item_id;
        broken_collection.scopes.extern_function_owners[0].item_id = second_item;
        let isolated = database
            .resolve_extern_function_predicates(&broken_collection, &module_tree, &snapshot)
            .expect("descriptor failures remain isolated to their owner");
        assert!(
            isolated.owners()[0].resolution().is_err(),
            "the corrupted extern owner reports its own failure"
        );
        assert!(
            isolated.owners()[0].test_only_diagnostics().is_err(),
            "the corrupted owner does not publish partial test-only diagnostics"
        );
        assert!(
            isolated.owners()[1].resolution().is_ok() && isolated.owners()[2].resolution().is_ok(),
            "later owners continue resolving after one descriptor fails"
        );

        // A real Def resolution must not erase the originating test-only
        // classification. Both import records and their visible bindings
        // carry the same definition, as after successful import resolution.
        let (fixture_symbol, fixture_import, flag_symbol, flag_import) = {
            let root_scope = collection
                .scopes()
                .module(ModuleId::ROOT)
                .expect("root module scope exists");
            let binding_for = |name: &str| {
                root_scope
                    .scope
                    .iter()
                    .find(|(symbol, _)| {
                        database
                            .resolve_symbol(**symbol)
                            .is_ok_and(|spelling| spelling.as_ref() == name)
                    })
                    .unwrap_or_else(|| panic!("root module scope contains `{name}`"))
            };
            let (fixture_symbol, fixture_binding) = binding_for("Fixture");
            let (flag_symbol, flag_binding) = binding_for("flag");
            let import_index = |binding: &sai_resolve::package_scopes::Binding| {
                let (BindingOrigin::Use { import } | BindingOrigin::PubUse { import }) =
                    binding.origin
                else {
                    panic!("test-only binding comes from an import");
                };
                import
            };
            (
                *fixture_symbol,
                import_index(fixture_binding),
                *flag_symbol,
                import_index(flag_binding),
            )
        };
        let resolved_definition = Res::Def(
            DefKind::Fn,
            collection.scopes.function_owners[0]
                .owner
                .def_id
                .to_def_id(),
        );
        let mut resolved_import_collection = collection.clone();
        {
            let root_scope =
                &mut resolved_import_collection.scopes.modules[ModuleId::ROOT.raw() as usize];
            for (symbol, import) in [(fixture_symbol, fixture_import), (flag_symbol, flag_import)] {
                assert!(
                    root_scope.imports[import.0 as usize].test_only,
                    "the import remains classified as test-only"
                );
                root_scope.imports[import.0 as usize].res = resolved_definition;
                root_scope
                    .scope
                    .get_mut(&symbol)
                    .expect("visible test-only binding exists")
                    .res = resolved_definition;
            }
        }
        let resolved_imports = database
            .resolve_extern_function_predicates(
                &resolved_import_collection,
                &module_tree,
                &snapshot,
            )
            .expect("resolved test-only imports remain diagnosable");
        let resolved_bodyless = &resolved_imports.owners()[0];
        let resolved_bodyless_diagnostics = resolved_bodyless
            .test_only_diagnostics()
            .expect("resolved bodyless signature diagnostics succeed")
            .expect("extern adapter keeps its signature diagnostic pass");
        assert_eq!(resolved_bodyless_diagnostics.len(), 2);
        for diagnostic in resolved_bodyless_diagnostics {
            assert_eq!(
                diagnostic.code,
                sai_diagnostics::Code::TestDependencyOutsideTest
            );
            assert_import_note(diagnostic, &fixture_package_path);
        }
        assert!(
            resolved_bodyless
                .test_only_path_resolution()
                .expect("resolved signature path lookup succeeds")
                .expect("bodyless signature path results exist")
                .paths()
                .values()
                .all(|path| path.base == Res::Err),
            "resolved test-only signature paths are rewritten to the error sentinel"
        );
        assert!(
            resolved_bodyless
                .type_path_resolution()
                .expect("resolved type path lookup succeeds")
                .expect("bodyless extern type results exist")
                .paths()
                .values()
                .all(|path| path.base == Res::Err),
            "resolved imports retain test-only rejection in the ordinary type result"
        );

        let resolved_contracted = &resolved_imports.owners()[2];
        let resolved_contract_diagnostics = resolved_contracted
            .test_only_diagnostics()
            .expect("resolved contract diagnostics succeed")
            .expect("extern contract diagnostic pass is present");
        assert_eq!(resolved_contract_diagnostics.len(), 2);
        for diagnostic in resolved_contract_diagnostics {
            assert_eq!(
                diagnostic.code,
                sai_diagnostics::Code::TestDependencyOutsideTest
            );
            assert_import_note(diagnostic, &flag_package_path);
        }
        assert!(
            resolved_contracted
                .module_resolution()
                .expect("resolved contract module lookup succeeds")
                .expect("contract module results exist")
                .paths
                .values()
                .all(|path| path.base == Res::Err),
            "resolved test-only contract paths are rewritten to the error sentinel"
        );

        // Reclassifying an imported name as ordinary keeps it outside the
        // test-only diagnostic channel while preserving signature diagnostics.
        let root_scope = &mut collection.scopes.modules[ModuleId::ROOT.raw() as usize];
        root_scope.imports[flag_import.0 as usize].test_only = false;
        let ordinary_import = database
            .resolve_extern_function_predicates(&collection, &module_tree, &snapshot)
            .expect("ordinary import classification remains resolvable");
        assert!(
            ordinary_import.owners()[2]
                .test_only_diagnostics()
                .expect("ordinary contract imports do not fail lookup")
                .expect("extern diagnostic pass is present")
                .is_empty(),
            "ordinary imports do not receive test-only contract diagnostics"
        );
    }

    #[test]
    fn extern_function_adapter_uses_target_filtered_block_disambiguators() {
        let root = concat!(
            "@target(\"wasm64-core\")\n",
            "extern \"wasm\" module \"env\" { fn filtered() }\n",
            "extern \"wasm\" module \"env\" {\n",
            "  fn retained() -> Bool requires { return true; }\n",
            "}\n",
        );
        let (mut database, module_tree, snapshot, _) = phase1_fixture(root.as_bytes(), b"");
        let target_cfg = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let collection = database
            .collect_phase1_package_scopes_collection(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
            )
            .expect("target-filtered extern function owners collect");
        assert_eq!(collection.scopes().extern_function_owners.len(), 1);

        let resolved = database
            .resolve_extern_function_predicates(&collection, &module_tree, &snapshot)
            .expect("target-filtered extern function predicate resolves");

        assert!(resolved.matches_collection(&collection));
        assert_eq!(resolved.owners().len(), 1);
        assert_eq!(
            resolved.owners()[0]
                .resolution()
                .expect("retained extern function lowers")
                .iter()
                .map(|diagnostic| diagnostic.code)
                .collect::<Vec<_>>(),
            [sai_diagnostics::Code::InvalidContractExpression]
        );
    }

    #[test]
    fn function_owner_label_adapter_rejects_a_collection_from_another_snapshot() {
        let root = b"fn duplicate() { 0 }\nfn duplicate() { 1 }\n";
        let (mut database, module_tree, snapshot, _) = phase1_fixture(root, b"");
        let target_cfg = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let old_collection = database
            .collect_phase1_package_scopes_collection(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
            )
            .expect("old snapshot collection succeeds");

        let root_file = module_tree.modules[0].file;
        let edited_root = b"fn duplicate() { 2 }\nfn duplicate() { 0 }\nfn duplicate() { 1 }\n";
        database
            .set_file_contents(
                FileKey::new("acme:phase1#1", "src/lib.sai").expect("root key is valid"),
                Arc::from(edited_root.as_slice()),
                Durability::Low,
            )
            .expect("edited source is recorded");
        let new_snapshot = WorkspaceSnapshot::new(snapshot.iter().map(|file| {
            let source = if file.source().id() == root_file {
                Arc::new(SourceFile::decode(root_file, edited_root).expect("edited source decodes"))
            } else {
                Arc::clone(file.source())
            };
            SnapshotFile::new(
                source,
                file.path().to_owned(),
                file.package().map(str::to_owned),
                Some(18),
            )
        }))
        .expect("edited workspace snapshot is valid");

        assert!(matches!(
            database.resolve_function_owner_labels(&old_collection, &module_tree, &new_snapshot),
            Err(FunctionOwnerLabelResolutionError::SnapshotMismatch)
        ));

        let new_collection = database
            .collect_phase1_package_scopes_collection(
                &module_tree,
                &new_snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
            )
            .expect("new snapshot collection succeeds");
        let resolved = database
            .resolve_function_owner_labels(&new_collection, &module_tree, &new_snapshot)
            .expect("new descriptors lower against the new snapshot");
        assert_eq!(resolved.owners().len(), 3);
    }

    #[test]
    fn function_owner_label_adapter_keeps_processing_after_one_descriptor_failure() {
        let root = "fn first() {}\nfn later() { break; }\n";
        let (mut database, module_tree, snapshot, _) = phase1_fixture(root.as_bytes(), b"");
        let target_cfg = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let mut collection = database
            .collect_phase1_package_scopes_collection(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
            )
            .expect("Phase 1 collection succeeds");
        // Simulate an internal descriptor-corruption failure in the legacy
        // function index: the public collection keeps this index immutable.
        let later_owner = collection.scopes.function_owners[1].owner;
        collection.scopes.function_owners[0].owner = later_owner;

        let resolved = database
            .resolve_function_owner_labels(&collection, &module_tree, &snapshot)
            .expect("per-owner lower failures do not abort the package");
        assert_eq!(resolved.owners().len(), 2);
        assert!(matches!(
            resolved.owners()[0].resolution(),
            Err(FunctionOwnerLabelResolutionError::TopLevelOwnerDescriptorMismatch { .. })
        ));
        assert!(matches!(
            resolved.owners()[0].local_resolution(),
            Err(FunctionOwnerResolutionError::TopLevelOwnerDescriptorMismatch { .. })
        ));
        assert!(matches!(
            resolved.owners()[0].test_only_diagnostics(),
            Err(FunctionOwnerResolutionError::TopLevelOwnerDescriptorMismatch { .. })
        ));
        let later = resolved.owners()[1]
            .resolution()
            .expect("later function still resolves");
        assert!(
            later
                .diagnostics
                .iter()
                .any(|diagnostic| { diagnostic.code == sai_diagnostics::Code::BreakOutsideLoop })
        );
        assert!(
            resolved.owners()[1]
                .test_only_diagnostics()
                .expect("later function diagnostics still resolve")
                .is_empty()
        );
    }

    fn graph_edge(target: &str, visible_identity: &str) -> PackageGraphEdge {
        PackageGraphEdge::new(
            PackageKey::new(target).expect("graph target key is valid"),
            visible_identity,
        )
        .expect("graph edge is valid")
    }

    fn graph_node(
        key: &str,
        identity: &str,
        version: &str,
        role: PackageGraphRole,
        edges: Vec<PackageGraphEdge>,
    ) -> PackageGraphNode {
        PackageGraphNode::new(
            PackageKey::new(key).expect("graph package key is valid"),
            identity,
            Version::parse(version).expect("graph package version is valid"),
            PackageForm::Source,
            role,
            edges,
        )
        .expect("graph package node is valid")
    }

    fn phase1_graph(dependency_version: &str, dependency_has_leaf: bool) -> PackageGraph {
        let dependency_edges = if dependency_has_leaf {
            vec![graph_edge("acme:leaf#1", "acme:leaf")]
        } else {
            Vec::new()
        };
        let mut nodes = vec![
            graph_node(
                "acme:phase1#1",
                "acme:phase1",
                "1.0.0",
                PackageGraphRole::Root,
                vec![graph_edge("acme:dep#1", "acme:dep")],
            ),
            graph_node(
                "acme:dep#1",
                "acme:dep",
                dependency_version,
                PackageGraphRole::Dependency,
                dependency_edges,
            ),
        ];
        if dependency_has_leaf {
            nodes.push(graph_node(
                "acme:leaf#1",
                "acme:leaf",
                "1.0.0",
                PackageGraphRole::Dependency,
                Vec::new(),
            ));
        }
        PackageGraph::new(
            Version::parse("1.8.2").expect("toolchain version is valid"),
            nodes,
        )
        .expect("active graph is valid")
    }

    fn phase1_root_only_graph() -> PackageGraph {
        phase1_root_only_graph_with_toolchain("1.8.2")
    }

    fn phase1_root_only_graph_with_toolchain(toolchain_version: &str) -> PackageGraph {
        PackageGraph::new(
            Version::parse(toolchain_version).expect("toolchain version is valid"),
            [graph_node(
                "acme:phase1#1",
                "acme:phase1",
                "1.0.0",
                PackageGraphRole::Root,
                Vec::new(),
            )],
        )
        .expect("root-only graph is valid")
    }

    #[test]
    fn package_scopes_query_tracks_manifest_requirements_and_backdates_unrelated_edits() {
        let (mut database, module_tree, snapshot, _) = phase1_fixture(
            b"use acme:test-support/fixtures as fixtures\n",
            b"fn child() {}\n",
        );
        let target = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let context = Phase1BuildContext::default();
        let manifest = Arc::<[u8]>::from(
            &b"package acme:phase1 @ 1.0.0\n\
              requires test { acme:test-support @ ^1 }\n"[..],
        );
        let first = database
            .collect_phase1_package_scopes_with_manifest(
                &module_tree,
                &snapshot,
                &target,
                context,
                Arc::clone(&manifest),
                PackageRole::Root,
            )
            .expect("manifest-backed package scopes collect");
        let first_import = &first.modules[0].imports[0];
        assert!(first_import.test_only);
        assert!(matches!(
            first_import.res,
            sai_resolve::package_scopes::Res::TestOnly(_)
        ));

        let package_key = PackageKey::new("acme:phase1#1").expect("package key is valid");
        let first_memo = database
            .package_scopes
            .query
            .get(&mut database.query_database, package_key.clone())
            .expect("first package-scope memo exists");
        let unrelated_edit = Arc::<[u8]>::from(
            &b"package acme:phase1 @ 1.0.0\n\
              description \"does not alter requirements\"\n\
              requires test { acme:test-support @ ^1 }\n"[..],
        );
        let second = database
            .collect_phase1_package_scopes_with_manifest(
                &module_tree,
                &snapshot,
                &target,
                context,
                unrelated_edit,
                PackageRole::Root,
            )
            .expect("scopes collect after unrelated manifest edit");
        assert!(second.modules[0].imports[0].test_only);
        let second_memo = database
            .package_scopes
            .query
            .get(&mut database.query_database, package_key.clone())
            .expect("second package-scope memo exists");
        assert!(
            Arc::ptr_eq(&first_memo, &second_memo),
            "manifest edits that preserve the normalized requirements backdate"
        );

        let restricted = Arc::<[u8]>::from(
            &b"package acme:phase1 @ 1.0.0\n\
              requires { acme:test-support @ ^1 only { wasm32-wasi } }\n"[..],
        );
        let third = database
            .collect_phase1_package_scopes_with_manifest(
                &module_tree,
                &snapshot,
                &target,
                context,
                restricted,
                PackageRole::Root,
            )
            .expect("scopes collect after the requirement changes");
        assert!(
            third
                .diagnostics
                .iter()
                .any(|diagnostic| diagnostic.code == sai_diagnostics::Code::InactiveDependency)
        );
        assert_eq!(
            third.modules[0].imports[0].res,
            sai_resolve::package_scopes::Res::Err
        );
        let third_memo = database
            .package_scopes
            .query
            .get(&mut database.query_database, package_key)
            .expect("third package-scope memo exists");
        assert!(
            !Arc::ptr_eq(&second_memo, &third_memo),
            "changing normalized requirements invalidates package scopes"
        );
    }

    #[test]
    fn package_scopes_query_tracks_root_package_context_for_test_edges() {
        let (mut database, module_tree, snapshot, _) = phase1_fixture(
            b"use acme:test-support/fixtures as fixtures\n",
            b"fn child() {}\n",
        );
        let target = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let manifest = Arc::<[u8]>::from(
            &b"package acme:phase1 @ 1.0.0\n\
              requires test { acme:test-support @ ^1 }\n"[..],
        );
        let root_context = Phase1BuildContext {
            is_root_package: true,
            analyzes_tests: true,
            ..Phase1BuildContext::default()
        };
        let root_scopes = database
            .collect_phase1_package_scopes_with_manifest(
                &module_tree,
                &snapshot,
                &target,
                root_context,
                Arc::clone(&manifest),
                PackageRole::Root,
            )
            .expect("root test dependencies are classified");
        assert!(root_scopes.diagnostics.iter().all(|diagnostic| {
            diagnostic.code != sai_diagnostics::Code::TestDependencyUnavailable
        }));

        let member_context = Phase1BuildContext {
            is_root_package: false,
            ..root_context
        };
        let member_scopes = database
            .collect_phase1_package_scopes_with_manifest(
                &module_tree,
                &snapshot,
                &target,
                member_context,
                Arc::clone(&manifest),
                PackageRole::Root,
            )
            .expect("non-root test dependencies are rejected");
        assert!(member_scopes.diagnostics.iter().any(|diagnostic| {
            diagnostic.code == sai_diagnostics::Code::TestDependencyUnavailable
        }));
        assert!(member_scopes.diagnostics.iter().all(|diagnostic| {
            diagnostic.code != sai_diagnostics::Code::UnknownPackage
                && diagnostic.code != sai_diagnostics::Code::UnknownModule
                && diagnostic.code != sai_diagnostics::Code::UnresolvedImport
        }));

        let repeated_root = database
            .collect_phase1_package_scopes_with_manifest(
                &module_tree,
                &snapshot,
                &target,
                root_context,
                manifest,
                PackageRole::Root,
            )
            .expect("the root result remains distinct from the member result");
        assert!(repeated_root.diagnostics.iter().all(|diagnostic| {
            diagnostic.code != sai_diagnostics::Code::TestDependencyUnavailable
        }));
    }

    #[test]
    fn package_scopes_do_not_classify_requirements_recovered_from_invalid_manifests() {
        let (mut database, module_tree, snapshot, _) = phase1_fixture(
            b"use acme:test-support/fixtures as fixtures\n",
            b"fn child() {}\n",
        );
        let target = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let invalid_manifest = Arc::<[u8]>::from(
            &b"package acme:phase1 @ 1.0.0\n\
              requires test { acme:test-support @ ^1 }\n\
              invalid declaration\n"[..],
        );
        let scopes = database
            .collect_phase1_package_scopes_with_manifest(
                &module_tree,
                &snapshot,
                &target,
                Phase1BuildContext::default(),
                invalid_manifest,
                PackageRole::Root,
            )
            .expect("invalid manifest ownership stays with package validation");
        assert!(scopes.modules[0].imports.is_empty());
        assert!(scopes.diagnostics.iter().all(|diagnostic| {
            diagnostic.code != sai_diagnostics::Code::TestDependencyOutsideTest
                && diagnostic.code != sai_diagnostics::Code::InactiveDependency
        }));
    }

    #[test]
    fn wit_contract_query_projects_manifest_fields_and_backdates_unrelated_edits() {
        let mut database = RootDatabase::new().expect("driver initializes");
        let package = database
            .intern_package("acme:wit-contract#1")
            .expect("package key interns");
        let first_source: Arc<[u8]> = Arc::from(
            &b"package acme:wit-contract @ 1.0.0\n\
              source \"src\"\n\
              wit \"wit\"\n\
              export world server\n\
              description \"one\"\n"[..],
        );
        database
            .set_package_manifest(package, first_source, PackageRole::Root, Durability::Low)
            .expect("manifest input is set");

        let first = database
            .wit_contract(package)
            .expect("WIT contract projection succeeds");
        assert_eq!(first.identity().to_string(), "acme:wit-contract");
        assert_eq!(first.version().to_string(), "1.0.0");
        assert_eq!(first.kind(), sai_wit::WitPackageKind::Source);
        assert_eq!(first.wit_directory(), Some("wit"));
        let export_world = first
            .export_world()
            .expect("the manifest declares an export world");
        assert_eq!(export_world.value(), "server");
        let export_span = export_world.span().clone();

        let package_key = PackageKey::new("acme:wit-contract#1").expect("package key is valid");
        let first_output = database
            .wit_contracts
            .query
            .get(&mut database.query_database, package_key.clone())
            .expect("first WIT contract memo exists");

        // Replacing an unrelated, same-width field preserves the exported
        // span as well as every projected contract field.
        let unrelated_edit: Arc<[u8]> = Arc::from(
            &b"package acme:wit-contract @ 1.0.0\n\
              source \"src\"\n\
              wit \"wit\"\n\
              export world server\n\
              description \"two\"\n"[..],
        );
        database
            .set_package_manifest(package, unrelated_edit, PackageRole::Root, Durability::Low)
            .expect("unrelated manifest edit is set");
        let second = database
            .wit_contract(package)
            .expect("WIT projection remains valid");
        let second_output = database
            .wit_contracts
            .query
            .get(&mut database.query_database, package_key.clone())
            .expect("second WIT contract memo exists");
        assert!(
            Arc::ptr_eq(&first_output, &second_output),
            "editing an unrelated field with stable offsets keeps the WIT query green"
        );
        assert_eq!(
            second
                .export_world()
                .expect("world remains declared")
                .span(),
            &export_span
        );

        let changed_contract: Arc<[u8]> = Arc::from(
            &b"package acme:wit-contract @ 1.0.0\n\
              source \"src\"\n\
              wit \"api\"\n\
              export world server\n\
              description \"two\"\n"[..],
        );
        database
            .set_package_manifest(
                package,
                changed_contract,
                PackageRole::Root,
                Durability::Low,
            )
            .expect("WIT directory edit is set");
        let third = database
            .wit_contract(package)
            .expect("edited WIT contract projection succeeds");
        assert_eq!(third.wit_directory(), Some("api"));
        assert!(
            !Arc::ptr_eq(&second, &third),
            "changing a WIT contract field changes the projected query value"
        );
    }

    #[test]
    fn wit_contract_query_returns_projection_errors_as_values_and_recovers() {
        let mut database = RootDatabase::new().expect("driver initializes");
        let package = database
            .intern_package("acme:wit-contract#1")
            .expect("package key interns");
        let invalid_source: Arc<[u8]> = Arc::from(
            &b"package acme:wit-contract @ 1.0.0\n\
              source \"src\"\n\
              wit \"../outside\"\n"[..],
        );
        database
            .set_package_manifest(package, invalid_source, PackageRole::Root, Durability::Low)
            .expect("invalid manifest input is still trackable");

        assert!(matches!(
            database.wit_contract(package),
            Err(WitContractQueryError::Projection { .. })
        ));

        let valid_source: Arc<[u8]> = Arc::from(
            &b"package acme:wit-contract @ 1.0.0\n\
              source \"src\"\n\
              wit \"wit\"\n"[..],
        );
        database
            .set_package_manifest(package, valid_source, PackageRole::Root, Durability::Low)
            .expect("corrected manifest input is set");
        let recovered = database
            .wit_contract(package)
            .expect("a corrected manifest recovers the query");
        assert_eq!(recovered.wit_directory(), Some("wit"));

        let mismatched_source: Arc<[u8]> = Arc::from(
            &b"package acme:other @ 1.0.0\n\
              source \"src\"\n"[..],
        );
        database
            .set_package_manifest(
                package,
                mismatched_source,
                PackageRole::Root,
                Durability::Low,
            )
            .expect("mismatched manifest input is set");
        assert!(matches!(
            database.wit_contract(package),
            Err(WitContractQueryError::ManifestPackageMismatch { .. })
        ));

        let wrong_version_source: Arc<[u8]> = Arc::from(
            &b"package acme:wit-contract @ 2.0.0\n\
              source \"src\"\n"[..],
        );
        database
            .set_package_manifest(
                package,
                wrong_version_source,
                PackageRole::Root,
                Durability::Low,
            )
            .expect("wrong compatibility-line manifest input is set");
        assert!(matches!(
            database.wit_contract(package),
            Err(WitContractQueryError::ManifestPackageMismatch {
                found_identity,
                found_compatibility_line,
                ..
            }) if found_identity == "acme:wit-contract" && found_compatibility_line == "2"
        ));
    }

    #[test]
    fn direct_wit_use_selects_exact_package_across_compatibility_lines() {
        let root = b"use acme:codec/iface as codec\ntype Client = codec.TypeV2\n";
        let (mut database, module_tree, snapshot, _) = phase1_fixture(root, b"");
        let target_cfg = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let root_key = PackageKey::new("acme:phase1#1").expect("root key is valid");
        let bridge_key = PackageKey::new("acme:bridge#1").expect("bridge key is valid");
        let codec_v1_key = PackageKey::new("acme:codec#1").expect("v1 key is valid");
        let codec_v2_key = PackageKey::new("acme:codec#2").expect("v2 key is valid");
        let bridge = database
            .intern_package(bridge_key.as_str())
            .expect("bridge package interns");
        let codec_v1 = database
            .intern_package(codec_v1_key.as_str())
            .expect("v1 package interns");
        let codec_v2 = database
            .intern_package(codec_v2_key.as_str())
            .expect("v2 package interns");
        let graph = PackageGraph::new(
            Version::parse("1.8.2").expect("toolchain version is valid"),
            [
                PackageGraphNode::new(
                    root_key,
                    "acme:phase1",
                    Version::parse("1.0.0").expect("root version is valid"),
                    PackageForm::Source,
                    PackageGraphRole::Root,
                    vec![
                        graph_edge("acme:codec#2", "acme:codec"),
                        graph_edge("acme:bridge#1", "acme:bridge"),
                    ],
                )
                .expect("root graph node is valid"),
                PackageGraphNode::new(
                    bridge_key,
                    "acme:bridge",
                    Version::parse("1.0.0").expect("bridge version is valid"),
                    PackageForm::Source,
                    PackageGraphRole::Dependency,
                    vec![graph_edge("acme:codec#1", "acme:codec")],
                )
                .expect("bridge graph node is valid"),
                PackageGraphNode::new(
                    codec_v1_key.clone(),
                    "acme:codec",
                    Version::parse("1.0.0").expect("codec v1 version is valid"),
                    PackageForm::Artifact,
                    PackageGraphRole::Dependency,
                    Vec::new(),
                )
                .expect("codec v1 graph node is valid"),
                PackageGraphNode::new(
                    codec_v2_key.clone(),
                    "acme:codec",
                    Version::parse("2.0.0").expect("codec v2 version is valid"),
                    PackageForm::Artifact,
                    PackageGraphRole::Dependency,
                    Vec::new(),
                )
                .expect("codec v2 graph node is valid"),
            ],
        )
        .expect("different compatibility lines may be reachable");
        database
            .set_package_graph(Some(graph.clone()))
            .expect("active package graph is recorded");
        database
            .set_package_manifest(
                bridge,
                Arc::from(
                    &b"package acme:bridge @ 1.0.0\n\
                       source \"src\"\n\
                       requires { acme:codec @ ^1 }\n"[..],
                ),
                PackageRole::Dependency,
                Durability::Low,
            )
            .expect("bridge manifest is recorded");

        let set_codec_wit = |database: &mut RootDatabase,
                             package,
                             key: &PackageKey,
                             version: &str,
                             member: &str| {
            database
                .set_package_manifest(
                    package,
                    Arc::<[u8]>::from(
                        format!(
                            "package acme:codec @ {version}\n\
                             artifact component {{}}\n\
                             wit \"wit\"\n"
                        )
                        .into_bytes(),
                    ),
                    PackageRole::Dependency,
                    Durability::Low,
                )
                .expect("artifact manifest is recorded");
            database
                .set_wit_files(
                    key.clone(),
                    WitFilesSnapshot::listed(
                        "wit",
                        [PackageRelativePath::new("wit/api.wit").expect("WIT path is valid")],
                    )
                    .expect("WIT inventory is valid"),
                    Durability::Low,
                )
                .expect("WIT inventory is recorded");
            database
                .set_file_contents(
                    FileKey::new(key.as_str(), "wit/api.wit").expect("WIT file key is valid"),
                    Arc::from(
                        format!(
                            "package acme:codec@{version}; interface iface {{ record {member} {{ value: u32 }} }}"
                        )
                        .into_bytes(),
                    ),
                    Durability::Low,
                )
                .expect("WIT source is recorded");
        };
        set_codec_wit(&mut database, codec_v1, &codec_v1_key, "1.0.0", "type-v1");
        set_codec_wit(&mut database, codec_v2, &codec_v2_key, "2.0.0", "type-v2");

        let wit_scopes = database
            .collect_active_wit_view_scopes(&module_tree, &snapshot, &target_cfg, &graph)
            .expect("all reachable WIT views load");
        let codec_v2_view_package = wit_scopes
            .views()
            .find(|view| view.view.unit.canonical_name() == "acme:codec@2.0.0")
            .expect("direct v2 view is available")
            .view
            .package;
        let root_manifest: Arc<[u8]> = Arc::from(
            &b"package acme:phase1 @ 1.0.0\n\
              source \"src\"\n\
              requires {\n\
                  acme:codec @ ^2\n\
                  acme:bridge @ ^1\n\
              }\n"[..],
        );
        let collection = database
            .collect_phase1_package_scopes_with_manifest_and_wit_views(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
                root_manifest,
                PackageRole::Root,
                &wit_scopes,
            )
            .expect("direct WIT import resolves");
        let codec = database
            .symbols
            .intern("codec")
            .expect("WIT alias symbol interns");
        let codec_binding = collection
            .scopes()
            .module(ModuleId::ROOT)
            .expect("root module scope exists")
            .scope
            .get(&codec)
            .expect("direct WIT alias is bound");
        assert!(
            matches!(codec_binding.res, Res::Def(DefKind::Interface, def_id) if def_id.package == codec_v2_view_package),
            "the direct alias must point at the exact directly selected package: {codec_binding:?}"
        );
        let resolved = database
            .resolve_type_owner_paths_with_wit_views(
                &collection,
                &module_tree,
                &snapshot,
                &wit_scopes,
            )
            .expect("direct view member resolves");
        let client_paths = resolved.owners()[0]
            .path_resolution()
            .expect("type owner paths resolve");
        let client = client_paths
            .paths()
            .values()
            .next()
            .unwrap_or_else(|| panic!("qualified type path is present: {client_paths:#?}"));
        assert!(
            matches!(client.base, Res::Def(DefKind::Struct, def_id) if def_id.package == codec_v2_view_package),
            "the direct v2 package must win over the transitive v1 package: {client:?}"
        );
        assert!(
            client_paths.module_path_errors().is_empty(),
            "the v2-only member resolves through the direct edge"
        );
    }

    #[test]
    fn type_owner_paths_resolve_active_wit_members_and_track_view_revisions() {
        let root = b"use acme:wit-api/streams as api\ntype Client = api.Request\ntype Local { value: Bool, request: api.Request }\n";
        let (mut database, module_tree, snapshot, _root_package) = phase1_fixture(root, b"");
        let target_cfg = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let artifact = database
            .intern_package("acme:wit-api#1")
            .expect("artifact package key interns");
        let graph_for_version = |version: &str| {
            PackageGraph::new(
                Version::parse("1.8.2").expect("toolchain version is valid"),
                [
                    PackageGraphNode::new(
                        PackageKey::new("acme:phase1#1").expect("root key is valid"),
                        "acme:phase1",
                        Version::parse("1.0.0").expect("root version is valid"),
                        PackageForm::Source,
                        PackageGraphRole::Root,
                        vec![graph_edge("acme:wit-api#1", "acme:wit-api")],
                    )
                    .expect("root graph node is valid"),
                    PackageGraphNode::new(
                        PackageKey::new("acme:wit-api#1").expect("artifact key is valid"),
                        "acme:wit-api",
                        Version::parse(version).expect("artifact version is valid"),
                        PackageForm::Artifact,
                        PackageGraphRole::Dependency,
                        Vec::new(),
                    )
                    .expect("artifact graph node is valid"),
                ],
            )
            .expect("package graph is valid")
        };
        let set_artifact_inputs = |database: &mut RootDatabase, version: &str, wit: &str| {
            database
                .set_package_manifest(
                    artifact,
                    Arc::<[u8]>::from(
                        format!(
                            "package acme:wit-api @ {version}\nartifact component {{}}\nwit \"wit\"\n"
                        )
                        .into_bytes(),
                    ),
                    PackageRole::Dependency,
                    Durability::Low,
                )
                .expect("artifact manifest is recorded");
            database
                .set_wit_files(
                    PackageKey::new("acme:wit-api#1").expect("artifact key is valid"),
                    WitFilesSnapshot::listed(
                        "wit",
                        [PackageRelativePath::new("wit/api.wit").expect("WIT path is valid")],
                    )
                    .expect("WIT inventory is valid"),
                    Durability::Low,
                )
                .expect("WIT inventory is recorded");
            database
                .set_file_contents(
                    FileKey::new("acme:wit-api#1", "wit/api.wit").expect("WIT key is valid"),
                    Arc::from(wit.as_bytes()),
                    Durability::Low,
                )
                .expect("WIT source is recorded");
        };
        let root_manifest: Arc<[u8]> = Arc::from(
            &b"package acme:phase1 @ 1.0.0\nsource \"src\"\nrequires { acme:wit-api @ ^1 }\n"[..],
        );

        let graph_v1 = graph_for_version("1.0.0");
        database
            .set_package_graph(Some(graph_v1.clone()))
            .expect("initial package graph is recorded");
        set_artifact_inputs(
            &mut database,
            "1.0.0",
            "package acme:wit-api@1.0.0; interface streams { record request { value: u32 } }",
        );
        let wit_scopes_v1 = database
            .collect_active_wit_view_scopes(&module_tree, &snapshot, &target_cfg, &graph_v1)
            .expect("active WIT views collect");
        assert_eq!(
            wit_scopes_v1
                .available_unit_names()
                .filter(|unit| !unit.starts_with("wasi:"))
                .collect::<Vec<_>>(),
            ["acme:wit-api@1.0.0"]
        );
        let collection_v1 = database
            .collect_phase1_package_scopes_with_manifest_and_wit_views(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
                Arc::clone(&root_manifest),
                PackageRole::Root,
                &wit_scopes_v1,
            )
            .expect("WIT module alias is collected");
        let resolved_v1 = database
            .resolve_type_owner_paths_with_wit_views(
                &collection_v1,
                &module_tree,
                &snapshot,
                &wit_scopes_v1,
            )
            .expect("qualified WIT member resolves");
        let path_v1 = resolved_v1.owners()[0]
            .path_resolution()
            .expect("type owner resolves")
            .paths()
            .values()
            .next()
            .expect("qualified type path is retained");
        assert!(matches!(path_v1.base, Res::Def(DefKind::Struct, _)));
        assert_eq!(path_v1.resolved_segments, 2);
        assert!(resolved_v1.matches_wit_view_scopes(&collection_v1, &wit_scopes_v1));
        let local_owner = collection_v1
            .scopes
            .top_level_owners
            .iter()
            .find(|descriptor| descriptor.kind == TopLevelOwnerKind::Struct)
            .expect("the local record owner is collected")
            .owner;
        let local_paths = resolved_v1
            .owners()
            .iter()
            .find(|owner| owner.owner() == local_owner)
            .expect("type-owner resolution includes the local record")
            .path_resolution()
            .expect("local record path analysis succeeds");
        assert!(
            local_paths
                .paths()
                .values()
                .any(|path| matches!(path.base, Res::Def(DefKind::Struct, _))
                    && path.resolved_segments == 2),
            "the record field path resolves through the active WIT view"
        );
        let local_field_types = resolved_v1
            .local_record_field_types_with_scopes(
                &collection_v1,
                None,
                Some(&wit_scopes_v1),
                local_owner,
            )
            .expect("matching active WIT-view closure guards the field projection")
            .expect("the direct local record has a projection");
        let local_value = local_field_types
            .fields()
            .expect("the record itself is eligible for projection")
            .iter()
            .find(|field| database.symbols.resolve(field.name()).ok().as_deref() == Some("value"))
            .expect("the local primitive field is projected");
        assert!(matches!(
            local_field_types.type_of_field(local_value.def_id()),
            Some(Ok(ty)) if matches!(ty.kind(), sai_ty::ty::TyKind::Bool)
        ));
        assert!(
            matches!(
                resolved_v1.local_record_field_types(&collection_v1, local_owner),
                Err(OwnerControlFlowResolutionError::SnapshotMismatch)
            ),
            "a WIT-scoped resolution rejects lookup without its active closure"
        );

        let owner_index = collection_v1.scopes.top_level_owners[0]
            .owner
            .def_id
            .index()
            .raw();
        let query_key = TypeOwnerPathQueryKey {
            package: collection_v1.package_key.clone(),
            owner_index,
        };
        let cached_v1 = database
            .type_owner_paths
            .query
            .get(&mut database.query_database, query_key.clone())
            .expect("first type-owner query output is cached");
        let repeated_v1 = database
            .resolve_type_owner_paths_with_wit_views(
                &collection_v1,
                &module_tree,
                &snapshot,
                &wit_scopes_v1,
            )
            .expect("repeated WIT type-owner query resolves");
        assert!(repeated_v1.matches_wit_view_scopes(&collection_v1, &wit_scopes_v1));
        let cached_v1_again = database
            .type_owner_paths
            .query
            .get(&mut database.query_database, query_key.clone())
            .expect("repeated type-owner query output is cached");
        assert!(Arc::ptr_eq(&cached_v1, &cached_v1_again));

        set_artifact_inputs(
            &mut database,
            "1.0.0",
            "package acme:wit-api@1.0.0; interface streams { record response { value: u32 } }",
        );
        assert!(matches!(
            database.resolve_type_owner_paths_with_wit_views(
                &collection_v1,
                &module_tree,
                &snapshot,
                &wit_scopes_v1,
            ),
            Err(OwnerControlFlowResolutionError::ModuleMemberScopes(
                Phase1ModuleMemberScopeError::WitViewScopeMismatch(_)
            ))
        ));
        let wit_scopes_changed = database
            .collect_active_wit_view_scopes(&module_tree, &snapshot, &target_cfg, &graph_v1)
            .expect("changed WIT view recollects");
        assert_ne!(
            wit_scopes_v1.closure_fingerprint(),
            wit_scopes_changed.closure_fingerprint(),
            "view content is part of the active WIT closure identity"
        );
        assert!(
            matches!(
                resolved_v1.local_record_field_types_with_scopes(
                    &collection_v1,
                    None,
                    Some(&wit_scopes_changed),
                    local_owner,
                ),
                Err(OwnerControlFlowResolutionError::SnapshotMismatch)
            ),
            "the original field projection rejects a changed WIT-view closure"
        );
        let collection_changed = database
            .collect_phase1_package_scopes_with_manifest_and_wit_views(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
                Arc::clone(&root_manifest),
                PackageRole::Root,
                &wit_scopes_changed,
            )
            .expect("scope collection refreshes with WIT");
        let resolved_changed = database
            .resolve_type_owner_paths_with_wit_views(
                &collection_changed,
                &module_tree,
                &snapshot,
                &wit_scopes_changed,
            )
            .expect("missing WIT member is reported after view refresh");
        let changed_error = &resolved_changed.owners()[0]
            .path_resolution()
            .expect("type owner still resolves")
            .module_path_errors()[0];
        assert!(matches!(
            changed_error.error(),
            ModulePathError::MissingMember { .. }
        ));
        let cached_changed = database
            .type_owner_paths
            .query
            .get(&mut database.query_database, query_key.clone())
            .expect("changed WIT query output is cached");
        assert!(!Arc::ptr_eq(&cached_v1, &cached_changed));

        let graph_v2 = graph_for_version("1.1.0");
        database
            .set_package_graph(Some(graph_v2.clone()))
            .expect("exact package version is refreshed");
        set_artifact_inputs(
            &mut database,
            "1.1.0",
            "package acme:wit-api@1.1.0; interface streams { record request { value: u32 } }",
        );
        let wit_scopes_v2 = database
            .collect_active_wit_view_scopes(&module_tree, &snapshot, &target_cfg, &graph_v2)
            .expect("exact-version WIT view recollects");
        assert_eq!(
            wit_scopes_v2
                .available_unit_names()
                .filter(|unit| !unit.starts_with("wasi:"))
                .collect::<Vec<_>>(),
            ["acme:wit-api@1.1.0"]
        );
        assert_ne!(
            wit_scopes_changed.closure_fingerprint(),
            wit_scopes_v2.closure_fingerprint(),
            "exact unit versions are part of the closure identity"
        );
        let collection_v2 = database
            .collect_phase1_package_scopes_with_manifest_and_wit_views(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
                Arc::clone(&root_manifest),
                PackageRole::Root,
                &wit_scopes_v2,
            )
            .expect("phase 1 scopes refresh against the selected exact version");
        let resolved_v2 = database
            .resolve_type_owner_paths_with_wit_views(
                &collection_v2,
                &module_tree,
                &snapshot,
                &wit_scopes_v2,
            )
            .expect("qualified WIT member resolves after exact-version refresh");
        assert!(matches!(
            resolved_v2.owners()[0]
                .path_resolution()
                .expect("type owner resolves")
                .paths()
                .values()
                .next()
                .expect("qualified path exists")
                .base,
            Res::Def(DefKind::Struct, _)
        ));
        let cached_v2 = database
            .type_owner_paths
            .query
            .get(&mut database.query_database, query_key)
            .expect("exact-version query output is cached");
        assert!(!Arc::ptr_eq(&cached_changed, &cached_v2));

        set_artifact_inputs(
            &mut database,
            "1.1.0",
            "package acme:wit-api@1.1.0; interface streams { record request { value: u32 }",
        );
        let wit_scopes_failed = database
            .collect_active_wit_view_scopes(&module_tree, &snapshot, &target_cfg, &graph_v2)
            .expect("a failed view is retained as a closure value");
        assert_eq!(
            wit_scopes_failed
                .unavailable_unit_names()
                .collect::<Vec<_>>(),
            ["acme:wit-api@1.1.0"]
        );
        let collection_failed = database
            .collect_phase1_package_scopes_with_manifest_and_wit_views(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
                Arc::clone(&root_manifest),
                PackageRole::Root,
                &wit_scopes_failed,
            )
            .expect("failed WIT view does not abort local Phase 1 collection");
        assert!(
            collection_failed
                .scopes()
                .diagnostics
                .iter()
                .all(|diagnostic| diagnostic.code != sai_diagnostics::Code::FeatureNotImplemented),
            "a failed artifact WIT view is not classified as an unsupported dependency feature"
        );
        let resolved_failed = database
            .resolve_type_owner_paths_with_wit_views(
                &collection_failed,
                &module_tree,
                &snapshot,
                &wit_scopes_failed,
            )
            .expect("failed WIT target leaves its suffix deferred");
        let failed_path = resolved_failed.owners()[0]
            .path_resolution()
            .expect("the local type owner remains usable");
        assert!(
            failed_path
                .module_path_errors()
                .iter()
                .all(|error| !matches!(error.error(), ModulePathError::MissingMember { .. })),
            "a failed WIT producer must not become a misleading missing member"
        );
        assert!(
            !failed_path.deferred_paths().is_empty()
                || failed_path
                    .paths()
                    .values()
                    .any(|path| path.base == Res::Err),
            "unavailable WIT aliases stay unresolved without consuming a member suffix"
        );

        let mut other_session = RootDatabase::new().expect("second session initializes");
        other_session
            .set_package_graph(Some(graph_v2))
            .expect("second session uses the same active graph");
        assert!(matches!(
            other_session.resolve_type_owner_paths_with_wit_views(
                &collection_v2,
                &module_tree,
                &snapshot,
                &wit_scopes_v2,
            ),
            Err(OwnerControlFlowResolutionError::ModuleMemberScopes(
                Phase1ModuleMemberScopeError::WitViewScopeMismatch(_)
            ))
        ));
    }

    #[test]
    fn active_wit_views_include_wasi_and_are_session_bound() {
        let root = concat!(
            "use wasi:io/streams as streams\n",
            "use wasi:io/streams.{InputStream as Stream}\n",
            "use wasi:cli/command as command\n",
            "type Client = streams.InputStream\n",
            "pub interface local {\n",
            "  fn send(value: borrow streams.StreamError)\n",
            "}\n",
        )
        .as_bytes();
        let (mut database, module_tree, snapshot, root_package) = phase1_fixture(root, b"");
        let target_cfg = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let root_key = PackageKey::new("acme:phase1#1").expect("root package key is valid");
        let graph = PackageGraph::new(
            Version::parse("1.8.2").expect("toolchain version is valid"),
            [PackageGraphNode::new(
                root_key.clone(),
                "acme:phase1",
                Version::parse("1.0.0").expect("root version is valid"),
                PackageForm::Source,
                PackageGraphRole::Root,
                Vec::new(),
            )
            .expect("root package graph node is valid")],
        )
        .expect("package graph is valid");
        let root_manifest: Arc<[u8]> =
            Arc::from(&b"package acme:phase1 @ 1.0.0\nsource \"src\"\n"[..]);
        database
            .set_package_graph(Some(graph.clone()))
            .expect("active package graph is recorded");

        let wit_scopes = database
            .collect_active_wit_view_scopes(&module_tree, &snapshot, &target_cfg, &graph)
            .expect("active and embedded WASI views collect");
        assert!(
            wit_scopes
                .available_unit_names()
                .any(|unit| unit == "wasi:io@0.2.3")
        );
        let collection = database
            .collect_phase1_package_scopes_with_manifest_and_wit_views(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
                Arc::clone(&root_manifest),
                PackageRole::Root,
                &wit_scopes,
            )
            .expect("WASI imports are resolved during phase 1");
        let incompatible_borrow = collection
            .interface_check_diagnostics()
            .iter()
            .find(|diagnostic| {
                diagnostic.code == sai_diagnostics::Code::WitIncompatibleType
                    && diagnostic.data.get("wit_incompatibility")
                        == Some(&sai_diagnostics::Value::String(
                            "borrow_of_non_resource".to_owned(),
                        ))
            })
            .expect("a borrowed WIT enum is rejected as a non-resource");
        let borrow_span = incompatible_borrow
            .primary()
            .expect("the boundary finding has a source location");
        let borrow_start = root
            .windows(b"borrow streams.StreamError".len())
            .position(|window| window == b"borrow streams.StreamError")
            .expect("the borrowed WIT enum occurs in the source");
        assert_eq!(
            borrow_span.span.range.start().to_usize(),
            borrow_start,
            "the diagnostic points to the complete borrowed WIT type"
        );
        assert_eq!(
            borrow_span.span.range.end().to_usize(),
            borrow_start + b"borrow streams.StreamError".len(),
            "the diagnostic spans the complete borrowed WIT type"
        );
        let module_scope = collection.scopes().module(ModuleId::ROOT).unwrap();
        let streams = database.symbols.intern("streams").unwrap();
        assert!(matches!(
            module_scope.scope.get(&streams).map(|binding| binding.res),
            Some(Res::Def(DefKind::Interface, _))
        ));
        assert!(
            collection
                .scopes()
                .diagnostics
                .iter()
                .any(|diagnostic| diagnostic.code == sai_diagnostics::Code::InvalidUseTarget),
            "a WASI world is rejected as a `use` target"
        );
        let stream = database.symbols.intern("Stream").unwrap();
        assert!(matches!(
            module_scope.scope.get(&stream).map(|binding| binding.res),
            Some(Res::Def(DefKind::Resource, _))
        ));
        let resolved = database
            .resolve_type_owner_paths_with_wit_views(
                &collection,
                &module_tree,
                &snapshot,
                &wit_scopes,
            )
            .expect("qualified WASI members resolve");
        assert!(matches!(
            resolved.owners()[0]
                .path_resolution()
                .expect("type owner path resolves")
                .paths()
                .values()
                .next()
                .expect("qualified path is retained")
                .base,
            Res::Def(DefKind::Resource, _)
        ));
        assert!(wit_scopes.matches_collection(&collection));
        assert!(resolved.matches_wit_view_scopes(&collection, &wit_scopes));

        let source_scopes = database
            .collect_active_source_member_scopes(&collection, &graph, &[])
            .expect("source-only closure validates");
        let other_database = RootDatabase::new().expect("second session initializes");
        other_database
            .intern_package("padding:package#1")
            .expect("padding package interns before source scopes");
        other_database
            .symbols
            .intern("padding")
            .expect("padding symbol interns before source scopes");
        let (mut other_session, other_tree, _other_snapshot, other_root_package) =
            phase1_fixture_with_database(other_database, root, b"");
        assert_eq!(
            module_tree.modules[0].file, other_tree.modules[0].file,
            "equivalent fixtures allocate the same source file IDs"
        );
        assert_ne!(
            root_package, other_root_package,
            "padding changes the session-local root package ID"
        );
        let other_graph = PackageGraph::new(
            Version::parse("1.8.2").expect("toolchain version is valid"),
            [PackageGraphNode::new(
                PackageKey::new("acme:phase1#1").expect("root package key is valid"),
                "acme:phase1",
                Version::parse("1.0.0").expect("root version is valid"),
                PackageForm::Source,
                PackageGraphRole::Root,
                Vec::new(),
            )
            .expect("root package graph node is valid")],
        )
        .expect("equivalent package graph is valid");
        other_session
            .set_package_graph(Some(other_graph.clone()))
            .expect("equivalent active package graph is recorded");
        let other_wit_scopes = other_session
            .collect_active_wit_view_scopes(&other_tree, &snapshot, &target_cfg, &other_graph)
            .expect("equivalent views collect in the other session");
        let other_collection = other_session
            .collect_phase1_package_scopes_with_manifest_and_wit_views(
                &other_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
                root_manifest,
                PackageRole::Root,
                &other_wit_scopes,
            )
            .expect("equivalent phase 1 inputs collect in the other session");
        let other_source_scopes = other_session
            .collect_active_source_member_scopes(&other_collection, &other_graph, &[])
            .expect("equivalent source closure collects in the other session");
        let other_resolved = other_session
            .resolve_type_owner_paths_with_wit_views(
                &other_collection,
                &other_tree,
                &snapshot,
                &other_wit_scopes,
            )
            .expect("equivalent type paths resolve in the other session");

        assert_ne!(
            wit_scopes
                .views()
                .find(|view| view.visible_identity == "wasi:io")
                .unwrap()
                .view
                .package,
            other_wit_scopes
                .views()
                .find(|view| view.visible_identity == "wasi:io")
                .unwrap()
                .view
                .package,
            "padding interners give equivalent views different runtime package IDs"
        );
        assert_eq!(
            wit_scopes.closure_fingerprint(),
            other_wit_scopes.closure_fingerprint(),
            "equivalent WIT closures keep their stable fingerprint across sessions"
        );
        assert!(!wit_scopes.matches_collection(&other_collection));
        assert!(!resolved.matches_collection(&other_collection));
        assert!(!resolved.matches_wit_view_scopes(&other_collection, &other_wit_scopes));
        assert!(!other_wit_scopes.matches_collection(&collection));
        assert!(!other_resolved.matches_wit_view_scopes(&collection, &wit_scopes));
        assert!(!source_scopes.matches_collection(&other_collection));
        assert!(other_source_scopes.matches_collection(&other_collection));
        assert!(matches!(
            other_session.resolve_type_owner_paths_with_member_scopes_and_wit_views(
                &other_collection,
                &other_tree,
                &snapshot,
                &source_scopes,
                &other_wit_scopes,
            ),
            Err(OwnerControlFlowResolutionError::ModuleMemberScopes(
                Phase1ModuleMemberScopeError::PackageGraphMismatch(_)
            ))
        ));
        assert_eq!(
            database
                .packages
                .resolve(root_package)
                .expect("first root package belongs to its session"),
            other_session
                .packages
                .resolve(other_root_package)
                .expect("second root package belongs to its session"),
            "equivalent fixtures retain the same stable root package key"
        );
    }

    #[test]
    fn active_wit_view_collection_propagates_query_cancellation() {
        let (mut database, module_tree, snapshot, root_package) =
            phase1_fixture(b"type Local = U32\n", b"");
        let target_cfg = target_cfg_for_check("wasm32-core").expect("target config is valid");
        let root_key = PackageKey::new(
            database
                .packages
                .resolve(root_package)
                .expect("root package resolves")
                .to_string(),
        )
        .expect("root package key is valid");
        let root_identity = root_key
            .as_str()
            .split_once('#')
            .expect("root package key has a selected line")
            .0;
        let wit_package = database
            .intern_package("acme:wit-api#1")
            .expect("WIT package key interns");
        let graph = PackageGraph::new(
            Version::parse("1.8.2").expect("toolchain version is valid"),
            [
                PackageGraphNode::new(
                    root_key.clone(),
                    root_identity,
                    Version::parse("1.0.0").expect("root version is valid"),
                    PackageForm::Source,
                    PackageGraphRole::Root,
                    vec![graph_edge("acme:wit-api#1", "acme:wit-api")],
                )
                .expect("root graph node is valid"),
                PackageGraphNode::new(
                    PackageKey::new("acme:wit-api#1").expect("WIT key is valid"),
                    "acme:wit-api",
                    Version::parse("1.0.0").expect("WIT version is valid"),
                    PackageForm::Artifact,
                    PackageGraphRole::Dependency,
                    Vec::new(),
                )
                .expect("WIT graph node is valid"),
            ],
        )
        .expect("package graph is valid");
        database
            .set_package_graph(Some(graph.clone()))
            .expect("package graph is recorded");
        database
            .set_package_manifest(
                wit_package,
                Arc::from(
                    &b"package acme:wit-api @ 1.0.0\n\
                      artifact component {}\n\
                      wit \"wit\"\n"[..],
                ),
                PackageRole::Dependency,
                Durability::Low,
            )
            .expect("WIT package contract is recorded");

        let cancellation = database.query_database.cancellation_token();
        cancellation.cancel();
        assert!(matches!(
            database.wit_unit_of(wit_package),
            Err(WitUnitOfError::Query(QueryError::Cancelled))
        ));
        database
            .query_database
            .reset_cancellation()
            .expect("query cancellation resets between requests");

        let unit = database
            .wit_unit_of(wit_package)
            .expect("WIT unit query succeeds")
            .expect("active WIT package has a unit");
        cancellation.cancel();
        assert!(matches!(
            database.wit_view(&unit),
            Err(WitViewQueryError::Query(QueryError::Cancelled))
        ));
        database
            .query_database
            .reset_cancellation()
            .expect("query cancellation resets between requests");

        cancellation.cancel();
        assert!(matches!(
            database.collect_active_wit_view_scopes(&module_tree, &snapshot, &target_cfg, &graph,),
            Err(Phase1ModuleMemberScopeError::WitViewRuntimeFailure {
                failure: Phase1WitViewRuntimeFailure::Query(QueryError::Cancelled),
                ..
            })
        ));
        database
            .query_database
            .reset_cancellation()
            .expect("query cancellation resets after the collection failure");
    }

    #[test]
    fn generated_wit_view_retries_after_source_def_paths_are_registered() {
        let (mut database, requester_tree, requester_snapshot, _) =
            phase1_fixture(b"type Local = U32\n", b"");
        let (source_package, source_tree, source_snapshot_files) = multi_package_fixture(
            &mut database,
            "acme:wit-source#1",
            "acme:wit-source@1.0.0",
            &[("lib.sai", b"fn source_item() {}\n")],
        );
        let source_snapshot = WorkspaceSnapshot::new(source_snapshot_files)
            .expect("source package snapshot is valid");
        let target_cfg = target_cfg_for_check("wasm32-wasi").expect("target config is valid");
        let requester_key = PackageKey::new("acme:phase1#1").expect("requester key is valid");
        let graph = PackageGraph::new(
            Version::parse("1.8.2").expect("toolchain version is valid"),
            [
                PackageGraphNode::new(
                    requester_key,
                    "acme:phase1",
                    Version::parse("1.0.0").expect("requester version is valid"),
                    PackageForm::Source,
                    PackageGraphRole::Root,
                    vec![graph_edge("acme:wit-source#1", "acme:wit-source")],
                )
                .expect("requester graph node is valid"),
                PackageGraphNode::new(
                    PackageKey::new("acme:wit-source#1").expect("source key is valid"),
                    "acme:wit-source",
                    Version::parse("1.0.0").expect("source version is valid"),
                    PackageForm::Source,
                    PackageGraphRole::Dependency,
                    Vec::new(),
                )
                .expect("source graph node is valid"),
            ],
        )
        .expect("package graph is valid");
        database
            .set_package_graph(Some(graph.clone()))
            .expect("package graph is recorded");
        database
            .set_package_manifest(
                source_package,
                Arc::from(&b"package acme:wit-source @ 1.0.0\nsource \"src\"\n"[..]),
                PackageRole::Dependency,
                Durability::Low,
            )
            .expect("source package contract is recorded");

        // Keep the future source interner alive but unpublished to WIT view
        // queries. This reproduces a generated snapshot arriving before the
        // source package has completed Phase 1 collection.
        let source_def_paths = Arc::new(
            DefPathInterner::new(source_package, &database.packages, &database.symbols)
                .expect("source definition paths initialize"),
        );
        let interface_name = database
            .symbols
            .intern("api")
            .expect("source interface name interns");
        let source_interface_path = DefPath::new(
            source_package,
            vec![sai_hir::DisambiguatedDefPathData {
                data: DefPathData::Interface(interface_name),
                disambiguator: 0,
            }],
            &database.packages,
            &database.symbols,
        )
        .expect("source interface path is valid");
        let source_interface = source_def_paths
            .intern(source_interface_path)
            .expect("source interface path interns")
            .to_def_id();
        database
            .def_paths
            .insert(source_package, Arc::clone(&source_def_paths));
        database
            .set_generated_wit_text(
                source_package,
                GeneratedText {
                    text: Arc::from("package acme:wit-source@1.0.0; interface api {}"),
                    complete: true,
                    origins: Arc::from([("api".to_owned(), source_interface)]),
                },
                Durability::Low,
            )
            .expect("generated WIT with a source origin is recorded");

        assert!(matches!(
            database.collect_active_wit_view_scopes(
                &requester_tree,
                &requester_snapshot,
                &target_cfg,
                &graph,
            ),
            Err(Phase1ModuleMemberScopeError::WitViewRuntimeFailure {
                failure: Phase1WitViewRuntimeFailure::View(WitViewQueryError::View(
                    WitViewError::GeneratedOriginInternerRequired
                )),
                ..
            })
        ));

        database
            .collect_phase1_package_scopes_collection(
                &source_tree,
                &source_snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
            )
            .expect("source package Phase 1 publishes its path interner");
        let retried = database
            .collect_active_wit_view_scopes(
                &requester_tree,
                &requester_snapshot,
                &target_cfg,
                &graph,
            )
            .expect("view retries after the source interner becomes tracked");
        assert_eq!(
            retried
                .available_unit_names()
                .filter(|unit| !unit.starts_with("wasi:"))
                .collect::<Vec<_>>(),
            ["acme:wit-source@1.0.0"]
        );
    }

    #[test]
    fn unavailable_generated_wit_view_defers_declared_imports() {
        let root = b"use acme:wit-source/streams as api\ntype Client = api.Request\n";
        let (mut database, module_tree, snapshot, root_package) = phase1_fixture(root, b"");
        let target_cfg = target_cfg_for_check("wasm32-wasi").expect("target config is valid");
        let root_key = PackageKey::new(
            database
                .packages
                .resolve(root_package)
                .expect("root package resolves")
                .to_string(),
        )
        .expect("root package key is valid");
        let root_identity = root_key
            .as_str()
            .split_once('#')
            .expect("root package key has a selected line")
            .0;
        let source_package = database
            .intern_package("acme:wit-source#1")
            .expect("source package key interns");
        let graph = PackageGraph::new(
            Version::parse("1.8.2").expect("toolchain version is valid"),
            [
                PackageGraphNode::new(
                    root_key.clone(),
                    root_identity,
                    Version::parse("1.0.0").expect("root version is valid"),
                    PackageForm::Source,
                    PackageGraphRole::Root,
                    vec![graph_edge("acme:wit-source#1", "acme:wit-source")],
                )
                .expect("root graph node is valid"),
                PackageGraphNode::new(
                    PackageKey::new("acme:wit-source#1").expect("source key is valid"),
                    "acme:wit-source",
                    Version::parse("1.0.0").expect("source version is valid"),
                    PackageForm::Source,
                    PackageGraphRole::Dependency,
                    Vec::new(),
                )
                .expect("source graph node is valid"),
            ],
        )
        .expect("package graph is valid");
        database
            .set_package_graph(Some(graph.clone()))
            .expect("package graph is recorded");
        database
            .set_package_manifest(
                source_package,
                Arc::from(&b"package acme:wit-source @ 1.0.0\nsource \"src\"\n"[..]),
                PackageRole::Dependency,
                Durability::Low,
            )
            .expect("source package contract is recorded");

        let wit_views = database
            .collect_active_wit_view_scopes(&module_tree, &snapshot, &target_cfg, &graph)
            .expect("missing generated output is a semantic WIT failure");
        assert_eq!(
            wit_views.unavailable_unit_names().collect::<Vec<_>>(),
            ["acme:wit-source@1.0.0"]
        );
        assert_eq!(
            wit_views
                .direct_unavailable_package_identities(&graph)
                .collect::<Vec<_>>(),
            ["acme:wit-source"]
        );
        let manifest: Arc<[u8]> = Arc::from(
            &b"package acme:phase1 @ 1.0.0\n\
              source \"src\"\n\
              requires { acme:wit-source @ ^1 }\n"[..],
        );
        let collection = database
            .collect_phase1_package_scopes_with_manifest_and_wit_views(
                &module_tree,
                &snapshot,
                &target_cfg,
                Phase1BuildContext::default(),
                manifest,
                PackageRole::Root,
                &wit_views,
            )
            .expect("local scopes collect with an unavailable generated WIT view");
        assert!(
            collection.scopes().diagnostics.iter().all(|diagnostic| {
                diagnostic.code != sai_diagnostics::Code::FeatureNotImplemented
            })
        );
        let root_scope = collection
            .scopes()
            .module(ModuleId::ROOT)
            .expect("root module scope is available");
        let api = database
            .symbols
            .intern("api")
            .expect("WIT alias name interns");
        assert!(
            !root_scope.scope.contains_key(&api),
            "the failed generated interface import stays deferred"
        );

        let resolutions = database
            .resolve_type_owner_paths_with_wit_views(
                &collection,
                &module_tree,
                &snapshot,
                &wit_views,
            )
            .expect("the failed generated interface target defers its suffix");
        let path = resolutions.owners()[0]
            .path_resolution()
            .expect("local type owner resolves");
        assert!(
            path.module_path_errors()
                .iter()
                .all(|error| !matches!(error.error(), ModulePathError::MissingMember { .. })),
            "an unavailable generated interface is not reported as a missing member"
        );
        assert!(
            !path.deferred_paths().is_empty()
                || path.paths().values().any(|path| path.base == Res::Err),
            "the generated WIT suffix remains deferred"
        );
    }

    #[test]
    fn wit_unit_of_projects_active_source_artifact_and_hybrid_packages() {
        let mut database = RootDatabase::new().expect("driver initializes");
        let root = database
            .intern_package("acme:wit-root#1")
            .expect("root package key interns");
        let source = database
            .intern_package("acme:wit-source#1")
            .expect("source package key interns");
        let artifact = database
            .intern_package("acme:wit-artifact#1")
            .expect("artifact package key interns");
        let hybrid_source = database
            .intern_package("acme:wit-hybrid-source#1")
            .expect("source-form hybrid package key interns");
        let hybrid_artifact = database
            .intern_package("acme:wit-hybrid-artifact#1")
            .expect("artifact-form hybrid package key interns");

        let node = |key: &str,
                    identity: &str,
                    form: PackageForm,
                    role: PackageGraphRole,
                    edges: Vec<PackageGraphEdge>| {
            PackageGraphNode::new(
                PackageKey::new(key).expect("graph key is valid"),
                identity,
                Version::parse("1.0.0").expect("version is valid"),
                form,
                role,
                edges,
            )
            .expect("graph node is valid")
        };
        let graph = PackageGraph::new(
            Version::parse("1.8.2").expect("toolchain version is valid"),
            [
                node(
                    "acme:wit-root#1",
                    "acme:wit-root",
                    PackageForm::Source,
                    PackageGraphRole::Root,
                    vec![
                        graph_edge("acme:wit-source#1", "acme:wit-source"),
                        graph_edge("acme:wit-artifact#1", "acme:wit-artifact"),
                        graph_edge("acme:wit-hybrid-source#1", "acme:wit-hybrid-source"),
                        graph_edge("acme:wit-hybrid-artifact#1", "acme:wit-hybrid-artifact"),
                    ],
                ),
                node(
                    "acme:wit-source#1",
                    "acme:wit-source",
                    PackageForm::Source,
                    PackageGraphRole::Dependency,
                    Vec::new(),
                ),
                node(
                    "acme:wit-artifact#1",
                    "acme:wit-artifact",
                    PackageForm::Artifact,
                    PackageGraphRole::Dependency,
                    Vec::new(),
                ),
                node(
                    "acme:wit-hybrid-source#1",
                    "acme:wit-hybrid-source",
                    PackageForm::Source,
                    PackageGraphRole::WorkspaceMember,
                    Vec::new(),
                ),
                node(
                    "acme:wit-hybrid-artifact#1",
                    "acme:wit-hybrid-artifact",
                    PackageForm::Artifact,
                    PackageGraphRole::Dependency,
                    Vec::new(),
                ),
            ],
        )
        .expect("active graph is valid");

        let set_manifest = |database: &mut RootDatabase, package, role, source: &str| {
            database
                .set_package_manifest(package, Arc::from(source.as_bytes()), role, Durability::Low)
                .expect("manifest input is set");
        };
        set_manifest(
            &mut database,
            root,
            PackageRole::Root,
            "package acme:wit-root @ 1.0.0\nsource \"src\"\n",
        );
        set_manifest(
            &mut database,
            source,
            PackageRole::Dependency,
            "package acme:wit-source @ 1.0.0\nsource \"src\"\nwit \"authored\"\n",
        );
        set_manifest(
            &mut database,
            artifact,
            PackageRole::Dependency,
            "package acme:wit-artifact @ 1.0.0\nartifact component {}\n",
        );
        set_manifest(
            &mut database,
            hybrid_source,
            PackageRole::Dependency,
            "package acme:wit-hybrid-source @ 1.0.0\nsource \"src\"\nartifact component {}\n",
        );
        set_manifest(
            &mut database,
            hybrid_artifact,
            PackageRole::Dependency,
            "package acme:wit-hybrid-artifact @ 1.0.0\nsource \"src\"\nartifact component {}\n",
        );
        database
            .set_package_graph(Some(graph))
            .expect("active package graph is set");

        let root_unit = database
            .wit_unit_of(root)
            .expect("root's dependent-facing unit resolves");
        assert_eq!(root_unit, None);

        let source_unit = database
            .wit_unit_of(source)
            .expect("source package unit resolves")
            .expect("source packages expose generated WIT");
        assert!(source_unit.stable_key().starts_with("wit:gen:"));
        assert_eq!(
            source_unit.kind(),
            WitUnitKind::Generated { package: source }
        );
        assert_eq!(source_unit.canonical_name(), "acme:wit-source@1.0.0");

        let artifact_unit = database
            .wit_unit_of(artifact)
            .expect("artifact package unit resolves")
            .expect("artifact packages expose directory WIT");
        assert!(artifact_unit.stable_key().starts_with("wit:dir:"));
        assert_eq!(artifact_unit.kind(), WitUnitKind::Dir { package: artifact });

        for (package, expected_prefix) in
            [(hybrid_source, "wit:dir:"), (hybrid_artifact, "wit:dir:")]
        {
            let unit = database
                .wit_unit_of(package)
                .expect("hybrid package unit resolves")
                .expect("hybrid packages expose directory WIT in either form");
            assert!(unit.stable_key().starts_with(expected_prefix));
            assert_eq!(unit.kind(), WitUnitKind::Dir { package });
        }

        set_manifest(
            &mut database,
            root,
            PackageRole::Root,
            "package acme:wit-root @ 1.0.0\nsource \"src\"\nartifact component {}\n",
        );
        assert_eq!(
            database
                .wit_unit_of(root)
                .expect("hybrid root unit resolves"),
            None,
            "the root's directory WIT is loaded by separate validation queries"
        );
    }

    #[test]
    fn wit_unit_of_handles_implicit_packages_and_rejects_invalid_active_inputs() {
        let mut database = RootDatabase::new().expect("driver initializes");
        for identity in ["sai:core", "sai:alloc"] {
            let package = database
                .intern_package(identity)
                .expect("implicit package key interns");
            assert_eq!(
                database
                    .wit_unit_of(package)
                    .expect("implicit package query resolves"),
                None
            );
        }

        let dependency = database
            .intern_package("acme:wit-dependency#1")
            .expect("dependency package key interns");
        assert!(matches!(
            database.wit_unit_of(dependency),
            Err(WitUnitOfError::PackageGraphUnavailable)
        ));

        let root_node = PackageGraphNode::new(
            PackageKey::new("acme:wit-root#1").expect("root key is valid"),
            "acme:wit-root",
            Version::parse("1.0.0").expect("root version is valid"),
            PackageForm::Source,
            PackageGraphRole::Root,
            vec![graph_edge("acme:wit-dependency#1", "acme:wit-dependency")],
        )
        .expect("root node is valid");
        let dependency_node = PackageGraphNode::new(
            PackageKey::new("acme:wit-dependency#1").expect("dependency key is valid"),
            "acme:wit-dependency",
            Version::parse("1.2.0").expect("selected version is valid"),
            PackageForm::Artifact,
            PackageGraphRole::Dependency,
            Vec::new(),
        )
        .expect("dependency node is valid");
        let graph = PackageGraph::new(
            Version::parse("1.8.2").expect("toolchain version is valid"),
            [root_node, dependency_node],
        )
        .expect("active graph is valid");
        database
            .set_package_graph(Some(graph))
            .expect("active package graph is set");

        database
            .set_package_manifest(
                dependency,
                Arc::from(&b"package acme:wit-dependency @ 1.1.0\nsource \"src\"\n"[..]),
                PackageRole::Dependency,
                Durability::Low,
            )
            .expect("older manifest version is tracked");
        assert!(matches!(
            database.wit_unit_of(dependency),
            Err(WitUnitOfError::PackageVersionMismatch {
                manifest_version,
                selected_version,
                ..
            }) if manifest_version == "1.1.0" && selected_version == "1.2.0"
        ));

        database
            .set_package_manifest(
                dependency,
                Arc::from(&b"package acme:wit-dependency @ 1.2.0\nsource \"src\"\n"[..]),
                PackageRole::Dependency,
                Durability::Low,
            )
            .expect("matching source contract is tracked");
        assert!(matches!(
            database.wit_unit_of(dependency),
            Err(WitUnitOfError::PackageFormMismatch {
                package_kind: sai_wit::WitPackageKind::Source,
                selected_form: PackageForm::Artifact,
                ..
            })
        ));

        let source_form_graph = PackageGraph::new(
            Version::parse("1.8.2").expect("toolchain version is valid"),
            [
                PackageGraphNode::new(
                    PackageKey::new("acme:wit-root#1").expect("root key is valid"),
                    "acme:wit-root",
                    Version::parse("1.0.0").expect("root version is valid"),
                    PackageForm::Source,
                    PackageGraphRole::Root,
                    vec![graph_edge("acme:wit-dependency#1", "acme:wit-dependency")],
                )
                .expect("root node is valid"),
                PackageGraphNode::new(
                    PackageKey::new("acme:wit-dependency#1").expect("dependency key is valid"),
                    "acme:wit-dependency",
                    Version::parse("1.2.0").expect("selected version is valid"),
                    PackageForm::Source,
                    PackageGraphRole::Dependency,
                    Vec::new(),
                )
                .expect("dependency node is valid"),
            ],
        )
        .expect("source-form graph is valid");
        database
            .set_package_graph(Some(source_form_graph))
            .expect("source-form package graph is set");
        database
            .set_package_manifest(
                dependency,
                Arc::from(&b"package acme:wit-dependency @ 1.2.0\nartifact component {}\n"[..]),
                PackageRole::Dependency,
                Durability::Low,
            )
            .expect("artifact contract is tracked");
        assert!(matches!(
            database.wit_unit_of(dependency),
            Err(WitUnitOfError::PackageFormMismatch {
                package_kind: sai_wit::WitPackageKind::Artifact,
                selected_form: PackageForm::Source,
                ..
            })
        ));

        // A package absent from the active graph is not an implicit no-WIT
        // package and must not silently look like an empty view.
        let inactive = database
            .intern_package("acme:wit-inactive#1")
            .expect("inactive package key interns");
        assert!(matches!(
            database.wit_unit_of(inactive),
            Err(WitUnitOfError::PackageNotActive { .. })
        ));
    }

    #[test]
    fn wit_unit_of_invalidates_dependents_when_exact_version_changes_within_a_line() {
        let mut database = RootDatabase::new().expect("driver initializes");
        let dependency = database
            .intern_package("acme:wit-versioned#1")
            .expect("dependency package key interns");
        let package_key = PackageKey::new("acme:wit-versioned#1").expect("dependency key is valid");

        let graph_for_version = |dependency_version: &str| {
            let root = PackageGraphNode::new(
                PackageKey::new("acme:wit-root#1").expect("root key is valid"),
                "acme:wit-root",
                Version::parse("1.0.0").expect("root version is valid"),
                PackageForm::Source,
                PackageGraphRole::Root,
                vec![graph_edge("acme:wit-versioned#1", "acme:wit-versioned")],
            )
            .expect("root node is valid");
            let dependency = PackageGraphNode::new(
                package_key.clone(),
                "acme:wit-versioned",
                Version::parse(dependency_version).expect("selected version is valid"),
                PackageForm::Source,
                PackageGraphRole::Dependency,
                Vec::new(),
            )
            .expect("dependency node is valid");
            PackageGraph::new(
                Version::parse("1.8.2").expect("toolchain version is valid"),
                [root, dependency],
            )
            .expect("active graph is valid")
        };
        let set_versioned_manifest = |database: &mut RootDatabase, version: &str| {
            let source = format!("package acme:wit-versioned @ {version}\nsource \"src\"\n");
            database
                .set_package_manifest(
                    dependency,
                    Arc::from(source.into_bytes()),
                    PackageRole::Dependency,
                    Durability::Low,
                )
                .expect("manifest input is set");
        };

        database
            .set_package_graph(Some(graph_for_version("1.2.3")))
            .expect("first selected graph is set");
        set_versioned_manifest(&mut database, "1.2.3");
        let first = database
            .wit_unit_of(dependency)
            .expect("first selected unit resolves")
            .expect("source package exposes generated WIT");
        assert_eq!(first.canonical_name(), "acme:wit-versioned@1.2.3");
        let first_output = database
            .wit_units
            .query
            .get(&mut database.query_database, package_key.clone())
            .expect("first unit query output exists");

        database
            .set_package_graph(Some(graph_for_version("1.2.4")))
            .expect("updated selected graph is set");
        set_versioned_manifest(&mut database, "1.2.4");
        let second = database
            .wit_unit_of(dependency)
            .expect("updated selected unit resolves")
            .expect("source package still exposes generated WIT");
        assert_eq!(second.canonical_name(), "acme:wit-versioned@1.2.4");
        assert_eq!(
            first.stable_key(),
            second.stable_key(),
            "the persistent WIT view key remains compatibility-line scoped"
        );
        assert_eq!(
            first, second,
            "WitUnit equality deliberately omits the exact selected version"
        );
        let second_output = database
            .wit_units
            .query
            .get(&mut database.query_database, package_key)
            .expect("updated unit query output exists");
        assert!(
            !Arc::ptr_eq(&first_output, &second_output),
            "the query output's exact-version projection prevents early cutoff"
        );
    }

    #[test]
    fn declared_requirements_are_sorted_keep_the_first_identity_and_preserve_only_order() {
        let mut database = RootDatabase::new().expect("driver initializes");
        let package = database
            .intern_package("acme:manifest#1")
            .expect("package key interns");
        let source: Arc<[u8]> = Arc::from(
            &b"package acme:manifest @ 1.0.0\n\
              requires {\n\
                  zed:dep @ ^1 only { wasm64-core, wasm32-core }\n\
                  zed:dep @ ^2 only { native }\n\
              }\n\
              requires test { acme:test @ ^1 }\n"[..],
        );

        database
            .set_package_manifest(package, source, PackageRole::Root, Durability::Low)
            .expect("manifest input is set");
        let requirements = database
            .declared_requirements(package)
            .expect("requirements query succeeds");

        assert_eq!(
            requirements.as_ref(),
            [
                DeclaredRequirement {
                    identity: "acme:test".to_owned(),
                    declaration_order: 2,
                    only: None,
                    test: true,
                },
                DeclaredRequirement {
                    identity: "zed:dep".to_owned(),
                    declaration_order: 0,
                    only: Some(Arc::from([
                        "wasm64-core".to_owned(),
                        "wasm32-core".to_owned(),
                    ])),
                    test: false,
                },
            ]
        );
    }

    #[test]
    fn declared_requirements_track_reordering_while_remaining_identity_sorted() {
        let mut database = RootDatabase::new().expect("driver initializes");
        let package = database
            .intern_package("acme:reordered#1")
            .expect("package key interns");
        let first_source: Arc<[u8]> = Arc::from(
            &b"package acme:reordered @ 1.0.0\n\
              requires {\n\
                  zed:dep @ ^1\n\
                  acme:dep @ ^1\n\
              }\n"[..],
        );
        database
            .set_package_manifest(package, first_source, PackageRole::Root, Durability::Low)
            .expect("initial manifest input is set");
        let first = database
            .declared_requirements(package)
            .expect("initial requirements query succeeds");

        assert_eq!(
            first
                .iter()
                .map(|requirement| {
                    (requirement.identity.as_str(), requirement.declaration_order)
                })
                .collect::<Vec<_>>(),
            [("acme:dep", 1), ("zed:dep", 0)]
        );

        let reordered_source: Arc<[u8]> = Arc::from(
            &b"package acme:reordered @ 1.0.0\n\
              requires {\n\
                  acme:dep @ ^1\n\
                  zed:dep @ ^1\n\
              }\n"[..],
        );
        database
            .set_package_manifest(
                package,
                reordered_source,
                PackageRole::Root,
                Durability::Low,
            )
            .expect("reordered manifest input is set");
        let reordered = database
            .declared_requirements(package)
            .expect("reordered requirements query succeeds");

        assert!(
            !Arc::ptr_eq(&first, &reordered),
            "reordering first declarations changes the tracked requirement value"
        );
        assert_eq!(
            reordered
                .iter()
                .map(|requirement| {
                    (requirement.identity.as_str(), requirement.declaration_order)
                })
                .collect::<Vec<_>>(),
            [("acme:dep", 0), ("zed:dep", 1)]
        );
    }

